def _normalize_fanout_target_csv(raw: str | None) -> list[str]:
    requested = [item.strip().lower() for item in str(raw or "").split(",") if item.strip()]
    normalized: list[str] = []
    seen: set[str] = set()
    for target in requested:
        if target not in FANOUT_TARGETS or target in seen:
            continue
        seen.add(target)
        normalized.append(target)
    return normalized


def _normalize_fanout_targets(raw: Any) -> list[str]:
    if isinstance(raw, str):
        return _normalize_fanout_target_csv(raw)
    if isinstance(raw, (list, tuple, set)):
        requested = [
            str(item).strip().lower()
            for item in raw
            if str(item).strip()
        ]
        normalized: list[str] = []
        seen: set[str] = set()
        for target in requested:
            if target not in FANOUT_TARGETS or target in seen:
                continue
            seen.add(target)
            normalized.append(target)
        return normalized
    return []


def _normalize_lower_csv(raw: str | None) -> list[str]:
    return [item.strip().lower() for item in str(raw or "").split(",") if item.strip()]


def _normalize_outbox_status_csv(raw: str | None) -> list[str]:
    allowed = {"pending", "retrying", "running"}
    requested = [item.strip().lower() for item in str(raw or "").split(",") if item.strip()]
    normalized: list[str] = []
    seen: set[str] = set()
    for status in requested:
        if status not in allowed or status in seen:
            continue
        seen.add(status)
        normalized.append(status)
    return normalized


def _normalize_project_alias_map(raw: str | None) -> dict[str, str]:
    aliases: dict[str, str] = {}
    for item in str(raw or "").split(","):
        token = str(item or "").strip()
        if not token or ":" not in token:
            continue
        source, target = token.split(":", 1)
        source_key = str(source or "").strip().lower()
        target_name = str(target or "").strip()
        if not source_key or not target_name:
            continue
        aliases[source_key] = target_name
    return aliases


def _normalize_task_action_csv(raw: str | None) -> tuple[str, ...]:
    allowed_defaults = ("memory_write", "memory_search", "messaging_command", "http_callback", "provider_chat")
    requested = [item.strip().lower() for item in str(raw or "").split(",") if item.strip()]
    normalized: list[str] = []
    seen: set[str] = set()
    for action in requested:
        if action in seen:
            continue
        seen.add(action)
        normalized.append(action)
    if not normalized:
        return allowed_defaults
    return tuple(normalized)


def _normalize_host_allowlist(raw: str | None) -> tuple[str, ...]:
    hosts = [item.strip().lower() for item in str(raw or "").split(",") if item.strip()]
    unique: list[str] = []
    seen: set[str] = set()
    for host in hosts:
        if host in seen:
            continue
        seen.add(host)
        unique.append(host)
    return tuple(unique)


