def _apply_memory_bank_default_source_policy(
    sources: list[str],
    *,
    explicit_override: bool,
) -> list[str]:
    if RETRIEVAL_MEMORY_BANK_DEFAULT_ENABLED or explicit_override:
        return list(sources)
    return [
        source
        for source in sources
        if source != RETRIEVAL_SOURCE_MEMORY_BANK
    ]


