async def _persist_recall_monitor_sample(sample: dict[str, Any]) -> None:
    line = json.dumps(sample, default=str)

    def _append(path: Path, payload: str) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("a", encoding="utf-8") as handle:
            handle.write(payload + "\n")

    try:
        await asyncio.to_thread(_append, RECALL_MONITOR_PATH, line)
    except Exception as exc:  # pragma: no cover
        logger.warning("Failed to persist recall monitor sample: %s", exc)


async def _collect_recall_monitor_sample() -> dict[str, Any]:
    quality_full = await _recall_quality_snapshot()
    latency_full = await _retrieval_latency_snapshot()
    quality = (
        quality_full.get("byTrafficClass", {}).get(TRAFFIC_CLASS_USER)
        if isinstance(quality_full.get("byTrafficClass"), dict)
        and isinstance(quality_full.get("byTrafficClass", {}).get(TRAFFIC_CLASS_USER), dict)
        else quality_full
    )
    latency = (
        latency_full.get("byTrafficClass", {}).get(TRAFFIC_CLASS_USER)
        if isinstance(latency_full.get("byTrafficClass"), dict)
        and isinstance(latency_full.get("byTrafficClass", {}).get(TRAFFIC_CLASS_USER), dict)
        else latency_full
    )
    recall_alerts = _build_recall_quality_alerts(quality)
    retrieval_alerts = _build_retrieval_alerts(latency)
    by_source = quality.get("bySource") if isinstance(quality.get("bySource"), dict) else {}
    max_source_error_rate = 0.0
    max_source_error_name = None
    for source, metrics in by_source.items():
        if not isinstance(metrics, dict):
            continue
        requests = max(0, int(metrics.get("requests", 0) or 0))
        if requests <= 0:
            continue
        error_rate = max(0.0, float(metrics.get("errorRate", 0.0) or 0.0))
        if error_rate > max_source_error_rate:
            max_source_error_rate = error_rate
            max_source_error_name = str(source)
    letta_metrics = (
        latency.get("sources", {}).get(RETRIEVAL_SOURCE_LETTA)
        if isinstance(latency.get("sources"), dict)
        else None
    )
    letta_requests = 0
    letta_timeouts = 0
    letta_p95 = 0.0
    letta_p99 = 0.0
    if isinstance(letta_metrics, dict):
        letta_requests = max(0, int(letta_metrics.get("requests", 0) or 0))
        letta_timeouts = max(0, int(letta_metrics.get("timeouts", 0) or 0))
        letta_p95 = max(0.0, float(letta_metrics.get("p95Ms", 0.0) or 0.0))
        letta_p99 = max(0.0, float(letta_metrics.get("p99Ms", 0.0) or 0.0))
    letta_timeout_rate = (letta_timeouts / letta_requests) if letta_requests > 0 else 0.0
    retrieval_active = retrieval_alerts.get("active") if isinstance(retrieval_alerts, dict) else []
    return {
        "timestamp": _utc_now(),
        "requests": int(quality.get("requests", 0) or 0),
        "noHitRate": float(quality.get("noHitRate", 0.0) or 0.0),
        "lowConfidenceRate": float(quality.get("lowConfidenceRate", 0.0) or 0.0),
        "staleHitRate": float(quality.get("staleHitRate", 0.0) or 0.0),
        "maxSourceErrorRate": max_source_error_rate,
        "maxSourceError": max_source_error_name,
        "lettaRequests": letta_requests,
        "lettaTimeoutRate": letta_timeout_rate,
        "lettaP95Ms": letta_p95,
        "lettaP99Ms": letta_p99,
        "recallAlertCount": len(recall_alerts),
        "retrievalAlertCount": len(retrieval_active) if isinstance(retrieval_active, list) else 0,
    }


async def _run_recall_monitor_once() -> dict[str, Any]:
    started = time.monotonic()
    sample = await _collect_recall_monitor_sample()
    await _persist_recall_monitor_sample(sample)
    async with recall_monitor_lock:
        recall_monitor_history.append(sample)
        recall_monitor_state["lastRunAt"] = str(sample.get("timestamp") or _utc_now())
        recall_monitor_state["lastDurationMs"] = round((time.monotonic() - started) * 1000, 2)
        recall_monitor_state["runs"] = int(recall_monitor_state.get("runs", 0) or 0) + 1
        recall_monitor_state["lastError"] = None
        recall_monitor_state["lastSample"] = dict(sample)
    return sample


async def _recall_monitor_worker() -> None:
    while True:
        try:
            await _run_recall_monitor_once()
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # pragma: no cover
            async with recall_monitor_lock:
                recall_monitor_state["lastRunAt"] = _utc_now()
                recall_monitor_state["lastError"] = str(exc)[:400]
            logger.warning("recall monitor worker run failed: %s", exc)
        await asyncio.sleep(max(30.0, RECALL_MONITOR_INTERVAL_SECS))


async def _recall_monitor_snapshot(limit: int) -> dict[str, Any]:
    limit = max(1, min(int(limit), RECALL_MONITOR_HISTORY_LIMIT))
    async with recall_monitor_lock:
        state = dict(recall_monitor_state)
        rows = list(recall_monitor_history)[-limit:]
    return {
        "state": state,
        "history": list(reversed(rows)),
        "historySize": len(rows),
        "path": str(RECALL_MONITOR_PATH),
    }


async def _recall_monitor_samples_for_window(
    lookback_hours: float,
    max_samples: int,
) -> list[dict[str, Any]]:
    async with recall_monitor_lock:
        rows = [dict(item) for item in recall_monitor_history if isinstance(item, dict)]
    if not rows:
        return []
    cutoff = datetime.now(timezone.utc) - timedelta(hours=max(1.0, float(lookback_hours)))
    selected: list[dict[str, Any]] = []
    for row in rows:
        parsed = _parse_timestamp_to_datetime(row.get("timestamp"))
        if parsed is None:
            continue
        if parsed >= cutoff:
            selected.append(row)
    if not selected:
        return rows[-max(1, int(max_samples)) :]
    return selected[-max(1, int(max_samples)) :]


def _recommend_rate_threshold(
    values: list[float],
    *,
    current: float,
    floor: float = 0.001,
    ceiling: float = 1.0,
) -> float:
    clean = sorted(max(0.0, float(value)) for value in values if value is not None)
    if not clean:
        return round(max(floor, min(ceiling, float(current))), 6)
    p95 = _percentile(clean, 0.95)
    p99 = _percentile(clean, 0.99)
    suggested = max(float(current) * 0.8, p95 * 1.2, p99 * 1.05)
    return round(max(floor, min(ceiling, suggested)), 6)


def _recommend_latency_threshold(
    values: list[float],
    *,
    current: float,
    floor: float,
) -> float:
    clean = sorted(max(0.0, float(value)) for value in values if value is not None)
    if not clean:
        return round(max(float(floor), float(current)), 3)
    p95 = _percentile(clean, 0.95)
    p99 = _percentile(clean, 0.99)
    suggested = max(float(current) * 0.85, p95 * 1.15, p99 * 1.05, float(floor))
    return round(suggested, 3)


def _build_recall_tuning_payload(
    samples: list[dict[str, Any]],
    *,
    lookback_hours: float,
    min_samples: int,
) -> dict[str, Any]:
    no_hit_values = [float(item.get("noHitRate", 0.0) or 0.0) for item in samples]
    low_conf_values = [float(item.get("lowConfidenceRate", 0.0) or 0.0) for item in samples]
    stale_values = [float(item.get("staleHitRate", 0.0) or 0.0) for item in samples]
    source_error_values = [float(item.get("maxSourceErrorRate", 0.0) or 0.0) for item in samples]
    letta_p95_values = [float(item.get("lettaP95Ms", 0.0) or 0.0) for item in samples if float(item.get("lettaP95Ms", 0.0) or 0.0) > 0.0]
    letta_p99_values = [float(item.get("lettaP99Ms", 0.0) or 0.0) for item in samples if float(item.get("lettaP99Ms", 0.0) or 0.0) > 0.0]
    letta_timeout_values = [float(item.get("lettaTimeoutRate", 0.0) or 0.0) for item in samples]
    recommendations = {
        "recall": {
            "noHitRate": _recommend_rate_threshold(no_hit_values, current=RECALL_ALERT_NO_HIT_RATE),
            "lowConfidenceRate": _recommend_rate_threshold(
                low_conf_values,
                current=RECALL_ALERT_LOW_CONFIDENCE_RATE,
            ),
            "staleHitRate": _recommend_rate_threshold(stale_values, current=RECALL_ALERT_STALE_HIT_RATE),
            "sourceErrorRate": _recommend_rate_threshold(
                source_error_values,
                current=RECALL_ALERT_SOURCE_ERROR_RATE,
            ),
            "minRequests": RECALL_ALERT_MIN_REQUESTS,
        },
        "retrieval": {
            "lettaP95Ms": _recommend_latency_threshold(
                letta_p95_values,
                current=RETRIEVAL_ALERT_LETTA_P95_MS,
                floor=1000.0,
            ),
            "lettaP99Ms": _recommend_latency_threshold(
                letta_p99_values,
                current=RETRIEVAL_ALERT_LETTA_P99_MS,
                floor=RETRIEVAL_ALERT_LETTA_P95_MS,
            ),
            "lettaTimeoutRate": _recommend_rate_threshold(
                letta_timeout_values,
                current=RETRIEVAL_ALERT_LETTA_TIMEOUT_RATE,
            ),
            "minRequests": RETRIEVAL_ALERT_MIN_REQUESTS,
        },
    }
    warnings: list[str] = []
    if len(samples) < max(1, int(min_samples)):
        warnings.append(
            f"Only {len(samples)} recall monitor samples available; collect at least {int(min_samples)} for stable tuning."
        )
    env = {
        "ORCH_RECALL_ALERT_NO_HIT_RATE": recommendations["recall"]["noHitRate"],
        "ORCH_RECALL_ALERT_LOW_CONFIDENCE_RATE": recommendations["recall"]["lowConfidenceRate"],
        "ORCH_RECALL_ALERT_STALE_HIT_RATE": recommendations["recall"]["staleHitRate"],
        "ORCH_RECALL_ALERT_SOURCE_ERROR_RATE": recommendations["recall"]["sourceErrorRate"],
        "ORCH_RETRIEVAL_ALERT_LETTA_P95_MS": recommendations["retrieval"]["lettaP95Ms"],
        "ORCH_RETRIEVAL_ALERT_LETTA_P99_MS": recommendations["retrieval"]["lettaP99Ms"],
        "ORCH_RETRIEVAL_ALERT_LETTA_TIMEOUT_RATE": recommendations["retrieval"]["lettaTimeoutRate"],
    }
    return {
        "window": {
            "lookbackHours": float(lookback_hours),
            "samples": len(samples),
            "minSamples": int(min_samples),
            "sufficient": len(samples) >= int(min_samples),
        },
        "current": {
            "recall": {
                "noHitRate": RECALL_ALERT_NO_HIT_RATE,
                "lowConfidenceRate": RECALL_ALERT_LOW_CONFIDENCE_RATE,
                "staleHitRate": RECALL_ALERT_STALE_HIT_RATE,
                "sourceErrorRate": RECALL_ALERT_SOURCE_ERROR_RATE,
                "minRequests": RECALL_ALERT_MIN_REQUESTS,
            },
            "retrieval": {
                "lettaP95Ms": RETRIEVAL_ALERT_LETTA_P95_MS,
                "lettaP99Ms": RETRIEVAL_ALERT_LETTA_P99_MS,
                "lettaTimeoutRate": RETRIEVAL_ALERT_LETTA_TIMEOUT_RATE,
                "minRequests": RETRIEVAL_ALERT_MIN_REQUESTS,
            },
        },
        "recommended": recommendations,
        "env": env,
        "warnings": warnings,
    }


async def _run_retrieval_pathway_warm_query(entry: dict[str, Any]) -> bool:
    query = str(entry.get("query") or "").strip()
    if not query:
        return False
    sources = entry.get("sources") if isinstance(entry.get("sources"), list) else None
    source_weights = entry.get("source_weights") if isinstance(entry.get("source_weights"), dict) else None
    mode = _normalize_retrieval_mode(str(entry.get("retrieval_mode") or RETRIEVAL_MODE_BALANCED))
    intent = _normalize_retrieval_intent(str(entry.get("retrieval_intent") or RETRIEVAL_INTENT_DEFAULT))
    limit = max(1, min(RETRIEVAL_PATHWAY_WARMER_LIMIT, 20))
    await federated_search_memory(
        query,
        limit=limit,
        project_filter=str(entry.get("project_filter") or "").strip() or None,
        topic_filter=str(entry.get("topic_filter") or "").strip() or None,
        sources=[str(item) for item in sources] if sources else None,
        source_weights={str(k): float(v) for k, v in source_weights.items()} if source_weights else None,
        preferences=None,
        rerank_with_learning=False,
        retrieval_mode=mode,
        retrieval_intent=intent,
        record_pathway_usage=False,
        traffic_class=TRAFFIC_CLASS_SYNTHETIC,
    )
    return True


async def _warm_retrieval_pathways_once() -> dict[str, Any]:
    if not RETRIEVAL_PATHWAY_WARMER_ENABLED:
        return {"enabled": False, "reason": "ORCH_RETRIEVAL_PATHWAY_WARMER_ENABLED=false"}
    started_at = time.monotonic()
    top_queries = await _list_hot_retrieval_pathways(RETRIEVAL_PATHWAY_WARMER_TOP_QUERIES)
    if not top_queries:
        return {
            "enabled": True,
            "candidates": 0,
            "warmed": 0,
            "skipped": 0,
            "errors": {},
            "durationMs": round((time.monotonic() - started_at) * 1000, 2),
        }
    semaphore = asyncio.Semaphore(max(1, RETRIEVAL_PATHWAY_WARMER_CONCURRENCY))
    warmed = 0
    skipped = 0
    errors: dict[str, str] = {}

    async def _warm(entry: dict[str, Any]) -> None:
        nonlocal warmed, skipped
        query = str(entry.get("query") or "").strip()
        if not query:
            skipped += 1
            return
        async with semaphore:
            try:
                warmed_now = await _run_retrieval_pathway_warm_query(entry)
                if warmed_now:
                    warmed += 1
                else:
                    skipped += 1
            except Exception as exc:
                errors[query[:120]] = str(exc)[:240]

    await asyncio.gather(*[_warm(entry) for entry in top_queries], return_exceptions=False)
    return {
        "enabled": True,
        "candidates": len(top_queries),
        "warmed": warmed,
        "skipped": skipped,
        "errors": errors,
        "durationMs": round((time.monotonic() - started_at) * 1000, 2),
    }


def _record_retrieval_pathway_warmer_run(
    *,
    result: dict[str, Any] | None,
    error: str | None = None,
    duration_ms: float = 0.0,
) -> None:
    retrieval_pathway_warmer_state["lastRunAt"] = _utc_now()
    retrieval_pathway_warmer_state["lastDurationMs"] = round(max(0.0, duration_ms), 2)
    retrieval_pathway_warmer_state["runs"] = int(retrieval_pathway_warmer_state.get("runs", 0) or 0) + 1
    retrieval_pathway_warmer_state["lastError"] = (str(error)[:400] if error else None)
    retrieval_pathway_warmer_state["lastResult"] = result or {}
    if isinstance(result, dict):
        retrieval_pathway_warmer_state["lastWarmed"] = int(result.get("warmed", 0) or 0)
        retrieval_pathway_warmer_state["lastSkipped"] = int(result.get("skipped", 0) or 0)


async def _retrieval_pathway_warmer_worker() -> None:
    interval = max(30.0, RETRIEVAL_PATHWAY_WARMER_INTERVAL_SECS)
    while True:
        started = time.monotonic()
        try:
            result = await _warm_retrieval_pathways_once()
            _record_retrieval_pathway_warmer_run(
                result=result,
                duration_ms=(time.monotonic() - started) * 1000,
            )
            if result.get("errors"):
                logger.warning(
                    "retrieval pathway warmer completed with errors: warmed=%s skipped=%s errors=%s",
                    result.get("warmed"),
                    result.get("skipped"),
                    len(result.get("errors") or {}),
                )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            _record_retrieval_pathway_warmer_run(
                result=None,
                error=str(exc),
                duration_ms=(time.monotonic() - started) * 1000,
            )
            logger.warning("retrieval pathway warmer run failed: %s", exc)
        await asyncio.sleep(interval)


async def _qdrant_warmup_worker() -> None:
    qdrant_warmup_state["running"] = True
    started = time.monotonic()
    warmed = 0
    error_text: str | None = None
    try:
        delay = max(0.0, QDRANT_WARMUP_DELAY_SECS)
        if delay > 0.0:
            await asyncio.sleep(delay)
        for query in list(QDRANT_WARMUP_QUERIES):
            text = str(query or "").strip()
            if not text:
                continue
            try:
                await asyncio.wait_for(
                    search_qdrant(
                        text,
                        limit=max(1, min(QDRANT_WARMUP_LIMIT, 16)),
                        project_filter=None,
                        topic_filter=None,
                        retrieval_mode=RETRIEVAL_MODE_FAST,
                    ),
                    timeout=max(1.0, QDRANT_WARMUP_TIMEOUT_SECS),
                )
                warmed += 1
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                error_text = str(exc)[:400]
                logger.debug("Qdrant warmup query failed (%s): %s", text[:80], exc)
    except asyncio.CancelledError:
        qdrant_warmup_state["running"] = False
        raise
    except Exception as exc:
        error_text = str(exc)[:400]
    finally:
        qdrant_warmup_state["running"] = False
        qdrant_warmup_state["lastRunAt"] = _utc_now()
        qdrant_warmup_state["lastDurationMs"] = round((time.monotonic() - started) * 1000, 2)
        qdrant_warmup_state["runs"] = int(qdrant_warmup_state.get("runs", 0) or 0) + 1
        qdrant_warmup_state["lastWarmed"] = warmed
        qdrant_warmup_state["lastError"] = error_text


async def _qdrant_payload_index_worker() -> None:
    qdrant_payload_index_state["running"] = True
    started = time.monotonic()
    error_text: str | None = None
    last_result: dict[str, Any] = {}
    try:
        target_collection = await _resolve_qdrant_collection_for_dimension(
            QDRANT_COLLECTION,
            max(1, FALLBACK_EMBED_DIM),
            operation="payload_index",
        )
        last_result = await _ensure_qdrant_payload_indexes(target_collection, force=True)
        if isinstance(last_result.get("failedFields"), dict) and last_result.get("failedFields"):
            error_text = (
                "failed fields: "
                + ", ".join(sorted(str(name) for name in last_result["failedFields"].keys()))
            )
    except asyncio.CancelledError:
        qdrant_payload_index_state["running"] = False
        raise
    except Exception as exc:
        error_text = str(exc)[:400]
    finally:
        qdrant_payload_index_state["running"] = False
        qdrant_payload_index_state["lastRunAt"] = _utc_now()
        qdrant_payload_index_state["lastDurationMs"] = round((time.monotonic() - started) * 1000, 2)
        qdrant_payload_index_state["runs"] = int(qdrant_payload_index_state.get("runs", 0) or 0) + 1
        qdrant_payload_index_state["lastError"] = error_text
        qdrant_payload_index_state["lastResult"] = last_result


def _should_log_http_request(status: int, duration_ms: float) -> bool:
    if status >= 400:
        return True
    if duration_ms >= max(0.0, ORCH_HTTP_REQUEST_LOG_SLOW_MS):
        return True
    sample_rate = _normalize_sample_rate(ORCH_HTTP_REQUEST_LOG_SUCCESS_SAMPLE_RATE)
    if sample_rate <= 0.0:
        return False
    if sample_rate >= 1.0:
        return True
    return random.random() < sample_rate


async def _ensure_shared_service_clients() -> None:
    global QDRANT_CLIENT, QDRANT_CLOUD_CLIENT, MINDSDB_CLIENT, LETTA_CLIENT, LANGFUSE_CLIENT, WEAVIATE_CLIENT
    cloud_needed = bool(QDRANT_CLUSTER_ENDPOINT)
    if (
        QDRANT_CLIENT is not None
        and MINDSDB_CLIENT is not None
        and LETTA_CLIENT is not None
        and (not LANGFUSE_API_KEY or LANGFUSE_CLIENT is not None)
        and (not WEAVIATE_ENABLED or WEAVIATE_CLIENT is not None)
        and (not cloud_needed or QDRANT_CLOUD_CLIENT is not None)
    ):
        return
    async with service_client_lock:
        if QDRANT_CLIENT is None:
            if AsyncQdrantClient is None or qdrant_models is None:
                raise RuntimeError("qdrant-client dependency is required (install qdrant-client)")
            QDRANT_CLIENT = AsyncQdrantClient(
                url=QDRANT_LOCAL_URL,
                prefer_grpc=QDRANT_GRPC_PREFER,
                grpc_port=QDRANT_GRPC_PORT,
                timeout=QDRANT_CLIENT_TIMEOUT_SECS,
            )
        if QDRANT_CLOUD_CLIENT is None and QDRANT_CLUSTER_ENDPOINT:
            if AsyncQdrantClient is None or qdrant_models is None:
                raise RuntimeError("qdrant-client dependency is required (install qdrant-client)")
            cloud_kwargs: dict[str, Any] = {
                "url": QDRANT_CLUSTER_ENDPOINT,
                "prefer_grpc": QDRANT_GRPC_PREFER,
                "grpc_port": QDRANT_CLOUD_GRPC_PORT,
                "timeout": QDRANT_CLIENT_TIMEOUT_SECS,
            }
            if QDRANT_API_KEY:
                cloud_kwargs["api_key"] = QDRANT_API_KEY
            QDRANT_CLOUD_CLIENT = AsyncQdrantClient(**cloud_kwargs)
        if MINDSDB_CLIENT is None:
            MINDSDB_CLIENT = httpx.AsyncClient(timeout=MINDSDB_CLIENT_TIMEOUT, limits=SHARED_SERVICE_CLIENT_LIMITS)
        if LETTA_CLIENT is None:
            LETTA_CLIENT = httpx.AsyncClient(timeout=LETTA_CLIENT_TIMEOUT, limits=SHARED_SERVICE_CLIENT_LIMITS)
        if LANGFUSE_CLIENT is None and LANGFUSE_API_KEY:
            LANGFUSE_CLIENT = httpx.AsyncClient(
                timeout=LANGFUSE_CLIENT_TIMEOUT,
                limits=SHARED_SERVICE_CLIENT_LIMITS,
            )
        if WEAVIATE_CLIENT is None and WEAVIATE_ENABLED:
            WEAVIATE_CLIENT = httpx.AsyncClient(
                timeout=WEAVIATE_CLIENT_TIMEOUT,
                limits=SHARED_SERVICE_CLIENT_LIMITS,
            )


def _qdrant_operation_targets() -> list[str]:
    cloud_available = bool(QDRANT_CLUSTER_ENDPOINT)
    if QDRANT_USE_CLOUD and cloud_available:
        targets = ["cloud"]
        if QDRANT_CLOUD_FALLBACK:
            targets.append("local")
        return targets
    targets = ["local"]
    if QDRANT_CLOUD_FALLBACK and cloud_available:
        targets.append("cloud")
    return targets


async def _get_qdrant_client(target: str = "local") -> AsyncQdrantClient:
    if QDRANT_CLIENT is None or (target == "cloud" and QDRANT_CLOUD_CLIENT is None):
        await _ensure_shared_service_clients()
    if target == "cloud":
        if QDRANT_CLOUD_CLIENT is None:
            raise RuntimeError("Qdrant cloud requested but QDRANT_CLUSTER_ENDPOINT is not configured")
        return QDRANT_CLOUD_CLIENT
    assert QDRANT_CLIENT is not None
    return QDRANT_CLIENT


async def _qdrant_call(
    operation: str,
    fn: Any,
) -> Any:
    targets = _qdrant_operation_targets()
    errors: list[str] = []
    for idx, target in enumerate(targets):
        client = await _get_qdrant_client(target)
        try:
            return await fn(client, target)
        except Exception as exc:
            errors.append(f"{target}:{exc}")
            if idx < (len(targets) - 1):
                logger.warning(
                    "Qdrant %s failed on %s backend; attempting fallback (%s)",
                    operation,
                    target,
                    str(exc)[:220],
                )
                continue
            raise
    raise RuntimeError(f"Qdrant {operation} failed ({'; '.join(errors)})")


async def _get_mindsdb_client() -> httpx.AsyncClient:
    if MINDSDB_CLIENT is None:
        await _ensure_shared_service_clients()
    assert MINDSDB_CLIENT is not None
    return MINDSDB_CLIENT


async def _get_letta_client() -> httpx.AsyncClient:
    if LETTA_CLIENT is None:
        await _ensure_shared_service_clients()
    assert LETTA_CLIENT is not None
    return LETTA_CLIENT


async def _get_langfuse_client() -> httpx.AsyncClient:
    if not LANGFUSE_API_KEY:
        raise OrchestratorError("LANGFUSE_API_KEY is not configured")
    if LANGFUSE_CLIENT is None:
        await _ensure_shared_service_clients()
    assert LANGFUSE_CLIENT is not None
    return LANGFUSE_CLIENT


async def _get_weaviate_client() -> httpx.AsyncClient:
    if not WEAVIATE_ENABLED:
        raise OrchestratorError("Weaviate source is disabled")
    if WEAVIATE_CLIENT is None:
        await _ensure_shared_service_clients()
    assert WEAVIATE_CLIENT is not None
    return WEAVIATE_CLIENT


def validate_orchestrator_security_posture() -> None:
    is_production = CONTEXTLATTICE_ENV in ("production", "prod")
    if not is_production:
        return
    issues: list[str] = []
    warnings: list[str] = []
    if not ORCH_API_KEY:
        issues.append(
            "CONTEXTLATTICE_ORCHESTRATOR_API_KEY is required in production"

        )
    if ORCH_PUBLIC_STATUS:
        warnings.append("ORCH_PUBLIC_STATUS=true exposes status endpoints without auth in production")
    if ORCH_PUBLIC_DOCS:
        warnings.append("ORCH_PUBLIC_DOCS=true exposes OpenAPI/docs endpoints without auth in production")
    if ORCH_PROMETHEUS_ENABLED and ORCH_PROMETHEUS_PUBLIC:
        warnings.append(
            f"ORCH_PROMETHEUS_PUBLIC=true exposes {ORCH_PROMETHEUS_ENDPOINT} without auth in production"
        )
    for item in warnings:
        logger.warning("Security warning: %s", item)
    if issues and ORCH_SECURITY_STRICT:
        raise RuntimeError("; ".join(issues))
    for item in issues:
        logger.error("Security issue: %s", item)


def _extract_api_key(request: Request) -> str:
    header = request.headers.get("x-api-key") or request.headers.get("authorization") or ""
    if header.lower().startswith("bearer "):
        return header.split(" ", 1)[1].strip()
    key = header.strip()
    if key:
        return key
    query_key = (
        request.query_params.get("api_key")
        or request.query_params.get("x_api_key")
        or request.query_params.get("token")
        or ""
    ).strip()
    return query_key


def _is_tool_request_path(path: str | None) -> bool:
    normalized = (path or "").strip()
    return bool(normalized.startswith("/tools/") and len(normalized) > len("/tools/"))


def _tool_name_from_path(path: str | None) -> str:
    if not _is_tool_request_path(path):
        return ""
    normalized = (path or "").strip().removeprefix("/tools/")
    return normalized.split("/", 1)[0].strip().lower()


def _tool_audit_agent_id(request: Request) -> str | None:
    value = (
        request.headers.get("x-agent-id")
        or request.headers.get("x-codex-agent")
        or request.headers.get("x-client-agent")
        or request.query_params.get("agent_id")
        or ""
    ).strip()
    return value[:120] if value else None


def _tool_audit_source(request: Request) -> str | None:
    value = (
        request.headers.get("x-source")
        or request.headers.get("x-client-source")
        or request.query_params.get("source")
        or ""
    ).strip()
    return value[:120] if value else None


def _tool_audit_project(request: Request) -> str | None:
    value = (
        request.query_params.get("project")
        or request.query_params.get("projectName")
        or request.headers.get("x-project")
        or request.headers.get("x-project-name")
        or ""
    ).strip()
    return value[:200] if value else None


def _tool_audit_query_payload(request: Request) -> str | None:
    if not request.query_params:
        return None
    query_payload: dict[str, Any] = {}
    for key in sorted(request.query_params.keys())[:TOOL_INVOCATION_AUDIT_MAX_QUERY_ITEMS]:
        value = (request.query_params.get(key) or "").strip()
        if not value:
            continue
        query_payload[key] = value[:256]
    if not query_payload:
        return None
    payload = json.dumps(query_payload, sort_keys=True)
    if len(payload) > TOOL_INVOCATION_AUDIT_MAX_METADATA_CHARS:
        return payload[:TOOL_INVOCATION_AUDIT_MAX_METADATA_CHARS]
    return payload


def _tool_audit_metadata_payload(request: Request) -> str | None:
    metadata = {
        "client": request.client.host if request.client else None,
        "user_agent": (request.headers.get("user-agent") or "").strip()[:240] or None,
    }
    compact = {key: value for key, value in metadata.items() if value is not None}
    if not compact:
        return None
    payload = json.dumps(compact, sort_keys=True)
    if len(payload) > TOOL_INVOCATION_AUDIT_MAX_METADATA_CHARS:
        return payload[:TOOL_INVOCATION_AUDIT_MAX_METADATA_CHARS]
    return payload


async def _write_tool_invocation_audit(
    *,
    request: Request,
    request_id: str,
    status_code: int,
    duration_ms: float,
    error: str | None = None,
) -> None:
    global tool_invocation_audit_last_prune_monotonic
    if not TOOL_INVOCATION_AUDIT_ENABLED:
        return
    path = (request.url.path or "").strip()
    if not _is_tool_request_path(path):
        return

    timestamp = _utc_now()
    invocation_id = uuid.uuid4().hex
    tool_name = _tool_name_from_path(path) or "unknown"
    method = (request.method or "").upper().strip() or "UNKNOWN"
    project = _tool_audit_project(request)
    agent_id = _tool_audit_agent_id(request)
    source = _tool_audit_source(request)
    query_payload = _tool_audit_query_payload(request)
    metadata_payload = _tool_audit_metadata_payload(request)
    payload_sha256 = hashlib.sha256(
        f"{request_id}:{method}:{path}:{status_code}:{duration_ms:.3f}".encode("utf-8")
    ).hexdigest()
    error_payload = (error or "").strip()[:500] or None

    def _insert(conn: sqlite3.Connection):
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            INSERT INTO tool_invocations (
                invocation_id, request_id, timestamp, method, path, tool, status_code, duration_ms,
                project, agent_id, source, query, payload_sha256, error, metadata
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                invocation_id,
                request_id,
                timestamp,
                method,
                path,
                tool_name,
                int(status_code),
                round(float(duration_ms), 3),
                project,
                agent_id,
                source,
                query_payload,
                payload_sha256,
                error_payload,
                metadata_payload,
            ),
        )

    try:
        await _task_db_exec(_insert)
        tool_invocation_audit_state["writes"] = int(tool_invocation_audit_state.get("writes", 0)) + 1
        tool_invocation_audit_state["lastWriteAt"] = timestamp
        tool_invocation_audit_state["lastStatusCode"] = int(status_code)
        if int(status_code) >= 400:
            tool_invocation_audit_state["errorWrites"] = int(tool_invocation_audit_state.get("errorWrites", 0)) + 1
    except Exception as exc:
        tool_invocation_audit_state["writeFailed"] = int(tool_invocation_audit_state.get("writeFailed", 0)) + 1
        tool_invocation_audit_state["lastError"] = str(exc)[:300]
        logger.warning("Tool invocation audit write failed: %s", exc)
        return

    now = time.monotonic()
    should_prune = (now - tool_invocation_audit_last_prune_monotonic) >= TOOL_INVOCATION_AUDIT_PRUNE_INTERVAL_SECS
    if not should_prune:
        return
    async with tool_invocation_audit_lock:
        now_locked = time.monotonic()
        if (now_locked - tool_invocation_audit_last_prune_monotonic) < TOOL_INVOCATION_AUDIT_PRUNE_INTERVAL_SECS:
            return
        cutoff = (datetime.utcnow() - timedelta(days=TOOL_INVOCATION_AUDIT_RETENTION_DAYS)).isoformat() + "Z"

        def _prune(conn: sqlite3.Connection):
            conn.execute("BEGIN IMMEDIATE")
            cur = conn.execute("DELETE FROM tool_invocations WHERE timestamp < ?", (cutoff,))
            return int(cur.rowcount)

        try:
            pruned = int(await _task_db_exec(_prune))
            tool_invocation_audit_state["prunedRows"] = int(tool_invocation_audit_state.get("prunedRows", 0)) + pruned
            tool_invocation_audit_state["lastPruneAt"] = _utc_now()
            tool_invocation_audit_state["lastPruneRows"] = pruned
            tool_invocation_audit_last_prune_monotonic = now_locked
        except Exception as exc:
            tool_invocation_audit_state["lastError"] = str(exc)[:300]
            logger.warning("Tool invocation audit prune failed: %s", exc)


async def _list_tool_invocations(
    *,
    limit: int = 100,
    tool: str | None = None,
    status_min: int | None = None,
) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit), 500))
    safe_tool = (tool or "").strip().lower() or None
    safe_status_min = int(status_min) if status_min is not None else None

    def _list(conn: sqlite3.Connection):
        clauses: list[str] = []
        params: list[Any] = []
        if safe_tool:
            clauses.append("tool = ?")
            params.append(safe_tool)
        if safe_status_min is not None:
            clauses.append("status_code >= ?")
            params.append(safe_status_min)
        where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        rows = conn.execute(
            f"""
            SELECT *
            FROM tool_invocations
            {where}
            ORDER BY id DESC
            LIMIT ?
            """,
            (*params, safe_limit),
        ).fetchall()
        return [dict(row) for row in rows]

    return await _task_db_exec(_list)


def _configure_prometheus_metrics(app_instance: FastAPI) -> None:
    if not ORCH_PROMETHEUS_ENABLED:
        return
    if Instrumentator is None:
        logger.warning("prometheus-fastapi-instrumentator unavailable; metrics endpoint disabled")
        return
    try:
        Instrumentator().instrument(app_instance).expose(
            app_instance,
            endpoint=ORCH_PROMETHEUS_ENDPOINT,
            include_in_schema=False,
        )
    except Exception as exc:  # pragma: no cover - optional observability path
        logger.warning("Prometheus instrumentation setup failed: %s", exc)


_configure_prometheus_metrics(app)


PYTHON_HOT_PATH_OWNERSHIP_MODE = os.getenv("ORCH_PYTHON_HOT_PATH_OWNERSHIP_MODE", "warn").strip().lower()
if PYTHON_HOT_PATH_OWNERSHIP_MODE not in {"off", "warn", "strict"}:
    PYTHON_HOT_PATH_OWNERSHIP_MODE = "warn"
PYTHON_HOT_PATH_ASSERT_ENABLED = PYTHON_HOT_PATH_OWNERSHIP_MODE != "off"
PYTHON_HOT_PATH_PREFIXES: tuple[str, ...] = (
    "/memory/search",
    "/memory/context-pack",
    "/memory/write",
    "/memory/write/batch",
    "/v1/memory/put",
    "/v1/memory/batch-put",
    "/v1/retrieval/query",
    "/v1/retrieval/query-with-grounding",
    "/v1/retrieval/batch-query",
)
python_hot_path_non_gateway_total = 0
python_hot_path_non_gateway_by_path: dict[str, int] = {}
python_hot_path_last_non_gateway_at: str | None = None
python_hot_path_ownership_lock = asyncio.Lock()


def _is_python_hot_path(path: str) -> bool:
    normalized = "/" + str(path or "").strip().lstrip("/")
    for prefix in PYTHON_HOT_PATH_PREFIXES:
        if normalized == prefix or normalized.startswith(prefix + "/"):
            return True
    return False


def _is_gateway_origin(request: Request) -> bool:
    marker = request.headers.get("x-contextlattice-gateway", "").strip().lower()
    return marker == "gateway-go"


async def _record_python_hot_path_non_gateway(path: str) -> None:
    global python_hot_path_non_gateway_total, python_hot_path_last_non_gateway_at
    normalized = "/" + str(path or "").strip().lstrip("/")
    async with python_hot_path_ownership_lock:
        python_hot_path_non_gateway_total += 1
        python_hot_path_non_gateway_by_path[normalized] = int(
            python_hot_path_non_gateway_by_path.get(normalized, 0)
        ) + 1
        python_hot_path_last_non_gateway_at = _utc_now()


def _python_hot_path_ownership_payload() -> dict[str, Any]:
    total = int(python_hot_path_non_gateway_total)
    status = "clean" if total == 0 else "non_gateway_hot_path_traffic_detected"
    return {
        "mode": PYTHON_HOT_PATH_OWNERSHIP_MODE,
        "ok": total == 0,
        "status": status,
        "nonGatewayRequests": total,
        "byPath": dict(python_hot_path_non_gateway_by_path),
        "lastNonGatewayAt": python_hot_path_last_non_gateway_at,
    }


@app.middleware("http")
async def request_context_middleware(request: Request, call_next):
    request_id = request.headers.get("x-request-id") or str(uuid.uuid4())
    request.state.request_id = request_id
    is_tool_request = _is_tool_request_path(request.url.path)
    public_prefixes = ["/health", "/pilot"]
    if MESSAGING_INTEGRATIONS_ENABLED and MESSAGING_WEBHOOK_PUBLIC:
        public_prefixes.extend(
            [
                "/integrations/telegram/webhook",
                "/integrations/slack/events",
            ]
        )
    if ORCH_PUBLIC_STATUS:
        public_prefixes.extend(["/status", "/status/ui"])
    if ORCH_PUBLIC_DOCS:
        public_prefixes.extend(["/openapi", "/docs", "/redoc"])
    if ORCH_PROMETHEUS_ENABLED and ORCH_PROMETHEUS_PUBLIC:
        public_prefixes.append(ORCH_PROMETHEUS_ENDPOINT)
    public_prefixes_tuple = tuple(public_prefixes)
    if ORCH_API_KEY and not request.url.path.startswith(public_prefixes_tuple):
        if _extract_api_key(request) != ORCH_API_KEY:
            if is_tool_request:
                await _write_tool_invocation_audit(
                    request=request,
                    request_id=request_id,
                    status_code=401,
                    duration_ms=0.0,
                    error="unauthorized",
                )
            return JSONResponse(
                status_code=401,
                content={"ok": False, "error": "Invalid API key"},
                headers={"x-request-id": request_id},
            )
    if PYTHON_HOT_PATH_ASSERT_ENABLED and _is_python_hot_path(request.url.path) and not _is_gateway_origin(request):
        await _record_python_hot_path_non_gateway(request.url.path)
        logger.warning(
            "python hot-path non-gateway request detected path=%s mode=%s",
            request.url.path,
            PYTHON_HOT_PATH_OWNERSHIP_MODE,
        )
        if PYTHON_HOT_PATH_OWNERSHIP_MODE == "strict":
            return JSONResponse(
                status_code=503,
                content={
                    "ok": False,
                    "error": "python_hot_path_non_gateway_blocked",
                    "path": request.url.path,
                },
                headers={"x-request-id": request_id},
            )
    start = time.monotonic()
    response = None
    try:
        response = await call_next(request)
    except Exception as exc:
        duration_ms = (time.monotonic() - start) * 1000
        if is_tool_request:
            await _write_tool_invocation_audit(
                request=request,
                request_id=request_id,
                status_code=500,
                duration_ms=duration_ms,
                error=str(exc),
            )
        raise
    assert response is not None
    response.headers["x-request-id"] = request_id
    duration_ms = (time.monotonic() - start) * 1000
    if is_tool_request:
        await _write_tool_invocation_audit(
            request=request,
            request_id=request_id,
            status_code=response.status_code,
            duration_ms=duration_ms,
        )
    if _should_log_http_request(response.status_code, duration_ms):
        _json_log(
            "http.request",
            {
                "request_id": request_id,
                "method": request.method,
                "path": request.url.path,
                "status": response.status_code,
                "duration_ms": round(duration_ms, 2),
                "client": request.client.host if request.client else None,
            },
        )
    return response


