@app.on_event("startup")
async def start_background_tasks() -> None:
    global mindsdb_queue_task, memory_write_queue_tasks, mindsdb_write_queue_tasks
    global memory_bank_queue_tasks, letta_write_queue_tasks, outbox_gc_task, hot_memory_rollup_task
    global topic_rollup_task
    global sink_retention_task, storage_governance_task, retrieval_pathway_warmer_task, recall_monitor_task
    global letta_auto_prune_task
    global qdrant_warmup_task, qdrant_payload_index_task
    if MONGO_RAW_ENABLED:
        await init_mongo_client()
    if RECALL_DEEP_ASYNC_PERSIST_ENABLED:
        restored = await _restore_recall_deep_async_jobs_from_store()
        loaded = int(restored.get("loaded", 0) or 0)
        resumed = int(restored.get("resumed", 0) or 0)
        if loaded > 0 or resumed > 0:
            logger.warning(
                "Deep async restore loaded=%s resumed=%s",
                loaded,
                resumed,
            )
    if _use_mongo_outbox():
        await init_fanout_outbox_mongo_client()
    recovered = await recover_stale_running_jobs()
    if recovered:
        logger.warning("Recovered %d stale fanout jobs that were left in running state", recovered)
    if not MINDSDB_FANOUT_ENABLED:
        settled = await settle_disabled_fanout_target_backlog(
            FANOUT_TARGET_MINDSDB,
            "mindsdb fanout disabled by ORCH_MINDSDB_FANOUT_ENABLED",
        )
        if settled > 0:
            _json_log(
                "memory.write.fanout_target_settled",
                {
                    "target": FANOUT_TARGET_MINDSDB,
                    "count": settled,
                    "reason": "mindsdb fanout disabled",
                },
            )
    if not WEAVIATE_FANOUT_ENABLED:
        settled = await settle_disabled_fanout_target_backlog(
            FANOUT_TARGET_WEAVIATE,
            "weaviate fanout disabled by ORCH_WEAVIATE_FANOUT_ENABLED",
        )
        if settled > 0:
            _json_log(
                "memory.write.fanout_target_settled",
                {
                    "target": FANOUT_TARGET_WEAVIATE,
                    "count": settled,
                    "reason": "weaviate fanout disabled",
                },
            )
    if MINDSDB_AUTOSYNC and mindsdb_queue_task is None:
        mindsdb_queue_task = asyncio.create_task(_mindsdb_queue_worker())
    if MINDSDB_AUTOSYNC and MINDSDB_AUTOSYNC_BOOTSTRAP:
        asyncio.create_task(_mindsdb_bootstrap())
    if not memory_bank_queue_tasks:
        worker_count = max(1, MEMORY_BANK_WORKERS)
        for idx in range(worker_count):
            memory_bank_queue_tasks.append(asyncio.create_task(_memory_bank_worker(idx)))
    if not memory_write_queue_tasks:
        worker_count = max(1, MEMORY_WRITE_WORKERS)
        for idx in range(worker_count):
            memory_write_queue_tasks.append(
                asyncio.create_task(_memory_write_worker(idx, exclude_target=FANOUT_TARGET_LETTA))
            )
    if not mindsdb_write_queue_tasks:
        worker_count = max(0, MINDSDB_FANOUT_WORKERS)
        for idx in range(worker_count):
            mindsdb_write_queue_tasks.append(
                asyncio.create_task(
                    _memory_write_worker(
                        2000 + idx,
                        target=FANOUT_TARGET_MINDSDB,
                    )
                )
            )
    if not letta_write_queue_tasks:
        worker_count = max(0, LETTA_FANOUT_WORKERS)
        for idx in range(worker_count):
            letta_write_queue_tasks.append(
                asyncio.create_task(
                    _memory_write_worker(
                        1000 + idx,
                        target=FANOUT_TARGET_LETTA,
                    )
                )
            )
    if FANOUT_OUTBOX_GC_ENABLED and outbox_gc_task is None:
        outbox_gc_task = asyncio.create_task(_fanout_outbox_gc_worker())
    if LETTA_AUTO_PRUNE_ENABLED and letta_auto_prune_task is None:
        letta_auto_prune_task = asyncio.create_task(_letta_auto_prune_worker())
    if SINK_RETENTION_ENABLED and sink_retention_task is None:
        sink_retention_task = asyncio.create_task(_sink_retention_worker())
    if STORAGE_GOVERNANCE_ENABLED and storage_governance_task is None:
        storage_governance_task = asyncio.create_task(_storage_governance_worker())
        if STORAGE_GOVERNANCE_RUN_ON_STARTUP:
            asyncio.create_task(run_storage_governance_once(force=True))
    if RETRIEVAL_PATHWAY_WARMER_ENABLED and retrieval_pathway_warmer_task is None:
        retrieval_pathway_warmer_task = asyncio.create_task(_retrieval_pathway_warmer_worker())
    if RECALL_MONITOR_ENABLED and recall_monitor_task is None:
        recall_monitor_task = asyncio.create_task(_recall_monitor_worker())
    if QDRANT_WARMUP_ENABLED and qdrant_warmup_task is None:
        qdrant_warmup_task = asyncio.create_task(_qdrant_warmup_worker())
    if (
        QDRANT_PAYLOAD_INDEX_HARDEN_ENABLED
        and QDRANT_PAYLOAD_INDEX_HARDEN_ON_STARTUP
        and qdrant_payload_index_task is None
    ):
        qdrant_payload_index_task = asyncio.create_task(_qdrant_payload_index_worker())
    if HOT_MEMORY_ROLLUP_ENABLED and hot_memory_rollup_task is None:
        hot_memory_rollup_task = asyncio.create_task(_hot_memory_rollup_worker())
    if TOPIC_ROLLUP_ENABLED and topic_rollup_task is None:
        topic_rollup_task = asyncio.create_task(_topic_rollup_worker())
        asyncio.create_task(rebuild_topic_rollups_once())


@app.on_event("startup")
async def init_mcp_client() -> None:
    global MCP_CLIENT, QDRANT_COLLECTION
    if MCP_CLIENT is None:
        MCP_CLIENT = httpx.AsyncClient(timeout=MCP_CLIENT_TIMEOUT, limits=MCP_CLIENT_LIMITS)
    await _ensure_shared_service_clients()
    try:
        resolved_collection = await _resolve_qdrant_collection_for_dimension(
            QDRANT_COLLECTION,
            max(1, FALLBACK_EMBED_DIM),
            operation="startup",
        )
        if resolved_collection != QDRANT_COLLECTION:
            logger.warning(
                "Qdrant default collection rerouted at startup: base=%s resolved=%s dim=%s policy=%s",
                QDRANT_COLLECTION,
                resolved_collection,
                FALLBACK_EMBED_DIM,
                QDRANT_DIMENSION_POLICY,
            )
            QDRANT_COLLECTION = resolved_collection
    except Exception as exc:
        logger.warning(
            "Qdrant startup dimension preflight failed: collection=%s dim=%s policy=%s error=%s",
            QDRANT_COLLECTION,
            FALLBACK_EMBED_DIM,
            QDRANT_DIMENSION_POLICY,
            str(exc)[:300],
        )
    if PGVECTOR_ENABLED:
        if await ensure_pgvector_schema():
            logger.info(
                "Postgres pgvector lane ready (table=%s vectorscale=%s)",
                PGVECTOR_TABLE,
                pgvector_vectorscale_available,
            )
        else:
            logger.warning(
                "Postgres pgvector lane unavailable (%s)",
                pgvector_last_error or "not configured",
            )
    logger.info(
        "Qdrant backend=%s grpc_prefer=%s cloud_configured=%s fallback=%s",
        _qdrant_operation_targets()[0],
        QDRANT_GRPC_PREFER,
        bool(QDRANT_CLUSTER_ENDPOINT),
        QDRANT_CLOUD_FALLBACK,
    )


@app.on_event("shutdown")
async def close_mcp_client() -> None:
    global MCP_CLIENT, MCP_SESSION_ID, MONGO_CLIENT, FANOUT_OUTBOX_MONGO_CLIENT, outbox_gc_task, hot_memory_rollup_task
    global mongo_client_retry_after_monotonic
    global topic_rollup_task
    global sink_retention_task, storage_governance_task, retrieval_pathway_warmer_task, recall_monitor_task
    global task_scheduler_task, agent_task_worker_tasks
    global letta_auto_prune_task
    global qdrant_warmup_task, qdrant_payload_index_task
    global QDRANT_CLIENT, QDRANT_CLOUD_CLIENT, MINDSDB_CLIENT, LETTA_CLIENT, LANGFUSE_CLIENT, WEAVIATE_CLIENT
    global PGVECTOR_POOL, pgvector_schema_ready, pgvector_vectorscale_available, pgvector_last_error
    if task_scheduler_task is not None:
        task_scheduler_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await task_scheduler_task
        task_scheduler_task = None
    if agent_task_worker_tasks:
        for worker_task in list(agent_task_worker_tasks):
            worker_task.cancel()
        for worker_task in list(agent_task_worker_tasks):
            with contextlib.suppress(asyncio.CancelledError):
                await worker_task
        agent_task_worker_tasks.clear()
    task_runtime_health["workersRunning"] = 0
    task_runtime_health["schedulerRunning"] = False
    task_runtime_health["lastSchedulerTickAt"] = _task_iso_now()
    if hot_memory_rollup_task is not None:
        hot_memory_rollup_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await hot_memory_rollup_task
        hot_memory_rollup_task = None
    if topic_rollup_task is not None:
        topic_rollup_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await topic_rollup_task
        topic_rollup_task = None
    if HOT_MEMORY_ROLLUP_ENABLED:
        with contextlib.suppress(Exception):
            await flush_hot_memory_rollups(force=True)
    if outbox_gc_task is not None:
        outbox_gc_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await outbox_gc_task
        outbox_gc_task = None
    if letta_auto_prune_task is not None:
        letta_auto_prune_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await letta_auto_prune_task
        letta_auto_prune_task = None
    if sink_retention_task is not None:
        sink_retention_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await sink_retention_task
        sink_retention_task = None
    if storage_governance_task is not None:
        storage_governance_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await storage_governance_task
        storage_governance_task = None
    if retrieval_pathway_warmer_task is not None:
        retrieval_pathway_warmer_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await retrieval_pathway_warmer_task
        retrieval_pathway_warmer_task = None
    if recall_monitor_task is not None:
        recall_monitor_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await recall_monitor_task
        recall_monitor_task = None
    if qdrant_warmup_task is not None:
        qdrant_warmup_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await qdrant_warmup_task
        qdrant_warmup_task = None
    if qdrant_payload_index_task is not None:
        qdrant_payload_index_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await qdrant_payload_index_task
        qdrant_payload_index_task = None
    async with recall_deep_async_subscribers_lock:
        recall_deep_async_subscribers.clear()
    if MCP_CLIENT is not None:
        await MCP_CLIENT.aclose()
        MCP_CLIENT = None
    if QDRANT_CLIENT is not None:
        close_result = QDRANT_CLIENT.close()
        if asyncio.iscoroutine(close_result):
            await close_result
        QDRANT_CLIENT = None
    if QDRANT_CLOUD_CLIENT is not None:
        close_result = QDRANT_CLOUD_CLIENT.close()
        if asyncio.iscoroutine(close_result):
            await close_result
        QDRANT_CLOUD_CLIENT = None
    if MINDSDB_CLIENT is not None:
        await MINDSDB_CLIENT.aclose()
        MINDSDB_CLIENT = None
    if LETTA_CLIENT is not None:
        await LETTA_CLIENT.aclose()
        LETTA_CLIENT = None
    if LANGFUSE_CLIENT is not None:
        await LANGFUSE_CLIENT.aclose()
        LANGFUSE_CLIENT = None
    if WEAVIATE_CLIENT is not None:
        await WEAVIATE_CLIENT.aclose()
        WEAVIATE_CLIENT = None
    if PGVECTOR_POOL is not None:
        with contextlib.suppress(Exception):
            await PGVECTOR_POOL.close()
        PGVECTOR_POOL = None
    pgvector_schema_ready = False
    pgvector_vectorscale_available = False
    pgvector_last_error = None
    qdrant_collection_dim_cache.clear()
    qdrant_collection_dim_routes.clear()
    qdrant_dimension_route_state["lastRouteAt"] = None
    qdrant_dimension_route_state["lastRoute"] = {}
    qdrant_dimension_route_state["routes"] = 0
    qdrant_dimension_route_state["strictFailures"] = 0
    async with qdrant_payload_index_cache_lock:
        qdrant_payload_index_cache.clear()
    MCP_SESSION_ID = None
    if FANOUT_OUTBOX_MONGO_CLIENT is not None and FANOUT_OUTBOX_MONGO_CLIENT is not MONGO_CLIENT:
        try:
            await asyncio.to_thread(FANOUT_OUTBOX_MONGO_CLIENT.close)
        except Exception:  # pragma: no cover
            pass
        FANOUT_OUTBOX_MONGO_CLIENT = None
    if MONGO_CLIENT is not None:
        try:
            await asyncio.to_thread(MONGO_CLIENT.close)
        except Exception:  # pragma: no cover
            pass
