async def settle_disabled_fanout_target_backlog(target: str, reason: str) -> int:
    target_name = str(target or "").strip().lower()
    if target_name not in FANOUT_TARGETS:
        return 0
    now = _utc_now()
    reason_text = str(reason or "target disabled")[:2000]
    if _use_mongo_outbox():
        if not await init_fanout_outbox_mongo_client():
            return 0
        assert FANOUT_OUTBOX_MONGO_CLIENT is not None
        coll = FANOUT_OUTBOX_MONGO_CLIENT[FANOUT_OUTBOX_MONGO_DB][FANOUT_OUTBOX_MONGO_COLLECTION]

        def _settle() -> int:
            result = coll.update_many(
                {
                    "target": target_name,
                    "status": {"$in": ["pending", "retrying", "running"]},
                },
                {
                    "$set": {
                        "status": "succeeded",
                        "next_attempt_at": now,
                        "completed_at": now,
                        "updated_at": now,
                        "last_error": reason_text,
                    }
                },
            )
            return int(result.modified_count or 0)

        return await asyncio.to_thread(_settle)

    def _settle_sqlite(conn: sqlite3.Connection) -> int:
        conn.execute("BEGIN IMMEDIATE")
        cursor = conn.execute(
            """
            UPDATE fanout_outbox
            SET status = ?, next_attempt_at = ?, completed_at = ?, updated_at = ?, last_error = ?
            WHERE target = ? AND status IN ('pending', 'retrying', 'running')
            """,
            ("succeeded", now, now, now, reason_text, target_name),
        )
        changed = int(cursor.rowcount or 0)
        conn.commit()
        return changed

    return await _task_db_exec(_settle_sqlite)


async def mark_fanout_retry(job: dict[str, Any], error: str) -> str:
    if _use_mongo_outbox():
        return await _mark_fanout_retry_mongo(job, error)
    now = _utc_now()
    attempts = int(job.get("attempts") or 0)
    max_attempts = int(job.get("max_attempts") or FANOUT_MAX_ATTEMPTS)
    next_status = "retrying"
    next_attempt = now
    if attempts < max_attempts:
        delay = _backoff_seconds(attempts)
        next_attempt = datetime.utcfromtimestamp(time.time() + delay).isoformat() + "Z"
    else:
        next_status = "failed"

    def _mark(conn: sqlite3.Connection):
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            UPDATE fanout_outbox
            SET status = ?, next_attempt_at = ?, updated_at = ?, last_error = ?,
                completed_at = CASE WHEN ? = 'failed' THEN ? ELSE completed_at END
            WHERE id = ?
            """,
            (next_status, next_attempt, now, error[:2000], next_status, now, job["id"]),
        )
        conn.commit()

    await _task_db_exec(_mark)
    return next_status


def _extract_source_kind_from_outbox_payload(payload: Any) -> str:
    if isinstance(payload, dict):
        letta_context = payload.get("letta_context")
        if isinstance(letta_context, dict):
            source_kind = str(letta_context.get("source_kind") or "").strip()
            if source_kind:
                return source_kind
        return str(payload.get("source_kind") or "").strip()
    return ""


async def _prune_letta_low_value_outbox_mongo(
    *,
    statuses: list[str],
    limit: int,
    dry_run: bool,
) -> dict[str, Any]:
    if not await init_fanout_outbox_mongo_client():
        raise OrchestratorError("mongo outbox unavailable")
    assert FANOUT_OUTBOX_MONGO_CLIENT is not None

    def _prune() -> dict[str, Any]:
        assert FANOUT_OUTBOX_MONGO_CLIENT is not None
        coll = FANOUT_OUTBOX_MONGO_CLIENT[FANOUT_OUTBOX_MONGO_DB][FANOUT_OUTBOX_MONGO_COLLECTION]
        base_query = {"target": FANOUT_TARGET_LETTA, "status": {"$in": statuses}}
        before_pending = int(coll.count_documents(base_query))
        scanned = 0
        matched = 0
        deleted = 0
        matched_excluded = 0
        matched_low_value = 0
        delete_batch: list[str] = []
        cursor = coll.find(
            base_query,
            {
                "_id": 1,
                "file": 1,
                "topic_path": 1,
                "summary": 1,
                "payload": 1,
            },
        ).sort([("updated_at", 1), ("_id", 1)])
        for row in cursor:
            scanned += 1
            file_name = str(row.get("file") or "")
            topic_path = str(row.get("topic_path") or "")
            summary = str(row.get("summary") or "")
            payload = row.get("payload")
            source_kind = _extract_source_kind_from_outbox_payload(payload)
            excluded, _ = _is_letta_excluded_memory_record(file_name, topic_path)
            low_value = _is_low_value_memory_record(
                file_name,
                topic_path,
                summary,
                source_kind=source_kind,
                include_short_summary=True,
            )
            if not (excluded or low_value):
                continue
            matched += 1
            if excluded:
                matched_excluded += 1
            if low_value:
                matched_low_value += 1
            if not dry_run:
                delete_batch.append(str(row.get("_id")))
                if len(delete_batch) >= 500:
                    result = coll.delete_many({"_id": {"$in": delete_batch}})
                    deleted += int(result.deleted_count or 0)
                    delete_batch = []
            if matched >= limit:
                break
        if not dry_run and delete_batch:
            result = coll.delete_many({"_id": {"$in": delete_batch}})
            deleted += int(result.deleted_count or 0)
        after_pending = before_pending if dry_run else int(coll.count_documents(base_query))
        return {
            "backend": "mongo",
            "statuses": statuses,
            "beforePending": before_pending,
            "afterPending": after_pending,
            "scanned": scanned,
            "matched": matched,
            "deleted": deleted,
            "dryRun": dry_run,
            "limit": limit,
            "matchedExcluded": matched_excluded,
            "matchedLowValue": matched_low_value,
        }

    return await asyncio.to_thread(_prune)


def _prune_letta_low_value_outbox_sqlite(
    conn: sqlite3.Connection,
    *,
    statuses: list[str],
    limit: int,
    dry_run: bool,
) -> dict[str, Any]:
    status_placeholders = ",".join("?" for _ in statuses)
    base_where = f"target = ? AND status IN ({status_placeholders})"
    base_params: tuple[Any, ...] = (FANOUT_TARGET_LETTA, *statuses)
    before_pending = int(
        conn.execute(
            f"SELECT COUNT(*) FROM fanout_outbox WHERE {base_where}",
            base_params,
        ).fetchone()[0]
    )
    rows = conn.execute(
        f"""
        SELECT id, file, topic_path, summary, payload
        FROM fanout_outbox
        WHERE {base_where}
        ORDER BY updated_at ASC, id ASC
        """,
        base_params,
    ).fetchall()
    scanned = 0
    matched = 0
    matched_excluded = 0
    matched_low_value = 0
    delete_ids: list[int] = []
    for row in rows:
        scanned += 1
        file_name = str(row["file"] or "")
        topic_path = str(row["topic_path"] or "")
        summary = str(row["summary"] or "")
        payload_obj: Any = _decode_fanout_payload_from_storage(row["payload"] if "payload" in row.keys() else None)
        source_kind = _extract_source_kind_from_outbox_payload(payload_obj)
        excluded, _ = _is_letta_excluded_memory_record(file_name, topic_path)
        low_value = _is_low_value_memory_record(
            file_name,
            topic_path,
            summary,
            source_kind=source_kind,
            include_short_summary=True,
        )
        if not (excluded or low_value):
            continue
        matched += 1
        if excluded:
            matched_excluded += 1
        if low_value:
            matched_low_value += 1
        if not dry_run:
            delete_ids.append(int(row["id"]))
        if matched >= limit:
            break
    deleted = 0
    if not dry_run and delete_ids:
        conn.execute("BEGIN IMMEDIATE")
        id_placeholders = ",".join("?" for _ in delete_ids)
        cursor = conn.execute(
            f"DELETE FROM fanout_outbox WHERE id IN ({id_placeholders})",
            tuple(delete_ids),
        )
        deleted = int(cursor.rowcount or 0)
        conn.commit()
    after_pending = before_pending
    if not dry_run:
        after_pending = int(
            conn.execute(
                f"SELECT COUNT(*) FROM fanout_outbox WHERE {base_where}",
                base_params,
            ).fetchone()[0]
        )
    return {
        "backend": "sqlite",
        "statuses": statuses,
        "beforePending": before_pending,
        "afterPending": after_pending,
        "scanned": scanned,
        "matched": matched,
        "deleted": deleted,
        "dryRun": dry_run,
        "limit": limit,
        "matchedExcluded": matched_excluded,
        "matchedLowValue": matched_low_value,
    }


async def prune_letta_low_value_outbox(
    *,
    statuses: list[str],
    limit: int = 50000,
    dry_run: bool = True,
) -> dict[str, Any]:
    normalized_statuses: list[str] = []
    seen: set[str] = set()
    for status in statuses:
        token = str(status or "").strip().lower()
        if token not in {"pending", "retrying", "running"}:
            continue
        if token in seen:
            continue
        seen.add(token)
        normalized_statuses.append(token)
    if not normalized_statuses:
        normalized_statuses = ["pending", "retrying"]
    max_limit = max(1, min(int(limit or 1), 250000))
    if _use_mongo_outbox():
        try:
            result = await _prune_letta_low_value_outbox_mongo(
                statuses=normalized_statuses,
                limit=max_limit,
                dry_run=dry_run,
            )
            _schedule_fanout_summary_refresh()
            return result
        except Exception as exc:
            _demote_outbox_backend(str(exc))
            logger.warning("Mongo outbox prune failed; retrying with sqlite: %s", exc)

    def _prune(conn: sqlite3.Connection) -> dict[str, Any]:
        return _prune_letta_low_value_outbox_sqlite(
            conn,
            statuses=normalized_statuses,
            limit=max_limit,
            dry_run=dry_run,
        )

    result = await _task_db_exec(_prune)
    _schedule_fanout_summary_refresh()
    return result


async def _run_fanout_payload_blob_gc_once(force: bool = False) -> dict[str, Any]:
    global fanout_payload_blob_gc_last_monotonic
    if not FANOUT_OUTBOX_PAYLOAD_BLOB_ENABLED:
        return {"ok": True, "skipped": "payload_blob_disabled"}
    if not FANOUT_OUTBOX_PAYLOAD_BLOB_GC_ENABLED:
        return {"ok": True, "skipped": "blob_gc_disabled"}
    if not FANOUT_OUTBOX_PAYLOAD_BLOB_DIR.exists():
        return {"ok": True, "skipped": "blob_dir_missing", "blobDir": str(FANOUT_OUTBOX_PAYLOAD_BLOB_DIR)}
    interval = max(60.0, FANOUT_OUTBOX_PAYLOAD_BLOB_GC_MIN_INTERVAL_SECS)
    if not force:
        elapsed = max(0.0, time.monotonic() - float(fanout_payload_blob_gc_last_monotonic))
        if elapsed < interval:
            return {
                "ok": True,
                "skipped": "interval_not_elapsed",
                "intervalSecs": interval,
                "elapsedSecs": round(elapsed, 3),
            }

    max_scan = max(100, int(FANOUT_OUTBOX_PAYLOAD_BLOB_GC_MAX_SCAN))
    grace_secs = max(300.0, float(FANOUT_OUTBOX_PAYLOAD_BLOB_GC_GRACE_SECS))
    cutoff_mtime = time.time() - grace_secs

    def _collect_refs(conn: sqlite3.Connection) -> set[str]:
        refs: set[str] = set()
        row = conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='fanout_outbox' LIMIT 1"
        ).fetchone()
        if row is None:
            return refs
        rows = conn.execute(
            """
            SELECT payload
            FROM fanout_outbox
            WHERE payload LIKE '%\"_blob_ref\"%'
            ORDER BY id DESC
            LIMIT ?
            """,
            (max_scan,),
        ).fetchall()
        for row in rows:
            ref_info = _extract_fanout_payload_blob_ref(row["payload"] if "payload" in row.keys() else None)
            if ref_info is None:
                continue
            refs.add(f"{ref_info[0]}.{ref_info[1]}")
        return refs

    referenced = await _task_db_exec(_collect_refs)
    scanned = 0
    deleted = 0
    errors = 0
    for pattern in ("*.zlib", "*.zstd"):
        for blob_path in FANOUT_OUTBOX_PAYLOAD_BLOB_DIR.glob(pattern):
            scanned += 1
            key = blob_path.name
            if key in referenced:
                continue
            try:
                if blob_path.stat().st_mtime >= cutoff_mtime:
                    continue
                blob_path.unlink()
                deleted += 1
            except Exception:
                errors += 1
    fanout_payload_blob_gc_last_monotonic = time.monotonic()
    return {
        "ok": errors == 0,
        "blobDir": str(FANOUT_OUTBOX_PAYLOAD_BLOB_DIR),
        "scanned": scanned,
        "deleted": deleted,
        "errors": errors,
        "referenced": len(referenced),
        "maxScan": max_scan,
        "graceSecs": grace_secs,
    }


async def _run_mongo_raw_content_blob_gc_once(force: bool = False) -> dict[str, Any]:
    global mongo_raw_content_blob_gc_last_monotonic
    if not MONGO_RAW_CONTENT_BLOB_ENABLED:
        return {"ok": True, "skipped": "mongo_raw_blob_disabled"}
    if not MONGO_RAW_CONTENT_BLOB_GC_ENABLED:
        return {"ok": True, "skipped": "mongo_raw_blob_gc_disabled"}
    if not MONGO_RAW_CONTENT_BLOB_DIR.exists():
        return {"ok": True, "skipped": "blob_dir_missing", "blobDir": str(MONGO_RAW_CONTENT_BLOB_DIR)}
    interval = max(60.0, MONGO_RAW_CONTENT_BLOB_GC_MIN_INTERVAL_SECS)
    if not force:
        elapsed = max(0.0, time.monotonic() - float(mongo_raw_content_blob_gc_last_monotonic))
        if elapsed < interval:
            return {
                "ok": True,
                "skipped": "interval_not_elapsed",
                "intervalSecs": interval,
                "elapsedSecs": round(elapsed, 3),
            }
    if not await init_mongo_client():
        return {"ok": True, "skipped": "mongo_unavailable", "blobDir": str(MONGO_RAW_CONTENT_BLOB_DIR)}
    assert MONGO_CLIENT is not None

    max_scan = max(100, int(MONGO_RAW_CONTENT_BLOB_GC_MAX_SCAN))
    grace_secs = max(300.0, float(MONGO_RAW_CONTENT_BLOB_GC_GRACE_SECS))
    cutoff_mtime = time.time() - grace_secs

    def _collect_refs() -> set[str]:
        coll = MONGO_CLIENT[MONGO_RAW_DB][MONGO_RAW_COLLECTION]
        projection = {
            "_id": 0,
            "content_raw_blob_ref": 1,
            "content_raw_blob_codec": 1,
            "content_raw_blob": 1,
        }
        docs = list(
            coll.find(
                {
                    "$or": [
                        {"content_raw_blob_ref": {"$exists": True}},
                        {"content_raw_blob": {"$exists": True}},
                    ]
                },
                projection=projection,
            )
            .sort("updated_at", -1)
            .limit(max_scan)
        )
        refs: set[str] = set()
        for doc in docs:
            ref_info = _content_blob_ref_from_doc(doc)
            if ref_info is None:
                continue
            refs.add(f"{ref_info[0]}.{ref_info[1]}")
        return refs

    referenced = await asyncio.to_thread(_collect_refs)
    scanned = 0
    deleted = 0
    errors = 0
    for pattern in ("*.zlib", "*.zstd"):
        for blob_path in MONGO_RAW_CONTENT_BLOB_DIR.glob(pattern):
            scanned += 1
            key = blob_path.name
            if key in referenced:
                continue
            try:
                if blob_path.stat().st_mtime >= cutoff_mtime:
                    continue
                blob_path.unlink()
                deleted += 1
            except Exception:
                errors += 1
    mongo_raw_content_blob_gc_last_monotonic = time.monotonic()
    return {
        "ok": errors == 0,
        "blobDir": str(MONGO_RAW_CONTENT_BLOB_DIR),
        "scanned": scanned,
        "deleted": deleted,
        "errors": errors,
        "referenced": len(referenced),
        "maxScan": max_scan,
        "graceSecs": grace_secs,
    }


async def _run_task_db_compaction_once(force: bool = False) -> dict[str, Any]:
    global task_db_compaction_last_monotonic
    if not STORAGE_GOVERNANCE_TASK_DB_COMPACT_ENABLED:
        return {"ok": True, "skipped": "disabled"}
    if not TASK_DB_PATH.exists():
        return {"ok": True, "skipped": "task_db_missing", "taskDbPath": str(TASK_DB_PATH)}
    interval = max(60.0, STORAGE_GOVERNANCE_TASK_DB_COMPACT_MIN_INTERVAL_SECS)
    if not force:
        elapsed = max(0.0, time.monotonic() - float(task_db_compaction_last_monotonic))
        if elapsed < interval:
            return {
                "ok": True,
                "skipped": "interval_not_elapsed",
                "intervalSecs": interval,
                "elapsedSecs": round(elapsed, 3),
            }

    min_reclaim = max(4 * 1024 * 1024, int(STORAGE_GOVERNANCE_TASK_DB_COMPACT_MIN_RECLAIM_BYTES))

    def _compact(conn: sqlite3.Connection) -> dict[str, Any]:
        before_bytes = int(TASK_DB_PATH.stat().st_size) if TASK_DB_PATH.exists() else 0
        page_size = int(conn.execute("PRAGMA page_size").fetchone()[0])
        page_count = int(conn.execute("PRAGMA page_count").fetchone()[0])
        freelist_count = int(conn.execute("PRAGMA freelist_count").fetchone()[0])
        reclaimable_bytes = max(0, freelist_count * page_size)
        if not force and reclaimable_bytes < min_reclaim:
            return {
                "ok": True,
                "skipped": "reclaimable_below_threshold",
                "beforeBytes": before_bytes,
                "pageSize": page_size,
                "pageCount": page_count,
                "freelistCount": freelist_count,
                "reclaimableBytes": reclaimable_bytes,
                "minReclaimBytes": min_reclaim,
            }
        checkpoint_error = None
        try:
            conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
        except Exception as exc:
            checkpoint_error = str(exc)
        vacuum_error = None
        vacuum_ran = False
        try:
            conn.execute("VACUUM")
            vacuum_ran = True
        except Exception as exc:
            vacuum_error = str(exc)
        after_bytes = int(TASK_DB_PATH.stat().st_size) if TASK_DB_PATH.exists() else before_bytes
        after_page_count = int(conn.execute("PRAGMA page_count").fetchone()[0])
        after_freelist_count = int(conn.execute("PRAGMA freelist_count").fetchone()[0])
        after_reclaimable = max(0, after_freelist_count * page_size)
        return {
            "ok": vacuum_error is None,
            "beforeBytes": before_bytes,
            "afterBytes": after_bytes,
            "bytesReclaimed": max(0, before_bytes - after_bytes),
            "pageSize": page_size,
            "pageCountBefore": page_count,
            "pageCountAfter": after_page_count,
            "freelistBefore": freelist_count,
            "freelistAfter": after_freelist_count,
            "reclaimableBeforeBytes": reclaimable_bytes,
            "reclaimableAfterBytes": after_reclaimable,
            "vacuumRan": vacuum_ran,
            "vacuumError": vacuum_error,
            "checkpointError": checkpoint_error,
            "minReclaimBytes": min_reclaim,
        }

    started = time.monotonic()
    result = await _task_db_exec(_compact)
    task_db_compaction_last_monotonic = time.monotonic()
    task_db_compaction_state["lastRunAt"] = _utc_now()
    task_db_compaction_state["lastDurationMs"] = round((time.monotonic() - started) * 1000, 2)
    task_db_compaction_state["lastSkipped"] = result.get("skipped")
    task_db_compaction_state["lastError"] = result.get("vacuumError") or None
    task_db_compaction_state["lastResult"] = result
    task_db_compaction_state["runs"] = int(task_db_compaction_state.get("runs") or 0) + 1
    return result


def _outbox_gc_cutoff_iso(hours: int) -> str:
    cutoff = datetime.now(timezone.utc) - timedelta(hours=max(0, int(hours)))
    return cutoff.isoformat().replace("+00:00", "Z")


def _should_run_outbox_gc_vacuum() -> bool:
    if not FANOUT_OUTBOX_GC_VACUUM:
        return False
    interval = max(0.0, FANOUT_OUTBOX_GC_VACUUM_MIN_INTERVAL_SECS)
    if interval <= 0:
        return True
    elapsed = max(0.0, time.monotonic() - float(outbox_gc_last_vacuum_monotonic))
    return elapsed >= interval


def _fanout_outbox_gc_sqlite(
    conn: sqlite3.Connection,
    *,
    succeeded_retention_hours: int,
    failed_retention_hours: int,
    stale_pending_hours: int,
    stale_targets: list[str],
    run_vacuum: bool,
    vacuum_min_deleted: int,
) -> dict[str, Any]:
    before_total = int(conn.execute("SELECT COUNT(*) FROM fanout_outbox").fetchone()[0])
    succeeded_cutoff = _outbox_gc_cutoff_iso(succeeded_retention_hours)
    failed_cutoff = _outbox_gc_cutoff_iso(failed_retention_hours)
    stale_cutoff = _outbox_gc_cutoff_iso(stale_pending_hours)
    conn.execute("BEGIN IMMEDIATE")
    succeeded_deleted = int(
        (
            conn.execute(
                "DELETE FROM fanout_outbox WHERE status = 'succeeded' AND COALESCE(completed_at, updated_at, created_at) < ?",
                (succeeded_cutoff,),
            ).rowcount
        )
        or 0
    )
    failed_deleted = int(
        (
            conn.execute(
                "DELETE FROM fanout_outbox WHERE status = 'failed' AND COALESCE(completed_at, updated_at, created_at) < ?",
                (failed_cutoff,),
            ).rowcount
        )
        or 0
    )
    stale_deleted = 0
    if stale_targets:
        status_values = ("pending", "retrying", "running")
        target_placeholders = ",".join("?" for _ in stale_targets)
        status_placeholders = ",".join("?" for _ in status_values)
        stale_query = (
            "DELETE FROM fanout_outbox WHERE "
            f"target IN ({target_placeholders}) "
            f"AND status IN ({status_placeholders}) "
            "AND COALESCE(last_attempt_at, updated_at, created_at) < ?"
        )
        stale_params = tuple(stale_targets) + status_values + (stale_cutoff,)
        stale_deleted = int((conn.execute(stale_query, stale_params).rowcount or 0))
    deleted_total = succeeded_deleted + failed_deleted + stale_deleted
    conn.commit()

    vacuum_ran = False
    vacuum_error = ""
    if run_vacuum and deleted_total >= max(0, int(vacuum_min_deleted)):
        try:
            conn.execute("VACUUM")
            vacuum_ran = True
        except Exception as exc:
            vacuum_error = str(exc)

    after_total = int(conn.execute("SELECT COUNT(*) FROM fanout_outbox").fetchone()[0])
    return {
        "backend": "sqlite",
        "before_total": before_total,
        "after_total": after_total,
        "deleted_total": deleted_total,
        "deleted": {
            "succeeded": succeeded_deleted,
            "failed": failed_deleted,
            "stale_pending_targets": stale_deleted,
        },
        "retention_hours": {
            "succeeded": int(succeeded_retention_hours),
            "failed": int(failed_retention_hours),
            "stale_pending": int(stale_pending_hours),
        },
        "stale_targets": stale_targets,
        "vacuum": {
            "requested": bool(run_vacuum),
            "ran": vacuum_ran,
            "min_deleted": int(vacuum_min_deleted),
            "error": vacuum_error,
        },
    }


async def _fanout_outbox_gc_mongo(
    *,
    succeeded_retention_hours: int,
    failed_retention_hours: int,
    stale_pending_hours: int,
    stale_targets: list[str],
) -> dict[str, Any]:
    if not await init_fanout_outbox_mongo_client():
        raise OrchestratorError("mongo outbox unavailable")
    assert FANOUT_OUTBOX_MONGO_CLIENT is not None
    succeeded_cutoff = _outbox_gc_cutoff_iso(succeeded_retention_hours)
    failed_cutoff = _outbox_gc_cutoff_iso(failed_retention_hours)
    stale_cutoff = _outbox_gc_cutoff_iso(stale_pending_hours)

    def _gc() -> dict[str, Any]:
        assert FANOUT_OUTBOX_MONGO_CLIENT is not None
        coll = FANOUT_OUTBOX_MONGO_CLIENT[FANOUT_OUTBOX_MONGO_DB][FANOUT_OUTBOX_MONGO_COLLECTION]
        before_total = int(coll.count_documents({}))
        succeeded_deleted = int(
            coll.delete_many(
                {
                    "status": "succeeded",
                    "updated_at": {"$lt": succeeded_cutoff},
                }
            ).deleted_count
        )
        failed_deleted = int(
            coll.delete_many(
                {
                    "status": "failed",
                    "updated_at": {"$lt": failed_cutoff},
                }
            ).deleted_count
        )
        stale_deleted = 0
        if stale_targets:
            stale_deleted = int(
                coll.delete_many(
                    {
                        "target": {"$in": stale_targets},
                        "status": {"$in": ["pending", "retrying", "running"]},
                        "updated_at": {"$lt": stale_cutoff},
                    }
                ).deleted_count
            )
        after_total = int(coll.count_documents({}))
        deleted_total = succeeded_deleted + failed_deleted + stale_deleted
        return {
            "backend": "mongo",
            "before_total": before_total,
            "after_total": after_total,
            "deleted_total": deleted_total,
            "deleted": {
                "succeeded": succeeded_deleted,
                "failed": failed_deleted,
                "stale_pending_targets": stale_deleted,
            },
            "retention_hours": {
                "succeeded": int(succeeded_retention_hours),
                "failed": int(failed_retention_hours),
                "stale_pending": int(stale_pending_hours),
            },
            "stale_targets": stale_targets,
            "vacuum": {
                "requested": False,
                "ran": False,
                "min_deleted": 0,
                "error": "",
            },
        }

    return await asyncio.to_thread(_gc)


def _record_outbox_gc_result(
    *,
    result: dict[str, Any] | None,
    error: str | None,
    duration_ms: float,
) -> None:
    gc_state = outbox_health.setdefault("gc", {})
    gc_state["lastRunAt"] = _utc_now()
    gc_state["lastDurationMs"] = round(duration_ms, 2)
    gc_state["runs"] = int(gc_state.get("runs", 0) or 0) + 1
    if error:
        gc_state["lastError"] = error[:400]
        return
    gc_state["lastError"] = None
    gc_state["lastDeleted"] = int((result or {}).get("deleted_total") or 0)
    vacuum = (result or {}).get("vacuum")
    if isinstance(vacuum, dict) and vacuum.get("ran"):
        gc_state["vacuumedAt"] = gc_state["lastRunAt"]


async def run_fanout_outbox_gc_once(
    *,
    policy: dict[str, Any] | None = None,
) -> dict[str, Any]:
    global outbox_gc_last_vacuum_monotonic
    policy_payload = policy if isinstance(policy, dict) else {}
    stale_targets_raw = policy_payload.get("staleTargets")
    stale_targets = (
        [str(item).strip() for item in stale_targets_raw if str(item).strip()]
        if isinstance(stale_targets_raw, list)
        else list(FANOUT_OUTBOX_STALE_TARGETS)
    )
    succeeded_retention_hours = max(
        1,
        _safe_int(
            policy_payload.get("succeededRetentionHours", FANOUT_OUTBOX_SUCCEEDED_RETENTION_HOURS),
            FANOUT_OUTBOX_SUCCEEDED_RETENTION_HOURS,
        ),
    )
    failed_retention_hours = max(
        1,
        _safe_int(
            policy_payload.get("failedRetentionHours", FANOUT_OUTBOX_FAILED_RETENTION_HOURS),
            FANOUT_OUTBOX_FAILED_RETENTION_HOURS,
        ),
    )
    stale_pending_hours = max(
        1,
        _safe_int(
            policy_payload.get("stalePendingHours", FANOUT_OUTBOX_STALE_PENDING_HOURS),
            FANOUT_OUTBOX_STALE_PENDING_HOURS,
        ),
    )
    vacuum_min_deleted = max(
        1,
        _safe_int(
            policy_payload.get("vacuumMinDeleted", FANOUT_OUTBOX_GC_VACUUM_MIN_DELETED),
            FANOUT_OUTBOX_GC_VACUUM_MIN_DELETED,
        ),
    )
    run_started = time.monotonic()
    run_vacuum = _should_run_outbox_gc_vacuum()
    try:
        if _use_mongo_outbox():
            try:
                result = await asyncio.wait_for(
                    _fanout_outbox_gc_mongo(
                        succeeded_retention_hours=succeeded_retention_hours,
                        failed_retention_hours=failed_retention_hours,
                        stale_pending_hours=stale_pending_hours,
                        stale_targets=stale_targets,
                    ),
                    timeout=max(1.0, FANOUT_OUTBOX_GC_TIMEOUT_SECS),
                )
                result["policy"] = policy_payload
                _record_outbox_gc_result(
                    result=result,
                    error=None,
                    duration_ms=(time.monotonic() - run_started) * 1000,
                )
                return result
            except Exception as exc:
                err_text = str(exc).strip() or exc.__class__.__name__
                _demote_outbox_backend(err_text)
                logger.warning("Mongo outbox GC failed; retrying with sqlite: %s", err_text)

        def _gc(conn: sqlite3.Connection) -> dict[str, Any]:
            return _fanout_outbox_gc_sqlite(
                conn,
                succeeded_retention_hours=succeeded_retention_hours,
                failed_retention_hours=failed_retention_hours,
                stale_pending_hours=stale_pending_hours,
                stale_targets=stale_targets,
                run_vacuum=run_vacuum,
                vacuum_min_deleted=vacuum_min_deleted,
            )

        result = await asyncio.wait_for(
            _task_db_exec(_gc),
            timeout=max(1.0, FANOUT_OUTBOX_GC_TIMEOUT_SECS),
        )
        result["policy"] = policy_payload
        vacuum_info = result.get("vacuum")
        if isinstance(vacuum_info, dict) and vacuum_info.get("ran"):
            outbox_gc_last_vacuum_monotonic = time.monotonic()
        _record_outbox_gc_result(
            result=result,
            error=None,
            duration_ms=(time.monotonic() - run_started) * 1000,
        )
        return result
    except Exception as exc:
        err_text = str(exc).strip() or exc.__class__.__name__
        _record_outbox_gc_result(
            result=None,
            error=err_text,
            duration_ms=(time.monotonic() - run_started) * 1000,
        )
        raise


async def _fanout_outbox_gc_worker() -> None:
    interval = max(30.0, FANOUT_OUTBOX_GC_INTERVAL_SECS)
    while True:
        try:
            result = await run_fanout_outbox_gc_once()
            logger.info(
                "fanout outbox gc: backend=%s deleted=%s before=%s after=%s",
                result.get("backend"),
                result.get("deleted_total"),
                result.get("before_total"),
                result.get("after_total"),
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # pragma: no cover - runtime resilience
            err_text = str(exc).strip() or exc.__class__.__name__
            await _promote_outbox_backend_to_mongo_if_sqlite_error(err_text)
            logger.warning("Fanout outbox GC run failed: %s", err_text)
        await asyncio.sleep(interval)


def _record_letta_auto_prune_run(
    *,
    result: dict[str, Any] | None,
    error: str | None,
    duration_ms: float,
) -> None:
    state = letta_auto_prune_state
    state["enabled"] = LETTA_AUTO_PRUNE_ENABLED
    state["intervalSecs"] = max(15.0, LETTA_AUTO_PRUNE_INTERVAL_SECS)
    state["backlogTrigger"] = max(1, LETTA_AUTO_PRUNE_BACKLOG_TRIGGER)
    state["limit"] = max(1, LETTA_AUTO_PRUNE_LIMIT)
    state["statuses"] = list(LETTA_AUTO_PRUNE_STATUSES)
    state["timeoutSecs"] = max(1.0, LETTA_AUTO_PRUNE_TIMEOUT_SECS)
    state["lastRunAt"] = _utc_now()
    state["lastDurationMs"] = round(max(0.0, duration_ms), 2)
    state["runs"] = int(state.get("runs", 0) or 0) + 1
    if error:
        state["lastError"] = error[:400]
        state["lastResult"] = result or {}
        state["lastSkippedReason"] = None
        return
    state["lastError"] = None
    payload = result or {}
    state["lastResult"] = payload
    skipped_reason = payload.get("skipped")
    state["lastSkippedReason"] = str(skipped_reason) if skipped_reason else None
    prune_payload = payload.get("prune") if isinstance(payload, dict) else {}
    deleted = 0
    if isinstance(prune_payload, dict):
        deleted = int(prune_payload.get("deleted") or 0)
    state["lastDeleted"] = deleted
    backlog_before = payload.get("backlogBefore")
    if backlog_before is None:
        backlog_before = payload.get("backlog")
    if backlog_before is not None:
        state["lastBacklogBefore"] = int(backlog_before or 0)
    backlog_after = payload.get("backlogAfter")
    if backlog_after is None and isinstance(prune_payload, dict):
        backlog_after = prune_payload.get("afterPending")
    if backlog_after is not None:
        state["lastBacklogAfter"] = int(backlog_after or 0)


async def run_letta_auto_prune_once(*, force: bool = False) -> dict[str, Any]:
    threshold = max(1, LETTA_AUTO_PRUNE_BACKLOG_TRIGGER)
    statuses = list(LETTA_AUTO_PRUNE_STATUSES) or ["pending", "retrying"]
    limit = max(1, LETTA_AUTO_PRUNE_LIMIT)
    timeout_secs = max(1.0, LETTA_AUTO_PRUNE_TIMEOUT_SECS)
    run_started = time.monotonic()
    try:
        if not LETTA_AUTO_PRUNE_ENABLED and not force:
            result = {
                "enabled": False,
                "forced": False,
                "ran": False,
                "skipped": "disabled",
                "threshold": threshold,
                "statuses": statuses,
                "limit": limit,
                "timeoutSecs": timeout_secs,
            }
            _record_letta_auto_prune_run(
                result=result,
                error=None,
                duration_ms=(time.monotonic() - run_started) * 1000,
            )
            return result

        summary = await get_fanout_summary()
        backlog = _fanout_target_outstanding_count(summary, FANOUT_TARGET_LETTA)
        if not force and backlog < threshold:
            result = {
                "enabled": LETTA_AUTO_PRUNE_ENABLED,
                "forced": False,
                "ran": False,
                "skipped": "below_threshold",
                "threshold": threshold,
                "backlog": backlog,
                "statuses": statuses,
                "limit": limit,
                "timeoutSecs": timeout_secs,
            }
            _record_letta_auto_prune_run(
                result=result,
                error=None,
                duration_ms=(time.monotonic() - run_started) * 1000,
            )
            return result

        prune_result = await asyncio.wait_for(
            prune_letta_low_value_outbox(
                statuses=statuses,
                limit=limit,
                dry_run=False,
            ),
            timeout=timeout_secs,
        )
        backlog_after: int | None = None
        with contextlib.suppress(Exception):
            refreshed = await asyncio.wait_for(
                _query_fanout_summary_uncached(),
                timeout=max(1.0, FANOUT_SUMMARY_TIMEOUT_SECS),
            )
            _set_fanout_summary_cache(refreshed)
            backlog_after = _fanout_target_outstanding_count(refreshed, FANOUT_TARGET_LETTA)
        if backlog_after is None:
            deleted = int(prune_result.get("deleted") or 0)
            backlog_after = max(0, backlog - deleted)
        result = {
            "enabled": LETTA_AUTO_PRUNE_ENABLED,
            "forced": bool(force),
            "ran": True,
            "skipped": None,
            "threshold": threshold,
            "backlogBefore": backlog,
            "backlogAfter": backlog_after,
            "statuses": statuses,
            "limit": limit,
            "timeoutSecs": timeout_secs,
            "prune": prune_result,
        }
        _record_letta_auto_prune_run(
            result=result,
            error=None,
            duration_ms=(time.monotonic() - run_started) * 1000,
        )
        return result
    except Exception as exc:
        err_text = str(exc).strip() or exc.__class__.__name__
        _record_letta_auto_prune_run(
            result=None,
            error=err_text,
            duration_ms=(time.monotonic() - run_started) * 1000,
        )
        raise


async def _letta_auto_prune_worker() -> None:
    interval = max(15.0, LETTA_AUTO_PRUNE_INTERVAL_SECS)
    while True:
        try:
            result = await run_letta_auto_prune_once(force=False)
            if result.get("ran"):
                prune_result = result.get("prune") if isinstance(result, dict) else {}
                logger.info(
                    "letta auto prune: deleted=%s before=%s after=%s threshold=%s",
                    (prune_result or {}).get("deleted"),
                    result.get("backlogBefore"),
                    result.get("backlogAfter"),
                    result.get("threshold"),
                )
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # pragma: no cover - runtime resilience
            logger.warning("Letta auto prune run failed: %s", exc)
        await asyncio.sleep(interval)


def _chunk_values(values: list[Any], chunk_size: int) -> list[list[Any]]:
    if not values:
        return []
    size = max(1, int(chunk_size))
    return [values[idx : idx + size] for idx in range(0, len(values), size)]


def _retention_cutoff_datetime(hours: float) -> datetime:
    span_hours = max(0.0, float(hours))
    return datetime.now(timezone.utc) - timedelta(hours=span_hours)


def _retention_cutoff_iso(hours: float) -> str:
    return _retention_cutoff_datetime(hours).isoformat().replace("+00:00", "Z")


async def _run_qdrant_low_value_retention_once(
    *,
    hours_override: float | None = None,
    scan_limit_override: int | None = None,
    max_deletes_override: int | None = None,
    delete_batch_override: int | None = None,
) -> dict[str, Any]:
    hours = max(
        0.0,
        float(hours_override if hours_override is not None else QDRANT_LOW_VALUE_RETENTION_HOURS),
    )
    if hours <= 0:
        return {"enabled": False, "reason": "QDRANT_LOW_VALUE_RETENTION_HOURS<=0", "scanned": 0, "deleted": 0}
    cutoff_epoch = int(time.time() - (hours * 3600.0))
    state_cutoff_epoch = int(time.time() - (max(hours, RETENTION_APPLICATION_STATE_HOURS) * 3600.0))
    max_scan = max(
        100,
        int(scan_limit_override if scan_limit_override is not None else SINK_RETENTION_SCAN_LIMIT),
    )
    max_deletes = max(
        1,
        int(max_deletes_override if max_deletes_override is not None else SINK_RETENTION_MAX_DELETES_PER_RUN),
    )
    delete_batch = max(
        1,
        int(delete_batch_override if delete_batch_override is not None else SINK_RETENTION_DELETE_BATCH),
    )
    scanned = 0
    candidates: list[Any] = []
    offset: Any = None
    while scanned < max_scan and len(candidates) < max_deletes:
        page_limit = min(256, max_scan - scanned)
        try:
            points, next_offset = await _qdrant_call(
                "retention_scroll",
                lambda client, _: client.scroll(
                    collection_name=QDRANT_COLLECTION,
                    limit=page_limit,
                    offset=offset,
                    with_payload=True,
                    with_vectors=False,
                ),
            )
        except Exception as exc:
            raise OrchestratorError(f"Qdrant retention scroll failed: {exc}") from exc
        if not points:
            break
        for point in points:
            scanned += 1
            payload_row = getattr(point, "payload", None) or {}
            file_name = str(payload_row.get("file") or "")
            topic_path = str(payload_row.get("topic_path") or "")
            summary = str(payload_row.get("summary") or "")
            if _is_retention_protected_memory_record(file_name, topic_path, summary):
                continue
            ts_raw = payload_row.get("ts")
            try:
                ts_value = int(ts_raw)
            except (TypeError, ValueError):
                continue
            if ts_value > cutoff_epoch:
                continue
            is_low_value = _is_low_value_memory_record(
                file_name,
                topic_path,
                summary,
                include_short_summary=False,
            )
            is_telemetry = _is_telemetry_memory_record(file_name, topic_path, summary)
            if RETENTION_TELEMETRY_ONLY:
                if not is_telemetry:
                    continue
            elif not (is_low_value or is_telemetry):
                continue
            is_state = _is_application_state_memory_record(file_name, topic_path, summary)
            if is_state and ts_value > state_cutoff_epoch:
                continue
            point_id = getattr(point, "id", None)
            if point_id is None:
                continue
            candidates.append(point_id)
            if len(candidates) >= max_deletes:
                break
        offset = next_offset
        if offset is None:
            break
    deleted = 0
    for id_batch in _chunk_values(candidates, delete_batch):
        if qdrant_models is None:
            raise OrchestratorError("qdrant-client dependency is required for Qdrant retention")
        try:
            await _qdrant_call(
                "retention_delete",
                lambda client, _: client.delete(
                    collection_name=QDRANT_COLLECTION,
                    points_selector=qdrant_models.PointIdsList(points=id_batch),
                    wait=True,
                ),
            )
        except Exception as exc:
            raise OrchestratorError(f"Qdrant retention delete failed: {exc}") from exc
        deleted += len(id_batch)
    return {
        "enabled": True,
        "cutoffEpoch": cutoff_epoch,
        "stateCutoffEpoch": state_cutoff_epoch,
        "scanned": scanned,
        "deleteCandidates": len(candidates),
        "deleted": deleted,
    }


async def _run_mongo_low_value_retention_once(
    *,
    hours_override: float | None = None,
    scan_limit_override: int | None = None,
    max_deletes_override: int | None = None,
) -> dict[str, Any]:
    hours = max(
        0.0,
        float(hours_override if hours_override is not None else MONGO_RAW_LOW_VALUE_RETENTION_HOURS),
    )
    if hours <= 0:
        return {"enabled": False, "reason": "MONGO_RAW_LOW_VALUE_RETENTION_HOURS<=0", "scanned": 0, "deleted": 0}
    if not await init_mongo_client():
        raise OrchestratorError("mongo raw store unavailable")
    assert MONGO_CLIENT is not None
    cutoff_iso = _retention_cutoff_iso(hours)
    state_cutoff_iso = _retention_cutoff_iso(max(hours, RETENTION_APPLICATION_STATE_HOURS))
    max_scan = max(
        100,
        int(scan_limit_override if scan_limit_override is not None else SINK_RETENTION_SCAN_LIMIT),
    )
    max_deletes = max(
        1,
        int(max_deletes_override if max_deletes_override is not None else SINK_RETENTION_MAX_DELETES_PER_RUN),
    )

    def _cleanup() -> dict[str, Any]:
        assert MONGO_CLIENT is not None
        coll = MONGO_CLIENT[MONGO_RAW_DB][MONGO_RAW_COLLECTION]
        docs = list(
            coll.find(
                {"updated_at": {"$lt": cutoff_iso}},
                projection={
                    "_id": 1,
                    "file": 1,
                    "topic_path": 1,
                    "summary": 1,
                    "source": 1,
                },
            )
            .sort("updated_at", 1)
            .limit(max_scan)
        )
        delete_ids: list[Any] = []
        for doc in docs:
            if len(delete_ids) >= max_deletes:
                break
            file_name = str(doc.get("file") or "")
            topic_path = str(doc.get("topic_path") or "")
            summary = str(doc.get("summary") or "")
            if _is_retention_protected_memory_record(file_name, topic_path, summary):
                continue
            is_low_value = _is_low_value_memory_record(
                file_name,
                topic_path,
                summary,
                source_kind=str(doc.get("source") or ""),
                include_short_summary=False,
            )
            is_telemetry = _is_telemetry_memory_record(file_name, topic_path, summary)
            if RETENTION_TELEMETRY_ONLY:
                if not is_telemetry:
                    continue
            elif not (is_low_value or is_telemetry):
                continue
            is_state = _is_application_state_memory_record(file_name, topic_path, summary)
            if not _retention_allows_delete_for_age(
                created_at_value=doc.get("updated_at"),
                source_hours=hours,
                is_application_state=is_state,
            ):
                continue
            delete_ids.append(doc.get("_id"))
        deleted = 0
        if delete_ids:
            result = coll.delete_many({"_id": {"$in": delete_ids}})
            deleted = int(result.deleted_count or 0)
        return {
            "enabled": True,
            "cutoffIso": cutoff_iso,
            "stateCutoffIso": state_cutoff_iso,
            "scanned": len(docs),
            "deleteCandidates": len(delete_ids),
            "deleted": deleted,
        }

    return await asyncio.to_thread(_cleanup)


async def _run_mindsdb_low_value_retention_once(
    *,
    hours_override: float | None = None,
    scan_limit_override: int | None = None,
    max_deletes_override: int | None = None,
) -> dict[str, Any]:
    hours = max(
        0.0,
        float(hours_override if hours_override is not None else MINDSDB_LOW_VALUE_RETENTION_HOURS),
    )
    if hours <= 0:
        return {"enabled": False, "reason": "MINDSDB_LOW_VALUE_RETENTION_HOURS<=0", "scanned": 0, "deleted": 0}
    if not MINDSDB_ENABLED or not MINDSDB_AUTOSYNC:
        return {"enabled": False, "reason": "mindsdb autosync disabled", "scanned": 0, "deleted": 0}
    await ensure_mindsdb_table()
    cutoff_iso = _retention_cutoff_iso(hours)
    state_cutoff_iso = _retention_cutoff_iso(max(hours, RETENTION_APPLICATION_STATE_HOURS))
    max_scan = max(
        100,
        int(scan_limit_override if scan_limit_override is not None else SINK_RETENTION_SCAN_LIMIT),
    )
    max_deletes = max(
        1,
        int(max_deletes_override if max_deletes_override is not None else SINK_RETENTION_MAX_DELETES_PER_RUN),
    )
    selected_rows: list[dict[str, Any]] = []
    rows: list[dict[str, Any]] = []
    deleted = 0
    db_name = mindsdb_target_db or MINDSDB_AUTOSYNC_DB
    table_name = mindsdb_target_table or MINDSDB_AUTOSYNC_TABLE
    repaired = False

    for attempt in range(2):
        db_name = mindsdb_target_db or db_name or MINDSDB_AUTOSYNC_DB
        table_name = mindsdb_target_table or table_name or MINDSDB_AUTOSYNC_TABLE
        select_query = (
            f"SELECT project, file, summary, created_at "
            f"FROM {db_name}.{table_name} "
            f"WHERE created_at < '{_escape_sql_literal(cutoff_iso)}' "
            f"ORDER BY created_at ASC LIMIT {max_scan};"
        )
        try:
            rows = _mindsdb_rows(await _mindsdb_execute(select_query))
            selected_rows = []
            for row in rows:
                if len(selected_rows) >= max_deletes:
                    break
                file_name = str(row.get("file") or "")
                topic_path = normalize_topic_path(derive_topic_path(file_name, None))
                summary = str(row.get("summary") or "")
                if _is_retention_protected_memory_record(file_name, topic_path, summary):
                    continue
                if not _is_telemetry_memory_record(file_name, topic_path, summary):
                    continue
                is_state = _is_application_state_memory_record(file_name, topic_path, summary)
                if not _retention_allows_delete_for_age(
                    created_at_value=row.get("created_at"),
                    source_hours=hours,
                    is_application_state=is_state,
                ):
                    continue
                selected_rows.append(row)
            deleted = 0
            for row in selected_rows:
                delete_query = (
                    f"DELETE FROM {db_name}.{table_name} "
                    f"WHERE project = '{_escape_sql_literal(str(row.get('project') or ''))}' "
                    f"AND file = '{_escape_sql_literal(str(row.get('file') or ''))}' "
                    f"AND summary = '{_escape_sql_literal(str(row.get('summary') or ''))}' "
                    f"AND created_at = '{_escape_sql_literal(str(row.get('created_at') or ''))}';"
                )
                await _mindsdb_execute(delete_query)
                deleted += 1
            break
        except Exception as exc:
            if (
                attempt == 0
                and _looks_like_mindsdb_table_corruption(str(exc))
                and await _switch_mindsdb_to_fallback(str(exc), current_table=table_name, current_db=db_name)
            ):
                repaired = True
                continue
            raise

    return {
        "enabled": True,
        "cutoffIso": cutoff_iso,
        "stateCutoffIso": state_cutoff_iso,
        "table": f"{db_name}.{table_name}",
        "repairedFallback": repaired,
        "scanned": len(rows),
        "deleteCandidates": len(selected_rows),
        "deleted": deleted,
    }


async def _run_letta_low_value_retention_once(
    *,
    hours_override: float | None = None,
    scan_limit_override: int | None = None,
    max_deletes_override: int | None = None,
) -> dict[str, Any]:
    hours = max(
        0.0,
        float(hours_override if hours_override is not None else LETTA_LOW_VALUE_RETENTION_HOURS),
    )
    if hours <= 0:
        return {"enabled": False, "reason": "LETTA_LOW_VALUE_RETENTION_HOURS<=0", "scanned": 0, "deleted": 0}
    if not _letta_config_enabled():
        return {"enabled": False, "reason": "letta not configured", "scanned": 0, "deleted": 0}
    headers: dict[str, str] = {}
    if LETTA_API_KEY:
        headers["Authorization"] = f"Bearer {LETTA_API_KEY}"
    cutoff_dt = _retention_cutoff_datetime(hours)
    state_cutoff_dt = _retention_application_state_cutoff_datetime(hours)
    scan_limit = max(
        100,
        int(scan_limit_override if scan_limit_override is not None else SINK_RETENTION_SCAN_LIMIT),
    )
    page_limit = max(10, min(LETTA_RETENTION_PAGE_LIMIT, 200))
    delete_cap = max(
        1,
        min(
            LETTA_RETENTION_MAX_DELETES_PER_RUN,
            int(max_deletes_override if max_deletes_override is not None else SINK_RETENTION_MAX_DELETES_PER_RUN),
        ),
    )
    agent_id = await _resolve_letta_agent_id(LETTA_AUTO_SESSION_ID, headers)
    client = await _get_letta_client()
    state_cutoff_dt = _retention_cutoff_datetime(RETENTION_APPLICATION_STATE_HOURS)
    scanned = 0
    deleted = 0
    delete_candidates = 0
    after: str | None = None
    stop_on_recent = False
    while scanned < scan_limit and deleted < delete_cap and not stop_on_recent:
        params: dict[str, Any] = {"limit": page_limit, "ascending": True}
        if after:
            params["after"] = after
        resp = await client.get(
            f"{LETTA_URL}/v1/agents/{agent_id}/archival-memory",
            params=params,
            headers=headers,
            timeout=LETTA_REQUEST_TIMEOUT_SECS,
        )
        if resp.status_code >= 400:
            raise OrchestratorError(
                f"Letta retention list failed: status={resp.status_code} body={resp.text[:240]}"
            )
        rows = resp.json() if resp.content else []
        if not isinstance(rows, list) or not rows:
            break
        for row in rows:
            if not isinstance(row, dict):
                continue
            scanned += 1
            after = str(row.get("id") or "") or after
            row_created = _parse_timestamp_to_datetime(row.get("created_at") or row.get("updated_at"))
            if row_created and row_created > cutoff_dt:
                stop_on_recent = True
                break
            text = str(row.get("text") or "")
            parsed = _parse_letta_archival_content(text)
            if _is_retention_protected_memory_record(
                parsed.get("file"),
                parsed.get("topic_path"),
                parsed.get("summary"),
            ):
                continue
            is_low_value = _is_low_value_memory_record(
                parsed.get("file"),
                parsed.get("topic_path"),
                parsed.get("summary"),
                include_short_summary=False,
            )
            is_telemetry = _is_telemetry_memory_record(
                parsed.get("file"),
                parsed.get("topic_path"),
                parsed.get("summary"),
            )
            if RETENTION_TELEMETRY_ONLY:
                if not is_telemetry:
                    continue
            elif not (is_low_value or is_telemetry):
                continue
            if _is_application_state_memory_record(
                parsed.get("file"),
                parsed.get("topic_path"),
                parsed.get("summary"),
            ):
                if row_created is None or row_created > state_cutoff_dt:
                    continue
            memory_id = str(row.get("id") or "").strip()
            if not memory_id:
                continue
            delete_candidates += 1
            delete_resp = await client.delete(
                f"{LETTA_URL}/v1/agents/{agent_id}/archival-memory/{memory_id}",
                headers=headers,
                timeout=LETTA_REQUEST_TIMEOUT_SECS,
            )
            if delete_resp.status_code in (200, 202, 204, 404):
                deleted += 1
            elif delete_resp.status_code >= 400:
                raise OrchestratorError(
                    f"Letta retention delete failed: status={delete_resp.status_code} body={delete_resp.text[:240]}"
                )
            if deleted >= delete_cap:
                break
        if len(rows) < page_limit:
            break
    return {
        "enabled": True,
        "cutoffIso": cutoff_dt.isoformat().replace("+00:00", "Z"),
        "stateCutoffIso": state_cutoff_dt.isoformat().replace("+00:00", "Z"),
        "scanned": scanned,
        "deleteCandidates": delete_candidates,
        "deleted": deleted,
    }


async def _run_qdrant_telemetry_purge_once(
    *,
    scan_limit: int,
    max_deletes: int,
    dry_run: bool,
) -> dict[str, Any]:
    if qdrant_models is None:
        raise OrchestratorError("qdrant-client dependency is required for telemetry purge")
    scan_limit = max(100, scan_limit)
    max_deletes = max(1, max_deletes)
    state_cutoff_epoch = int(time.time() - (RETENTION_APPLICATION_STATE_HOURS * 3600.0))
    scanned = 0
    candidates: list[Any] = []
    offset: Any = None
    while scanned < scan_limit and len(candidates) < max_deletes:
        page_limit = min(256, scan_limit - scanned)
        points, next_offset = await _qdrant_call(
            "telemetry_purge_scroll",
            lambda client, _: client.scroll(
                collection_name=QDRANT_COLLECTION,
                limit=page_limit,
                offset=offset,
                with_payload=True,
                with_vectors=False,
            ),
        )
        if not points:
            break
        for point in points:
            scanned += 1
            payload_row = getattr(point, "payload", None) or {}
            file_name = str(payload_row.get("file") or "")
            topic_path = str(payload_row.get("topic_path") or "")
            summary = str(payload_row.get("summary") or "")
            if _is_retention_protected_memory_record(file_name, topic_path, summary):
                continue
            if not _is_telemetry_memory_record(file_name, topic_path, summary):
                continue
            if _is_application_state_memory_record(file_name, topic_path, summary):
                ts_raw = payload_row.get("ts")
                try:
                    ts_value = int(ts_raw)
                except (TypeError, ValueError):
                    continue
                if ts_value > state_cutoff_epoch:
                    continue
            point_id = getattr(point, "id", None)
            if point_id is None:
                continue
            candidates.append(point_id)
            if len(candidates) >= max_deletes:
                break
        offset = next_offset
        if offset is None:
            break
    deleted = 0
    if not dry_run and candidates:
        for id_batch in _chunk_values(candidates, max(1, SINK_RETENTION_DELETE_BATCH)):
            await _qdrant_call(
                "telemetry_purge_delete",
                lambda client, _: client.delete(
                    collection_name=QDRANT_COLLECTION,
                    points_selector=qdrant_models.PointIdsList(points=id_batch),
                    wait=True,
                ),
            )
            deleted += len(id_batch)
    return {
        "enabled": True,
        "dryRun": bool(dry_run),
        "stateCutoffEpoch": state_cutoff_epoch,
        "scanned": scanned,
        "deleteCandidates": len(candidates),
        "deleted": deleted,
    }


async def _run_mindsdb_telemetry_purge_once(
    *,
    scan_limit: int,
    max_deletes: int,
    dry_run: bool,
) -> dict[str, Any]:
    if not MINDSDB_ENABLED or not MINDSDB_AUTOSYNC:
        return {"enabled": False, "reason": "mindsdb autosync disabled", "scanned": 0, "deleted": 0}
    await ensure_mindsdb_table()
    scan_limit = max(100, scan_limit)
    max_deletes = max(1, max_deletes)
    state_cutoff_iso = _retention_cutoff_iso(RETENTION_APPLICATION_STATE_HOURS)
    rows: list[dict[str, Any]] = []
    selected_rows: list[dict[str, Any]] = []
    deleted = 0
    db_name = mindsdb_target_db or MINDSDB_AUTOSYNC_DB
    table_name = mindsdb_target_table or MINDSDB_AUTOSYNC_TABLE
    repaired = False

    for attempt in range(2):
        db_name = mindsdb_target_db or db_name or MINDSDB_AUTOSYNC_DB
        table_name = mindsdb_target_table or table_name or MINDSDB_AUTOSYNC_TABLE
        select_query = (
            f"SELECT project, file, summary, created_at "
            f"FROM {db_name}.{table_name} "
            f"ORDER BY created_at ASC LIMIT {scan_limit};"
        )
        try:
            rows = _mindsdb_rows(await _mindsdb_execute(select_query))
            selected_rows = []
            for row in rows:
                if len(selected_rows) >= max_deletes:
                    break
                file_name = str(row.get("file") or "")
                topic_path = normalize_topic_path(derive_topic_path(file_name, None))
                summary = str(row.get("summary") or "")
                if _is_retention_protected_memory_record(file_name, topic_path, summary):
                    continue
                if not _is_telemetry_memory_record(file_name, topic_path, summary):
                    continue
                is_state = _is_application_state_memory_record(file_name, topic_path, summary)
                if is_state and not _retention_allows_delete_for_age(
                    created_at_value=row.get("created_at"),
                    source_hours=0.0,
                    is_application_state=True,
                ):
                    continue
                selected_rows.append(row)
            deleted = 0
            if not dry_run:
                for row in selected_rows:
                    delete_query = (
                        f"DELETE FROM {db_name}.{table_name} "
                        f"WHERE project = '{_escape_sql_literal(str(row.get('project') or ''))}' "
                        f"AND file = '{_escape_sql_literal(str(row.get('file') or ''))}' "
                        f"AND summary = '{_escape_sql_literal(str(row.get('summary') or ''))}' "
                        f"AND created_at = '{_escape_sql_literal(str(row.get('created_at') or ''))}';"
                    )
                    await _mindsdb_execute(delete_query)
                    deleted += 1
            break
        except Exception as exc:
            if (
                attempt == 0
                and _looks_like_mindsdb_table_corruption(str(exc))
                and await _switch_mindsdb_to_fallback(str(exc), current_table=table_name, current_db=db_name)
            ):
                repaired = True
                continue
            raise
    return {
        "enabled": True,
        "dryRun": bool(dry_run),
        "table": f"{db_name}.{table_name}",
        "stateCutoffIso": state_cutoff_iso,
        "repairedFallback": repaired,
        "scanned": len(rows),
        "deleteCandidates": len(selected_rows),
        "deleted": deleted,
    }


async def _run_letta_telemetry_purge_once(
    *,
    scan_limit: int,
    max_deletes: int,
    dry_run: bool,
) -> dict[str, Any]:
    if not _letta_config_enabled():
        return {"enabled": False, "reason": "letta not configured", "scanned": 0, "deleted": 0}
    headers: dict[str, str] = {}
    if LETTA_API_KEY:
        headers["Authorization"] = f"Bearer {LETTA_API_KEY}"
    page_limit = max(10, min(LETTA_RETENTION_PAGE_LIMIT, 200))
    scan_limit = max(100, scan_limit)
    max_deletes = max(1, min(max_deletes, LETTA_RETENTION_MAX_DELETES_PER_RUN))
    agent_id = await _resolve_letta_agent_id(LETTA_AUTO_SESSION_ID, headers)
    client = await _get_letta_client()
    scanned = 0
    deleted = 0
    delete_candidates = 0
    after: str | None = None
    while scanned < scan_limit and delete_candidates < max_deletes:
        params: dict[str, Any] = {"limit": page_limit, "ascending": True}
        if after:
            params["after"] = after
        resp = await client.get(
            f"{LETTA_URL}/v1/agents/{agent_id}/archival-memory",
            params=params,
            headers=headers,
            timeout=LETTA_REQUEST_TIMEOUT_SECS,
        )
        if resp.status_code >= 400:
            raise OrchestratorError(
                f"Letta telemetry purge list failed: status={resp.status_code} body={resp.text[:240]}"
            )
        rows = resp.json() if resp.content else []
        if not isinstance(rows, list) or not rows:
            break
        for row in rows:
            if not isinstance(row, dict):
                continue
            scanned += 1
            after = str(row.get("id") or "") or after
            parsed = _parse_letta_archival_content(str(row.get("text") or ""))
            if _is_retention_protected_memory_record(
                parsed.get("file"),
                parsed.get("topic_path"),
                parsed.get("summary"),
            ):
                continue
            if not _is_telemetry_memory_record(
                parsed.get("file"),
                parsed.get("topic_path"),
                parsed.get("summary"),
            ):
                continue
            if _is_application_state_memory_record(
                parsed.get("file"),
                parsed.get("topic_path"),
                parsed.get("summary"),
            ):
                row_created = _parse_timestamp_to_datetime(row.get("created_at") or row.get("updated_at"))
                if row_created is None or row_created > state_cutoff_dt:
                    continue
            memory_id = str(row.get("id") or "").strip()
            if not memory_id:
                continue
            delete_candidates += 1
            if dry_run:
                continue
            delete_resp = await client.delete(
                f"{LETTA_URL}/v1/agents/{agent_id}/archival-memory/{memory_id}",
                headers=headers,
                timeout=LETTA_REQUEST_TIMEOUT_SECS,
            )
            if delete_resp.status_code in (200, 202, 204, 404):
                deleted += 1
            elif delete_resp.status_code >= 400:
                raise OrchestratorError(
                    f"Letta telemetry purge delete failed: status={delete_resp.status_code} body={delete_resp.text[:240]}"
                )
            if delete_candidates >= max_deletes:
                break
        if len(rows) < page_limit:
            break
    return {
        "enabled": True,
        "dryRun": bool(dry_run),
        "stateCutoffIso": state_cutoff_dt.isoformat().replace("+00:00", "Z"),
        "scanned": scanned,
        "deleteCandidates": delete_candidates,
        "deleted": deleted,
    }


def _memory_bank_telemetry_tombstone_content(*, project: str, file_name: str, topic_path: str) -> str:
    lines = [
        "# ContextLattice Memory-Bank Cleanup",
        "",
        f"- archived_at: {_utc_now()}",
        f"- project: {project}",
        f"- file: {file_name}",
        f"- topic_path: {topic_path or DEFAULT_TOPIC_ROOT}",
        f"- reason: telemetry_low_value_cleanup",
        "",
        MEMORY_BANK_TELEMETRY_TOMBSTONE_CONTENT,
        "",
    ]
    return "\n".join(lines)


def _load_memory_bank_telemetry_cleanup_state_file() -> dict[str, set[str]]:
    path = MEMORY_BANK_TELEMETRY_CLEANUP_STATE_PATH
    try:
        if not path.exists():
            return {}
        raw = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        logger.warning("Failed to load memory-bank cleanup state: %s", exc)
        return {}
    if not isinstance(raw, dict):
        return {}
    state: dict[str, set[str]] = {}
    for project_name, files in raw.items():
        key = str(project_name or "").strip()
        if not key or not isinstance(files, list):
            continue
        normalized = {
            str(file_name or "").strip()
            for file_name in files
            if str(file_name or "").strip()
        }
        if normalized:
            state[key] = normalized
    return state


def _persist_memory_bank_telemetry_cleanup_state_file(state: dict[str, set[str]]) -> None:
    path = MEMORY_BANK_TELEMETRY_CLEANUP_STATE_PATH
    payload = {
        str(project_name): sorted(files)
        for project_name, files in state.items()
        if str(project_name or "").strip() and files
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")


async def _memory_bank_cleanup_state_get_snapshot() -> dict[str, set[str]]:
    global memory_bank_telemetry_cleanup_state_loaded
    async with memory_bank_telemetry_cleanup_state_lock:
        if not memory_bank_telemetry_cleanup_state_loaded:
            memory_bank_telemetry_cleanup_state.clear()
            memory_bank_telemetry_cleanup_state.update(_load_memory_bank_telemetry_cleanup_state_file())
            memory_bank_telemetry_cleanup_state_loaded = True
        return {project: set(files) for project, files in memory_bank_telemetry_cleanup_state.items()}


async def _memory_bank_cleanup_state_mark_processed(entries: list[tuple[str, str]]) -> None:
    global memory_bank_telemetry_cleanup_state_loaded
    if not entries:
        return
    async with memory_bank_telemetry_cleanup_state_lock:
        if not memory_bank_telemetry_cleanup_state_loaded:
            memory_bank_telemetry_cleanup_state.clear()
            memory_bank_telemetry_cleanup_state.update(_load_memory_bank_telemetry_cleanup_state_file())
            memory_bank_telemetry_cleanup_state_loaded = True
        for project_name, file_name in entries:
            project_key = str(project_name or "").strip()
            file_key = str(file_name or "").strip()
            if not project_key or not file_key:
                continue
            memory_bank_telemetry_cleanup_state.setdefault(project_key, set()).add(file_key)
        try:
            _persist_memory_bank_telemetry_cleanup_state_file(memory_bank_telemetry_cleanup_state)
        except Exception as exc:
            logger.warning("Failed to persist memory-bank cleanup state: %s", exc)


async def run_memory_bank_telemetry_cleanup(
    *,
    project: str | None = None,
    limit: int = MEMORY_BANK_TELEMETRY_CLEANUP_DEFAULT_LIMIT,
    dry_run: bool = True,
) -> dict[str, Any]:
    max_items = max(1, int(limit))
    projects = [str(project).strip()] if str(project or "").strip() else await list_projects()
    processed_state = await _memory_bank_cleanup_state_get_snapshot()
    selected: list[tuple[str, str, str]] = []
    scanned = 0
    matched = 0
    already_processed = 0
    scan_truncated = False
    for project_name in projects:
        processed_files = processed_state.get(project_name) or set()
        try:
            files = await list_files(project_name)
        except Exception as exc:
            logger.warning("memory-bank cleanup skipped %s: %s", project_name, exc)
            continue
        for file_name in files:
            scanned += 1
            topic_path = derive_topic_path(file_name, None)
            if not _looks_memory_bank_telemetry_file(file_name, topic_path):
                continue
            matched += 1
            if file_name in processed_files:
                already_processed += 1
                continue
            selected.append((project_name, file_name, topic_path))
            if len(selected) >= max_items:
                scan_truncated = True
                break
        if len(selected) >= max_items:
            break
    if dry_run:
        return {
            "ok": True,
            "dryRun": True,
            "project": str(project or "").strip() or None,
            "scanned": scanned,
            "matched": matched,
            "alreadyProcessed": already_processed,
            "selected": len(selected),
            "scanTruncated": scan_truncated,
            "sample": [
                {"project": proj, "file": file_name, "topic_path": topic}
                for proj, file_name, topic in selected[:25]
            ],
        }

    concurrency = max(1, int(MEMORY_BANK_TELEMETRY_CLEANUP_MAX_CONCURRENCY))
    semaphore = asyncio.Semaphore(concurrency)
    updated = 0
    failed = 0
    errors: list[str] = []
    processed_entries: list[tuple[str, str]] = []

    async def _rewrite(project_name: str, file_name: str, topic_path: str) -> None:
        nonlocal updated, failed
        async with semaphore:
            content = _memory_bank_telemetry_tombstone_content(
                project=project_name,
                file_name=file_name,
                topic_path=topic_path,
            )
            try:
                await call_memory_tool(
                    "memory_bank_update",
                    {
                        "projectName": project_name,
                        "fileName": file_name,
                        "content": content,
                    },
                )
                updated += 1
                processed_entries.append((project_name, file_name))
            except Exception as exc:
                failed += 1
                if len(errors) < 50:
                    errors.append(f"{project_name}/{file_name}: {exc}")

    await asyncio.gather(*[_rewrite(proj, file_name, topic) for proj, file_name, topic in selected])
    await _memory_bank_cleanup_state_mark_processed(processed_entries)
    return {
        "ok": failed == 0,
        "dryRun": False,
        "project": str(project or "").strip() or None,
        "scanned": scanned,
        "matched": matched,
        "alreadyProcessed": already_processed,
        "selected": len(selected),
        "scanTruncated": scan_truncated,
        "updated": updated,
        "failed": failed,
        "errors": errors,
    }


async def run_memory_bank_telemetry_cleanup_chunked(
    *,
    project: str | None = None,
    start_after: str | None = None,
    project_batch: int = 12,
    per_project_limit: int = 250,
    dry_run: bool = True,
) -> dict[str, Any]:
    explicit_project = str(project or "").strip()
    all_projects: list[str] = []
    if explicit_project:
        projects = [explicit_project]
    else:
        project_rows = [str(item or "").strip() for item in await list_projects() if str(item or "").strip()]
        unique_projects = sorted(set(project_rows))
        all_projects = unique_projects
        if start_after:
            marker = str(start_after).strip()
            unique_projects = [name for name in unique_projects if name > marker]
        batch_size = max(1, int(project_batch))
        projects = unique_projects[:batch_size]

    per_project_cap = max(1, int(per_project_limit))
    project_results: list[dict[str, Any]] = []
    totals = {
        "projectsProcessed": 0,
        "scanned": 0,
        "matched": 0,
        "alreadyProcessed": 0,
        "selected": 0,
        "updated": 0,
        "failed": 0,
    }
    next_start_after: str | None = None

    for project_name in projects:
        result = await run_memory_bank_telemetry_cleanup(
            project=project_name,
            limit=per_project_cap,
            dry_run=dry_run,
        )
        project_results.append(result)
        totals["projectsProcessed"] += 1
        totals["scanned"] += int(result.get("scanned", 0) or 0)
        totals["matched"] += int(result.get("matched", 0) or 0)
        totals["alreadyProcessed"] += int(result.get("alreadyProcessed", 0) or 0)
        totals["selected"] += int(result.get("selected", 0) or 0)
        totals["updated"] += int(result.get("updated", 0) or 0)
        totals["failed"] += int(result.get("failed", 0) or 0)
        next_start_after = project_name

    if explicit_project:
        next_start_after = None
    else:
        marker = next_start_after or str(start_after or "").strip()
        remaining = [name for name in all_projects if marker and name > marker]
        if not remaining:
            next_start_after = None

    return {
        "ok": totals["failed"] == 0,
        "dryRun": bool(dry_run),
        "project": explicit_project or None,
        "startAfter": str(start_after or "").strip() or None,
        "nextStartAfter": next_start_after,
        "projectBatch": max(1, int(project_batch)),
        "perProjectLimit": per_project_cap,
        "totals": totals,
        "projects": project_results,
    }


def _record_sink_retention_run(
    *,
    result: dict[str, Any] | None,
    error: str | None,
    duration_ms: float,
) -> None:
    sink_retention_state["lastRunAt"] = _utc_now()
    sink_retention_state["lastDurationMs"] = round(duration_ms, 2)
    sink_retention_state["runs"] = int(sink_retention_state.get("runs", 0) or 0) + 1
    sink_retention_state["lastResult"] = result or {}
    sink_retention_state["lastError"] = (error or "")[:400] if error else None


async def run_sink_retention_once(policy: dict[str, Any] | None = None) -> dict[str, Any]:
    started = time.monotonic()
    sinks: dict[str, Any] = {}
    errors: dict[str, str] = {}
    policy_payload = policy if isinstance(policy, dict) else {}
    retention_hours = (
        policy_payload.get("retentionHours")
        if isinstance(policy_payload.get("retentionHours"), dict)
        else {}
    )
    scan_limit_override_raw = policy_payload.get("scanLimit")
    max_deletes_override_raw = policy_payload.get("maxDeletesPerRun")
    delete_batch_override_raw = policy_payload.get("deleteBatch")
    scan_limit_override = int(scan_limit_override_raw) if isinstance(scan_limit_override_raw, (int, float)) else None
    max_deletes_override = (
        int(max_deletes_override_raw) if isinstance(max_deletes_override_raw, (int, float)) else None
    )
    delete_batch_override = (
        int(delete_batch_override_raw) if isinstance(delete_batch_override_raw, (int, float)) else None
    )
    try:
        try:
            sinks["qdrant"] = await asyncio.wait_for(
                _run_qdrant_low_value_retention_once(
                    hours_override=(
                        float(retention_hours.get("qdrant"))
                        if isinstance(retention_hours.get("qdrant"), (int, float))
                        else None
                    ),
                    scan_limit_override=scan_limit_override,
                    max_deletes_override=max_deletes_override,
                    delete_batch_override=delete_batch_override,
                ),
                timeout=max(5.0, SINK_RETENTION_TIMEOUT_SECS),
            )
        except Exception as exc:
            errors["qdrant"] = str(exc)
        try:
            sinks["mongo_raw"] = await asyncio.wait_for(
                _run_mongo_low_value_retention_once(
                    hours_override=(
                        float(retention_hours.get("mongo_raw"))
                        if isinstance(retention_hours.get("mongo_raw"), (int, float))
                        else None
                    ),
                    scan_limit_override=scan_limit_override,
                    max_deletes_override=max_deletes_override,
                ),
                timeout=max(5.0, SINK_RETENTION_TIMEOUT_SECS),
            )
        except Exception as exc:
            errors["mongo_raw"] = str(exc)
        try:
            sinks["mindsdb"] = await asyncio.wait_for(
                _run_mindsdb_low_value_retention_once(
                    hours_override=(
                        float(retention_hours.get("mindsdb"))
                        if isinstance(retention_hours.get("mindsdb"), (int, float))
                        else None
                    ),
                    scan_limit_override=scan_limit_override,
                    max_deletes_override=max_deletes_override,
                ),
                timeout=max(5.0, SINK_RETENTION_TIMEOUT_SECS),
            )
        except Exception as exc:
            errors["mindsdb"] = str(exc)
        try:
            sinks["letta"] = await asyncio.wait_for(
                _run_letta_low_value_retention_once(
                    hours_override=(
                        float(retention_hours.get("letta"))
                        if isinstance(retention_hours.get("letta"), (int, float))
                        else None
                    ),
                    scan_limit_override=scan_limit_override,
                    max_deletes_override=max_deletes_override,
                ),
                timeout=max(5.0, SINK_RETENTION_TIMEOUT_SECS),
            )
        except Exception as exc:
            errors["letta"] = str(exc)
        result = {
            "sinks": sinks,
            "errors": errors,
            "ok": not bool(errors),
            "policy": policy_payload,
        }
        _record_sink_retention_run(
            result=result,
            error=None if not errors else json.dumps(errors)[:400],
            duration_ms=(time.monotonic() - started) * 1000,
        )
        return result
    except Exception as exc:
        err_text = str(exc).strip() or exc.__class__.__name__
        _record_sink_retention_run(
            result={"sinks": sinks, "errors": errors, "ok": False},
            error=err_text,
            duration_ms=(time.monotonic() - started) * 1000,
        )
        raise


def _storage_governance_history_paths() -> dict[str, Path]:
    return {
        "memory_write_history": MEMORY_WRITE_HISTORY_PATH,
        "trading_history": TRADING_HISTORY_PATH,
        "strategy_history": STRATEGY_HISTORY_PATH,
        "signal_history": SIGNAL_HISTORY_PATH,
        "override_history": OVERRIDE_HISTORY_PATH,
        "recall_monitor": RECALL_MONITOR_PATH,
    }


def _resolve_storage_governance_disk_root() -> Path:
    if STORAGE_GOVERNANCE_DISK_ROOT_ENV:
        candidate = Path(STORAGE_GOVERNANCE_DISK_ROOT_ENV).expanduser()
    else:
        candidate = TASK_DB_PATH.parent
    if candidate.is_file():
        candidate = candidate.parent
    if candidate.exists():
        return candidate
    for parent in [candidate.parent, TASK_DB_PATH.parent, Path(__file__).resolve().parent]:
        if parent.exists():
            return parent
    return candidate


def _safe_path_total_bytes(path: Path) -> int:
    try:
        if not path.exists():
            return 0
        if path.is_file():
            return int(path.stat().st_size)
    except Exception:
        return 0
    total = 0
    try:
        for root, _, files in os.walk(path):
            for file_name in files:
                file_path = Path(root) / file_name
                with contextlib.suppress(Exception):
                    total += int(file_path.stat().st_size)
    except Exception:
        return total
    return total


def _safe_mongo_db_storage_bytes(db_name: str) -> int:
    if MongoClient is None:
        return 0
    if MONGO_CLIENT is None:
        return 0
    db_name = str(db_name or "").strip()
    if not db_name:
        return 0
    try:
        stats = MONGO_CLIENT[db_name].command("dbstats")
    except Exception:
        return 0
    storage_size = int(stats.get("storageSize") or 0)
    data_size = int(stats.get("dataSize") or 0)
    return max(storage_size, data_size, 0)


def _storage_pressure_band(*, used_ratio: float, free_bytes: int) -> str:
    if used_ratio >= STORAGE_GOVERNANCE_HIGH_USED_RATIO or free_bytes <= STORAGE_GOVERNANCE_MIN_FREE_BYTES:
        return "high"
    free_warn = int(STORAGE_GOVERNANCE_MIN_FREE_BYTES * 1.5)
    if used_ratio >= STORAGE_GOVERNANCE_WARN_USED_RATIO or free_bytes <= free_warn:
        return "warn"
    return "healthy"


def _collect_storage_governance_snapshot() -> dict[str, Any]:
    tracked_paths: dict[str, Path] = {
        "task_db": TASK_DB_PATH,
        "memory_write_history": MEMORY_WRITE_HISTORY_PATH,
        "trading_history": TRADING_HISTORY_PATH,
        "strategy_history": STRATEGY_HISTORY_PATH,
        "signal_history": SIGNAL_HISTORY_PATH,
        "override_history": OVERRIDE_HISTORY_PATH,
        "recall_monitor": RECALL_MONITOR_PATH,
        "topic_index": TOPIC_INDEX_PATH,
        "memory_bank_cleanup_state": MEMORY_BANK_TELEMETRY_CLEANUP_STATE_PATH,
        "fanout_payload_blobs": FANOUT_OUTBOX_PAYLOAD_BLOB_DIR,
        "mongo_raw_content_blobs": MONGO_RAW_CONTENT_BLOB_DIR,
        "continuity_snapshots": CONTINUITY_SNAPSHOT_DIR,
    }
    tracked_sizes = {name: _safe_path_total_bytes(path) for name, path in tracked_paths.items()}
    tracked_total_bytes = int(sum(int(size or 0) for size in tracked_sizes.values()))
    history_total_bytes = int(
        tracked_sizes.get("memory_write_history", 0)
        + tracked_sizes.get("trading_history", 0)
        + tracked_sizes.get("strategy_history", 0)
        + tracked_sizes.get("signal_history", 0)
        + tracked_sizes.get("override_history", 0)
        + tracked_sizes.get("recall_monitor", 0)
    )
    logical_mongo_dbs = {
        "raw": str(MONGO_RAW_DB or "").strip(),
        "telemetry": str(TELEMETRY_DB or "").strip(),
        "outbox": str(FANOUT_OUTBOX_MONGO_DB or "").strip(),
    }
    mongo_bytes: dict[str, int] = {}
    mongo_physical_by_db: dict[str, int] = {}
    mongo_aliases: dict[str, list[str]] = {}
    for lane, db_name in logical_mongo_dbs.items():
        if not db_name:
            mongo_bytes[lane] = 0
            continue
        if db_name not in mongo_physical_by_db:
            mongo_physical_by_db[db_name] = int(_safe_mongo_db_storage_bytes(db_name))
        size = int(mongo_physical_by_db.get(db_name) or 0)
        mongo_bytes[lane] = size
        mongo_aliases.setdefault(db_name, []).append(lane)
    mongo_total_bytes = int(sum(int(value or 0) for value in mongo_physical_by_db.values()))
    mongo_logical_total_bytes = int(sum(int(value or 0) for value in mongo_bytes.values()))
    mongo_shared_aliases = {
        db_name: lanes
        for db_name, lanes in mongo_aliases.items()
        if len(lanes) > 1
    }
    disk_root = _resolve_storage_governance_disk_root()
    usage_total = 0
    usage_used = 0
    usage_free = 0
    usage_error = None
    try:
        usage = shutil.disk_usage(disk_root)
        usage_total = int(usage.total)
        usage_used = int(usage.used)
        usage_free = int(usage.free)
    except Exception as exc:
        usage_error = str(exc)
    used_ratio = (float(usage_used) / float(usage_total)) if usage_total > 0 else 0.0
    pressure = _storage_pressure_band(used_ratio=used_ratio, free_bytes=usage_free)
    allocations: dict[str, dict[str, Any]] = {}
    denominator = max(1, tracked_total_bytes)
    for name, size in tracked_sizes.items():
        allocations[name] = {
            "bytes": int(size),
            "share": round(float(size) / float(denominator), 6),
        }
    return {
        "capturedAt": _utc_now(),
        "diskRoot": str(disk_root),
        "diskUsage": {
            "totalBytes": usage_total,
            "usedBytes": usage_used,
            "freeBytes": usage_free,
            "usedRatio": round(used_ratio, 6),
            "error": usage_error,
        },
        "trackedBytesTotal": tracked_total_bytes,
        "historyBytesTotal": history_total_bytes,
        "mongoBytesTotal": mongo_total_bytes,
        "mongoBytesLogicalTotal": mongo_logical_total_bytes,
        "tracked": {
            name: {"path": str(tracked_paths[name]), "bytes": int(tracked_sizes[name])}
            for name in sorted(tracked_paths.keys())
        },
        "remoteStores": {
            "mongo": {
                **mongo_bytes,
                "logicalTotalBytes": mongo_logical_total_bytes,
                "uniqueTotalBytes": mongo_total_bytes,
                "physicalByDb": mongo_physical_by_db,
                "sharedDbAliases": mongo_shared_aliases,
            },
        },
        "allotments": allocations,
        "pressureBand": pressure,
    }


def _storage_governance_retention_policy(snapshot: dict[str, Any]) -> dict[str, Any]:
    pressure = str(snapshot.get("pressureBand") or "healthy")
    multiplier = 1.0
    if pressure == "high":
        multiplier = STORAGE_GOVERNANCE_RETENTION_MULTIPLIER_HIGH
    elif pressure == "warn":
        multiplier = STORAGE_GOVERNANCE_RETENTION_MULTIPLIER_WARN
    scan_limit = max(100, int(round(float(SINK_RETENTION_SCAN_LIMIT) * multiplier)))
    max_deletes = max(1, int(round(float(SINK_RETENTION_MAX_DELETES_PER_RUN) * multiplier)))
    delete_batch = max(
        1,
        int(round(float(SINK_RETENTION_DELETE_BATCH) * min(multiplier, 2.0))),
    )
    qdrant_hours = (
        max(6.0, float(QDRANT_LOW_VALUE_RETENTION_HOURS) / multiplier)
        if QDRANT_LOW_VALUE_RETENTION_HOURS > 0
        else 0.0
    )
    mindsdb_hours = (
        max(6.0, float(MINDSDB_LOW_VALUE_RETENTION_HOURS) / multiplier)
        if MINDSDB_LOW_VALUE_RETENTION_HOURS > 0
        else 0.0
    )
    letta_hours = (
        max(6.0, float(LETTA_LOW_VALUE_RETENTION_HOURS) / multiplier)
        if LETTA_LOW_VALUE_RETENTION_HOURS > 0
        else 0.0
    )
    mongo_hours = (
        max(1.0, float(MONGO_RAW_LOW_VALUE_RETENTION_HOURS) / multiplier)
        if MONGO_RAW_LOW_VALUE_RETENTION_HOURS > 0
        else 0.0
    )
    outbox_policy = {
        "succeededRetentionHours": max(
            1,
            int(math.ceil(float(FANOUT_OUTBOX_SUCCEEDED_RETENTION_HOURS) / multiplier)),
        ),
        "failedRetentionHours": max(
            1,
            int(math.ceil(float(FANOUT_OUTBOX_FAILED_RETENTION_HOURS) / multiplier)),
        ),
        "stalePendingHours": max(
            1,
            int(math.ceil(float(FANOUT_OUTBOX_STALE_PENDING_HOURS) / multiplier)),
        ),
        "staleTargets": list(FANOUT_OUTBOX_STALE_TARGETS),
        "vacuumMinDeleted": max(
            1,
            int(math.ceil(float(FANOUT_OUTBOX_GC_VACUUM_MIN_DELETED) / max(1.0, multiplier))),
        ),
    }
    return {
        "pressureBand": pressure,
        "multiplier": round(multiplier, 3),
        "sinkRetention": {
            "scanLimit": scan_limit,
            "maxDeletesPerRun": max_deletes,
            "deleteBatch": delete_batch,
            "retentionHours": {
                "qdrant": round(qdrant_hours, 3),
                "mongo_raw": round(mongo_hours, 3),
                "mindsdb": round(mindsdb_hours, 3),
                "letta": round(letta_hours, 3),
            },
        },
        "outboxGc": outbox_policy,
        "taskDbCompaction": {
            "enabled": STORAGE_GOVERNANCE_TASK_DB_COMPACT_ENABLED,
            "minReclaimBytes": STORAGE_GOVERNANCE_TASK_DB_COMPACT_MIN_RECLAIM_BYTES,
            "minIntervalSecs": STORAGE_GOVERNANCE_TASK_DB_COMPACT_MIN_INTERVAL_SECS,
        },
        "fanoutPayloadBlobGc": {
            "enabled": FANOUT_OUTBOX_PAYLOAD_BLOB_GC_ENABLED and FANOUT_OUTBOX_PAYLOAD_BLOB_ENABLED,
            "minIntervalSecs": FANOUT_OUTBOX_PAYLOAD_BLOB_GC_MIN_INTERVAL_SECS,
            "graceSecs": FANOUT_OUTBOX_PAYLOAD_BLOB_GC_GRACE_SECS,
            "maxScan": FANOUT_OUTBOX_PAYLOAD_BLOB_GC_MAX_SCAN,
        },
        "mongoRawContentBlobGc": {
            "enabled": MONGO_RAW_CONTENT_BLOB_GC_ENABLED and MONGO_RAW_CONTENT_BLOB_ENABLED,
            "minIntervalSecs": MONGO_RAW_CONTENT_BLOB_GC_MIN_INTERVAL_SECS,
            "graceSecs": MONGO_RAW_CONTENT_BLOB_GC_GRACE_SECS,
            "maxScan": MONGO_RAW_CONTENT_BLOB_GC_MAX_SCAN,
        },
    }


def _sqlite_fanout_table_exists(conn: sqlite3.Connection) -> bool:
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='fanout_outbox' LIMIT 1"
    ).fetchone()
    return row is not None


async def _prune_legacy_sqlite_outbox_once(*, max_rows: int, max_bytes: int) -> dict[str, Any]:
    max_rows = max(100, int(max_rows))
    max_bytes = max(128 * 1024 * 1024, int(max_bytes))
    if not STORAGE_GOVERNANCE_SQLITE_LEGACY_PRUNE_ENABLED:
        return {"ok": True, "skipped": "disabled"}
    if fanout_outbox_backend_active != "mongo":
        return {"ok": True, "skipped": "active_backend_not_mongo", "activeBackend": fanout_outbox_backend_active}

    def _prune(conn: sqlite3.Connection) -> dict[str, Any]:
        before_bytes = int(TASK_DB_PATH.stat().st_size) if TASK_DB_PATH.exists() else 0
        if not _sqlite_fanout_table_exists(conn):
            return {
                "ok": True,
                "skipped": "table_missing",
                "beforeBytes": before_bytes,
                "afterBytes": before_bytes,
            }
        before_rows = int(conn.execute("SELECT COUNT(*) FROM fanout_outbox").fetchone()[0])
        delete_budget = max(0, before_rows - max_rows)
        if delete_budget <= 0 and before_bytes > max_bytes and before_rows > 0:
            avg_bytes_per_row = max(1, int(before_bytes / max(1, before_rows)))
            delete_budget = max(1, int(math.ceil(float(before_bytes - max_bytes) / float(avg_bytes_per_row))))
        if delete_budget <= 0:
            return {
                "ok": True,
                "skipped": "within_limits",
                "beforeRows": before_rows,
                "afterRows": before_rows,
                "beforeBytes": before_bytes,
                "afterBytes": before_bytes,
                "deleted": 0,
                "maxRows": max_rows,
                "maxBytes": max_bytes,
            }
        conn.execute("BEGIN IMMEDIATE")
        cursor = conn.execute(
            """
            DELETE FROM fanout_outbox
            WHERE id IN (
                SELECT id
                FROM fanout_outbox
                WHERE status IN ('succeeded', 'failed')
                ORDER BY COALESCE(completed_at, updated_at, created_at) ASC, id ASC
                LIMIT ?
            )
            """,
            (delete_budget,),
        )
        deleted = int(cursor.rowcount or 0)
        remaining_budget = max(0, delete_budget - deleted)
        if remaining_budget > 0:
            # Mongo is active backend; trim additional oldest legacy rows if needed.
            fallback_cursor = conn.execute(
                """
                DELETE FROM fanout_outbox
                WHERE id IN (
                    SELECT id
                    FROM fanout_outbox
                    ORDER BY COALESCE(updated_at, created_at) ASC, id ASC
                    LIMIT ?
                )
                """,
                (remaining_budget,),
            )
            deleted += int(fallback_cursor.rowcount or 0)
        conn.commit()
        checkpoint_error = None
        try:
            conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
        except Exception as exc:
            checkpoint_error = str(exc)
        run_vacuum = bool(deleted > 0 and before_bytes > max_bytes)
        if run_vacuum:
            with contextlib.suppress(Exception):
                conn.execute("VACUUM")
        after_rows = int(conn.execute("SELECT COUNT(*) FROM fanout_outbox").fetchone()[0])
        after_bytes = int(TASK_DB_PATH.stat().st_size) if TASK_DB_PATH.exists() else 0
        return {
            "ok": True,
            "beforeRows": before_rows,
            "afterRows": after_rows,
            "beforeBytes": before_bytes,
            "afterBytes": after_bytes,
            "deleted": deleted,
            "maxRows": max_rows,
            "maxBytes": max_bytes,
            "vacuumRan": run_vacuum,
            "checkpointError": checkpoint_error,
        }

    try:
        return await _task_db_exec(_prune)
    except Exception as exc:
        return {"ok": False, "error": str(exc)}


def _compress_history_file_once(path: Path, *, min_bytes: int, keep_archives: int) -> dict[str, Any]:
    min_bytes = max(1024 * 1024, int(min_bytes))
    keep_archives = max(1, int(keep_archives))
    if not path.exists() or not path.is_file():
        return {"path": str(path), "compressed": False, "reason": "missing"}
    before_bytes = int(path.stat().st_size)
    if before_bytes < min_bytes:
        return {
            "path": str(path),
            "compressed": False,
            "reason": "below_threshold",
            "beforeBytes": before_bytes,
            "thresholdBytes": min_bytes,
        }
    requested_codec = STORAGE_GOVERNANCE_HISTORY_COMPRESS_CODEC
    codec = requested_codec
    fallback_reason = None
    if codec == "zstd" and zstd is None:
        codec = "gzip"
        fallback_reason = "zstd_unavailable_fallback_to_gzip"
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    ext = "zst" if codec == "zstd" else "gz"
    archive_path = path.with_name(f"{path.name}.{stamp}.{ext}")
    with path.open("rb") as source:
        if codec == "zstd" and zstd is not None:
            compressor = zstd.ZstdCompressor(level=STORAGE_GOVERNANCE_HISTORY_COMPRESS_ZSTD_LEVEL)
            with archive_path.open("wb") as target:
                with compressor.stream_writer(target) as writer:
                    shutil.copyfileobj(source, writer, length=1024 * 1024)
        else:
            with gzip.open(archive_path, "wb", compresslevel=6) as target:
                shutil.copyfileobj(source, target, length=1024 * 1024)
    # Truncate active file after successful archive.
    path.write_text("", encoding="utf-8")
    removed: list[str] = []
    archives = sorted(
        list(path.parent.glob(f"{path.name}.*.gz")) + list(path.parent.glob(f"{path.name}.*.zst")),
        key=lambda item: item.stat().st_mtime,
        reverse=True,
    )
    for stale in archives[keep_archives:]:
        with contextlib.suppress(Exception):
            stale.unlink()
            removed.append(str(stale))
    result = {
        "path": str(path),
        "compressed": True,
        "codecRequested": requested_codec,
        "codecUsed": codec,
        "archivePath": str(archive_path),
        "beforeBytes": before_bytes,
        "archiveBytes": int(archive_path.stat().st_size) if archive_path.exists() else 0,
        "afterBytes": int(path.stat().st_size) if path.exists() else 0,
        "removedArchives": removed,
    }
    if fallback_reason:
        result["warning"] = fallback_reason
    return result


async def _run_history_compression_once() -> dict[str, Any]:
    if not STORAGE_GOVERNANCE_HISTORY_COMPRESS_ENABLED:
        return {"enabled": False, "results": {}, "compressed": 0}
    requested = {
        token.strip().lower()
        for token in STORAGE_GOVERNANCE_HISTORY_TARGETS_ENV.split(",")
        if token.strip()
    }
    all_paths = _storage_governance_history_paths()
    targets = {
        name: path
        for name, path in all_paths.items()
        if not requested or name in requested
    }
    results: dict[str, Any] = {}
    compressed = 0
    for name, path in targets.items():
        try:
            item = await asyncio.to_thread(
                _compress_history_file_once,
                path,
                min_bytes=STORAGE_GOVERNANCE_HISTORY_COMPRESS_MIN_BYTES,
                keep_archives=STORAGE_GOVERNANCE_HISTORY_COMPRESS_KEEP,
            )
            results[name] = item
            if bool(item.get("compressed")):
                compressed += 1
        except Exception as exc:
            results[name] = {"path": str(path), "compressed": False, "error": str(exc)}
    return {
        "enabled": True,
        "compressed": compressed,
        "codecRequested": STORAGE_GOVERNANCE_HISTORY_COMPRESS_CODEC,
        "zstdAvailable": bool(zstd is not None),
        "zstdLevel": STORAGE_GOVERNANCE_HISTORY_COMPRESS_ZSTD_LEVEL,
        "targets": sorted(targets.keys()),
        "results": results,
    }


async def run_storage_governance_once(*, force: bool = False) -> dict[str, Any]:
    async with storage_governance_lock:
        started = time.monotonic()
        snapshot = _collect_storage_governance_snapshot()
        policy = _storage_governance_retention_policy(snapshot)
        pressure = str(snapshot.get("pressureBand") or "healthy")
        actions: dict[str, Any] = {}
        errors: dict[str, str] = {}
        should_enforce = bool(force or pressure in {"warn", "high"})

        if should_enforce:
            try:
                actions["sinkRetention"] = await run_sink_retention_once(policy=policy.get("sinkRetention"))
            except Exception as exc:
                errors["sinkRetention"] = str(exc)
            try:
                actions["fanoutOutboxGc"] = await run_fanout_outbox_gc_once(policy=policy.get("outboxGc"))
            except Exception as exc:
                errors["fanoutOutboxGc"] = str(exc)
            try:
                actions["sqliteLegacyOutboxPrune"] = await _prune_legacy_sqlite_outbox_once(
                    max_rows=STORAGE_GOVERNANCE_SQLITE_LEGACY_MAX_ROWS,
                    max_bytes=STORAGE_GOVERNANCE_SQLITE_LEGACY_MAX_BYTES,
                )
            except Exception as exc:
                errors["sqliteLegacyOutboxPrune"] = str(exc)
        else:
            actions["sinkRetention"] = {"ok": True, "skipped": "pressure_healthy"}
            actions["fanoutOutboxGc"] = {"ok": True, "skipped": "pressure_healthy"}
            actions["sqliteLegacyOutboxPrune"] = {"ok": True, "skipped": "pressure_healthy"}

        try:
            actions["taskDbCompaction"] = await _run_task_db_compaction_once(force=bool(force))
        except Exception as exc:
            errors["taskDbCompaction"] = str(exc)
        try:
            actions["fanoutPayloadBlobGc"] = await _run_fanout_payload_blob_gc_once(force=bool(force))
        except Exception as exc:
            errors["fanoutPayloadBlobGc"] = str(exc)
        try:
            actions["mongoRawContentBlobGc"] = await _run_mongo_raw_content_blob_gc_once(force=bool(force))
        except Exception as exc:
            errors["mongoRawContentBlobGc"] = str(exc)

        try:
            actions["historyCompression"] = await _run_history_compression_once()
        except Exception as exc:
            errors["historyCompression"] = str(exc)

        duration_ms = (time.monotonic() - started) * 1000
        result = {
            "ok": not bool(errors),
            "forced": bool(force),
            "pressureBand": pressure,
            "snapshot": snapshot,
            "policy": policy,
            "actions": actions,
            "errors": errors,
            "durationMs": round(duration_ms, 2),
            "capturedAt": _utc_now(),
        }
        storage_governance_state["enabled"] = STORAGE_GOVERNANCE_ENABLED
        storage_governance_state["intervalSecs"] = STORAGE_GOVERNANCE_INTERVAL_SECS
        storage_governance_state["lastRunAt"] = result["capturedAt"]
        storage_governance_state["lastDurationMs"] = result["durationMs"]
        storage_governance_state["runs"] = int(storage_governance_state.get("runs") or 0) + 1
        storage_governance_state["lastError"] = json.dumps(errors)[:400] if errors else None
        storage_governance_state["lastResult"] = result
        storage_governance_state["lastSnapshot"] = snapshot
        storage_governance_state["lastPolicy"] = policy
        storage_governance_state["lastPressureBand"] = pressure
        return result


async def _storage_governance_worker() -> None:
    interval = max(120.0, STORAGE_GOVERNANCE_INTERVAL_SECS)
    while True:
        try:
            result = await run_storage_governance_once(force=False)
            logger.info(
                "storage governance: pressure=%s tracked=%s compressed=%s errors=%s",
                result.get("pressureBand"),
                ((result.get("snapshot") or {}).get("trackedBytesTotal")),
                (((result.get("actions") or {}).get("historyCompression") or {}).get("compressed")),
                result.get("errors"),
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # pragma: no cover - runtime resilience
            logger.warning("Storage governance run failed: %s", exc)
        await asyncio.sleep(interval)


async def _sink_retention_worker() -> None:
    interval = max(60.0, SINK_RETENTION_INTERVAL_SECS)
    while True:
        try:
            result = await run_sink_retention_once()
            logger.info(
                "sink retention: qdrant_deleted=%s mongo_deleted=%s mindsdb_deleted=%s letta_deleted=%s errors=%s",
                ((result.get("sinks") or {}).get("qdrant") or {}).get("deleted"),
                ((result.get("sinks") or {}).get("mongo_raw") or {}).get("deleted"),
                ((result.get("sinks") or {}).get("mindsdb") or {}).get("deleted"),
                ((result.get("sinks") or {}).get("letta") or {}).get("deleted"),
                result.get("errors"),
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # pragma: no cover - runtime resilience
            logger.warning("Sink retention run failed: %s", exc)
        await asyncio.sleep(interval)


def _set_fanout_summary_cache(summary: dict[str, Any]) -> None:
    by_status = summary.get("by_status") if isinstance(summary, dict) else {}
    by_target = summary.get("by_target") if isinstance(summary, dict) else {}
    fanout_summary_cache["by_status"] = dict(by_status) if isinstance(by_status, dict) else {}
    fanout_summary_cache["by_target"] = dict(by_target) if isinstance(by_target, dict) else {}
    fanout_summary_cache["updated_at"] = _utc_now()
    fanout_summary_cache["updated_monotonic"] = time.monotonic()


def _get_fanout_summary_cache() -> dict[str, Any]:
    return {
        "by_status": dict(fanout_summary_cache.get("by_status") or {}),
        "by_target": dict(fanout_summary_cache.get("by_target") or {}),
    }


def _fanout_cache_fresh(cached: dict[str, Any]) -> bool:
    if not (cached.get("by_status") or cached.get("by_target")):
        return False
    cache_updated = fanout_summary_cache.get("updated_monotonic")
    if not isinstance(cache_updated, (int, float)):
        return False
    cache_age = max(0.0, time.monotonic() - float(cache_updated))
    return cache_age <= max(0.0, FANOUT_SUMMARY_CACHE_TTL_SECS)


def _fanout_sqlite_summary(conn: sqlite3.Connection) -> dict[str, Any]:
    statuses = ("pending", "retrying", "running", "succeeded", "failed")
    by_status: dict[str, int] = {}
    for status in statuses:
        row = conn.execute(
            "SELECT COUNT(*) AS c FROM fanout_outbox WHERE status = ?",
            (status,),
        ).fetchone()
        count = int(row["c"] if row else 0)
        if count > 0:
            by_status[status] = count
    by_target: dict[str, dict[str, int]] = {}
    for target in FANOUT_TARGETS:
        counts: dict[str, int] = {}
        for status in statuses:
            row = conn.execute(
                "SELECT COUNT(*) AS c FROM fanout_outbox WHERE target = ? AND status = ?",
                (target, status),
            ).fetchone()
            count = int(row["c"] if row else 0)
            if count > 0:
                counts[status] = count
        if counts:
            by_target[target] = counts
    return {"by_status": by_status, "by_target": by_target}


async def _query_fanout_summary_uncached() -> dict[str, Any]:
    if _use_mongo_outbox():
        try:
            return await asyncio.wait_for(
                _get_fanout_summary_mongo(),
                timeout=max(1.0, FANOUT_SUMMARY_TIMEOUT_SECS),
            )
        except Exception as exc:
            _demote_outbox_backend(str(exc))
    try:
        return await asyncio.wait_for(
            _task_db_exec(_fanout_sqlite_summary),
            timeout=max(1.0, FANOUT_SUMMARY_TIMEOUT_SECS),
        )
    except Exception as exc:
        if await _promote_outbox_backend_to_mongo_if_sqlite_error(str(exc)):
            return await asyncio.wait_for(
                _get_fanout_summary_mongo(),
                timeout=max(1.0, FANOUT_SUMMARY_TIMEOUT_SECS),
            )
        raise


async def _refresh_fanout_summary_in_background() -> None:
    try:
        summary = await _query_fanout_summary_uncached()
    except Exception as exc:
        logger.warning("Fanout summary background refresh failed: %s", exc)
        return
    _set_fanout_summary_cache(summary)


def _schedule_fanout_summary_refresh() -> None:
    global fanout_summary_refresh_task
    task = fanout_summary_refresh_task
    if task is not None and not task.done():
        return
    fanout_summary_refresh_task = asyncio.create_task(_refresh_fanout_summary_in_background())


async def get_fanout_summary() -> dict[str, Any]:
    cached = _get_fanout_summary_cache()
    if _fanout_cache_fresh(cached):
        return cached
    if cached.get("by_status") or cached.get("by_target"):
        _schedule_fanout_summary_refresh()
        return cached

    try:
        summary = await _query_fanout_summary_uncached()
    except Exception as exc:
        logger.warning("Fanout summary query failed; serving empty summary: %s", exc)
        return {"by_status": {}, "by_target": {}}
    _set_fanout_summary_cache(summary)
    return summary


async def list_fanout_jobs(
    statuses: list[str],
    limit: int = 100,
    target: str | None = None,
) -> list[dict[str, Any]]:
    statuses = [status for status in statuses if status]
    if not statuses:
        return []
    limit = max(1, min(limit, 500))
    if _use_mongo_outbox():
        try:
            return await _list_fanout_jobs_mongo(statuses=statuses, limit=limit, target=target)
        except Exception as exc:
            _demote_outbox_backend(str(exc))

    def _list(conn: sqlite3.Connection):
        placeholders = ",".join("?" for _ in statuses)
        params: list[Any] = list(statuses)
        query = f"SELECT * FROM fanout_outbox WHERE status IN ({placeholders})"
        if target:
            query += " AND target = ?"
            params.append(target)
        query += " ORDER BY updated_at DESC, id DESC LIMIT ?"
        params.append(limit)
        rows = conn.execute(query, params).fetchall()
        return [_fanout_row_to_dict(row) for row in rows]

    return await _task_db_exec(_list)


async def restore_letta_runtime_state_from_outbox() -> None:
    if not _letta_config_enabled():
        return
    failed_jobs = await list_fanout_jobs(["failed"], limit=50, target=FANOUT_TARGET_LETTA)
    for job in failed_jobs:
        error_text = str(job.get("last_error") or "")
        if _is_letta_permanent_error(error_text):
            _set_letta_runtime_disabled(error_text or "prior permanent Letta error")
            await fail_letta_backlog(letta_runtime_disabled_reason or "letta fanout disabled")
            return


def _task_payload_json(payload: dict[str, Any] | None) -> str | None:
    if payload is None:
        return None
    return json.dumps(payload)


def _task_metadata_json(metadata: dict[str, Any] | None) -> str | None:
    if metadata is None:
        return None
    return json.dumps(metadata)


def _feedback_tags_json(tags: list[str] | None) -> str | None:
    if tags is None:
        return None
    return json.dumps(tags)


def _feedback_metadata_json(metadata: dict[str, Any] | None) -> str | None:
    if metadata is None:
        return None
    return json.dumps(metadata)


def _feedback_submit_cache_key(key: str) -> str:
    normalized = str(key or "").strip()
    if not normalized:
        return ""
    digest = hashlib.sha256(f"feedback:{normalized}".encode("utf-8")).hexdigest()
    return f"feedback:{digest}"


def _feedback_submit_fingerprint(payload: dict[str, Any]) -> str:
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


async def _feedback_submit_idempotency_lookup(
    key: str,
    fingerprint: str,
) -> tuple[dict[str, Any] | None, bool]:
    if not key:
        return None, False
    now = time.monotonic()
    stale: list[str] = []
    ttl = max(30.0, FEEDBACK_SUBMIT_IDEMPOTENCY_TTL_SECS)
    for cache_key, payload in list(feedback_submit_idempotency_seen.items()):
        seen_at = float(payload.get("seenAtMonotonic") or 0.0)
        if seen_at + ttl < now:
            stale.append(cache_key)
    for cache_key in stale:
        feedback_submit_idempotency_seen.pop(cache_key, None)
    payload = feedback_submit_idempotency_seen.get(key)
    if payload is None:
        return None, False
    feedback_submit_idempotency_seen.move_to_end(key)
    if str(payload.get("fingerprint") or "") != fingerprint:
        return None, True
    cached_result = payload.get("result")
    if isinstance(cached_result, dict):
        replay = dict(cached_result)
        replay["idempotentReplay"] = True
        replay["idempotencyScope"] = "request"
        return replay, False
    return None, False


async def _feedback_submit_idempotency_store(
    key: str,
    fingerprint: str,
    result: dict[str, Any],
) -> None:
    if not key:
        return
    feedback_submit_idempotency_seen[key] = {
        "seenAtMonotonic": time.monotonic(),
        "fingerprint": fingerprint,
        "result": dict(result),
    }
    feedback_submit_idempotency_seen.move_to_end(key)
    max_keys = max(128, MEMORY_WRITE_DEDUP_MAX_KEYS)
    while len(feedback_submit_idempotency_seen) > max_keys:
        feedback_submit_idempotency_seen.popitem(last=False)


def _normalize_feedback_source(value: str | None, *, default: str) -> str:
    source = str(value or default).strip().lower() or default
    if source not in {"user", "agent", "system"}:
        raise HTTPException(422, "source must be one of: user, agent, system")
    return source


def _normalize_feedback_sentiment(value: str | None) -> str | None:
    sentiment = str(value or "").strip().lower()
    if not sentiment:
        return None
    aliases = {
        "good": "positive",
        "liked": "positive",
        "bad": "negative",
        "disliked": "negative",
    }
    normalized = aliases.get(sentiment, sentiment)
    if normalized not in {"positive", "neutral", "negative"}:
        raise HTTPException(422, "sentiment must be one of: positive, neutral, negative")
    return normalized


def _normalize_feedback_tags(tags: list[str] | None) -> list[str] | None:
    if tags is None:
        return None
    normalized: list[str] = []
    seen: set[str] = set()
    for raw_tag in tags:
        tag = str(raw_tag or "").strip().lower()
        if not tag:
            continue
        if len(tag) > FEEDBACK_TAG_MAX_LENGTH:
            raise HTTPException(422, f"tag '{tag[:24]}' exceeds FEEDBACK_TAG_MAX_LENGTH={FEEDBACK_TAG_MAX_LENGTH}")
        if not re.match(r"^[a-z0-9][a-z0-9:_./-]*$", tag):
            raise HTTPException(422, f"tag '{tag}' is malformed")
        if tag in seen:
            continue
        seen.add(tag)
        normalized.append(tag)
        if len(normalized) > FEEDBACK_TAG_MAX_COUNT:
            raise HTTPException(422, f"tags exceed FEEDBACK_TAG_MAX_COUNT={FEEDBACK_TAG_MAX_COUNT}")
    return normalized or None


def _normalize_feedback_metadata(metadata: dict[str, Any] | None) -> dict[str, Any] | None:
    if metadata is None:
        return None
    if not isinstance(metadata, dict):
        raise HTTPException(422, "metadata must be an object")
    if len(metadata) > FEEDBACK_METADATA_MAX_KEYS:
        raise HTTPException(422, f"metadata exceeds FEEDBACK_METADATA_MAX_KEYS={FEEDBACK_METADATA_MAX_KEYS}")
    normalized: dict[str, Any] = {}
    for key, value in metadata.items():
        token = str(key or "").strip()
        if not token:
            continue
        normalized[token] = value
    encoded = json.dumps(normalized, separators=(",", ":"), default=str)
    if len(encoded.encode("utf-8")) > FEEDBACK_METADATA_MAX_BYTES:
        raise HTTPException(422, f"metadata exceeds FEEDBACK_METADATA_MAX_BYTES={FEEDBACK_METADATA_MAX_BYTES}")
    return normalized or None


def _validate_feedback_submit_payload(payload: FeedbackSubmitRequest) -> dict[str, Any]:
    project = str(payload.project or "").strip() or None
    user_id = str(payload.user_id or "").strip() or None
    task_id = str(payload.task_id or "").strip() or None
    topic_path = normalize_topic_path(payload.topic_path) if payload.topic_path else None
    content_raw = str(payload.content or "").strip()
    if len(content_raw) > FEEDBACK_MAX_CONTENT:
        raise HTTPException(422, f"content exceeds FEEDBACK_MAX_CONTENT={FEEDBACK_MAX_CONTENT}")
    content = content_raw or None
    rating = payload.rating
    sentiment = _normalize_feedback_sentiment(payload.sentiment)
    tags = _normalize_feedback_tags(payload.tags)
    metadata = _normalize_feedback_metadata(payload.metadata)
    if not any([rating is not None, sentiment, tags, content, metadata]):
        raise HTTPException(422, "feedback_submit requires at least one of rating/sentiment/tags/content/metadata")
    source = _normalize_feedback_source(payload.source, default="agent")
    return {
        "project": project,
        "user_id": user_id,
        "source": source,
        "task_id": task_id,
        "rating": rating,
        "sentiment": sentiment,
        "tags": tags,
        "content": content,
        "topic_path": topic_path,
        "metadata": metadata,
    }


async def _persist_feedback_to_memory(record: dict[str, Any]) -> tuple[bool, str | None]:
    if not LEARNING_LOOP_ENABLED:
        return False, None
    if not record.get("project") or not record.get("content"):
        return False, None
    file_name = f"feedback/{record['id']}.md"
    content = json.dumps(record, indent=2)
    try:
        await call_memory_tool(
            "memory_bank_write",
            {
                "projectName": record["project"],
                "fileName": file_name,
                "content": content,
            },
        )
    except Exception as exc:
        return False, str(exc)
    return True, None


def _detect_action_type(payload: dict[str, Any] | None) -> str | None:
    if not payload:
        return None
    action_type = payload.get("action_type") or payload.get("actionType")
    if isinstance(action_type, str) and action_type.strip():
        return action_type.strip().lower()
    actions = payload.get("actions")
    if isinstance(actions, list) and actions:
        first = actions[0]
        if isinstance(first, dict):
            value = first.get("type") or first.get("action") or first.get("category")
            if isinstance(value, str) and value.strip():
                return value.strip().lower()
        if isinstance(first, str) and first.strip():
            return first.strip().lower()
    return None


def _detect_risk_level(payload: dict[str, Any] | None) -> str:
    if not payload:
        return "low"
    raw = payload.get("risk_level") or payload.get("riskLevel") or payload.get("risk")
    if isinstance(raw, str) and raw.strip():
        return raw.strip().lower()
    action_type = _detect_action_type(payload)
    if action_type and action_type in HIGH_RISK_ACTIONS:
        return "high"
    return "low"


def _requires_approval(payload: dict[str, Any] | None) -> bool:
    if not HIGH_RISK_APPROVAL_REQUIRED:
        return False
    risk_level = _detect_risk_level(payload)
    return risk_level in ("high", "critical")


def _feedback_row_to_dict(row: sqlite3.Row) -> dict[str, Any]:
    return {
        "id": row["id"],
        "created_at": row["created_at"],
        "project": row["project"],
        "user_id": row["user_id"],
        "source": row["source"],
        "task_id": row["task_id"],
        "rating": row["rating"],
        "sentiment": row["sentiment"],
        "tags": json.loads(row["tags"]) if row["tags"] else None,
        "content": row["content"],
        "topic_path": row["topic_path"],
        "metadata": json.loads(row["metadata"]) if row["metadata"] else None,
    }


async def create_feedback_record(
    project: str | None,
    user_id: str | None,
    source: str | None,
    task_id: str | None,
    rating: int | None,
    sentiment: str | None,
    tags: list[str] | None,
    content: str | None,
    topic_path: str | None,
    metadata: dict[str, Any] | None,
) -> dict[str, Any]:
    feedback_id = uuid.uuid4().hex
    timestamp = datetime.utcnow().isoformat() + "Z"
    tags_json = _feedback_tags_json(tags)
    metadata_json = _feedback_metadata_json(metadata)
    safe_content = (content or "").strip()[:FEEDBACK_MAX_CONTENT]
    safe_source = (source or "user").lower()

    def _create(conn: sqlite3.Connection):
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            INSERT INTO feedback (
                id, created_at, project, user_id, source, task_id, rating, sentiment, tags, content, topic_path, metadata
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                feedback_id,
                timestamp,
                project,
                user_id,
                safe_source,
                task_id,
                rating,
                sentiment,
                tags_json,
                safe_content,
                topic_path,
                metadata_json,
            ),
        )
        conn.commit()
        row = conn.execute("SELECT * FROM feedback WHERE id = ?", (feedback_id,)).fetchone()
        return _feedback_row_to_dict(row)

    return await _task_db_exec(_create)


async def list_feedback_records(
    project: str | None,
    user_id: str | None,
    source: str | None,
    limit: int,
) -> list[dict[str, Any]]:
    limit = max(1, min(limit, 200))

    def _list(conn: sqlite3.Connection):
        clauses = []
        params: list[Any] = []
        if project:
            clauses.append("project = ?")
            params.append(project)
        if user_id:
            clauses.append("user_id = ?")
            params.append(user_id)
        if source:
            clauses.append("source = ?")
            params.append(source.lower())
        where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(limit)
        rows = conn.execute(
            f"SELECT * FROM feedback {where} ORDER BY created_at DESC LIMIT ?",
            params,
        ).fetchall()
        return [_feedback_row_to_dict(row) for row in rows]

    return await _task_db_exec(_list)


def build_preference_context(records: list[dict[str, Any]]) -> dict[str, Any]:
    positives: list[str] = []
    negatives: list[str] = []
    notes: list[str] = []
    for entry in records:
        rating = entry.get("rating")
        sentiment = (entry.get("sentiment") or "").lower()
        content = (entry.get("content") or "").strip()
        source = entry.get("source") or "user"
        topic_path = entry.get("topic_path") or ""
        tags = entry.get("tags") or []
        line = content or entry.get("metadata") or ""
        if not line:
            continue
        tag_str = f" [tags: {', '.join(tags)}]" if tags else ""
        topic_str = f" [topic: {topic_path}]" if topic_path else ""
        rendered = f"{line} (source: {source}){topic_str}{tag_str}"
        if rating is not None:
            if rating >= 4:
                positives.append(rendered)
                continue
            if rating <= 2:
                negatives.append(rendered)
                continue
        if sentiment in ("positive", "liked", "good"):
            positives.append(rendered)
        elif sentiment in ("negative", "disliked", "bad"):
            negatives.append(rendered)
        else:
            notes.append(rendered)
    context_lines: list[str] = []
    if positives:
        context_lines.append("Positive preferences:")
        context_lines.extend([f"- {item}" for item in positives])
    if negatives:
        context_lines.append("Avoid or dislike:")
        context_lines.extend([f"- {item}" for item in negatives])
    if notes:
        context_lines.append("Notes:")
        context_lines.extend([f"- {item}" for item in notes])
    return {
        "positive": positives,
        "negative": negatives,
        "notes": notes,
        "context": "\n".join(context_lines).strip(),
        "total": len(records),
        "updated_at": datetime.utcnow().isoformat() + "Z",
    }


TASK_TERMINAL_STATUSES = {"succeeded", "failed", "canceled"}
TASK_MUTABLE_STATUSES = {"queued", "approved", "running", "blocked"}


def _task_parse_datetime(value: str | None) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    if raw.isdigit():
        return datetime.utcfromtimestamp(float(raw))
    candidate = raw
    if candidate.endswith("Z"):
        candidate = candidate[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(candidate)
    except ValueError:
        return None
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    return parsed


def _task_iso_now() -> str:
    return datetime.utcnow().isoformat() + "Z"


def _task_iso_after(seconds: float) -> str:
    when = datetime.utcnow() + timedelta(seconds=max(0.0, seconds))
    return when.isoformat() + "Z"


def _safe_json_load(value: str | None) -> Any:
    if value is None:
        return None
    try:
        return json.loads(value)
    except Exception:
        return value


def _task_row_to_dict(row: sqlite3.Row) -> dict[str, Any]:
    payload = _safe_json_load(row["payload"] if "payload" in row.keys() else None)
    result = _safe_json_load(row["result"] if "result" in row.keys() else None)
    return {
        "id": row["id"],
        "title": row["title"],
        "status": row["status"],
        "project": row["project"],
        "agent": row["agent"],
        "priority": row["priority"],
        "payload": payload if isinstance(payload, dict) else payload,
        "approval_required": bool(row["approval_required"]) if "approval_required" in row.keys() else False,
        "approved": bool(row["approved"]) if "approved" in row.keys() else False,
        "risk_level": row["risk_level"] if "risk_level" in row.keys() else None,
        "action_type": row["action_type"] if "action_type" in row.keys() else None,
        "run_after": row["run_after"] if "run_after" in row.keys() else None,
        "attempts": int(row["attempts"]) if "attempts" in row.keys() and row["attempts"] is not None else 0,
        "max_attempts": int(row["max_attempts"]) if "max_attempts" in row.keys() and row["max_attempts"] is not None else TASK_DEFAULT_MAX_ATTEMPTS,
        "lease_expires_at": row["lease_expires_at"] if "lease_expires_at" in row.keys() else None,
        "claimed_by": row["claimed_by"] if "claimed_by" in row.keys() else None,
        "last_error": row["last_error"] if "last_error" in row.keys() else None,
        "result": result,
        "completed_at": row["completed_at"] if "completed_at" in row.keys() else None,
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }


def _normalize_task_action(raw: Any) -> str | None:
    if raw is None:
        return None
    action = str(raw).strip().lower()
    if not action:
        return None
    alias = {
        "write": "memory_write",
        "remember": "memory_write",
        "search": "memory_search",
        "recall": "memory_search",
        "message": "messaging_command",
        "messaging": "messaging_command",
        "callback": "http_callback",
        "http": "http_callback",
        "provider": "provider_chat",
    }
    return alias.get(action, action)


def _task_validate_callback_url(url: str) -> None:
    from urllib.parse import urlparse

    parsed = urlparse(url)
    if parsed.scheme.lower() not in {"http", "https"}:
        raise HTTPException(422, "http_callback requires http/https URL")
    host = (parsed.hostname or "").lower()
    if not host:
        raise HTTPException(422, "http_callback URL host is required")
    if TASK_CALLBACK_ALLOWED_HOSTS:
        if host not in TASK_CALLBACK_ALLOWED_HOSTS:
            raise HTTPException(422, f"http_callback host '{host}' not allowlisted")


def _validate_task_payload_contract(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    if payload is None:
        return None
    if not isinstance(payload, dict):
        raise HTTPException(422, "task payload must be an object")
    normalized = dict(payload)
    action = _normalize_task_action(
        normalized.get("action")
        or normalized.get("action_type")
        or _detect_action_type(normalized)
    )
    if not action:
        raise HTTPException(422, "task payload requires action")
    if action not in TASK_ALLOWED_ACTIONS:
        raise HTTPException(422, f"task action '{action}' is not allowed")
    normalized["action"] = action
    normalized["action_type"] = action

    if action == "memory_write":
        project_name = str(normalized.get("projectName") or normalized.get("project") or "").strip()
        file_name = str(normalized.get("fileName") or normalized.get("file") or "").strip()
        content = str(normalized.get("content") or "").strip()
        if not project_name or not file_name or not content:
            raise HTTPException(422, "memory_write requires projectName, fileName, and content")
        normalized["projectName"] = project_name
        normalized["fileName"] = file_name
        normalized["content"] = content
    elif action == "memory_search":
        query = str(normalized.get("query") or "").strip()
        if not query:
            raise HTTPException(422, "memory_search requires query")
        normalized["query"] = query
    elif action == "messaging_command":
        text = str(normalized.get("text") or "").strip()
        if not text:
            raise HTTPException(422, "messaging_command requires text")
        normalized["text"] = text
    elif action == "http_callback":
        callback_url = str(normalized.get("url") or "").strip()
        if not callback_url:
            raise HTTPException(422, "http_callback requires url")
        _task_validate_callback_url(callback_url)
        normalized["url"] = callback_url
        method = str(normalized.get("method") or "POST").strip().upper()
        if method not in {"GET", "POST", "PUT", "PATCH", "DELETE"}:
            raise HTTPException(422, f"http_callback method '{method}' not allowed")
        normalized["method"] = method
    elif action == "provider_chat":
        has_prompt = bool(str(normalized.get("prompt") or "").strip())
        has_messages = isinstance(normalized.get("messages"), list) and bool(normalized.get("messages"))
        if not has_prompt and not has_messages:
            raise HTTPException(422, "provider_chat requires prompt or messages")
    return normalized


def _task_retry_delay_secs(attempt: int) -> float:
    exp = max(0, int(attempt) - 1)
    delay = TASK_RETRY_BASE_SECS * (2**exp)
    return min(delay, TASK_RETRY_MAX_SECS)

async def create_task_record(
    title: str,
    project: str | None,
    agent: str | None,
    priority: int,
    payload: dict[str, Any] | None,
    *,
    run_after: str | None = None,
    max_attempts: int | None = None,
) -> dict[str, Any]:
    task_id = uuid.uuid4().hex
    timestamp = _task_iso_now()
    normalized_payload = _validate_task_payload_contract(payload)
    payload_json = _task_payload_json(normalized_payload)
    risk_level = _detect_risk_level(normalized_payload)
    action_type = _normalize_task_action(
        (normalized_payload or {}).get("action") if isinstance(normalized_payload, dict) else None
    ) or _detect_action_type(normalized_payload)
    approval_required = bool((normalized_payload or {}).get("approval_required")) if normalized_payload else False
    if not approval_required:
        approval_required = _requires_approval(normalized_payload)
    approved = bool((normalized_payload or {}).get("approved") or (normalized_payload or {}).get("approval")) if normalized_payload else False
    due_dt = _task_parse_datetime(run_after) if run_after else None
    if run_after and due_dt is None:
        raise HTTPException(422, "run_after must be ISO-8601 timestamp")
    due_at = due_dt.isoformat() + "Z" if due_dt else timestamp
    capped_max_attempts = max(1, min(int(max_attempts or TASK_DEFAULT_MAX_ATTEMPTS), 50))

    def _create(conn: sqlite3.Connection):
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            INSERT INTO tasks (
                id, title, status, project, agent, priority, payload, run_after, attempts, max_attempts,
                lease_expires_at, claimed_by, last_error, result, completed_at, created_at, updated_at,
                approval_required, approved, risk_level, action_type
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                task_id,
                title,
                "queued",
                project,
                agent,
                priority,
                payload_json,
                due_at,
                0,
                capped_max_attempts,
                None,
                None,
                None,
                None,
                None,
                timestamp,
                timestamp,
                int(approval_required),
                int(approved),
                risk_level,
                action_type,
            ),
        )
        event_message = f"Task created (due {due_at})"
        conn.execute(
            """
            INSERT INTO task_events (task_id, timestamp, status, message, metadata)
            VALUES (?, ?, ?, ?, ?)
            """,
            (task_id, timestamp, "queued", event_message, None),
        )
        conn.commit()
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        return _task_row_to_dict(row)

    return await _task_db_exec(_create)


async def list_task_records(
    status: str | None = None,
    project: str | None = None,
    agent: str | None = None,
    limit: int = 50,
) -> list[dict[str, Any]]:
    limit = max(1, min(limit, 200))

    def _list(conn: sqlite3.Connection):
        clauses = []
        params: list[Any] = []
        if status:
            clauses.append("status = ?")
            params.append(str(status).lower())
        if project:
            clauses.append("project = ?")
            params.append(project)
        if agent:
            normalized_agent = str(agent).strip().lower()
            if normalized_agent == "unassigned":
                clauses.append("(agent IS NULL OR trim(agent) = '')")
            else:
                clauses.append("lower(trim(coalesce(agent, ''))) = ?")
                params.append(normalized_agent)
        where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(limit)
        rows = conn.execute(
            f"SELECT * FROM tasks {where} ORDER BY priority DESC, run_after ASC, created_at DESC LIMIT ?",
            params,
        ).fetchall()
        return [_task_row_to_dict(row) for row in rows]

    return await _task_db_exec(_list)


async def get_task_record(task_id: str) -> dict[str, Any] | None:
    def _get(conn: sqlite3.Connection):
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        if not row:
            return None
        return _task_row_to_dict(row)

    return await _task_db_exec(_get)


async def get_task_events(task_id: str) -> list[dict[str, Any]]:
    def _events(conn: sqlite3.Connection):
        rows = conn.execute(
            "SELECT * FROM task_events WHERE task_id = ? ORDER BY id DESC", (task_id,)
        ).fetchall()
        events: list[dict[str, Any]] = []
        for row in rows:
            metadata = row["metadata"]
            events.append(
                {
                    "id": row["id"],
                    "task_id": row["task_id"],
                    "timestamp": row["timestamp"],
                    "status": row["status"],
                    "message": row["message"],
                    "metadata": json.loads(metadata) if metadata else None,
                }
            )
        return events

    return await _task_db_exec(_events)


async def list_deadletter_task_records(
    project: str | None = None,
    limit: int = 100,
) -> list[dict[str, Any]]:
    limit = max(1, min(limit, 500))

    def _list(conn: sqlite3.Connection):
        params: list[Any] = []
        where = "WHERE status = 'failed'"
        if project:
            where += " AND project = ?"
            params.append(project)
        params.append(limit)
        rows = conn.execute(
            f"SELECT * FROM tasks {where} ORDER BY updated_at DESC LIMIT ?",
            params,
        ).fetchall()
        return [_task_row_to_dict(row) for row in rows]

    return await _task_db_exec(_list)


async def replay_task_record(
    task_id: str,
    *,
    actor: str | None = None,
    note: str | None = None,
    reset_attempts: bool = True,
) -> dict[str, Any] | None:
    now = _task_iso_now()

    def _replay(conn: sqlite3.Connection):
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        if not row:
            return None
        conn.execute("BEGIN IMMEDIATE")
        attempts = 0 if reset_attempts else int(row["attempts"] or 0)
        conn.execute(
            """
            UPDATE tasks
            SET status = 'queued',
                run_after = ?,
                lease_expires_at = NULL,
                claimed_by = NULL,
                completed_at = NULL,
                attempts = ?,
                last_error = NULL,
                updated_at = ?
            WHERE id = ?
            """,
            (now, attempts, now, task_id),
        )
        event_metadata = {"actor": actor, "note": note, "reset_attempts": bool(reset_attempts)}
        conn.execute(
            """
            INSERT INTO task_events (task_id, timestamp, status, message, metadata)
            VALUES (?, ?, ?, ?, ?)
            """,
            (
                task_id,
                now,
                "queued",
                "Task replayed to queue",
                json.dumps(event_metadata),
            ),
        )
        conn.commit()
        updated = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        return _task_row_to_dict(updated)

    return await _task_db_exec(_replay)


async def get_task_runtime_snapshot() -> dict[str, Any]:
    now = _task_iso_now()

    def _snapshot(conn: sqlite3.Connection) -> dict[str, Any]:
        by_status_rows = conn.execute(
            "SELECT status, COUNT(*) AS total FROM tasks GROUP BY status"
        ).fetchall()
        by_status = {
            str(row["status"]): int(row["total"])
            for row in by_status_rows
            if row["status"] is not None
        }
        ready_row = conn.execute(
            """
            SELECT COUNT(*) AS total
            FROM tasks
            WHERE status IN ('queued', 'approved')
              AND (approval_required = 0 OR approved = 1)
              AND attempts < max_attempts
              AND (run_after IS NULL OR run_after <= ?)
            """,
            (now,),
        ).fetchone()
        oldest_row = conn.execute(
            """
            SELECT run_after
            FROM tasks
            WHERE status IN ('queued', 'approved')
            ORDER BY run_after ASC, created_at ASC
            LIMIT 1
            """
        ).fetchone()
        running_row = conn.execute(
            "SELECT COUNT(*) AS total FROM tasks WHERE status = 'running'"
        ).fetchone()
        deadletter_row = conn.execute(
            "SELECT COUNT(*) AS total FROM tasks WHERE status = 'failed'"
        ).fetchone()
        return {
            "queueReady": int((ready_row["total"] if ready_row else 0) or 0),
            "running": int((running_row["total"] if running_row else 0) or 0),
            "deadletter": int((deadletter_row["total"] if deadletter_row else 0) or 0),
            "oldestPendingRunAfter": oldest_row["run_after"] if oldest_row else None,
            "byStatus": by_status,
        }

    snapshot = await _task_db_exec(_snapshot)
    return {
        **task_runtime_health,
        **snapshot,
        "timestamp": now,
    }


async def update_task_status(
    task_id: str,
    status: str,
    message: str | None,
    metadata: dict[str, Any] | None,
) -> dict[str, Any] | None:
    normalized_status = str(status or "").strip().lower()
    if normalized_status not in TASK_TERMINAL_STATUSES.union(TASK_MUTABLE_STATUSES):
        raise HTTPException(422, f"invalid task status '{status}'")
    timestamp = _task_iso_now()
    metadata_json = _task_metadata_json(metadata)
    terminal = normalized_status in TASK_TERMINAL_STATUSES
    run_after_override = None
    if isinstance(metadata, dict) and metadata.get("run_after"):
        parsed = _task_parse_datetime(str(metadata.get("run_after")))
        if parsed is not None:
            run_after_override = parsed.isoformat() + "Z"
    result_payload = None
    if isinstance(metadata, dict):
        result_payload = metadata.get("result") if "result" in metadata else metadata
    result_json = json.dumps(result_payload) if result_payload is not None else None

    def _update(conn: sqlite3.Connection):
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        if not row:
            return None
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            UPDATE tasks
            SET status = ?, updated_at = ?, run_after = ?, lease_expires_at = ?, claimed_by = ?,
                completed_at = ?, last_error = ?, result = ?
            WHERE id = ?
            """,
            (
                normalized_status,
                timestamp,
                run_after_override if run_after_override is not None else (timestamp if normalized_status in {"queued", "approved"} else row["run_after"]),
                None if terminal or normalized_status in {"queued", "approved", "blocked"} else row["lease_expires_at"],
                None if terminal or normalized_status in {"queued", "approved", "blocked"} else row["claimed_by"],
                timestamp if terminal else row["completed_at"],
                (str(message or row["last_error"] or "")[:2000] if normalized_status == "failed" else row["last_error"]),
                result_json if result_json is not None else row["result"],
                task_id,
            ),
        )
        conn.execute(
            """
            INSERT INTO task_events (task_id, timestamp, status, message, metadata)
            VALUES (?, ?, ?, ?, ?)
            """,
            (task_id, timestamp, normalized_status, message, metadata_json),
        )
        conn.commit()
        updated = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        return _task_row_to_dict(updated)

    task = await _task_db_exec(_update)
    if task and terminal and TASK_RESULT_WRITEBACK_ENABLED:
        with contextlib.suppress(Exception):
            await _record_task_outcome_memory(task, message=message, metadata=metadata)
    return task


async def approve_task_record(
    task_id: str,
    approver: str | None,
    note: str | None,
) -> dict[str, Any] | None:
    timestamp = _task_iso_now()

    def _approve(conn: sqlite3.Connection):
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        if not row:
            return None
        conn.execute("BEGIN IMMEDIATE")
        status = row["status"]
        if status in ("blocked", "queued"):
            status = "approved"
        conn.execute(
            "UPDATE tasks SET approved = 1, status = ?, updated_at = ?, run_after = COALESCE(run_after, ?) WHERE id = ?",
            (status, timestamp, timestamp, task_id),
        )
        metadata = {"approver": approver, "note": note} if approver or note else None
        conn.execute(
            """
            INSERT INTO task_events (task_id, timestamp, status, message, metadata)
            VALUES (?, ?, ?, ?, ?)
            """,
            (task_id, timestamp, "approved", "Task approved", json.dumps(metadata) if metadata else None),
        )
        conn.commit()
        updated = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        return _task_row_to_dict(updated)

    return await _task_db_exec(_approve)


async def recover_expired_task_leases(limit: int = 100) -> int:
    if limit <= 0:
        return 0
    now = _task_iso_now()

    def _recover(conn: sqlite3.Connection) -> int:
        conn.execute("BEGIN IMMEDIATE")
        rows = conn.execute(
            """
            SELECT id FROM tasks
            WHERE status = 'running'
              AND lease_expires_at IS NOT NULL
              AND lease_expires_at <= ?
            ORDER BY lease_expires_at ASC
            LIMIT ?
            """,
            (now, int(limit)),
        ).fetchall()
        recovered = 0
        for row in rows:
            task_id = row["id"]
            conn.execute(
                """
                UPDATE tasks
                SET status = 'queued',
                    run_after = ?,
                    lease_expires_at = NULL,
                    claimed_by = NULL,
                    updated_at = ?,
                    last_error = COALESCE(last_error, 'lease expired; requeued')
                WHERE id = ?
                """,
                (now, now, task_id),
            )
            conn.execute(
                """
                INSERT INTO task_events (task_id, timestamp, status, message, metadata)
                VALUES (?, ?, ?, ?, ?)
                """,
                (task_id, now, "queued", "Lease expired; requeued by scheduler", None),
            )
            recovered += 1
        conn.commit()
        return recovered

    return await _task_db_exec(_recover)


async def requeue_task_for_retry(
    task_id: str,
    *,
    error: str,
    worker: str | None = None,
) -> dict[str, Any] | None:
    now = _task_iso_now()
    error_text = str(error or "task execution failed")[:2000]

    def _requeue(conn: sqlite3.Connection):
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        if not row:
            return None
        attempts = int(row["attempts"] or 0)
        max_attempts = int(row["max_attempts"] or TASK_DEFAULT_MAX_ATTEMPTS)
        terminal_failure = attempts >= max_attempts
        conn.execute("BEGIN IMMEDIATE")
        if terminal_failure:
            next_status = "failed"
            next_run_after = row["run_after"]
            completed_at = now
            message = f"Task failed permanently after {attempts}/{max_attempts} attempts"
        else:
            next_status = "queued"
            delay_secs = _task_retry_delay_secs(attempts)
            next_run_after = _task_iso_after(delay_secs)
            completed_at = None
            message = f"Task requeued after failure (attempt {attempts}/{max_attempts})"
        conn.execute(
            """
            UPDATE tasks
            SET status = ?, run_after = ?, lease_expires_at = NULL, claimed_by = NULL,
                updated_at = ?, completed_at = ?, last_error = ?
            WHERE id = ?
            """,
            (next_status, next_run_after, now, completed_at, error_text, task_id),
        )
        event_metadata = {"worker": worker, "error": error_text}
        conn.execute(
            """
            INSERT INTO task_events (task_id, timestamp, status, message, metadata)
            VALUES (?, ?, ?, ?, ?)
            """,
            (task_id, now, next_status, message, json.dumps(event_metadata)),
        )
        conn.commit()
        updated = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        return _task_row_to_dict(updated)

    task = await _task_db_exec(_requeue)
    if task and task.get("status") == "failed" and TASK_RESULT_WRITEBACK_ENABLED:
        with contextlib.suppress(Exception):
            await _record_task_outcome_memory(task, message="Task failed after retries", metadata={"error": error_text})
    return task


async def claim_next_task(worker: str | None) -> dict[str, Any] | None:
    timestamp = _task_iso_now()
    lease_expires = _task_iso_after(TASK_LEASE_SECS)
    worker_name = str(worker or "external").strip() or "external"
    worker_key = worker_name.lower()
    worker_is_internal = worker_key.startswith("internal-worker")
    await recover_expired_task_leases(limit=25)

    def _claim(conn: sqlite3.Connection):
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT * FROM tasks
            WHERE status IN ('queued', 'approved')
              AND (approval_required = 0 OR approved = 1)
              AND attempts < max_attempts
              AND (run_after IS NULL OR run_after <= ?)
              AND (
                    agent IS NULL
                    OR trim(agent) = ''
                    OR lower(trim(agent)) = 'any'
                    OR lower(trim(agent)) = ?
                    OR (? = 1 AND lower(trim(agent)) = 'internal')
                    OR (? = 0 AND lower(trim(agent)) = 'external')
              )
            ORDER BY priority DESC, run_after ASC, created_at ASC
            LIMIT 1
            """,
            (timestamp, worker_key, int(worker_is_internal), int(worker_is_internal)),
        ).fetchone()
        if not row:
            conn.commit()
            return None
        conn.execute(
            """
            UPDATE tasks
            SET status = ?, updated_at = ?, lease_expires_at = ?, claimed_by = ?, attempts = attempts + 1
            WHERE id = ?
            """,
            ("running", timestamp, lease_expires, worker_name, row["id"]),
        )
        message = f"Claimed by {worker_name}"
        conn.execute(
            """
            INSERT INTO task_events (task_id, timestamp, status, message, metadata)
            VALUES (?, ?, ?, ?, ?)
            """,
            (row["id"], timestamp, "running", message, json.dumps({"worker": worker_name})),
        )
        conn.commit()
        updated = conn.execute("SELECT * FROM tasks WHERE id = ?", (row["id"],)).fetchone()
        return _task_row_to_dict(updated)

    return await _task_db_exec(_claim)


async def _execute_task_action(task: dict[str, Any], worker_name: str) -> dict[str, Any]:
    payload = task.get("payload")
    if not isinstance(payload, dict):
        raise OrchestratorError("task payload missing")
    action = _normalize_task_action(payload.get("action") or task.get("action_type"))
    if not action:
        raise OrchestratorError("task action missing")
    if action not in TASK_ALLOWED_ACTIONS:
        raise OrchestratorError(f"task action '{action}' is not allowed")

    if action == "memory_write":
        write_payload = MemoryWrite(
            projectName=str(payload.get("projectName") or payload.get("project") or task.get("project") or "").strip(),
            fileName=str(payload.get("fileName") or payload.get("file") or "").strip(),
            content=str(payload.get("content") or ""),
            topicPath=(str(payload.get("topic_path") or "").strip() or None),
        )
        result = await write_memory(write_payload, _synthetic_request("/agents/tasks/worker"))
        return {"action": action, "result": result}

    if action == "memory_search":
        search_payload = MemorySearch(
            query=str(payload.get("query") or "").strip(),
            limit=max(1, min(int(payload.get("limit") or 10), 50)),
            project=str(payload.get("project") or task.get("project") or "").strip() or None,
            topic_path=str(payload.get("topic_path") or "").strip() or None,
            fetch_content=bool(payload.get("fetch_content", False)),
            retrieval_mode=str(payload.get("retrieval_mode") or "").strip() or None,
            retrieval_intent=str(payload.get("retrieval_intent") or "").strip() or None,
            sources=payload.get("sources") if isinstance(payload.get("sources"), list) else None,
            source_weights=payload.get("source_weights") if isinstance(payload.get("source_weights"), dict) else None,
            rerank_with_learning=bool(payload.get("rerank_with_learning", True)),
            include_retrieval_debug=bool(payload.get("include_retrieval_debug", False)),
            include_grounding=bool(payload.get("include_grounding", True)),
            user_id=str(payload.get("user_id") or "").strip() or None,
            include_preferences=bool(payload.get("include_preferences", True)),
            agent_id=str(payload.get("agent_id") or task.get("agent") or "").strip() or None,
            auto_escalate=payload.get("auto_escalate")
            if isinstance(payload.get("auto_escalate"), bool)
            else None,
            query_expansion=payload.get("query_expansion")
            if isinstance(payload.get("query_expansion"), bool)
            else None,
            deep_async=False,
            callback_url=None,
        )
        result = await search_memory(search_payload)
        return {"action": action, "result": result}

    if action == "messaging_command":
        channel = str(payload.get("channel") or "custom").strip() or "custom"
        source_id = str(payload.get("source_id") or worker_name).strip() or worker_name
        text = str(payload.get("text") or "").strip()
        if not text:
            raise OrchestratorError("messaging_command text is required")
        parsed = _parse_messaging_command(text, require_prefix=bool(payload.get("require_prefix", False)))
        if parsed is None:
            parsed = {"action": "help", "content": "", "directives": {}, "raw": text}
        result = await _execute_messaging_command(
            parsed,
            channel=channel,
            source_id=source_id,
            default_project=str(payload.get("project") or task.get("project") or MESSAGING_DEFAULT_PROJECT),
            topic_root=str(payload.get("topic_path") or payload.get("topic_root") or f"channels/{channel}"),
            project_override=str(payload.get("project") or "").strip() or None,
            topic_override=str(payload.get("topic_path") or "").strip() or None,
            user_id=str(payload.get("user_id") or "").strip() or None,
        )
        return {"action": action, "result": result}

    if action == "http_callback":
        callback_url = str(payload.get("url") or "").strip()
        _task_validate_callback_url(callback_url)
        method = str(payload.get("method") or "POST").strip().upper()
        body = payload.get("body")
        headers_raw = payload.get("headers")
        headers = {str(k): str(v) for k, v in headers_raw.items()} if isinstance(headers_raw, dict) else {}
        async with httpx.AsyncClient(timeout=TASK_CALLBACK_TIMEOUT_SECS) as client:
            response = await client.request(method, callback_url, json=body, headers=headers)
        return {
            "action": action,
            "status_code": response.status_code,
            "response_text": response.text[:600],
        }

    if action == "provider_chat":
        if not TASK_PROVIDER_CHAT_ENABLED:
            raise OrchestratorError("provider_chat action is disabled")
        endpoint = str(payload.get("url") or TASK_PROVIDER_CHAT_URL).strip()
        if not endpoint:
            raise OrchestratorError("provider_chat endpoint is not configured")
        if endpoint.endswith("/"):
            endpoint = endpoint[:-1]
        if endpoint.endswith("/v1"):
            endpoint = f"{endpoint}/chat/completions"
        elif not endpoint.endswith("/chat/completions"):
            endpoint = f"{endpoint}/v1/chat/completions"
        model = str(payload.get("model") or TASK_PROVIDER_CHAT_MODEL or LETTA_AGENT_MODEL or "").strip()
        if not model:
            raise OrchestratorError("provider_chat model is not configured")
        messages = payload.get("messages")
        if not isinstance(messages, list) or not messages:
            prompt = str(payload.get("prompt") or "").strip()
            if not prompt:
                raise OrchestratorError("provider_chat requires prompt or messages")
            messages = [{"role": "user", "content": prompt}]
        body = {
            "model": model,
            "messages": messages,
            "temperature": float(payload.get("temperature", 0.2)),
        }
        headers = {"content-type": "application/json"}
        if TASK_PROVIDER_CHAT_API_KEY:
            headers["authorization"] = f"Bearer {TASK_PROVIDER_CHAT_API_KEY}"
        async with httpx.AsyncClient(timeout=max(10.0, TASK_CALLBACK_TIMEOUT_SECS)) as client:
            response = await client.post(endpoint, json=body, headers=headers)
        if response.status_code >= 400:
            raise OrchestratorError(f"provider_chat failed: status={response.status_code} body={response.text[:240]}")
        data = response.json() if response.content else {}
        choices = data.get("choices") if isinstance(data, dict) else None
        content = None
        if isinstance(choices, list) and choices:
            first = choices[0]
            if isinstance(first, dict):
                message = first.get("message")
                if isinstance(message, dict):
                    content = message.get("content")
        return {
            "action": action,
            "model": model,
            "content": str(content or "")[:1200],
            "raw": data,
        }

    raise OrchestratorError(f"unsupported task action '{action}'")


async def _record_task_outcome_memory(
    task: dict[str, Any],
    *,
    message: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> None:
    if not TASK_RESULT_WRITEBACK_ENABLED:
        return
    payload = task.get("payload") if isinstance(task.get("payload"), dict) else {}
    project = str(task.get("project") or payload.get("projectName") or payload.get("project") or "").strip()
    if not project:
        return
    task_id = str(task.get("id") or "").strip()
    if not task_id:
        return
    action = str(task.get("action_type") or payload.get("action") or "task").strip().lower()
    topic_path = normalize_topic_path(str(payload.get("topic_path") or f"tasks/{action}"))
    file_name = normalize_memory_path(f"tasks/{task_id}__latest.json")
    outcome_payload = {
        "task_id": task_id,
        "title": task.get("title"),
        "status": task.get("status"),
        "project": project,
        "action": action,
        "attempts": task.get("attempts"),
        "max_attempts": task.get("max_attempts"),
        "message": message,
        "metadata": metadata,
        "result": task.get("result"),
        "updated_at": task.get("updated_at") or _task_iso_now(),
    }
    write_payload = MemoryWrite(
        projectName=project,
        fileName=file_name,
        content=json.dumps(outcome_payload, ensure_ascii=True, sort_keys=True),
        topicPath=topic_path,
    )
    await write_memory(write_payload, _synthetic_request("/agents/tasks/outcome"))


async def _agent_task_worker(worker_index: int) -> None:
    worker_name = f"internal-worker-{worker_index}"
    task_runtime_health["workersRunning"] = int(task_runtime_health.get("workersRunning") or 0) + 1
    try:
        while True:
            task: dict[str, Any] | None = None
            try:
                task = await _scheduler_claim_via_runtime(worker_name)
                if not task:
                    await asyncio.sleep(max(0.2, TASK_WORKER_POLL_SECS))
                    continue
                task_runtime_health["claimed"] = int(task_runtime_health.get("claimed") or 0) + 1
                result = await _execute_task_action(task, worker_name=worker_name)
                await _scheduler_update_via_runtime(
                    task_id=str(task["id"]),
                    status="succeeded",
                    message="Task executed successfully",
                    metadata={"worker": worker_name, "result": result},
                )
                task_runtime_health["succeeded"] = int(task_runtime_health.get("succeeded") or 0) + 1
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                task_runtime_health["lastWorkerError"] = str(exc)[:300]
                if task and task.get("id"):
                    retried = await _scheduler_retry_via_runtime(
                        task_id=str(task["id"]),
                        error=str(exc),
                        worker=worker_name,
                    )
                    if retried and retried.get("status") == "queued":
                        task_runtime_health["retried"] = int(task_runtime_health.get("retried") or 0) + 1
                    else:
                        task_runtime_health["failed"] = int(task_runtime_health.get("failed") or 0) + 1
                else:
                    await asyncio.sleep(max(0.3, TASK_WORKER_POLL_SECS))
    finally:
        task_runtime_health["workersRunning"] = max(0, int(task_runtime_health.get("workersRunning") or 0) - 1)


async def _task_scheduler_worker() -> None:
    task_runtime_health["schedulerRunning"] = True
    try:
        while True:
            try:
                recovered = await recover_expired_task_leases(limit=200)
                task_runtime_health["lastSchedulerTickAt"] = _task_iso_now()
                task_runtime_health["lastSchedulerRecovered"] = recovered
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                task_runtime_health["lastWorkerError"] = str(exc)[:300]
                logger.warning("Task scheduler loop failed: %s", exc)
            await asyncio.sleep(max(0.5, TASK_WORKER_POLL_SECS))
    finally:
        task_runtime_health["schedulerRunning"] = False


_load_override_history()
_load_memory_write_history()
_load_topic_tree()
_load_topic_rollup_index()
if TOPIC_ROLLUP_SQLITE_ENABLED:
    with contextlib.suppress(Exception):
        _topic_rollup_sqlite_sync_sync(topic_rollup_index, source="startup")
_load_agent_memory_profiles()
_load_recall_monitor_history()
_ensure_recall_eval_cases_file()


@app.on_event("startup")
async def orchestrator_startup() -> None:
    global task_scheduler_task, agent_task_worker_tasks
    validate_orchestrator_security_posture()
    if SIGNAL_REFRESH_ENABLED:
        asyncio.create_task(_signal_refresh_loop())
    if OVERRIDE_REFRESH_ENABLED:
        asyncio.create_task(_override_refresh_loop())
    await ensure_task_db()
    if TASK_SCHEDULER_ENABLED and task_scheduler_task is None:
        task_scheduler_task = asyncio.create_task(_task_scheduler_worker(), name="task-scheduler")
    if TASK_INTERNAL_WORKERS_ENABLED and AGENT_TASK_WORKERS > 0 and not agent_task_worker_tasks:
        for idx in range(AGENT_TASK_WORKERS):
            agent_task_worker_tasks.append(
                asyncio.create_task(_agent_task_worker(idx), name=f"task-worker-{idx}")
            )


