def _build_mcp_headers(session_id: str | None = None) -> dict[str, str]:
    headers = dict(MCP_HEADERS)
    if session_id:
        headers[MCP_SESSION_HEADER] = session_id
    return headers


def _extract_mcp_session_id(headers: Any) -> str | None:
    if headers is None or not hasattr(headers, "get"):
        return None
    for key in ("mcp-session-id", "x-mcp-session-id", "Mcp-Session-Id", "X-Mcp-Session-Id"):
        value = headers.get(key)
        if not isinstance(value, str):
            continue
        value = value.strip()
        if value:
            return value
    return None


def _mcp_error_detail_from_response(resp: httpx.Response) -> str:
    text = (resp.text or "").strip()
    if text:
        try:
            payload = json.loads(text)
            if isinstance(payload, dict):
                error = payload.get("error")
                if isinstance(error, dict):
                    message = error.get("message")
                    if isinstance(message, str) and message.strip():
                        return message.strip()
        except json.JSONDecodeError:
            pass
    if text:
        return text[:500]
    return f"Memory MCP HTTP {resp.status_code}"


def _is_mcp_missing_session_error(status_code: int, detail: str) -> bool:
    if status_code not in (400, 401, 404, 422):
        return False
    lowered = (detail or "").lower()
    return (
        "no valid session id" in lowered
        or "no valid session-id" in lowered
        or "session id required" in lowered
        or "invalid session id" in lowered
        or "session not found" in lowered
    )


def _extract_mcp_payload(resp: httpx.Response) -> dict[str, Any]:
    event_payload: dict[str, Any] | None = None
    text = resp.text or ""
    for line in text.splitlines():
        line = line.strip()
        if not line.startswith("data:"):
            continue
        raw = line[5:].strip()
        if not raw:
            continue
        try:
            candidate = json.loads(raw)
        except json.JSONDecodeError:
            continue
        if isinstance(candidate, dict):
            event_payload = candidate
    if event_payload is not None:
        return event_payload
    try:
        payload = resp.json()
        if isinstance(payload, dict):
            return payload
    except Exception:
        pass
    if text:
        raise HTTPException(502, f"Unable to parse MCP response payload: {text[:300]}")
    raise HTTPException(502, "No MCP response payload")


async def _post_mcp_request(
    payload: dict[str, Any],
    session_id: str | None = None,
) -> httpx.Response:
    last_error: Exception | None = None
    for attempt in range(1, max(CONTEXTLATTICE_HTTP_RETRIES, 1) + 1):
        try:
            headers = _build_mcp_headers(session_id=session_id)
            client = MCP_CLIENT
            if client is None:
                async with httpx.AsyncClient(timeout=MCP_CLIENT_TIMEOUT) as temp_client:
                    resp = await temp_client.post(
                        CONTEXTLATTICE_HTTP_URL, json=payload, headers=headers
                    )
            else:
                resp = await client.post(CONTEXTLATTICE_HTTP_URL, json=payload, headers=headers)
            return resp
        except httpx.ReadTimeout as err:
            last_error = err
            if attempt >= CONTEXTLATTICE_HTTP_RETRIES:
                raise HTTPException(504, "Memory MCP timeout") from err
            await asyncio.sleep(CONTEXTLATTICE_HTTP_RETRY_DELAY_SECS * attempt)
        except httpx.HTTPError as err:
            last_error = err
            if attempt >= CONTEXTLATTICE_HTTP_RETRIES:
                raise HTTPException(502, f"Memory MCP error: {err}") from err
            await asyncio.sleep(CONTEXTLATTICE_HTTP_RETRY_DELAY_SECS * attempt)
    raise HTTPException(502, f"Memory MCP error: {last_error}")


def _invalidate_mcp_session() -> None:
    global MCP_SESSION_ID
    MCP_SESSION_ID = None


async def _ensure_mcp_session(force_refresh: bool = False) -> str:
    global MCP_SESSION_ID
    if MCP_SESSION_ID and not force_refresh:
        return MCP_SESSION_ID
    async with mcp_session_lock:
        if MCP_SESSION_ID and not force_refresh:
            return MCP_SESSION_ID
        if force_refresh:
            MCP_SESSION_ID = None
        init_payload = {
            "jsonrpc": "2.0",
            "id": str(uuid.uuid4()),
            "method": "initialize",
            "params": {
                "protocolVersion": MCP_HEADERS.get("MCP-Protocol-Version", "2024-11-05"),
                "capabilities": {},
                "clientInfo": {"name": MCP_CLIENT_NAME, "version": MCP_CLIENT_VERSION},
            },
        }
        resp = await _post_mcp_request(init_payload, session_id=None)
        detail = _mcp_error_detail_from_response(resp)
        if resp.status_code != 200:
            raise HTTPException(resp.status_code, detail)
        session_id = _extract_mcp_session_id(resp.headers)
        if not session_id:
            init_response = _extract_mcp_payload(resp)
            maybe_result = init_response.get("result") if isinstance(init_response, dict) else None
            if isinstance(maybe_result, dict):
                for key in ("sessionId", "session_id"):
                    value = maybe_result.get(key)
                    if isinstance(value, str) and value.strip():
                        session_id = value.strip()
                        break
        if not session_id:
            raise HTTPException(502, "Memory MCP initialize did not return a session id")
        MCP_SESSION_ID = session_id
        initialized_payload = {"jsonrpc": "2.0", "method": "notifications/initialized", "params": {}}
        with contextlib.suppress(Exception):
            await _post_mcp_request(initialized_payload, session_id=session_id)
        return session_id


async def _call_mcp(payload: dict[str, Any]) -> dict[str, Any]:
    global MCP_SESSION_ID
    for attempt in range(2):
        session_id = await _ensure_mcp_session(force_refresh=attempt > 0)
        resp = await _post_mcp_request(payload, session_id=session_id)
        refreshed_session_id = _extract_mcp_session_id(resp.headers)
        if refreshed_session_id and refreshed_session_id != MCP_SESSION_ID:
            MCP_SESSION_ID = refreshed_session_id
        detail = _mcp_error_detail_from_response(resp)
        if resp.status_code != 200:
            if _is_mcp_missing_session_error(resp.status_code, detail):
                _invalidate_mcp_session()
                continue
            raise HTTPException(resp.status_code, detail)
        data = _extract_mcp_payload(resp)
        if "error" in data:
            error_payload = data.get("error")
            error_text = (
                error_payload
                if isinstance(error_payload, str)
                else json.dumps(error_payload, ensure_ascii=True)
            )
            if _is_mcp_missing_session_error(400, error_text):
                _invalidate_mcp_session()
                continue
            raise HTTPException(500, f"MCP error: {error_payload}")
        result = data.get("result")
        if result is None:
            raise HTTPException(500, "No MCP response data")
        return result
    raise HTTPException(502, "Memory MCP session invalid and refresh failed")


def _mcp_content_entries(content: Any) -> list[Any]:
    if isinstance(content, list):
        return content
    if content is None:
        return []
    return [content]


def _extract_mcp_text_chunks(content: Any) -> list[str]:
    chunks: list[str] = []
    if isinstance(content, str):
        if content:
            chunks.append(content)
        return chunks
    if isinstance(content, list):
        for item in content:
            chunks.extend(_extract_mcp_text_chunks(item))
        return chunks
    if isinstance(content, dict):
        text = content.get("text")
        if isinstance(text, str) and text:
            chunks.append(text)
        # Some adapters wrap tool output under nested content/data fields.
        nested_content = content.get("content")
        if nested_content is not None:
            chunks.extend(_extract_mcp_text_chunks(nested_content))
        nested_data = content.get("data")
        if nested_data is not None and nested_data is not nested_content:
            chunks.extend(_extract_mcp_text_chunks(nested_data))
    return chunks


def _mcp_result_error_message(result: dict[str, Any]) -> str | None:
    if not result.get("isError"):
        return None
    text_chunks = _extract_mcp_text_chunks(result.get("content"))
    for chunk in text_chunks:
        text = chunk.strip()
        if not text:
            continue
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError:
            return text
        if isinstance(parsed, dict):
            detail = parsed.get("error") or parsed.get("message") or parsed.get("detail")
            name = parsed.get("name")
            if isinstance(detail, str) and detail:
                if isinstance(name, str) and name:
                    return f"{name}: {detail}"
                return detail
        return text
    return "MCP tool returned isError=true"


def _coerce_mcp_name_tokens(value: Any) -> list[str]:
    tokens: list[str] = []

    def _append(raw: str) -> None:
        token = raw.strip()
        if token:
            tokens.append(token)

    if isinstance(value, str):
        text = value.strip()
        if not text:
            return []
        # Tool adapters may serialize JSON into the text field.
        if text.startswith("{") or text.startswith("["):
            try:
                parsed = json.loads(text)
            except json.JSONDecodeError:
                parsed = None
            if parsed is not None and parsed is not value:
                return _coerce_mcp_name_tokens(parsed)
        if "," in text or "\n" in text:
            for part in re.split(r"[\n,]", text):
                _append(part)
            return tokens
        _append(text)
        return tokens

    if isinstance(value, list):
        for item in value:
            tokens.extend(_coerce_mcp_name_tokens(item))
        return tokens

    if isinstance(value, dict):
        if any(
            isinstance(value.get(key), str) and value.get(key).strip()
            for key in ("error", "message", "detail")
        ):
            return []
        for key in ("name", "file", "fileName", "path", "project", "projectName"):
            candidate = value.get(key)
            if isinstance(candidate, str):
                _append(candidate)
        for key in ("text", "value", "content"):
            if key in value:
                tokens.extend(_coerce_mcp_name_tokens(value.get(key)))
        return tokens

    return tokens


def _parse_mcp_name_list(result: dict[str, Any]) -> list[str]:
    names: list[str] = []
    for entry in _mcp_content_entries(result.get("content")):
        names.extend(_coerce_mcp_name_tokens(entry))
    # Preserve order while removing duplicates.
    deduped: list[str] = []
    seen: set[str] = set()
    for name in names:
        normalized = name.strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        deduped.append(normalized)
    return deduped


def _normalize_retrieval_sources(
    sources: list[str] | None,
    *,
    explicit_source_override: bool | None = None,
) -> list[str]:
    explicit_override = (
        bool(explicit_source_override)
        if explicit_source_override is not None
        else bool(sources is not None)
    )
    if sources:
        requested = [str(item).strip().lower() for item in sources if str(item).strip()]
    else:
        requested = [item.strip().lower() for item in RETRIEVAL_SOURCES_ENV.split(",") if item.strip()]
    normalized: list[str] = []
    seen: set[str] = set()
    for source in requested:
        if source not in RETRIEVAL_SOURCES or source in seen:
            continue
        seen.add(source)
        normalized.append(source)
    normalized = _apply_memory_bank_default_source_policy(
        normalized,
        explicit_override=explicit_override,
    )
    if not normalized:
        normalized = [RETRIEVAL_SOURCE_QDRANT]
    return normalized


def _normalize_retrieval_weights(
    custom_weights: dict[str, float] | None,
) -> dict[str, float]:
    weights = dict(DEFAULT_RETRIEVAL_SOURCE_WEIGHTS)
    if not custom_weights:
        return weights
    for source, value in custom_weights.items():
        key = str(source).strip().lower()
        if key not in RETRIEVAL_SOURCES:
            continue
        try:
            score = float(value)
        except (TypeError, ValueError):
            continue
        weights[key] = max(0.0, min(score, 2.0))
    return weights


def _normalize_project_key(project: str | None) -> str:
    return str(project or "").strip().lower()


def _resolve_project_alias(project: str | None, max_hops: int = 6) -> tuple[str | None, list[dict[str, str]]]:
    current = str(project or "").strip()
    if not current:
        return None, []
    hops: list[dict[str, str]] = []
    visited: set[str] = set()
    while len(hops) < max(1, int(max_hops)):
        key = _normalize_project_key(current)
        if not key or key in visited:
            break
        visited.add(key)
        target = str(PROJECT_ALIAS_MAP.get(key) or "").strip()
        if not target:
            break
        hops.append({"from": current, "to": target})
        current = target
    return current or None, hops


def _resolve_project_case_insensitive(project: str | None, candidates: list[str]) -> str | None:
    key = _normalize_project_key(project)
    if not key:
        return None
    by_key = {_normalize_project_key(item): item for item in candidates if str(item).strip()}
    return by_key.get(key)


def _suggest_similar_projects(
    requested_project: str | None,
    candidates: list[str],
    *,
    limit: int = PROJECT_SUGGESTION_LIMIT,
) -> list[str]:
    requested = str(requested_project or "").strip()
    if not requested:
        return []
    requested_key = _normalize_project_key(requested)
    scored: list[tuple[float, str]] = []
    seen: set[str] = set()
    for candidate in candidates:
        candidate_name = str(candidate or "").strip()
        if not candidate_name or candidate_name in seen:
            continue
        seen.add(candidate_name)
        candidate_key = _normalize_project_key(candidate_name)
        ratio = difflib.SequenceMatcher(None, requested_key, candidate_key).ratio()
        substring_bonus = 0.18 if requested_key in candidate_key or candidate_key in requested_key else 0.0
        score = ratio + substring_bonus
        if score < PROJECT_SUGGESTION_MIN_SIMILARITY and substring_bonus <= 0.0:
            continue
        scored.append((score, candidate_name))
    scored.sort(key=lambda item: (item[0], -len(item[1])), reverse=True)
    return [name for _, name in scored[: max(1, int(limit))]]


def _query_targets_low_value_paths(query: str) -> bool:
    tokens = _query_terms(query, max_terms=14)
    if not tokens:
        return False
    lookup = set(RETRIEVAL_LOW_VALUE_BYPASS_TERMS)
    for token in tokens:
        if token in lookup:
            return True
        for candidate in lookup:
            if token.startswith(candidate) or candidate.startswith(token):
                return True
    return False


def _looks_like_trading_project(project: str | None) -> bool:
    normalized = _normalize_project_key(project)
    if not normalized:
        return False
    for hint in TRADING_PROJECT_HINTS:
        token = _normalize_project_key(hint)
        if not token:
            continue
        if normalized == token or token in normalized or normalized in token:
            return True
    return False


def _row_topic_path(row: dict[str, Any]) -> str:
    topic_path = normalize_topic_path(str(row.get("topic_path") or ""))
    if topic_path:
        return topic_path
    return derive_topic_path(str(row.get("file") or ""), None)


def _row_matches_any_topic_prefix(row: dict[str, Any], prefixes: list[str]) -> bool:
    if not prefixes:
        return True
    topic_path = _row_topic_path(row)
    if not topic_path:
        return False
    for prefix in prefixes:
        normalized_prefix = normalize_topic_path(str(prefix or ""))
        if not normalized_prefix:
            continue
        if topic_path == normalized_prefix or topic_path.startswith(f"{normalized_prefix}/"):
            return True
    return False


def _query_terms(query: str, max_terms: int = 8) -> list[str]:
    terms: list[str] = []
    seen: set[str] = set()
    for token in re.findall(r"[A-Za-z0-9_:/.-]{3,}", query.lower()):
        if token in seen:
            continue
        seen.add(token)
        terms.append(token)
        if len(terms) >= max_terms:
            break
    return terms


def _text_match_score(query: str, text: str) -> float:
    query_text = (query or "").strip().lower()
    body = (text or "").lower()
    if not query_text or not body:
        return 0.0
    if query_text in body:
        # Full phrase matches are strongly preferred.
        return 1.0
    terms = _query_terms(query_text, max_terms=10)
    if not terms:
        return 0.0
    hits = sum(1 for term in terms if term in body)
    if hits <= 0:
        return 0.0
    density = min(1.0, len(body) / 4000.0)
    return min(0.95, (hits / max(1, len(terms))) * (0.55 + 0.45 * density))


def _next_retrieval_mode(mode: str) -> str:
    normalized = _normalize_retrieval_mode(mode)
    if normalized == RETRIEVAL_MODE_FAST:
        return RETRIEVAL_MODE_BALANCED
    return RETRIEVAL_MODE_DEEP


def _expand_query_variants(query: str) -> list[str]:
    normalized = re.sub(r"\s+", " ", str(query or "").strip())
    if not normalized:
        return []
    variants: list[str] = [normalized]
    seen = {normalized.lower()}
    if not RETRIEVAL_QUERY_EXPANSION_ENABLED:
        return variants
    if " " in normalized and "/" not in normalized:
        for candidate in (normalized.replace(" ", "/"), normalized.replace(" ", "_")):
            key = candidate.lower()
            if key in seen:
                continue
            seen.add(key)
            variants.append(candidate)
            if len(variants) >= RETRIEVAL_QUERY_EXPANSION_MAX_VARIANTS:
                return variants
    terms = _query_terms(normalized, max_terms=RETRIEVAL_QUERY_EXPANSION_MAX_TERMS)
    for token in terms:
        synonyms = RETRIEVAL_QUERY_SYNONYM_MAP.get(token, [])
        if not synonyms:
            continue
        for synonym in synonyms:
            candidate = re.sub(
                rf"\b{re.escape(token)}\b",
                synonym,
                normalized,
                count=1,
                flags=re.IGNORECASE,
            )
            candidate = re.sub(r"\s+", " ", candidate).strip()
            if not candidate:
                continue
            key = candidate.lower()
            if key in seen:
                continue
            seen.add(key)
            variants.append(candidate)
            if len(variants) >= RETRIEVAL_QUERY_EXPANSION_MAX_VARIANTS:
                return variants
    return variants


def _result_timestamp_iso(row: dict[str, Any]) -> str | None:
    parsed = _parse_timestamp_to_datetime(row.get("created_at") or row.get("updated_at"))
    if parsed is None:
        return None
    return parsed.isoformat().replace("+00:00", "Z")


def _is_result_stale(row: dict[str, Any]) -> bool:
    parsed = _parse_timestamp_to_datetime(row.get("created_at") or row.get("updated_at"))
    if parsed is None:
        return False
    cutoff = datetime.now(timezone.utc) - timedelta(hours=max(1.0, RECALL_STALE_HOURS))
    return parsed < cutoff


def _extract_numeric_values_verbatim(text: str, limit: int = RECALL_NUMERIC_FACTS_MAX) -> list[str]:
    values: list[str] = []
    seen: set[str] = set()
    for match in re.finditer(r"(?<![A-Za-z0-9_])[-+]?\$?\d[\d,]*(?:\.\d+)?%?", str(text or "")):
        token = str(match.group(0) or "").strip()
        if not token or token in seen:
            continue
        seen.add(token)
        values.append(token)
        if len(values) >= max(1, int(limit)):
            break
    return values


def _build_grounding_payload(results: list[dict[str, Any]]) -> dict[str, Any]:
    facts: list[dict[str, Any]] = []
    numeric_facts: list[dict[str, Any]] = []
    fact_limit = max(1, min(len(results), 64))
    numeric_seen: set[str] = set()
    for index, row in enumerate(results[:fact_limit], start=1):
        summary = _topic_rollup_sanitize_text(
            str(row.get("summary") or ""),
            max_chars=RECALL_GROUNDING_SNIPPET_CHARS,
        )
        if not summary:
            continue
        source = {
            "project": row.get("project"),
            "file": row.get("file"),
            "source": row.get("source"),
            "topic_path": row.get("topic_path"),
            "timestamp": _result_timestamp_iso(row),
        }
        numeric_values = _extract_numeric_values_verbatim(summary)
        fact = {
            "id": f"fact_{index}",
            "fact": summary,
            "snippet": summary,
            "score": float(row.get("score") or 0.0),
            "source": source,
            "numeric_values": numeric_values,
        }
        facts.append(fact)
        for value in numeric_values:
            key = "|".join(
                [
                    value,
                    str(source.get("project") or ""),
                    str(source.get("file") or ""),
                    summary,
                ]
            )
            if key in numeric_seen:
                continue
            numeric_seen.add(key)
            numeric_facts.append(
                {
                    "value": value,
                    "snippet": summary,
                    "source": dict(source),
                    "verbatim": True,
                }
            )
            if len(numeric_facts) >= RECALL_NUMERIC_FACTS_MAX:
                break
        if len(numeric_facts) >= RECALL_NUMERIC_FACTS_MAX:
            continue
    return {
        "strict_numeric_copy": True,
        "facts": facts,
        "numeric_facts": numeric_facts,
    }


def _normalize_expected_file_token(file_name: str) -> str:
    normalized = normalize_memory_path(str(file_name or "")).strip().lower()
    return normalized


def _result_hits_expectations(
    row: dict[str, Any],
    expected_files: set[str],
    expected_terms: list[str],
) -> bool:
    row_file = _normalize_expected_file_token(str(row.get("file") or ""))
    if row_file and expected_files:
        for candidate in expected_files:
            if row_file == candidate or row_file.endswith(candidate):
                return True
    if expected_terms:
        summary = str(row.get("summary") or "").strip().lower()
        project = str(row.get("project") or "").strip().lower()
        source = str(row.get("source") or "").strip().lower()
        haystack = "\n".join([row_file, project, source, summary])
        for token in expected_terms:
            if token and token in haystack:
                return True
    return False


def _match_rank_within_k(
    results: list[dict[str, Any]],
    expected_files: set[str],
    expected_terms: list[str],
    k: int,
) -> int | None:
    if not expected_files and not expected_terms:
        return None
    for index, row in enumerate(results[: max(1, int(k))], start=1):
        if not isinstance(row, dict):
            continue
        if _result_hits_expectations(row, expected_files, expected_terms):
            return index
    return None


def _grounding_numeric_value_set(grounding: dict[str, Any]) -> set[str]:
    values: set[str] = set()
    rows = grounding.get("numeric_facts") if isinstance(grounding, dict) else []
    if not isinstance(rows, list):
        return values
    for row in rows:
        if not isinstance(row, dict):
            continue
        value = str(row.get("value") or "").strip()
        if value:
            values.add(value)
    return values


RECALL_EVAL_TRANSIENT_ERROR_MARKERS = (
    "timed out",
    "timeout",
    "deferred",
    "call budget exhausted",
    "temporarily unavailable",
    "service unavailable",
    "gateway timeout",
    "upstream",
    "connection reset",
    "connection aborted",
    "connection refused",
    "rate limit",
    "status=429",
    "status=503",
    "status=504",
)


def _recall_eval_response_has_transient_failure(search_response: dict[str, Any]) -> bool:
    messages: list[str] = []
    warnings = search_response.get("warnings")
    if isinstance(warnings, list):
        messages.extend(str(item or "") for item in warnings)
    retrieval = search_response.get("retrieval")
    if isinstance(retrieval, dict):
        source_errors = retrieval.get("source_errors")
        if isinstance(source_errors, dict):
            messages.extend(str(item or "") for item in source_errors.values())
    for raw in messages:
        text = str(raw or "").strip().lower()
        if not text:
            continue
        if any(marker in text for marker in RECALL_EVAL_TRANSIENT_ERROR_MARKERS):
            return True
    return False


def _recall_eval_retry_modes(primary_mode: str | None) -> list[str]:
    if RECALL_EVAL_TRANSIENT_RETRY_MAX_ATTEMPTS <= 0:
        return []
    configured = [
        token.strip()
        for token in RECALL_EVAL_TRANSIENT_RETRY_MODES_ENV.split(",")
        if token.strip()
    ]
    if not configured:
        configured = [RETRIEVAL_MODE_BALANCED, RETRIEVAL_MODE_DEEP]
    normalized_primary = _normalize_retrieval_mode(primary_mode)
    allowed = {RETRIEVAL_MODE_FAST, RETRIEVAL_MODE_BALANCED, RETRIEVAL_MODE_DEEP}
    retry_modes: list[str] = []
    seen: set[str] = {normalized_primary}
    for token in configured:
        normalized = _normalize_retrieval_mode(token)
        if normalized not in allowed or normalized in seen:
            continue
        seen.add(normalized)
        retry_modes.append(normalized)
        if len(retry_modes) >= RECALL_EVAL_TRANSIENT_RETRY_MAX_ATTEMPTS:
            break
    return retry_modes


def _build_context_pack_payload(
    *,
    query: str,
    search_response: dict[str, Any],
    max_facts: int,
    max_results: int,
) -> dict[str, Any]:
    results = search_response.get("results")
    if not isinstance(results, list):
        results = []
    grounding = search_response.get("grounding")
    if not isinstance(grounding, dict):
        grounding = {"facts": [], "numeric_facts": [], "strict_numeric_copy": True}
    facts = grounding.get("facts") if isinstance(grounding.get("facts"), list) else []
    numeric_facts = (
        grounding.get("numeric_facts")
        if isinstance(grounding.get("numeric_facts"), list)
        else []
    )
    citations: list[dict[str, Any]] = []
    seen_citations: set[str] = set()
    for fact in facts[: max(1, int(max_facts))]:
        if not isinstance(fact, dict):
            continue
        source = fact.get("source") if isinstance(fact.get("source"), dict) else {}
        project = str(source.get("project") or "").strip()
        file_name = str(source.get("file") or "").strip()
        key = f"{project}:{file_name}:{source.get('timestamp')}"
        if key in seen_citations:
            continue
        seen_citations.add(key)
        citations.append(
            {
                "project": project or None,
                "file": file_name or None,
                "source": source.get("source"),
                "topic_path": source.get("topic_path"),
                "timestamp": source.get("timestamp"),
            }
        )
    result_rows: list[dict[str, Any]] = []
    for row in results[: max(1, int(max_results))]:
        if not isinstance(row, dict):
            continue
        rendered_row = {
            "project": row.get("project"),
            "file": row.get("file"),
            "source": row.get("source"),
            "score": float(row.get("score") or 0.0),
            "topic_path": row.get("topic_path"),
            "timestamp": _result_timestamp_iso(row),
            "summary": _topic_rollup_sanitize_text(
                str(row.get("summary") or ""),
                max_chars=RECALL_GROUNDING_SNIPPET_CHARS,
            ),
        }
        topic_rollup = row.get("topic_rollup") if isinstance(row.get("topic_rollup"), dict) else None
        if isinstance(topic_rollup, dict):
            raw_refs = [
                str(item)
                for item in (topic_rollup.get("raw_refs") if isinstance(topic_rollup.get("raw_refs"), list) else [])
                if str(item).strip()
            ][:TOPIC_ROLLUP_RAW_REFS_MAX]
            file_partitions = []
            if isinstance(topic_rollup.get("file_partitions"), list):
                for partition in topic_rollup.get("file_partitions"):
                    if not isinstance(partition, dict):
                        continue
                    file_partitions.append(
                        {
                            "topic_path": str(partition.get("topic_path") or DEFAULT_TOPIC_ROOT),
                            "file_count": int(partition.get("file_count") or 0),
                            "sample_files": [
                                str(item)
                                for item in (
                                    partition.get("sample_files")
                                    if isinstance(partition.get("sample_files"), list)
                                    else []
                                )
                                if str(item).strip()
                            ][:TOPIC_ROLLUP_RAW_REFS_MAX],
                        }
                    )
            rendered_row["topic_rollup"] = {
                "event_count": int(topic_rollup.get("event_count") or 0),
                "recent_event_count": int(topic_rollup.get("recent_event_count") or 0),
                "unique_file_count": int(topic_rollup.get("unique_file_count") or 0),
                "latest_timestamp": topic_rollup.get("latest_timestamp"),
                "raw_refs": raw_refs,
                "file_partitions": file_partitions,
            }
            for raw_file in raw_refs:
                key = f"{row.get('project')}:{raw_file}:rollup"
                if key in seen_citations:
                    continue
                seen_citations.add(key)
                citations.append(
                    {
                        "project": row.get("project"),
                        "file": raw_file,
                        "source": "topic_rollup_raw_ref",
                        "topic_path": row.get("topic_path"),
                        "timestamp": topic_rollup.get("latest_timestamp"),
                    }
                )
            for partition in file_partitions:
                partition_path = str(partition.get("topic_path") or DEFAULT_TOPIC_ROOT)
                for file_name in partition.get("sample_files", []):
                    sample_file = str(file_name or "").strip()
                    if not sample_file:
                        continue
                    key = f"{row.get('project')}:{sample_file}:{partition_path}:rollup_partition"
                    if key in seen_citations:
                        continue
                    seen_citations.add(key)
                    citations.append(
                        {
                            "project": row.get("project"),
                            "file": sample_file,
                            "source": "topic_rollup_partition_ref",
                            "topic_path": partition_path,
                            "timestamp": topic_rollup.get("latest_timestamp"),
                        }
                    )
        result_rows.append(rendered_row)
    return {
        "query": query,
        "generatedAt": _utc_now(),
        "factualOnly": True,
        "strictNumericCopy": bool(grounding.get("strict_numeric_copy", True)),
        "facts": facts[: max(1, int(max_facts))],
        "numericFacts": numeric_facts[: max(1, int(max_facts))],
        "citations": citations,
        "results": result_rows,
        "warnings": search_response.get("warnings") if isinstance(search_response.get("warnings"), list) else [],
        "retrievalMode": search_response.get("retrieval_mode"),
        "retrievalIntent": search_response.get("retrieval_intent"),
        "agentId": search_response.get("agent_id"),
    }


def _continuity_snapshot_storage_path(project: str, snapshot_id: str) -> Path:
    project_token = _slug_token(project, fallback="project", max_len=64)
    safe_snapshot = re.sub(r"[^a-f0-9]", "", str(snapshot_id).lower())[:64] or "snapshot"
    return CONTINUITY_SNAPSHOT_DIR / project_token / f"{safe_snapshot}.json"


def _continuity_snapshot_row_to_dict(row: sqlite3.Row) -> dict[str, Any]:
    metadata: dict[str, Any] = {}
    raw_metadata = row["metadata"] if "metadata" in row.keys() else None
    if isinstance(raw_metadata, str) and raw_metadata.strip():
        try:
            parsed = json.loads(raw_metadata)
            if isinstance(parsed, dict):
                metadata = parsed
        except Exception:
            metadata = {}
    return {
        "snapshot_id": row["snapshot_id"],
        "created_at": row["created_at"],
        "project": row["project"],
        "topic_path": row["topic_path"],
        "query": row["query"],
        "label": row["label"],
        "content_hash": row["content_hash"],
        "file_path": row["file_path"],
        "retrieval_mode": row["retrieval_mode"],
        "retrieval_intent": row["retrieval_intent"],
        "agent_id": row["agent_id"],
        "metadata": metadata,
    }


async def _continuity_snapshot_index_get(snapshot_id: str) -> dict[str, Any] | None:
    snapshot_id = re.sub(r"[^a-f0-9]", "", str(snapshot_id or "").lower())[:64]
    if not snapshot_id:
        return None

    def _get(conn: sqlite3.Connection) -> dict[str, Any] | None:
        row = conn.execute(
            """
            SELECT snapshot_id, created_at, project, topic_path, query, label,
                   content_hash, file_path, retrieval_mode, retrieval_intent, agent_id, metadata
            FROM continuity_snapshots
            WHERE snapshot_id = ?
            LIMIT 1
            """,
            (snapshot_id,),
        ).fetchone()
        if row is None:
            return None
        return _continuity_snapshot_row_to_dict(row)

    return await _task_db_exec(_get)


async def _continuity_snapshot_index_insert(entry: dict[str, Any]) -> dict[str, Any]:
    def _insert(conn: sqlite3.Connection) -> dict[str, Any]:
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            INSERT OR IGNORE INTO continuity_snapshots(
                snapshot_id, created_at, project, topic_path, query, label, content_hash, file_path,
                retrieval_mode, retrieval_intent, agent_id, metadata
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                entry["snapshot_id"],
                entry["created_at"],
                entry["project"],
                entry.get("topic_path"),
                entry["query"],
                entry.get("label"),
                entry["content_hash"],
                entry["file_path"],
                entry.get("retrieval_mode"),
                entry.get("retrieval_intent"),
                entry.get("agent_id"),
                json.dumps(entry.get("metadata") or {}, separators=(",", ":"), sort_keys=True),
            ),
        )
        conn.commit()
        row = conn.execute(
            """
            SELECT snapshot_id, created_at, project, topic_path, query, label,
                   content_hash, file_path, retrieval_mode, retrieval_intent, agent_id, metadata
            FROM continuity_snapshots
            WHERE snapshot_id = ?
            LIMIT 1
            """,
            (entry["snapshot_id"],),
        ).fetchone()
        if row is None:
            raise OrchestratorError("continuity snapshot index insert failed")
        return _continuity_snapshot_row_to_dict(row)

    return await _task_db_exec(_insert)


async def _continuity_snapshot_index_list(
    *,
    project: str | None,
    topic_prefix: str | None,
    limit: int,
) -> list[dict[str, Any]]:
    limit = max(1, min(int(limit or 20), 200))

    def _list(conn: sqlite3.Connection) -> list[dict[str, Any]]:
        clauses: list[str] = []
        params: list[Any] = []
        if project:
            clauses.append("project = ?")
            params.append(project)
        if topic_prefix:
            clauses.append("topic_path LIKE ?")
            params.append(f"{topic_prefix}%")
        where_clause = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        rows = conn.execute(
            f"""
            SELECT snapshot_id, created_at, project, topic_path, query, label,
                   content_hash, file_path, retrieval_mode, retrieval_intent, agent_id, metadata
            FROM continuity_snapshots
            {where_clause}
            ORDER BY created_at DESC
            LIMIT ?
            """,
            (*params, limit),
        ).fetchall()
        return [_continuity_snapshot_row_to_dict(row) for row in rows]

    return await _task_db_exec(_list)


def _write_continuity_snapshot_file(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = path.with_suffix(path.suffix + ".tmp")
    rendered = json.dumps(payload, indent=2, ensure_ascii=False)
    temp_path.write_text(rendered, encoding="utf-8")
    temp_path.replace(path)


def _read_continuity_snapshot_file(path: Path) -> dict[str, Any] | None:
    if not path.exists() or not path.is_file():
        return None
    try:
        raw = path.read_text(encoding="utf-8")
        parsed = json.loads(raw)
    except Exception:
        return None
    return parsed if isinstance(parsed, dict) else None


def _top_result_score(results: list[dict[str, Any]]) -> float:
    if not results:
        return 0.0
    return max(float(row.get("score") or 0.0) for row in results if isinstance(row, dict))


def _recall_should_escalate(
    *,
    results: list[dict[str, Any]],
    min_results: int,
    min_top_score: float,
) -> bool:
    if len(results) < max(1, int(min_results)):
        return True
    top_score = _top_result_score(results)
    return top_score < min(1.0, max(0.0, float(min_top_score)))


def _merge_ranked_result_sets(result_sets: list[list[dict[str, Any]]], limit: int) -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    for rows in result_sets:
        for row in rows:
            if not isinstance(row, dict):
                continue
            key = _result_identity(row)
            existing = merged.get(key)
            if existing is None or float(row.get("score") or 0.0) > float(existing.get("score") or 0.0):
                merged[key] = dict(row)
    ordered = list(merged.values())
    ordered.sort(
        key=lambda row: (
            float(row.get("score") or 0.0),
            float(row.get("base_score") or 0.0),
        ),
        reverse=True,
    )
    return ordered[: max(1, int(limit))]


async def _record_recall_quality_observation(
    *,
    results: list[dict[str, Any]],
    retrieval_debug: dict[str, Any],
    traffic_class: str = TRAFFIC_CLASS_USER,
) -> None:
    global recall_quality_updated_at
    top_score = _top_result_score(results)
    no_hit = not results
    low_confidence = top_score < RECALL_LOW_CONFIDENCE_SCORE
    stale_hit = bool(results) and _is_result_stale(results[0])
    source_errors = retrieval_debug.get("source_errors") if isinstance(retrieval_debug, dict) else {}
    source_counts = retrieval_debug.get("source_counts") if isinstance(retrieval_debug, dict) else {}
    class_name = _normalize_traffic_class(traffic_class)
    source_error_kinds: dict[str, str] = {}
    async with recall_quality_lock:
        recall_quality_totals["requests"] = int(recall_quality_totals.get("requests", 0) or 0) + 1
        if no_hit:
            recall_quality_totals["noHit"] = int(recall_quality_totals.get("noHit", 0) or 0) + 1
        if low_confidence:
            recall_quality_totals["lowConfidence"] = int(recall_quality_totals.get("lowConfidence", 0) or 0) + 1
        if stale_hit:
            recall_quality_totals["staleHit"] = int(recall_quality_totals.get("staleHit", 0) or 0) + 1
        class_totals = recall_quality_totals_by_class.setdefault(
            class_name,
            {"requests": 0, "noHit": 0, "lowConfidence": 0, "staleHit": 0},
        )
        class_totals["requests"] = int(class_totals.get("requests", 0) or 0) + 1
        if no_hit:
            class_totals["noHit"] = int(class_totals.get("noHit", 0) or 0) + 1
        if low_confidence:
            class_totals["lowConfidence"] = int(class_totals.get("lowConfidence", 0) or 0) + 1
        if stale_hit:
            class_totals["staleHit"] = int(class_totals.get("staleHit", 0) or 0) + 1
        if isinstance(source_counts, dict):
            for source, count in source_counts.items():
                source_name = str(source or "").strip().lower()
                if not source_name:
                    continue
                delta = max(0, int(count or 0))
                recall_quality_source_requests[source_name] = int(
                    recall_quality_source_requests.get(source_name, 0) or 0
                ) + delta
                class_requests = recall_quality_source_requests_by_class.setdefault(class_name, {})
                class_requests[source_name] = int(class_requests.get(source_name, 0) or 0) + delta
        if isinstance(source_errors, dict):
            for source, error_text in source_errors.items():
                source_name = str(source or "").strip().lower()
                if not source_name:
                    continue
                detail = _normalize_source_error_detail(error_text)
                kind = str(detail.get("kind") or "").strip().lower()
                if not str(detail.get("error") or "").strip():
                    continue
                source_error_kinds[source_name] = kind or "unknown"
                if kind == "budget_exceeded":
                    recall_quality_source_budget_exceeded[source_name] = int(
                        recall_quality_source_budget_exceeded.get(source_name, 0) or 0
                    ) + 1
                    class_budget = recall_quality_source_budget_exceeded_by_class.setdefault(class_name, {})
                    class_budget[source_name] = int(class_budget.get(source_name, 0) or 0) + 1
                else:
                    recall_quality_source_errors[source_name] = int(
                        recall_quality_source_errors.get(source_name, 0) or 0
                    ) + 1
                    class_errors = recall_quality_source_errors_by_class.setdefault(class_name, {})
                    class_errors[source_name] = int(class_errors.get(source_name, 0) or 0) + 1
        recall_quality_history.append(
            {
                "timestamp": _utc_now(),
                "resultCount": len(results),
                "topScore": round(top_score, 6),
                "noHit": no_hit,
                "lowConfidence": low_confidence,
                "staleHit": stale_hit,
                "trafficClass": class_name,
                "sources": sorted(
                    {
                        str(row.get("source") or "").strip().lower()
                        for row in results
                        if str(row.get("source") or "").strip()
                    }
                ),
                "sourceCounts": dict(source_counts) if isinstance(source_counts, dict) else {},
                "sourceErrors": dict(source_errors) if isinstance(source_errors, dict) else {},
                "sourceErrorKinds": source_error_kinds,
            }
        )
        recall_quality_updated_at = _utc_now()


def _build_recall_quality_payload(
    *,
    totals: dict[str, int],
    source_requests: dict[str, int],
    source_errors: dict[str, int],
    source_budget_exceeded: dict[str, int],
    history_tail: list[dict[str, Any]],
) -> dict[str, Any]:
    requests = max(0, int(totals.get("requests", 0) or 0))
    no_hit = max(0, int(totals.get("noHit", 0) or 0))
    low_conf = max(0, int(totals.get("lowConfidence", 0) or 0))
    stale_hit = max(0, int(totals.get("staleHit", 0) or 0))
    by_source: dict[str, dict[str, Any]] = {}
    source_names = sorted(
        set(source_requests.keys())
        | set(source_errors.keys())
        | set(source_budget_exceeded.keys())
    )
    for source in source_names:
        req_count = source_requests.get(source, 0)
        requests_count = max(0, int(req_count or 0))
        errors_count = max(0, int(source_errors.get(source, 0) or 0))
        budget_exceeded_count = max(0, int(source_budget_exceeded.get(source, 0) or 0))
        by_source[source] = {
            "requests": requests_count,
            "errors": errors_count,
            "budgetExceeded": budget_exceeded_count,
            "errorRate": round((errors_count / requests_count), 6) if requests_count > 0 else 0.0,
            "budgetExceededRate": (
                round((budget_exceeded_count / requests_count), 6)
                if requests_count > 0
                else 0.0
            ),
        }
    return {
        "requests": requests,
        "noHit": no_hit,
        "lowConfidence": low_conf,
        "staleHit": stale_hit,
        "noHitRate": round((no_hit / requests), 6) if requests > 0 else 0.0,
        "lowConfidenceRate": round((low_conf / requests), 6) if requests > 0 else 0.0,
        "staleHitRate": round((stale_hit / requests), 6) if requests > 0 else 0.0,
        "bySource": by_source,
        "recent": history_tail,
    }


async def _recall_quality_snapshot() -> dict[str, Any]:
    async with recall_quality_lock:
        totals = dict(recall_quality_totals)
        source_requests = dict(recall_quality_source_requests)
        source_errors = dict(recall_quality_source_errors)
        source_budget_exceeded = dict(recall_quality_source_budget_exceeded)
        history_tail = list(recall_quality_history)[-50:]
        totals_by_class = {
            class_name: dict(values)
            for class_name, values in recall_quality_totals_by_class.items()
        }
        source_requests_by_class = {
            class_name: dict(values)
            for class_name, values in recall_quality_source_requests_by_class.items()
        }
        source_errors_by_class = {
            class_name: dict(values)
            for class_name, values in recall_quality_source_errors_by_class.items()
        }
        source_budget_by_class = {
            class_name: dict(values)
            for class_name, values in recall_quality_source_budget_exceeded_by_class.items()
        }
        updated_at = recall_quality_updated_at
    payload = _build_recall_quality_payload(
        totals=totals,
        source_requests=source_requests,
        source_errors=source_errors,
        source_budget_exceeded=source_budget_exceeded,
        history_tail=history_tail,
    )
    by_traffic_class: dict[str, Any] = {}
    all_classes = (
        set(totals_by_class.keys())
        | set(source_requests_by_class.keys())
        | set(source_errors_by_class.keys())
        | set(source_budget_by_class.keys())
    )
    for class_name in sorted(all_classes):
        class_history = [
            row
            for row in history_tail
            if _normalize_traffic_class(row.get("trafficClass")) == class_name
        ]
        by_traffic_class[class_name] = _build_recall_quality_payload(
            totals=totals_by_class.get(class_name, {}),
            source_requests=source_requests_by_class.get(class_name, {}),
            source_errors=source_errors_by_class.get(class_name, {}),
            source_budget_exceeded=source_budget_by_class.get(class_name, {}),
            history_tail=class_history,
        )
    return {
        "updatedAt": updated_at,
        **payload,
        "byTrafficClass": by_traffic_class,
    }


def _build_recall_quality_alerts(snapshot: dict[str, Any]) -> list[dict[str, Any]]:
    requests = max(0, int(snapshot.get("requests", 0) or 0))
    if requests < RECALL_ALERT_MIN_REQUESTS:
        return []
    alerts: list[dict[str, Any]] = []
    no_hit_rate = float(snapshot.get("noHitRate") or 0.0)
    low_conf_rate = float(snapshot.get("lowConfidenceRate") or 0.0)
    stale_rate = float(snapshot.get("staleHitRate") or 0.0)
    if no_hit_rate >= RECALL_ALERT_NO_HIT_RATE:
        alerts.append(
            {
                "code": "recall_no_hit_rate_high",
                "severity": "warn",
                "metric": "noHitRate",
                "value": round(no_hit_rate, 6),
                "threshold": RECALL_ALERT_NO_HIT_RATE,
                "requests": requests,
                "message": f"Recall no-hit rate {no_hit_rate:.2%} exceeded threshold {RECALL_ALERT_NO_HIT_RATE:.2%}.",
            }
        )
    if low_conf_rate >= RECALL_ALERT_LOW_CONFIDENCE_RATE:
        alerts.append(
            {
                "code": "recall_low_confidence_rate_high",
                "severity": "warn",
                "metric": "lowConfidenceRate",
                "value": round(low_conf_rate, 6),
                "threshold": RECALL_ALERT_LOW_CONFIDENCE_RATE,
                "requests": requests,
                "message": (
                    f"Recall low-confidence rate {low_conf_rate:.2%} exceeded "
                    f"threshold {RECALL_ALERT_LOW_CONFIDENCE_RATE:.2%}."
                ),
            }
        )
    if stale_rate >= RECALL_ALERT_STALE_HIT_RATE:
        alerts.append(
            {
                "code": "recall_stale_hit_rate_high",
                "severity": "warn",
                "metric": "staleHitRate",
                "value": round(stale_rate, 6),
                "threshold": RECALL_ALERT_STALE_HIT_RATE,
                "requests": requests,
                "message": f"Recall stale-hit rate {stale_rate:.2%} exceeded threshold {RECALL_ALERT_STALE_HIT_RATE:.2%}.",
            }
        )
    by_source = snapshot.get("bySource")
    if isinstance(by_source, dict):
        for source, metrics in by_source.items():
            if not isinstance(metrics, dict):
                continue
            source_requests = max(0, int(metrics.get("requests", 0) or 0))
            if source_requests < RECALL_ALERT_MIN_REQUESTS:
                continue
            error_rate = float(metrics.get("errorRate") or 0.0)
            if error_rate < RECALL_ALERT_SOURCE_ERROR_RATE:
                continue
            alerts.append(
                {
                    "code": "recall_source_error_rate_high",
                    "severity": "critical",
                    "source": source,
                    "metric": "sourceErrorRate",
                    "value": round(error_rate, 6),
                    "threshold": RECALL_ALERT_SOURCE_ERROR_RATE,
                    "requests": source_requests,
                    "message": (
                        f"Recall source error rate for {source} ({error_rate:.2%}) exceeded "
                        f"threshold {RECALL_ALERT_SOURCE_ERROR_RATE:.2%}."
                    ),
                }
            )
    return alerts


def _mindsdb_rows(data: dict[str, Any]) -> list[dict[str, Any]]:
    rows = data.get("data")
    if not isinstance(rows, list):
        return []
    if rows and isinstance(rows[0], dict):
        return [row for row in rows if isinstance(row, dict)]
    columns = data.get("column_names")
    if not isinstance(columns, list):
        return []
    result: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, list):
            continue
        values = list(row) + [None] * max(0, len(columns) - len(row))
        result.append({str(columns[idx]): values[idx] for idx in range(len(columns))})
    return result


def _escape_sql_literal(value: str) -> str:
    return value.replace("'", "''")


def _parse_letta_archival_content(text: str) -> dict[str, str]:
    project = ""
    file_name = ""
    topic = ""
    summary = ""
    lines = [line.strip() for line in (text or "").splitlines() if line.strip()]
    if lines:
        header = lines[0]
        match = re.search(r"project=([^\s]+)", header)
        if match:
            project = match.group(1).strip()
        match = re.search(r"file=([^\s]+)", header)
        if match:
            file_name = match.group(1).strip()
        match = re.search(r"topic=([^\s]+)", header)
        if match:
            topic = match.group(1).strip()
    for line in lines[1:]:
        if line.lower().startswith("summary:"):
            summary = line.split(":", 1)[1].strip()
            break
    if not summary:
        summary = (text or "")[:500]
    return {
        "project": project if project and project != "-" else "",
        "file": file_name if file_name and file_name != "-" else "",
        "topic_path": topic if topic and topic != "-" else "",
        "summary": summary,
    }


def _extract_learning_terms(preferences: dict[str, Any] | None) -> tuple[set[str], set[str]]:
    stop_words = {
        "about",
        "after",
        "again",
        "already",
        "avoid",
        "from",
        "into",
        "just",
        "like",
        "more",
        "only",
        "that",
        "this",
        "with",
        "would",
    }

    def _terms(items: Any) -> set[str]:
        extracted: set[str] = set()
        if not isinstance(items, list):
            return extracted
        for value in items:
            if not isinstance(value, str):
                continue
            for token in re.findall(r"[A-Za-z0-9_:/.-]{4,}", value.lower()):
                if token in stop_words:
                    continue
                extracted.add(token)
        return extracted

    if not preferences:
        return set(), set()
    return _terms(preferences.get("positive")), _terms(preferences.get("negative"))


def _result_identity(row: dict[str, Any]) -> str:
    project = str(row.get("project") or "").strip().lower()
    file_name = str(row.get("file") or "").strip().lower()
    if project or file_name:
        return f"{project}:{file_name}"
    summary = str(row.get("summary") or "").strip().lower()
    if not summary:
        return uuid.uuid4().hex
    return hashlib.sha1(summary.encode("utf-8")).hexdigest()


async def call_memory_tool(name: str, arguments: dict[str, Any]) -> dict[str, Any]:
    payload = {
        "jsonrpc": "2.0",
        "id": str(uuid.uuid4()),
        "method": "tools/call",
        "params": {"name": name, "arguments": arguments},
    }
    result = await _call_mcp(payload)
    error_message = _mcp_result_error_message(result)
    if error_message:
        raise HTTPException(500, f"{name} failed: {error_message}")
    return result


async def list_projects() -> list[str]:
    try:
        result = await asyncio.wait_for(
            call_memory_tool("list_projects", {}),
            timeout=CONTEXTLATTICE_LIST_TIMEOUT_SECS,
        )
        projects = _parse_mcp_name_list(result)
        if projects:
            return projects
    except asyncio.TimeoutError:
        logger.warning("list_projects timed out; falling back to qdrant")
    except HTTPException as exc:
        logger.warning("list_projects failed (%s); falling back to qdrant", exc.detail)
    try:
        return await list_qdrant_projects()
    except Exception as exc:  # pragma: no cover - fallback only
        logger.warning("Qdrant fallback project list failed: %s", exc)
        return []


async def list_files(project: str) -> list[str]:
    try:
        result = await asyncio.wait_for(
            call_memory_tool("list_project_files", {"projectName": project}),
            timeout=CONTEXTLATTICE_LIST_TIMEOUT_SECS,
        )
    except asyncio.TimeoutError:
        logger.warning("list_project_files timed out for %s; falling back to qdrant", project)
        try:
            return await list_qdrant_files(project)
        except Exception as fallback_exc:  # pragma: no cover - fallback only
            logger.warning("Qdrant fallback list failed for %s: %s", project, fallback_exc)
            return []
    except HTTPException as exc:
        detail = str(exc.detail)
        if "resource not found" in detail.lower() or "enoent" in detail.lower():
            logger.info("Project path missing in memory-bank for %s; falling back to qdrant", project)
        else:
            logger.warning("list_project_files failed for %s: %s", project, detail)
        try:
            return await list_qdrant_files(project)
        except Exception as fallback_exc:  # pragma: no cover - fallback only
            logger.warning("Qdrant fallback list failed for %s: %s", project, fallback_exc)
            return []
    filenames = _parse_mcp_name_list(result)
    if filenames:
        return filenames
    try:
        return await list_qdrant_files(project)
    except Exception as exc:  # pragma: no cover - fallback only
        logger.warning("Qdrant fallback list failed for %s: %s", project, exc)
        return filenames


async def list_qdrant_files(project: str, limit: int = 1000) -> list[str]:
    if qdrant_models is None:
        raise RuntimeError("qdrant-client dependency is required for Qdrant operations")
    files: set[str] = set()
    offset: Any = None
    remaining = max(0, limit)
    if remaining == 0:
        return []
    scroll_filter = qdrant_models.Filter(
        must=[
            qdrant_models.FieldCondition(
                key="project",
                match=qdrant_models.MatchValue(value=project),
            )
        ]
    )
    while remaining > 0:
        page_limit = min(remaining, 256)
        points, next_offset = await _qdrant_call(
            "list_files_scroll",
            lambda client, _: client.scroll(
                collection_name=QDRANT_COLLECTION,
                scroll_filter=scroll_filter,
                limit=page_limit,
                offset=offset,
                with_payload=True,
                with_vectors=False,
            ),
        )
        for point in points:
            payload = getattr(point, "payload", None) or {}
            file_name = payload.get("file")
            if isinstance(file_name, str) and file_name:
                files.add(file_name)
        remaining -= len(points)
        offset = next_offset
        if not points or offset is None:
            break
    return sorted(files)


async def list_qdrant_projects(limit: int = 5000) -> list[str]:
    projects: set[str] = set()
    offset: Any = None
    remaining = max(0, limit)
    if remaining == 0:
        return []
    while remaining > 0:
        page_limit = min(remaining, 256)
        points, next_offset = await _qdrant_call(
            "list_projects_scroll",
            lambda client, _: client.scroll(
                collection_name=QDRANT_COLLECTION,
                limit=page_limit,
                offset=offset,
                with_payload=True,
                with_vectors=False,
            ),
        )
        for point in points:
            payload_row = getattr(point, "payload", None) or {}
            project_name = payload_row.get("project")
            if isinstance(project_name, str) and project_name:
                projects.add(project_name)
        remaining -= len(points)
        offset = next_offset
        if not points or offset is None:
            break
    return sorted(projects)


def _memory_read_cache_key(project: str, file_name: str) -> str:
    project_token = str(project or "").strip().lower()
    file_token = normalize_memory_path(file_name).strip().lower()
    return f"{project_token}::{file_token}"


async def _memory_read_cache_get(
    project: str,
    file_name: str,
    *,
    allow_stale: bool = False,
) -> tuple[str, bool] | None:
    global memory_read_cache_hits, memory_read_cache_misses
    if CONTEXTLATTICE_READ_CACHE_MAX_KEYS <= 0:
        return None
    key = _memory_read_cache_key(project, file_name)
    now = time.monotonic()
    stale_keys: list[str] = []
    async with memory_read_cache_lock:
        payload = memory_read_cache.get(key)
        if isinstance(payload, dict):
            content = payload.get("content")
            fetched_monotonic = float(payload.get("fetched_monotonic") or 0.0)
            if isinstance(content, str) and fetched_monotonic > 0:
                age_secs = max(0.0, now - fetched_monotonic)
                is_fresh = age_secs <= CONTEXTLATTICE_READ_CACHE_FRESH_TTL_SECS
                is_acceptable_stale = (
                    allow_stale
                    and age_secs <= CONTEXTLATTICE_READ_CACHE_STALE_MAX_SECS
                )
                if is_fresh or is_acceptable_stale:
                    memory_read_cache.move_to_end(key)
                    memory_read_cache_hits += 1
                    return content, (not is_fresh)
            stale_keys.append(key)
        for stale_key in stale_keys:
            memory_read_cache.pop(stale_key, None)
    memory_read_cache_misses += 1
    return None


async def _memory_read_cache_set(project: str, file_name: str, content: str) -> None:
    global memory_read_cache_evictions, memory_read_cache_writes
    if CONTEXTLATTICE_READ_CACHE_MAX_KEYS <= 0:
        return
    body = str(content or "")
    if not body:
        return
    key = _memory_read_cache_key(project, file_name)
    payload = {
        "content": body,
        "fetched_at": _utc_now(),
        "fetched_monotonic": time.monotonic(),
    }
    async with memory_read_cache_lock:
        memory_read_cache[key] = payload
        memory_read_cache.move_to_end(key)
        memory_read_cache_writes += 1
        while len(memory_read_cache) > CONTEXTLATTICE_READ_CACHE_MAX_KEYS:
            memory_read_cache.popitem(last=False)
            memory_read_cache_evictions += 1


def _is_transient_memory_read_http_error(exc: HTTPException) -> bool:
    try:
        status_code = int(exc.status_code)
    except Exception:
        status_code = 500
    detail = str(exc.detail or "").lower()
    return (
        status_code in (408, 429, 500, 502, 503, 504)
        or "timeout" in detail
        or "temporarily unavailable" in detail
    )


async def _read_project_file_remote(
    project: str,
    file_name: str,
    *,
    timeout_secs: float,
) -> str:
    result = await asyncio.wait_for(
        call_memory_tool(
            "memory_bank_read",
            {"projectName": project, "fileName": file_name},
        ),
        timeout=max(1.0, float(timeout_secs)),
    )
    chunks = _extract_mcp_text_chunks(result.get("content"))
    if chunks:
        return "\n".join(chunk for chunk in chunks if chunk)
    return ""


async def _schedule_memory_read_cache_refresh(project: str, file_name: str) -> None:
    global memory_read_cache_refresh_started, memory_read_cache_refresh_completed, memory_read_cache_refresh_failed
    if not CONTEXTLATTICE_READ_FAIL_OPEN_ENABLED:
        return
    key = _memory_read_cache_key(project, file_name)
    async with memory_read_cache_refresh_lock:
        if key in memory_read_cache_refresh_inflight:
            return
        if len(memory_read_cache_refresh_inflight) >= CONTEXTLATTICE_READ_CACHE_REFRESH_MAX_INFLIGHT:
            return
        memory_read_cache_refresh_inflight[key] = time.monotonic()
        memory_read_cache_refresh_started += 1

    async def _runner() -> None:
        global memory_read_cache_refresh_completed, memory_read_cache_refresh_failed
        try:
            content = await _read_project_file_remote(
                project,
                file_name,
                timeout_secs=CONTEXTLATTICE_READ_CACHE_REFRESH_TIMEOUT_SECS,
            )
            if content:
                await _memory_read_cache_set(project, file_name, content)
            memory_read_cache_refresh_completed += 1
        except Exception as exc:
            memory_read_cache_refresh_failed += 1
            logger.debug("Memory read cache refresh failed for %s/%s: %s", project, file_name, exc)
        finally:
            async with memory_read_cache_refresh_lock:
                memory_read_cache_refresh_inflight.pop(key, None)

    asyncio.create_task(_runner())


def _memory_not_found_detail(detail: str) -> bool:
    detail_lower = detail.lower()
    return any(
        token in detail_lower
        for token in (
            "notfounderror",
            "resource not found",
            "file not found",
            "no such file",
            "enoent",
        )
    )


def _is_memory_not_found_http_error(exc: HTTPException) -> bool:
    return _memory_not_found_detail(str(exc.detail))


def _build_missing_memory_file_stub(project: str, file_name: str) -> dict[str, Any] | None:
    normalized_file = normalize_memory_path(file_name)
    now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

    if project == OVERRIDE_PROJECT and normalized_file in OPTIONAL_OVERRIDE_FILENAMES:
        return {
            "kind": "override_smoke_test",
            "symbol": "SMOKE",
            "priority": "LOW",
            "reason": "Auto-created placeholder override file",
            "size_before": 0.0,
            "size_after": 0.0,
            "confidence_before": 0.0,
            "confidence_after": 0.0,
            "override_strength": 0.0,
            "multiplier": 1.0,
            "timestamp": now,
            "generated_by": "contextlattice-orchestrator",
            "bootstrap": True,
        }

    if not (normalized_file.startswith("index__") and normalized_file.endswith(".json")):
        return None

    latest_hint = INDEX_FILE_LATEST_HINTS.get(normalized_file)
    if latest_hint is None:
        stem = normalized_file[len("index__") : -len(".json")]
        latest_hint = f"{stem}__latest.json" if stem else ""

    return {
        "kind": "memory_index",
        "project": project,
        "index_file": normalized_file,
        "latest": latest_hint,
        "latest_file": latest_hint,
        "files": [latest_hint] if latest_hint else [],
        "entries": [{"file": latest_hint}] if latest_hint else [],
        "generated_at": now,
        "generated_by": "contextlattice-orchestrator",
        "bootstrap": True,
    }


async def _bootstrap_missing_memory_file(project: str, file_name: str) -> str | None:
    if not ORCH_MISSING_FILE_AUTOSTUB:
        return None
    stub_payload = _build_missing_memory_file_stub(project, file_name)
    if stub_payload is None:
        return None
    content = json.dumps(stub_payload, indent=2, sort_keys=True)
    try:
        await call_memory_tool(
            "memory_bank_write",
            {"projectName": project, "fileName": file_name, "content": content},
        )
    except Exception as exc:
        logger.warning(
            "Missing memory file %s/%s could not be auto-bootstrapped: %s",
            project,
            file_name,
            exc,
        )
        return content
    logger.warning("Auto-bootstrapped missing memory file %s/%s", project, file_name)
    return content


async def read_project_file(
    project: str,
    file_name: str,
    *,
    allow_missing: bool = False,
    bootstrap_missing: bool = False,
    log_missing: bool = True,
) -> str:
    global memory_read_cache_stale_fallbacks
    try:
        content = await _read_project_file_remote(
            project,
            file_name,
            timeout_secs=CONTEXTLATTICE_READ_TIMEOUT_SECS,
        )
    except asyncio.TimeoutError as exc:
        cached = (
            await _memory_read_cache_get(project, file_name, allow_stale=True)
            if CONTEXTLATTICE_READ_FAIL_OPEN_ENABLED
            else None
        )
        if cached is not None:
            memory_read_cache_stale_fallbacks += 1
            await _schedule_memory_read_cache_refresh(project, file_name)
            logger.warning(
                "memory_bank_read timeout for %s/%s; serving stale cached content",
                project,
                file_name,
            )
            return cached[0]
        raise HTTPException(504, f"memory_bank_read timeout for {project}/{file_name}") from exc
    except HTTPException as exc:
        if CONTEXTLATTICE_READ_FAIL_OPEN_ENABLED and _is_transient_memory_read_http_error(exc):
            cached = await _memory_read_cache_get(project, file_name, allow_stale=True)
            if cached is not None:
                memory_read_cache_stale_fallbacks += 1
                await _schedule_memory_read_cache_refresh(project, file_name)
                logger.warning(
                    "memory_bank_read transient error for %s/%s (%s); serving stale cached content",
                    project,
                    file_name,
                    exc.detail,
                )
                return cached[0]
        if _is_memory_not_found_http_error(exc):
            if bootstrap_missing:
                fallback = await _bootstrap_missing_memory_file(project, file_name)
                if fallback:
                    await _memory_read_cache_set(project, file_name, fallback)
                    return fallback
            if allow_missing:
                if log_missing:
                    logger.warning("Missing memory file %s/%s", project, file_name)
                return ""
        raise
    if content:
        await _memory_read_cache_set(project, file_name, content)
        return content
    return ""


def _qdrant_payload_index_specs() -> list[tuple[str, Any]]:
    if qdrant_models is None:
        return []
    keyword_schema = getattr(getattr(qdrant_models, "PayloadSchemaType", None), "KEYWORD", "keyword")
    integer_schema = getattr(getattr(qdrant_models, "PayloadSchemaType", None), "INTEGER", "integer")
    return [
        ("project", keyword_schema),
        ("file", keyword_schema),
        ("topic_path", keyword_schema),
        ("topic_tags", keyword_schema),
        ("ts", integer_schema),
    ]


def _qdrant_collection_missing_error(exc: Exception | str | None) -> bool:
    text = str(exc or "").strip().lower()
    if not text:
        return False
    return ("404" in text) or ("not found" in text and "collection" in text)


async def _ensure_qdrant_payload_indexes(
    collection_name: str | None = None,
    *,
    force: bool = False,
) -> dict[str, Any]:
    collection = str(collection_name or QDRANT_COLLECTION).strip() or QDRANT_COLLECTION
    now_iso = _utc_now()
    if not QDRANT_PAYLOAD_INDEX_HARDEN_ENABLED:
        result = {
            "enabled": False,
            "collection": collection,
            "updatedAt": now_iso,
            "indexed": [],
            "existing": [],
            "failedFields": {},
            "collectionMissing": False,
            "reason": "disabled",
        }
        async with qdrant_payload_index_cache_lock:
            qdrant_payload_index_cache[collection] = dict(result)
        qdrant_payload_index_state["lastRunAt"] = now_iso
        qdrant_payload_index_state["lastResult"] = dict(result)
        return result
    if qdrant_models is None:
        raise RuntimeError("qdrant-client dependency is required for Qdrant payload-index hardening")
    async with qdrant_payload_index_cache_lock:
        cached = qdrant_payload_index_cache.get(collection)
        if isinstance(cached, dict) and not force:
            failed_fields = cached.get("failedFields")
            collection_missing = bool(cached.get("collectionMissing"))
            if not collection_missing and not failed_fields:
                return dict(cached)

    try:
        await _qdrant_call(
            "payload_index_collection_info",
            lambda client, _: client.get_collection(collection_name=collection),
        )
    except Exception as exc:
        if _qdrant_collection_missing_error(exc):
            result = {
                "enabled": True,
                "collection": collection,
                "updatedAt": now_iso,
                "indexed": [],
                "existing": [],
                "failedFields": {},
                "collectionMissing": True,
                "reason": str(exc)[:300],
            }
            async with qdrant_payload_index_cache_lock:
                qdrant_payload_index_cache[collection] = dict(result)
            qdrant_payload_index_state["lastRunAt"] = now_iso
            qdrant_payload_index_state["lastResult"] = dict(result)
            return result
        raise

    indexed: list[str] = []
    existing: list[str] = []
    failed_fields: dict[str, str] = {}
    for field_name, field_schema in _qdrant_payload_index_specs():
        try:
            await _qdrant_call(
                "ensure_payload_index",
                lambda client, _: client.create_payload_index(
                    collection_name=collection,
                    field_name=field_name,
                    field_schema=field_schema,
                    wait=QDRANT_PAYLOAD_INDEX_HARDEN_WAIT,
                ),
            )
            indexed.append(field_name)
        except Exception as exc:
            error_text = str(exc).strip()
            lowered = error_text.lower()
            if (
                "already exists" in lowered
                or "already indexed" in lowered
                or "already has index" in lowered
            ):
                existing.append(field_name)
                continue
            failed_fields[field_name] = error_text[:300]
    result = {
        "enabled": True,
        "collection": collection,
        "updatedAt": now_iso,
        "indexed": sorted(set(indexed)),
        "existing": sorted(set(existing)),
        "failedFields": failed_fields,
        "collectionMissing": False,
    }
    async with qdrant_payload_index_cache_lock:
        qdrant_payload_index_cache[collection] = dict(result)
    qdrant_payload_index_state["lastRunAt"] = now_iso
    qdrant_payload_index_state["lastResult"] = dict(result)
    return result


async def ensure_qdrant_collection(vector_size: int, collection_name: str | None = None) -> None:
    collection = collection_name or QDRANT_COLLECTION
    cached_size = qdrant_collection_dim_cache.get(collection)
    if cached_size is not None:
        if cached_size != vector_size:
            raise RuntimeError(
                "Qdrant collection dimension mismatch: "
                f"existing={cached_size}, required={vector_size}. "
                "Drop the collection or adjust the embedding model."
            )
        if QDRANT_PAYLOAD_INDEX_HARDEN_ENABLED:
            with contextlib.suppress(Exception):
                await _ensure_qdrant_payload_indexes(collection)
        return
    if qdrant_models is None:
        raise RuntimeError("qdrant-client dependency is required for Qdrant operations")

    def _extract_vector_size(info: Any) -> int | None:
        config = getattr(info, "config", None)
        params = getattr(config, "params", None) if config is not None else None
        vectors = getattr(params, "vectors", None) if params is not None else None
        if vectors is None and isinstance(info, dict):
            vectors = ((((info.get("result") or {}).get("config") or {}).get("params") or {}).get("vectors"))
        size = getattr(vectors, "size", None)
        if size is None and isinstance(vectors, dict):
            size = vectors.get("size")
        if size is None:
            return None
        try:
            return int(size)
        except (TypeError, ValueError):
            return None

    async def _ensure_on_backend(client: AsyncQdrantClient, target: str) -> None:
        try:
            info = await client.get_collection(collection_name=collection)
            current_size = _extract_vector_size(info)
            if current_size and current_size != vector_size:
                raise RuntimeError(
                    "Qdrant collection dimension mismatch: "
                    f"existing={current_size}, required={vector_size}. "
                    "Drop the collection or adjust the embedding model."
                )
            if current_size:
                qdrant_collection_dim_cache[collection] = int(current_size)
            return
        except Exception as exc:
            error_text = str(exc).lower()
            if "404" not in error_text and "not found" not in error_text:
                raise

        await client.create_collection(
            collection_name=collection,
            vectors_config=qdrant_models.VectorParams(
                size=vector_size,
                distance=qdrant_models.Distance.COSINE,
            ),
        )
        qdrant_collection_dim_cache[collection] = vector_size
        logger.info("Created Qdrant collection %s on %s backend with dim=%s", collection, target, vector_size)

    await _qdrant_call("ensure_collection", _ensure_on_backend)
    if QDRANT_PAYLOAD_INDEX_HARDEN_ENABLED:
        try:
            result = await _ensure_qdrant_payload_indexes(collection)
            if result.get("failedFields"):
                logger.warning(
                    "Qdrant payload index hardening completed with failures for %s: %s",
                    collection,
                    sorted(result["failedFields"].keys()),
                )
        except Exception as exc:
            logger.warning("Qdrant payload index hardening failed for %s: %s", collection, exc)


def _qdrant_expected_dim(error_text: str) -> int | None:
    patterns = [
        r"expected dim:\s*(\d+)",
        r"existing=(\d+),\s*required=\d+",
    ]
    for pattern in patterns:
        match = re.search(pattern, error_text, flags=re.IGNORECASE)
        if match:
            try:
                return int(match.group(1))
            except (TypeError, ValueError):
                return None
    return None


def _qdrant_dimension_collection_name(collection: str, vector_size: int) -> str:
    base = str(collection or QDRANT_COLLECTION).strip() or QDRANT_COLLECTION
    return f"{base}{QDRANT_DIMENSION_SUFFIX}{int(vector_size)}"


def _record_qdrant_dimension_route(
    base_collection: str,
    resolved_collection: str,
    vector_size: int,
    existing_dim: int,
    operation: str,
) -> None:
    now_iso = _utc_now()
    qdrant_dimension_route_state["lastRouteAt"] = now_iso
    qdrant_dimension_route_state["lastRoute"] = {
        "baseCollection": base_collection,
        "resolvedCollection": resolved_collection,
        "vectorSize": int(vector_size),
        "existingDim": int(existing_dim),
        "operation": operation,
        "policy": QDRANT_DIMENSION_POLICY,
    }
    qdrant_dimension_route_state["routes"] = int(qdrant_dimension_route_state.get("routes", 0) or 0) + 1


async def _resolve_qdrant_collection_for_dimension(
    collection_name: str | None,
    vector_size: int,
    *,
    operation: str,
) -> str:
    normalized_size = max(1, int(vector_size))
    base_collection = str(collection_name or QDRANT_COLLECTION).strip() or QDRANT_COLLECTION
    cached = qdrant_collection_dim_routes.get((base_collection, normalized_size))
    if cached:
        return cached
    try:
        await ensure_qdrant_collection(normalized_size, base_collection)
        return base_collection
    except RuntimeError as exc:
        message = str(exc)
        existing_dim = _qdrant_expected_dim(message)
        if not existing_dim or existing_dim <= 0 or existing_dim == normalized_size:
            raise
        if QDRANT_DIMENSION_POLICY == "strict":
            qdrant_dimension_route_state["strictFailures"] = (
                int(qdrant_dimension_route_state.get("strictFailures", 0) or 0) + 1
            )
            raise RuntimeError(
                "Qdrant dimension mismatch blocked by strict policy: "
                f"collection={base_collection} existing={existing_dim} required={normalized_size} operation={operation}"
            ) from exc
        if QDRANT_DIMENSION_POLICY == "legacy_fallback":
            return base_collection
        resolved_collection = _qdrant_dimension_collection_name(base_collection, normalized_size)
        await ensure_qdrant_collection(normalized_size, resolved_collection)
        qdrant_collection_dim_routes[(base_collection, normalized_size)] = resolved_collection
        _record_qdrant_dimension_route(
            base_collection,
            resolved_collection,
            normalized_size,
            existing_dim,
            operation,
        )
        logger.warning(
            "Qdrant dimension mismatch routed (%s): base=%s existing=%s required=%s resolved=%s policy=%s",
            operation,
            base_collection,
            existing_dim,
            normalized_size,
            resolved_collection,
            QDRANT_DIMENSION_POLICY,
        )
        return resolved_collection


def _pgvector_vector_literal(vector: list[float]) -> str:
    return "[" + ",".join(f"{float(value):.8f}" for value in vector) + "]"


async def _ensure_pgvector_pool() -> bool:
    global PGVECTOR_POOL, pgvector_last_error
    if not PGVECTOR_ENABLED or not PGVECTOR_DSN:
        return False
    if asyncpg is None:
        pgvector_last_error = "asyncpg dependency unavailable"
        return False
    if PGVECTOR_POOL is not None:
        return True
    async with pgvector_pool_lock:
        if PGVECTOR_POOL is not None:
            return True
        try:
            PGVECTOR_POOL = await asyncpg.create_pool(
                dsn=PGVECTOR_DSN,
                min_size=PGVECTOR_POOL_MIN_SIZE,
                max_size=PGVECTOR_POOL_MAX_SIZE,
                timeout=PGVECTOR_CONNECT_TIMEOUT_SECS,
                command_timeout=PGVECTOR_STATEMENT_TIMEOUT_SECS,
            )
            pgvector_last_error = None
            return True
        except Exception as exc:
            pgvector_last_error = str(exc).strip() or exc.__class__.__name__
            logger.warning("Postgres pgvector pool initialization failed: %s", pgvector_last_error)
            PGVECTOR_POOL = None
            return False


async def ensure_pgvector_schema() -> bool:
    global pgvector_schema_ready, pgvector_vectorscale_available, pgvector_last_error
    if not await _ensure_pgvector_pool():
        return False
    if pgvector_schema_ready:
        return True
    assert PGVECTOR_POOL is not None
    async with pgvector_pool_lock:
        if pgvector_schema_ready:
            return True
        vectorscale_available = False
        table_name = PGVECTOR_TABLE
        try:
            async with PGVECTOR_POOL.acquire() as conn:
                await conn.execute("CREATE EXTENSION IF NOT EXISTS vector;")
                if PGVECTOR_PREFER_VECTORSCALE:
                    try:
                        await conn.execute("CREATE EXTENSION IF NOT EXISTS vectorscale CASCADE;")
                        vectorscale_available = True
                    except Exception as exc:
                        logger.info("vectorscale extension unavailable; using ivfflat fallback (%s)", exc)
                await conn.execute(
                    f"""
                    CREATE TABLE IF NOT EXISTS {table_name} (
                      event_id TEXT PRIMARY KEY,
                      project TEXT NOT NULL,
                      file TEXT NOT NULL,
                      summary TEXT NOT NULL,
                      topic_path TEXT,
                      topic_tags TEXT[],
                      code_context JSONB,
                      embedding VECTOR({PGVECTOR_EMBED_DIM}) NOT NULL,
                      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                    );
                    """
                )
                await conn.execute(
                    f"CREATE INDEX IF NOT EXISTS {table_name}_project_idx ON {table_name} (project);"
                )
                await conn.execute(
                    f"CREATE INDEX IF NOT EXISTS {table_name}_topic_idx ON {table_name} (topic_path);"
                )
                if vectorscale_available:
                    try:
                        await conn.execute(
                            f"CREATE INDEX IF NOT EXISTS {table_name}_embedding_diskann_idx "
                            f"ON {table_name} USING diskann (embedding);"
                        )
                    except Exception as exc:
                        vectorscale_available = False
                        logger.warning(
                            "Postgres pgvector diskann index creation failed; using ivfflat fallback (%s)",
                            exc,
                        )
                if not vectorscale_available:
                    await conn.execute(
                        f"CREATE INDEX IF NOT EXISTS {table_name}_embedding_ivfflat_idx "
                        f"ON {table_name} USING ivfflat (embedding vector_cosine_ops) "
                        f"WITH (lists = {PGVECTOR_IVFFLAT_LISTS});"
                    )
                await conn.execute(f"ANALYZE {table_name};")
            pgvector_schema_ready = True
            pgvector_vectorscale_available = vectorscale_available
            pgvector_last_error = None
            return True
        except Exception as exc:
            pgvector_last_error = str(exc).strip() or exc.__class__.__name__
            logger.warning("Postgres pgvector schema init failed: %s", pgvector_last_error)
            return False


async def push_batch_to_pgvector(items: list[dict[str, Any]]) -> None:
    if not PGVECTOR_FANOUT_ENABLED or not items:
        return
    if not await ensure_pgvector_schema():
        raise OrchestratorError(f"postgres pgvector unavailable: {pgvector_last_error or 'schema not ready'}")
    assert PGVECTOR_POOL is not None

    contents = [str(item.get("content") or "") for item in items]
    vectors = await embed_text_batch(contents)
    rows: list[tuple[Any, ...]] = []
    for idx, item in enumerate(items):
        project = str(item.get("project") or "").strip()
        file_name = str(item.get("file") or "").strip()
        summary = str(item.get("content") or "").strip()
        if not project or not file_name or not summary:
            continue
        embedding = vectors[idx] if idx < len(vectors) else []
        if len(embedding) != PGVECTOR_EMBED_DIM:
            embedding = _cheap_embedding(summary, PGVECTOR_EMBED_DIM)
        topic_path = normalize_topic_path(str(item.get("topic_path") or "")) or derive_topic_path(file_name, None)
        topic_tags = [
            str(token).strip()
            for token in (item.get("topic_tags") if isinstance(item.get("topic_tags"), list) else [])
            if str(token).strip()
        ]
        code_context = item.get("code_context") if isinstance(item.get("code_context"), dict) else {}
        event_id = str(item.get("event_id") or build_event_id(project, file_name, summary)).strip()
        rows.append(
            (
                event_id,
                project,
                file_name,
                summary,
                topic_path,
                topic_tags,
                json.dumps(code_context, default=str),
                _pgvector_vector_literal(embedding),
            )
        )
    if not rows:
        return
    table_name = PGVECTOR_TABLE
    sql = (
        f"INSERT INTO {table_name} "
        "(event_id, project, file, summary, topic_path, topic_tags, code_context, embedding, created_at, updated_at) "
        "VALUES ($1, $2, $3, $4, $5, $6::text[], $7::jsonb, $8::vector, NOW(), NOW()) "
        "ON CONFLICT (event_id) DO UPDATE SET "
        "project = EXCLUDED.project, "
        "file = EXCLUDED.file, "
        "summary = EXCLUDED.summary, "
        "topic_path = EXCLUDED.topic_path, "
        "topic_tags = EXCLUDED.topic_tags, "
        "code_context = EXCLUDED.code_context, "
        "embedding = EXCLUDED.embedding, "
        "updated_at = NOW();"
    )
    async with _fanout_rate_limit(pgvector_fanout_rate_limiter):
        async with PGVECTOR_POOL.acquire() as conn:
            await conn.executemany(sql, rows)


async def search_postgres_pgvector(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
) -> list[dict[str, Any]]:
    if not PGVECTOR_ENABLED:
        return []
    terms = _query_terms(query)
    if not terms:
        return []
    if not await ensure_pgvector_schema():
        return []
    assert PGVECTOR_POOL is not None
    try:
        query_vector = await asyncio.wait_for(
            embed_text(query),
            timeout=max(1.0, QDRANT_EMBED_TIMEOUT_SECS),
        )
    except Exception:
        query_vector = _cheap_embedding(query, PGVECTOR_EMBED_DIM)
    if len(query_vector) != PGVECTOR_EMBED_DIM:
        query_vector = _cheap_embedding(query, PGVECTOR_EMBED_DIM)

    table_name = PGVECTOR_TABLE
    scan_limit = max(limit * 8, RETRIEVAL_PGVECTOR_SCAN_LIMIT)
    sql = (
        f"SELECT project, file, summary, topic_path, created_at, (1 - (embedding <=> $1::vector)) AS similarity "
        f"FROM {table_name} "
        "WHERE ($2::text IS NULL OR project = $2) "
        "AND ($3::text IS NULL OR topic_path LIKE ($3 || '%')) "
        "ORDER BY embedding <=> $1::vector "
        "LIMIT $4;"
    )
    try:
        async with PGVECTOR_POOL.acquire() as conn:
            raw_rows = await conn.fetch(
                sql,
                _pgvector_vector_literal(query_vector),
                project_filter,
                topic_filter,
                scan_limit,
            )
    except Exception as exc:
        logger.warning("Postgres pgvector retrieval failed: %s", exc)
        return []

    rows: list[dict[str, Any]] = []
    for row in raw_rows:
        project_name = str(row.get("project") or "")
        file_name = str(row.get("file") or "")
        summary = str(row.get("summary") or "")
        if not project_name or not file_name or not summary:
            continue
        topic_path = normalize_topic_path(str(row.get("topic_path") or "")) or derive_topic_path(file_name, None)
        lexical_score = _text_match_score(query, f"{project_name}\n{file_name}\n{summary}")
        vector_score = float(row.get("similarity") or 0.0)
        score = max(0.0, max(vector_score, lexical_score))
        if score <= 0 and terms:
            continue
        rows.append(
            {
                "project": project_name,
                "file": file_name,
                "summary": summary,
                "score": score,
                "source": RETRIEVAL_SOURCE_POSTGRES_PGVECTOR,
                "topic_path": topic_path,
                "created_at": row.get("created_at"),
                "backend": "vectorscale" if pgvector_vectorscale_available else "ivfflat",
            }
        )
    rows.sort(key=lambda item: float(item.get("score") or 0.0), reverse=True)
    return rows[:limit]


async def push_to_qdrant(
    project: str,
    file_name: str,
    content: str,
    topic_path: str | None = None,
    topic_tags: list[str] | None = None,
    collection_name: str | None = None,
) -> None:
    await push_batch_to_qdrant(
        [
            {
                "project": project,
                "file": file_name,
                "content": content,
                "topic_path": topic_path,
                "topic_tags": topic_tags or [],
                "collection_name": collection_name,
            }
        ]
    )


def _qdrant_point_payload(
    project: str,
    file_name: str,
    summary: str,
    vector: list[float],
    topic_path: str | None = None,
    topic_tags: list[str] | None = None,
    code_context: dict[str, Any] | None = None,
) -> Any:
    payload_meta: dict[str, Any] = {
        "project": project,
        "file": file_name,
        "summary": summary[:500],
        # Epoch seconds for retention/cold-storage workflows
        "ts": int(datetime.utcnow().timestamp()),
    }
    if topic_path:
        payload_meta["topic_path"] = topic_path
    if topic_tags:
        payload_meta["topic_tags"] = topic_tags
    if isinstance(code_context, dict) and code_context:
        payload_meta["code_context"] = code_context
    if qdrant_models is None:
        raise RuntimeError("qdrant-client dependency is required for Qdrant operations")
    return qdrant_models.PointStruct(
        id=str(uuid.uuid4()),
        vector=vector,
        payload=payload_meta,
    )


async def push_batch_to_qdrant(items: list[dict[str, Any]]) -> None:
    if not items:
        return
    grouped: dict[str, list[dict[str, Any]]] = {}
    for item in items:
        collection = str(item.get("collection_name") or QDRANT_COLLECTION).strip() or QDRANT_COLLECTION
        grouped.setdefault(collection, []).append(item)

    for collection, rows in grouped.items():
        contents = [str(row.get("content") or "") for row in rows]
        vectors = await embed_text_batch(contents)
        if not vectors:
            vectors = [_cheap_embedding(str(row.get("content") or ""), FALLBACK_EMBED_DIM) for row in rows]
        vector_dim = max(1, len(vectors[0]))
        target_collection = await _resolve_qdrant_collection_for_dimension(
            collection,
            vector_dim,
            operation="write",
        )

        points = [
            _qdrant_point_payload(
                str(row.get("project") or ""),
                str(row.get("file") or ""),
                str(row.get("content") or ""),
                vectors[idx],
                row.get("topic_path"),
                row.get("topic_tags"),
                row.get("code_context") if isinstance(row.get("code_context"), dict) else None,
            )
            for idx, row in enumerate(rows)
        ]

        async def _upsert(target: str, batch_points: list[Any]) -> Any:
            async with _fanout_rate_limit(qdrant_fanout_rate_limiter):
                return await _qdrant_call(
                    "upsert",
                    lambda client, _: client.upsert(
                        collection_name=target,
                        points=batch_points,
                        wait=False,
                    ),
                )

        try:
            await _upsert(target_collection, points)
            continue
        except Exception as exc:
            expected_dim = _qdrant_expected_dim(str(exc))
            if not expected_dim or expected_dim <= 0 or expected_dim == vector_dim:
                raise RuntimeError(f"Qdrant upsert failed: {exc}") from exc
        if QDRANT_DIMENSION_POLICY == "legacy_fallback":
            qdrant_collection_dim_cache[target_collection] = expected_dim
            logger.warning(
                "Qdrant upsert dimension mismatch fallback (legacy mode): collection=%s expected=%s got=%s",
                target_collection,
                expected_dim,
                vector_dim,
            )
            fallback_points = [
                _qdrant_point_payload(
                    str(row.get("project") or ""),
                    str(row.get("file") or ""),
                    str(row.get("content") or ""),
                    _cheap_embedding(str(row.get("content") or ""), expected_dim),
                    row.get("topic_path"),
                    row.get("topic_tags"),
                    row.get("code_context") if isinstance(row.get("code_context"), dict) else None,
                )
                for row in rows
            ]
            try:
                await _upsert(target_collection, fallback_points)
                continue
            except Exception as retry_exc:
                raise RuntimeError(f"Qdrant upsert failed after legacy fallback: {retry_exc}") from retry_exc
        rerouted_collection = await _resolve_qdrant_collection_for_dimension(
            collection,
            vector_dim,
            operation="write_retry",
        )
        try:
            await _upsert(rerouted_collection, points)
        except Exception as retry_exc:
            raise RuntimeError(
                f"Qdrant upsert failed after reroute (collection={rerouted_collection}): {retry_exc}"
            ) from retry_exc


def _weaviate_headers() -> dict[str, str]:
    headers = {"content-type": "application/json"}
    if WEAVIATE_API_KEY:
        headers["Authorization"] = f"Bearer {WEAVIATE_API_KEY}"
    return headers


def _weaviate_text(value: Any) -> str:
    return str(value or "").strip()


def _weaviate_graphql_escape(text: str) -> str:
    return (
        str(text or "")
        .replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", " ")
        .replace("\r", " ")
    )


def _weaviate_stable_id(item: dict[str, Any]) -> str:
    seed = (
        _weaviate_text(item.get("event_id"))
        or f"{_weaviate_text(item.get('project'))}:{_weaviate_text(item.get('file'))}:{_weaviate_text(item.get('summary'))}"
    )
    return str(uuid.uuid5(uuid.NAMESPACE_URL, seed))


async def _ensure_weaviate_schema() -> None:
    global weaviate_schema_ready, weaviate_schema_last_error
    if not WEAVIATE_ENABLED:
        return
    if not WEAVIATE_BOOTSTRAP_SCHEMA:
        return
    if weaviate_schema_ready:
        return
    async with weaviate_schema_lock:
        if weaviate_schema_ready:
            return
        client = await _get_weaviate_client()
        base = WEAVIATE_URL.rstrip("/")
        headers = _weaviate_headers()
        class_url = f"{base}/v1/schema/{WEAVIATE_CLASS}"
        try:
            response = await client.get(class_url, headers=headers)
            if response.status_code == 200:
                weaviate_schema_ready = True
                weaviate_schema_last_error = None
                return
            if response.status_code != 404:
                raise OrchestratorError(
                    f"weaviate schema probe failed ({response.status_code}): {response.text[:240]}"
                )
            schema_payload = {
                "class": WEAVIATE_CLASS,
                "vectorizer": "none",
                "properties": [
                    {"name": "project", "dataType": ["text"]},
                    {"name": "file", "dataType": ["text"]},
                    {"name": "summary", "dataType": ["text"]},
                    {"name": "topic_path", "dataType": ["text"]},
                    {"name": "topic_tags", "dataType": ["text[]"]},
                    {"name": "event_id", "dataType": ["text"]},
                    {"name": "created_at", "dataType": ["text"]},
                ],
            }
            create = await client.post(f"{base}/v1/schema", json=schema_payload, headers=headers)
            if create.status_code >= 300:
                raise OrchestratorError(
                    f"weaviate schema create failed ({create.status_code}): {create.text[:240]}"
                )
            weaviate_schema_ready = True
            weaviate_schema_last_error = None
        except Exception as exc:
            weaviate_schema_last_error = str(exc).strip() or exc.__class__.__name__
            raise


async def push_batch_to_weaviate(items: list[dict[str, Any]]) -> None:
    if not items or not WEAVIATE_FANOUT_ENABLED:
        return
    await _ensure_weaviate_schema()
    client = await _get_weaviate_client()
    base = WEAVIATE_URL.rstrip("/")
    headers = _weaviate_headers()
    for chunk in _chunk_rows(items, WEAVIATE_BATCH_SIZE):
        objects: list[dict[str, Any]] = []
        for item in chunk:
            objects.append(
                {
                    "class": WEAVIATE_CLASS,
                    "id": _weaviate_stable_id(item),
                    "properties": {
                        "project": _weaviate_text(item.get("project")),
                        "file": _weaviate_text(item.get("file")),
                        "summary": _weaviate_text(item.get("summary")),
                        "topic_path": _weaviate_text(item.get("topic_path")),
                        "topic_tags": [
                            _weaviate_text(tag)
                            for tag in (item.get("topic_tags") if isinstance(item.get("topic_tags"), list) else [])
                            if _weaviate_text(tag)
                        ],
                        "event_id": _weaviate_text(item.get("event_id")),
                        "created_at": _utc_now(),
                    },
                }
            )
        async with _fanout_rate_limit(weaviate_fanout_rate_limiter):
            response = await client.post(
                f"{base}/v1/batch/objects",
                json={"objects": objects},
                headers=headers,
            )
        if response.status_code >= 300:
            raise OrchestratorError(
                f"Weaviate batch upsert failed ({response.status_code}): {response.text[:240]}"
            )
        payload = response.json() if response.content else {}
        if isinstance(payload, dict):
            batch_rows = payload.get("objects")
        elif isinstance(payload, list):
            batch_rows = payload
        else:
            batch_rows = []
        if isinstance(batch_rows, list):
            for row in batch_rows:
                if not isinstance(row, dict):
                    continue
                result = row.get("result") if isinstance(row.get("result"), dict) else {}
                errors = result.get("errors") if isinstance(result.get("errors"), dict) else {}
                messages = errors.get("error") if isinstance(errors.get("error"), list) else []
                if messages:
                    text = "; ".join(
                        str(message.get("message") or message.get("msg") or "")
                        for message in messages
                        if isinstance(message, dict)
                    ).strip()
                    raise OrchestratorError(
                        f"Weaviate batch item failed: {text or 'unknown error'}"
                    )


def _langfuse_trace_event(project: str, summary: str, payload: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": str(uuid.uuid4()),
        "type": "trace",
        "name": project,
        "metadata": {"summary": summary},
        "input": payload,
    }


async def _ingest_langfuse_events(
    events: list[dict[str, Any]],
    raise_on_error: bool = True,
) -> None:
    if not LANGFUSE_API_KEY or not events:
        return
    headers = {"x-langfuse-api-key": LANGFUSE_API_KEY}
    client = await _get_langfuse_client()
    try:
        resp = await client.post(f"{LANGFUSE_URL}/api/public/ingest", json=events, headers=headers)
    except Exception as exc:
        if raise_on_error:
            raise OrchestratorError(f"Langfuse ingest failed: {exc}") from exc
        logger.warning("Failed to push trace to Langfuse: %s", exc)
        return
    if resp.status_code >= 400:
        message = f"Langfuse ingest failed: status={resp.status_code} body={resp.text[:300]}"
        if raise_on_error:
            raise OrchestratorError(message)
        logger.warning(message)


async def push_to_langfuse(project: str, summary: str, payload: dict[str, Any]) -> None:
    await _ingest_langfuse_events([_langfuse_trace_event(project, summary, payload)], raise_on_error=True)


async def push_batch_to_langfuse(items: list[dict[str, Any]]) -> None:
    if not LANGFUSE_API_KEY or not items:
        return
    events = [
        _langfuse_trace_event(
            str(item.get("project") or ""),
            str(item.get("summary") or ""),
            item.get("payload") if isinstance(item.get("payload"), dict) else {},
        )
        for item in items
    ]
    async with _fanout_rate_limit(langfuse_fanout_rate_limiter):
        await _ingest_langfuse_events(events, raise_on_error=True)


async def trace_to_langfuse(
    operation: str,
    latency_ms: float,
    metadata: dict[str, Any] | None = None,
) -> None:
    """Enhanced Langfuse tracing for orchestrator operations."""
    if not LANGFUSE_API_KEY:
        return
    event = {
        "id": str(uuid.uuid4()),
        "type": "span",
        "name": f"orchestrator.{operation}",
        "startTime": datetime.utcnow().isoformat() + "Z",
        "endTime": (datetime.utcnow()).isoformat() + "Z",
        "metadata": {
            "latency_ms": latency_ms,
            **(metadata or {}),
        },
    }
    await _ingest_langfuse_events([event], raise_on_error=False)


async def summarize_content(content: str, max_length: int = 500) -> str:
    """Summarize long content for embedding. Simple truncation for now."""
    if len(content) <= max_length:
        return content
    # Take first and last portions to preserve context
    mid = max_length // 2
    return content[:mid] + "..." + content[-mid:]


async def search_qdrant(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
    retrieval_mode: str | None = None,
) -> list[dict[str, Any]]:
    """Search Qdrant for relevant notes."""
    start_time = asyncio.get_event_loop().time()
    normalized_mode = _normalize_retrieval_mode(retrieval_mode)
    try:
        query_vector = await asyncio.wait_for(
            embed_text(query),
            timeout=max(1.0, QDRANT_EMBED_TIMEOUT_SECS),
        )
    except Exception as exc:
        logger.warning(
            "Qdrant embedding fallback activated (%s); using deterministic vector",
            str(exc)[:200],
        )
        query_vector = _cheap_embedding(query, FALLBACK_EMBED_DIM)
    if not query_vector:
        query_vector = _cheap_embedding(query, FALLBACK_EMBED_DIM)
    query_dim = max(1, len(query_vector))
    target_collection = await _resolve_qdrant_collection_for_dimension(
        QDRANT_COLLECTION,
        query_dim,
        operation="read",
    )

    if qdrant_models is None:
        raise RuntimeError("qdrant-client dependency is required for Qdrant operations")

    def _build_filter() -> Any:
        must: list[Any] = []
        if project_filter:
            must.append(
                qdrant_models.FieldCondition(
                    key="project",
                    match=qdrant_models.MatchValue(value=project_filter),
                )
            )
        if topic_filter:
            must.append(
                qdrant_models.FieldCondition(
                    key="topic_tags",
                    match=qdrant_models.MatchValue(value=topic_filter),
                )
            )
        if not must:
            return None
        return qdrant_models.Filter(must=must)

    query_filter = _build_filter()

    def _extract_points_from_query_response(response: Any) -> list[Any]:
        if isinstance(response, list):
            return response
        points = getattr(response, "points", None)
        if isinstance(points, list):
            return points
        if isinstance(response, dict):
            candidate = response.get("points")
            if isinstance(candidate, list):
                return candidate
        return []

    effective_hnsw_ef = _qdrant_mode_hnsw_ef(normalized_mode)
    search_params = None
    if qdrant_models is not None and (
        effective_hnsw_ef > 0
        or QDRANT_SEARCH_EXACT
        or QDRANT_SEARCH_INDEXED_ONLY
    ):
        search_params = qdrant_models.SearchParams(
            hnsw_ef=effective_hnsw_ef if effective_hnsw_ef > 0 else None,
            exact=bool(QDRANT_SEARCH_EXACT),
            indexed_only=bool(QDRANT_SEARCH_INDEXED_ONLY),
        )

    async def _run_search(vector: list[float], requested_limit: int, collection_name: str) -> Any:
        bounded_limit = _qdrant_mode_limit_cap(normalized_mode, max(1, int(requested_limit)))
        if query_filter is None and QDRANT_FILTERLESS_LIMIT_CAP > 0:
            bounded_limit = min(bounded_limit, int(QDRANT_FILTERLESS_LIMIT_CAP))

        async def _execute_search(client: Any, _: str) -> Any:
            if hasattr(client, "search"):
                return await client.search(
                    collection_name=collection_name,
                    query_vector=vector,
                    query_filter=query_filter,
                    limit=bounded_limit,
                    with_payload=True,
                    search_params=search_params,
                )
            if hasattr(client, "query_points"):
                response = await client.query_points(
                    collection_name=collection_name,
                    query=vector,
                    query_filter=query_filter,
                    limit=bounded_limit,
                    with_payload=True,
                    search_params=search_params,
                )
                return _extract_points_from_query_response(response)
            raise RuntimeError("Qdrant client does not expose search/query_points")

        return await _qdrant_call("search", _execute_search)

    try:
        hits = await _run_search(query_vector, limit, target_collection)
    except Exception as exc:
        expected_dim = _qdrant_expected_dim(str(exc))
        if expected_dim and expected_dim > 0 and expected_dim != len(query_vector):
            if QDRANT_DIMENSION_POLICY == "legacy_fallback":
                fallback_vector = _cheap_embedding(query, expected_dim)
                hits = await _run_search(fallback_vector, limit, QDRANT_COLLECTION)
            else:
                rerouted_collection = await _resolve_qdrant_collection_for_dimension(
                    QDRANT_COLLECTION,
                    query_dim,
                    operation="read_retry",
                )
                hits = await _run_search(query_vector, limit, rerouted_collection)
        elif QDRANT_SEARCH_TIMEOUT_RETRY_ENABLED and _is_retrieval_timeout_error(exc):
            retry_limit = max(1, int(math.ceil(limit * QDRANT_SEARCH_TIMEOUT_RETRY_LIMIT_FACTOR)))
            hits = await _run_search(query_vector, retry_limit, target_collection)
        else:
            raise RuntimeError(f"Qdrant search failed: {exc}") from exc

    results = []
    for hit in hits:
        payload = getattr(hit, "payload", None) or {}
        file_name = str(payload.get("file") or "")
        topic_path = normalize_topic_path(str(payload.get("topic_path") or "")) or derive_topic_path(file_name, None)
        results.append({
            "project": payload.get("project"),
            "file": file_name,
            "summary": payload.get("summary"),
            "score": getattr(hit, "score", None),
            "topic_path": topic_path or None,
            "code_context": payload.get("code_context") if isinstance(payload.get("code_context"), dict) else None,
        })

    latency_ms = (asyncio.get_event_loop().time() - start_time) * 1000
    await trace_to_langfuse(
        "search",
        latency_ms,
        {"query_length": len(query), "results": len(results)},
    )
    return results


async def search_weaviate(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
) -> list[dict[str, Any]]:
    if not WEAVIATE_ENABLED:
        return []
    await _ensure_weaviate_schema()
    client = await _get_weaviate_client()
    base = WEAVIATE_URL.rstrip("/")
    headers = _weaviate_headers()
    escaped_query = _weaviate_graphql_escape(query)
    where_clauses: list[str] = []
    if project_filter:
        where_clauses.append(
            '{path:["project"],operator:Equal,valueText:"%s"}'
            % _weaviate_graphql_escape(project_filter)
        )
    if topic_filter:
        where_clauses.append(
            '{path:["topic_path"],operator:Like,valueText:"%s*"}'
            % _weaviate_graphql_escape(topic_filter)
        )
    where_block = ""
    if len(where_clauses) == 1:
        where_block = f" where:{where_clauses[0]}"
    elif len(where_clauses) > 1:
        where_block = " where:{operator:And operands:[%s]}" % ",".join(where_clauses)
    graphql = (
        "{ Get { %s(limit:%d bm25:{query:\"%s\"}%s) "
        "{ project file summary topic_path topic_tags _additional { score } } } }"
        % (
            WEAVIATE_CLASS,
            max(1, int(limit)),
            escaped_query,
            where_block,
        )
    )
    response = await client.post(
        f"{base}/v1/graphql",
        json={"query": graphql},
        headers=headers,
        timeout=max(1.0, RETRIEVAL_WEAVIATE_TIMEOUT_SECS),
    )
    if response.status_code >= 300:
        raise OrchestratorError(
            f"Weaviate search failed ({response.status_code}): {response.text[:240]}"
        )
    payload = response.json() if response.content else {}
    rows = (
        payload.get("data", {})
        .get("Get", {})
        .get(WEAVIATE_CLASS, [])
        if isinstance(payload, dict)
        else []
    )
    if not isinstance(rows, list):
        return []
    results: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        project_name = _weaviate_text(row.get("project"))
        file_name = _weaviate_text(row.get("file"))
        summary = _weaviate_text(row.get("summary"))
        topic_path = normalize_topic_path(_weaviate_text(row.get("topic_path")))
        if topic_filter and topic_path and not (
            topic_path == topic_filter or topic_path.startswith(f"{topic_filter}/")
        ):
            continue
        if not project_name or not file_name or not summary:
            continue
        additional = row.get("_additional") if isinstance(row.get("_additional"), dict) else {}
        score = additional.get("score")
        if score is None:
            score = _text_match_score(query, f"{project_name}\n{file_name}\n{summary}")
        results.append(
            {
                "project": project_name,
                "file": file_name,
                "summary": summary,
                "score": float(score or 0.0),
                "source": RETRIEVAL_SOURCE_WEAVIATE,
                "topic_path": topic_path or derive_topic_path(file_name, None),
            }
        )
    results.sort(key=lambda item: float(item.get("score") or 0.0), reverse=True)
    return results[: max(1, int(limit))]


async def search_memory_bank_lexical(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
    time_budget_secs: float | None = None,
    backend_mode_override: str | None = None,
    fallback_trace: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    global memory_bank_spike_fallbacks

    def _memory_bank_backend_mode() -> str:
        if backend_mode_override is not None:
            return _normalize_memory_bank_backend_choice(
                backend_mode_override,
                default=MEMORY_BANK_SPIKE_BACKEND,
            )
        return MEMORY_BANK_SPIKE_BACKEND

    async def _search_memory_bank_spike_backend(
        *,
        backend_mode: str,
        search_query: str,
        search_limit: int,
        project_name: str | None,
        topic_path: str | None,
        budget_secs: float,
    ) -> list[dict[str, Any]]:
        global memory_bank_spike_attempts, memory_bank_spike_successes, memory_bank_spike_failures
        global memory_bank_spike_last_error, memory_bank_spike_last_latency_ms

        if backend_mode in {"native", "disabled"}:
            return []
        if not MEMORY_BANK_SPIKE_HTTP_URL:
            raise OrchestratorError("memory-bank spike backend URL is not configured")

        route = MEMORY_BANK_SPIKE_SEARCH_ROUTE.strip() or "/search"
        if not route.startswith("/"):
            route = "/" + route
        url = MEMORY_BANK_SPIKE_HTTP_URL.rstrip("/") + route
        payload: dict[str, Any] = {
            "query": search_query,
            "limit": max(1, int(search_limit)),
            "backend": backend_mode,
        }
        if project_name:
            payload["project"] = project_name
        if topic_path:
            payload["topic_path"] = topic_path
        timeout_cap = float(
            MEMORY_BANK_SPIKE_TIMEOUT_OVERRIDES_SECS.get(backend_mode, MEMORY_BANK_SPIKE_TIMEOUT_SECS)
        )
        timeout_secs = max(0.2, min(timeout_cap, max(0.2, float(budget_secs))))

        memory_bank_spike_attempts += 1
        started = time.monotonic()
        try:
            async with httpx.AsyncClient(timeout=timeout_secs) as client:
                response = await client.post(url, json=payload)
            response.raise_for_status()
            response_payload = response.json()
            rows_raw = (
                response_payload.get("results")
                if isinstance(response_payload, dict) and isinstance(response_payload.get("results"), list)
                else response_payload.get("rows")
                if isinstance(response_payload, dict) and isinstance(response_payload.get("rows"), list)
                else []
            )
            parsed_rows: list[dict[str, Any]] = []
            for row in rows_raw:
                if not isinstance(row, dict):
                    continue
                project_name = str(row.get("project") or project_filter or "").strip()
                file_name = str(row.get("file") or row.get("path") or "").strip()
                summary = str(row.get("summary") or row.get("content") or "").strip()
                if not project_name or not file_name or not summary:
                    continue
                score = max(
                    0.0,
                    float(
                        row.get("score")
                        if row.get("score") is not None
                        else _text_match_score(search_query, f"{file_name}\n{summary}")
                    ),
                )
                parsed_rows.append(
                    {
                        "project": project_name,
                        "file": file_name,
                        "summary": summary,
                        "score": score,
                        "source": RETRIEVAL_SOURCE_MEMORY_BANK,
                        "topic_path": normalize_topic_path(str(row.get("topic_path") or "")) or derive_topic_path(
                            file_name,
                            None,
                        ),
                        "backend": backend_mode,
                    }
                )
            parsed_rows.sort(key=lambda item: float(item.get("score") or 0.0), reverse=True)
            memory_bank_spike_successes += 1
            memory_bank_spike_last_error = None
            memory_bank_spike_last_latency_ms = (time.monotonic() - started) * 1000.0
            return parsed_rows[: max(1, int(search_limit))]
        except Exception as exc:
            memory_bank_spike_failures += 1
            memory_bank_spike_last_error = str(exc).strip() or exc.__class__.__name__
            memory_bank_spike_last_latency_ms = (time.monotonic() - started) * 1000.0
            raise

    terms = _query_terms(query)
    trace_payload = fallback_trace if isinstance(fallback_trace, dict) else None
    trace_steps: list[dict[str, Any]] = []
    trace_native_used = False
    trace_selected_backend: str | None = None
    trace_native_rows = 0
    if not terms:
        if trace_payload is not None:
            trace_payload.clear()
            trace_payload.update(
                {
                    "version": 1,
                    "backend_requested": None,
                    "backend_sequence": [],
                    "steps": [],
                    "selected_backend": None,
                    "native_used": False,
                    "native_rows": 0,
                    "budget_secs": 0.0,
                    "reason": "empty_query_terms",
                }
            )
        return []
    backend_mode = _memory_bank_backend_mode()
    if backend_mode == "disabled":
        if trace_payload is not None:
            trace_payload.clear()
            trace_payload.update(
                {
                    "version": 1,
                    "backend_requested": backend_mode,
                    "backend_sequence": [],
                    "steps": [],
                    "selected_backend": None,
                    "native_used": False,
                    "native_rows": 0,
                    "budget_secs": 0.0,
                    "reason": "backend_disabled",
                }
            )
        return []
    fallback_candidates: list[str] = []
    for configured in MEMORY_BANK_SPIKE_FALLBACK_BACKENDS:
        candidate = _normalize_memory_bank_backend_choice(configured, default="native")
        if candidate in {"native", "disabled"} or candidate == backend_mode:
            continue
        if candidate in fallback_candidates:
            continue
        fallback_candidates.append(candidate)
    query_targets_low_value_paths = _query_targets_low_value_paths(query)
    started = time.monotonic()
    budget_secs = max(
        0.75,
        float(time_budget_secs if time_budget_secs is not None else RETRIEVAL_MEMORY_TIMEOUT_SECS),
    )

    def _remaining_budget() -> float:
        return max(0.0, budget_secs - (time.monotonic() - started))

    def _record_trace_step(
        *,
        backend: str,
        status: str,
        reason: str,
        rows: int | None = None,
        error: str | None = None,
        elapsed_ms: float | None = None,
        timeout_secs: float | None = None,
        next_backend: str | None = None,
    ) -> None:
        if trace_payload is None:
            return
        step: dict[str, Any] = {
            "backend": str(backend).strip().lower(),
            "status": str(status).strip().lower(),
            "reason": str(reason).strip().lower(),
        }
        if rows is not None:
            step["rows"] = max(0, int(rows))
        if error:
            step["error"] = str(error).strip()[:240]
        if elapsed_ms is not None:
            step["elapsed_ms"] = round(max(0.0, float(elapsed_ms)), 3)
        if timeout_secs is not None:
            step["timeout_secs"] = round(max(0.0, float(timeout_secs)), 3)
        if next_backend:
            step["next_backend"] = str(next_backend).strip().lower()
        trace_steps.append(step)

    def _finalize_trace(*, reason: str, selected_backend: str | None, native_rows: int = 0) -> None:
        if trace_payload is None:
            return
        trace_payload.clear()
        trace_payload.update(
            {
                "version": 1,
                "backend_requested": backend_mode,
                "backend_sequence": (
                    [backend_mode, *fallback_candidates]
                    if backend_mode != "native"
                    else ["native"]
                ),
                "steps": [dict(step) for step in trace_steps],
                "selected_backend": selected_backend,
                "native_used": bool(selected_backend == "native" or trace_native_used or backend_mode == "native"),
                "native_rows": max(0, int(native_rows)),
                "budget_secs": round(max(0.0, float(budget_secs)), 3),
                "empty_result_fallback": bool(MEMORY_BANK_SPIKE_EMPTY_RESULT_FALLBACK),
                "fallback_to_native": bool(MEMORY_BANK_SPIKE_FALLBACK_TO_NATIVE),
                "reason": str(reason).strip().lower(),
            }
        )

    if backend_mode != "native":
        spike_candidates = [backend_mode, *fallback_candidates]
        for idx, spike_backend in enumerate(spike_candidates):
            is_last_candidate = idx == (len(spike_candidates) - 1)
            candidate_started = time.monotonic()
            remaining_budget = _remaining_budget()
            timeout_budget = max(0.2, min(budget_secs, max(0.2, remaining_budget)))
            try:
                spike_rows = await _search_memory_bank_spike_backend(
                    backend_mode=spike_backend,
                    search_query=query,
                    search_limit=limit,
                    project_name=project_filter,
                    topic_path=topic_filter,
                    budget_secs=timeout_budget,
                )
                if spike_rows:
                    trace_selected_backend = spike_backend
                    _record_trace_step(
                        backend=spike_backend,
                        status="success",
                        reason="rows_returned",
                        rows=len(spike_rows),
                        elapsed_ms=(time.monotonic() - candidate_started) * 1000.0,
                        timeout_secs=timeout_budget,
                    )
                    _finalize_trace(
                        reason="spike_success",
                        selected_backend=trace_selected_backend,
                        native_rows=0,
                    )
                    return spike_rows[:limit]
                _record_trace_step(
                    backend=spike_backend,
                    status="empty",
                    reason="no_rows",
                    rows=0,
                    elapsed_ms=(time.monotonic() - candidate_started) * 1000.0,
                    timeout_secs=timeout_budget,
                    next_backend=(
                        "native"
                        if is_last_candidate or not MEMORY_BANK_SPIKE_EMPTY_RESULT_FALLBACK
                        else spike_candidates[idx + 1]
                    ),
                )
                if not MEMORY_BANK_SPIKE_EMPTY_RESULT_FALLBACK or is_last_candidate:
                    if not MEMORY_BANK_SPIKE_FALLBACK_TO_NATIVE:
                        trace_selected_backend = spike_backend
                        _finalize_trace(
                            reason="spike_empty_terminal",
                            selected_backend=trace_selected_backend,
                            native_rows=0,
                        )
                        return []
                    memory_bank_spike_fallbacks += 1
                    _record_trace_step(
                        backend=spike_backend,
                        status="fallback",
                        reason="empty_result_to_native",
                        rows=0,
                        next_backend="native",
                    )
                    break
                memory_bank_spike_fallbacks += 1
                _record_trace_step(
                    backend=spike_backend,
                    status="fallback",
                    reason="empty_result_to_next",
                    rows=0,
                    next_backend=spike_candidates[idx + 1],
                )
                logger.debug(
                    "Memory-bank spike backend %s returned no rows; trying fallback backend %s",
                    spike_backend,
                    spike_candidates[idx + 1],
                )
            except Exception as exc:
                _record_trace_step(
                    backend=spike_backend,
                    status="error",
                    reason="backend_error",
                    error=str(exc),
                    elapsed_ms=(time.monotonic() - candidate_started) * 1000.0,
                    timeout_secs=timeout_budget,
                    next_backend=("native" if is_last_candidate else spike_candidates[idx + 1]),
                )
                if not is_last_candidate:
                    memory_bank_spike_fallbacks += 1
                    _record_trace_step(
                        backend=spike_backend,
                        status="fallback",
                        reason="error_to_next",
                        next_backend=spike_candidates[idx + 1],
                    )
                    logger.debug(
                        "Memory-bank spike backend %s failed (%s); trying fallback backend %s",
                        spike_backend,
                        exc,
                        spike_candidates[idx + 1],
                    )
                    continue
                if not MEMORY_BANK_SPIKE_FALLBACK_TO_NATIVE:
                    trace_selected_backend = spike_backend
                    _finalize_trace(
                        reason="spike_error_terminal",
                        selected_backend=trace_selected_backend,
                        native_rows=0,
                    )
                    return []
                memory_bank_spike_fallbacks += 1
                _record_trace_step(
                    backend=spike_backend,
                    status="fallback",
                    reason="error_to_native",
                    next_backend="native",
                )
                logger.debug("Memory-bank spike backend %s failed (%s); using native fallback", spike_backend, exc)
        trace_native_used = True

    project_cap = min(
        max(1, RETRIEVAL_MEMORY_PROJECT_LIMIT),
        max(1, int(math.ceil(budget_secs * 2.5))),
    )
    files_per_project = min(
        max(1, RETRIEVAL_MEMORY_FILES_PER_PROJECT),
        max(6, int(math.ceil(budget_secs * 10))),
    )
    scan_limit = min(
        max(limit * 2, RETRIEVAL_MEMORY_SCAN_LIMIT),
        max(limit * 2, int(math.ceil(budget_secs * 16))),
    )
    if project_filter:
        projects = [project_filter]
    else:
        projects = await list_projects()
    projects = projects[:project_cap]
    name_candidate_cap = max(
        files_per_project,
        scan_limit * 2,
        limit * 4,
    )
    candidates: list[tuple[float, str, str]] = []
    for project in projects:
        if _remaining_budget() <= 0.1:
            break
        try:
            files = await list_files(project)
        except Exception as exc:
            logger.warning("Memory-bank lexical search skipped %s: %s", project, exc)
            continue
        if topic_filter:
            files = [
                file_name
                for file_name in files
                if derive_topic_path(file_name, None).startswith(topic_filter)
            ]
        for file_name in files:
            if _remaining_budget() <= 0.05:
                break
            topic_path = derive_topic_path(file_name, None)
            if (
                MEMORY_BANK_TELEMETRY_GUARD_ENABLED
                and not query_targets_low_value_paths
                and _looks_memory_bank_telemetry_file(file_name, topic_path)
            ):
                continue
            name_score = _text_match_score(query, f"{project}\n{file_name}")
            if name_score <= 0:
                continue
            if len(candidates) < name_candidate_cap:
                heapq.heappush(candidates, (name_score, project, file_name))
                continue
            if name_score <= candidates[0][0]:
                continue
            heapq.heapreplace(candidates, (name_score, project, file_name))
    if not candidates:
        _finalize_trace(
            reason="native_no_candidates",
            selected_backend=("native" if (trace_native_used or backend_mode == "native") else trace_selected_backend),
            native_rows=0,
        )
        return []
    selected = sorted(candidates, key=lambda row: row[0], reverse=True)[:scan_limit]
    parallelism = max(2, min(8, int(math.ceil(budget_secs * 1.5))))
    semaphore = asyncio.Semaphore(parallelism)
    rows: list[dict[str, Any]] = []

    async def _inspect(name_score: float, project: str, file_name: str) -> None:
        async with semaphore:
            remaining = _remaining_budget()
            if remaining <= 0.05:
                return
            try:
                content = await asyncio.wait_for(
                    read_project_file(project, file_name),
                    timeout=max(0.5, min(CONTEXTLATTICE_READ_TIMEOUT_SECS, remaining)),
                )
            except Exception:
                return
            if not content:
                return
            summary = await summarize_content(content)
            score = max(name_score, _text_match_score(query, f"{file_name}\n{summary}"))
            if score <= 0:
                return
            rows.append(
                {
                    "project": project,
                    "file": file_name,
                    "summary": summary,
                    "score": score,
                    "source": RETRIEVAL_SOURCE_MEMORY_BANK,
                    "topic_path": derive_topic_path(file_name, None),
                }
            )

    await asyncio.gather(*[_inspect(score, project, file_name) for score, project, file_name in selected])
    rows.sort(key=lambda row: float(row.get("score") or 0.0), reverse=True)
    if trace_selected_backend is None and rows:
        trace_selected_backend = "native"
    trace_native_rows = len(rows)
    _record_trace_step(
        backend="native",
        status="success" if rows else "empty",
        reason="native_scan_completed",
        rows=len(rows),
        elapsed_ms=(time.monotonic() - started) * 1000.0,
    )
    _finalize_trace(
        reason="native_completed",
        selected_backend=(trace_selected_backend or "native"),
        native_rows=trace_native_rows,
    )
    return rows[:limit]


async def search_topic_rollups(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
) -> list[dict[str, Any]]:
    async with topic_rollup_lock:
        snapshot = json.loads(json.dumps(topic_rollup_index))
    sqlite_snapshot_aligned = (
        bool(TOPIC_ROLLUP_SQLITE_ENABLED)
        and str(topic_rollup_sqlite_health.get("lastGeneratedAt") or "") == str(snapshot.get("generatedAt") or "")
        and bool(snapshot.get("generatedAt"))
    )
    if sqlite_snapshot_aligned:
        sqlite_rows = await _topic_rollup_sqlite_search(
            query,
            limit=max(1, int(limit)),
            project_filter=project_filter,
            topic_filter=topic_filter,
        )
        if sqlite_rows:
            return sqlite_rows[: max(1, int(limit))]
    raw_rows = _topic_rollup_rows_from_snapshot(
        snapshot,
        project_filter=project_filter,
        topic_filter=topic_filter,
    )
    rows: list[dict[str, Any]] = []
    for row in raw_rows:
        score = _text_match_score(query, str(row.get("_index_text") or ""))
        if score <= 0:
            continue
        rows.append(
            {
                "project": row.get("project"),
                "file": row.get("file"),
                "summary": row.get("summary"),
                "score": score,
                "source": row.get("source"),
                "topic_path": row.get("topic_path"),
                "topic_rollup": row.get("topic_rollup"),
            }
        )
    rows.sort(key=lambda item: float(item.get("score") or 0.0), reverse=True)
    return rows[: max(1, int(limit))]


async def search_mongo_raw(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
) -> list[dict[str, Any]]:
    if not await init_mongo_client():
        return []
    assert MONGO_CLIENT is not None
    terms = _query_terms(query)
    max_scan = max(limit * 12, RETRIEVAL_MONGO_SCAN_LIMIT)

    def _scan() -> list[dict[str, Any]]:
        coll = MONGO_CLIENT[MONGO_RAW_DB][MONGO_RAW_COLLECTION]
        query_filter: dict[str, Any] = {}
        if project_filter:
            query_filter["project"] = project_filter
        if topic_filter:
            query_filter["topic_path"] = {"$regex": f"^{re.escape(topic_filter)}"}
        projection = {
            "_id": 0,
            "event_id": 1,
            "project": 1,
            "file": 1,
            "summary": 1,
            "content_raw": 1,
            "content_raw_blob_ref": 1,
            "content_raw_blob_codec": 1,
            "content_raw_blob_bytes": 1,
            "content_raw_raw_bytes": 1,
            "topic_path": 1,
            "topic_tags": 1,
            "code_context": 1,
            "created_at": 1,
            "updated_at": 1,
        }
        docs = list(
            coll.find(query_filter, projection=projection)
            .sort("updated_at", -1)
            .limit(max_scan)
        )
        return docs

    try:
        docs = await asyncio.to_thread(_scan)
    except Exception as exc:
        logger.warning("Mongo retrieval search failed: %s", exc)
        return []
    rows: list[dict[str, Any]] = []
    for doc in docs:
        content = _decode_mongo_raw_content_from_doc(doc)
        summary = str(doc.get("summary") or "")
        snippet = summary or (content[:500] if content else "")
        haystack = "\n".join(
            [
                str(doc.get("project") or ""),
                str(doc.get("file") or ""),
                str(doc.get("topic_path") or ""),
                snippet,
            ]
        )
        score = _text_match_score(query, haystack)
        if score <= 0 and terms:
            continue
        rows.append(
            {
                "project": doc.get("project"),
                "file": doc.get("file"),
                "summary": snippet,
                "score": score,
                "source": RETRIEVAL_SOURCE_MONGO_RAW,
                "event_id": doc.get("event_id"),
                "topic_path": doc.get("topic_path"),
                "created_at": doc.get("created_at"),
                "code_context": doc.get("code_context") if isinstance(doc.get("code_context"), dict) else None,
            }
        )
    rows.sort(key=lambda row: float(row.get("score") or 0.0), reverse=True)
    return rows[:limit]


async def search_mindsdb_memory(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
) -> list[dict[str, Any]]:
    global mindsdb_retrieval_lz4_cooldown_until_monotonic, mindsdb_retrieval_lz4_hits, mindsdb_retrieval_lz4_skipped
    if not MINDSDB_ENABLED or not MINDSDB_AUTOSYNC:
        return []
    if _mindsdb_retrieval_circuit_open():
        mindsdb_retrieval_lz4_skipped += 1
        remaining = max(0.0, mindsdb_retrieval_lz4_cooldown_until_monotonic - time.monotonic())
        _log_mindsdb_retrieval_warning(
            "circuit-open",
            f"MindsDB retrieval temporarily skipped while LZ4 circuit is open ({remaining:.1f}s remaining).",
        )
        return []
    try:
        await ensure_mindsdb_table()
    except Exception as exc:
        _log_mindsdb_retrieval_warning("bootstrap", f"MindsDB retrieval bootstrap failed: {exc}")
        return []
    safe_query = _sanitize_mindsdb_query_text(query)
    if not safe_query:
        return []
    db_name = mindsdb_target_db or MINDSDB_AUTOSYNC_DB
    table_name = mindsdb_target_table or MINDSDB_AUTOSYNC_TABLE
    clauses: list[str] = []
    if project_filter:
        clauses.append(f"project = '{_escape_sql_literal(project_filter)}'")
    if topic_filter:
        escaped_topic = _escape_sql_literal(topic_filter)
        clauses.append(f"(file LIKE '{escaped_topic}/%' OR file LIKE '{escaped_topic}%')")
    terms = _query_terms(safe_query, max_terms=6)
    if terms:
        term_predicates = [
            f"LOWER(summary) LIKE '%{_escape_sql_literal(term.lower())}%'"
            for term in terms
        ]
        term_predicates.extend(
            [
                f"LOWER(file) LIKE '%{_escape_sql_literal(term.lower())}%'"
                for term in terms
            ]
        )
        clauses.append("(" + " OR ".join(term_predicates) + ")")
    where_clause = f"WHERE {' AND '.join(clauses)}" if clauses else ""
    scan_limit = max(limit * 12, RETRIEVAL_MINDSDB_SCAN_LIMIT)
    raw: dict[str, Any] | None = None
    query_error: Exception | None = None
    for attempt in range(2):
        db_name = mindsdb_target_db or db_name or MINDSDB_AUTOSYNC_DB
        table_name = mindsdb_target_table or table_name or MINDSDB_AUTOSYNC_TABLE
        sql = (
            f"SELECT project, file, summary, created_at "
            f"FROM {db_name}.{table_name} "
            f"{where_clause} ORDER BY created_at DESC LIMIT {scan_limit};"
        )
        try:
            raw = await _mindsdb_execute(sql)
            query_error = None
            break
        except Exception as exc:
            query_error = exc
            if (
                attempt == 0
                and _looks_like_mindsdb_table_corruption(str(exc))
                and not _is_mindsdb_lz4_decompress_error(exc)
                and await _switch_mindsdb_to_fallback(str(exc), current_table=table_name, current_db=db_name)
            ):
                continue
            break
    if raw is None:
        assert query_error is not None
        if _is_mindsdb_lz4_decompress_error(query_error):
            mindsdb_retrieval_lz4_hits += 1
            mindsdb_retrieval_lz4_cooldown_until_monotonic = (
                time.monotonic() + MINDSDB_RETRIEVAL_LZ4_COOLDOWN_SECS
            )
            _log_mindsdb_retrieval_warning(
                "lz4",
                (
                    "MindsDB retrieval query failed with storage decode/format error; "
                    f"circuit opened for {MINDSDB_RETRIEVAL_LZ4_COOLDOWN_SECS:.1f}s."
                ),
            )
        else:
            _log_mindsdb_retrieval_warning(
                "query",
                f"MindsDB retrieval query failed: {query_error}",
            )
        return []
    rows: list[dict[str, Any]] = []
    for row in _mindsdb_rows(raw):
        project = str(row.get("project") or "")
        file_name = str(row.get("file") or "")
        summary = str(row.get("summary") or "")
        score = _text_match_score(safe_query, f"{project}\n{file_name}\n{summary}")
        if score <= 0 and terms:
            continue
        rows.append(
            {
                "project": project,
                "file": file_name,
                "summary": summary,
                "score": score,
                "source": RETRIEVAL_SOURCE_MINDSDB,
                "created_at": row.get("created_at"),
                "topic_path": derive_topic_path(file_name, None),
            }
        )
    rows.sort(key=lambda row: float(row.get("score") or 0.0), reverse=True)
    return rows[:limit]


async def search_letta_archival(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
    timeout_secs: float | None = None,
    retrieval_mode: str | None = None,
) -> list[dict[str, Any]]:
    if not _letta_config_enabled():
        return []
    limit = max(1, int(limit))
    headers: dict[str, str] = {}
    if LETTA_API_KEY:
        headers["Authorization"] = f"Bearer {LETTA_API_KEY}"
    try:
        agent_id = await _resolve_letta_agent_id(LETTA_AUTO_SESSION_ID, headers)
    except Exception as exc:
        logger.warning("Letta retrieval agent resolution failed: %s", exc)
        return []
    top_k_factor, top_k_cap = _letta_top_k_settings_for_mode(retrieval_mode)
    top_k = max(limit, int(limit * max(1.0, top_k_factor)))
    top_k = min(top_k, max(1, int(top_k_cap)))
    cache_key = _letta_search_cache_key(
        query=query,
        limit=limit,
        project_filter=project_filter,
        topic_filter=topic_filter,
        top_k=top_k,
    )
    cached_rows = await _letta_search_cache_get(cache_key)
    if cached_rows is not None:
        return cached_rows[:limit]
    effective_timeout = _letta_effective_timeout(timeout_secs)
    try:
        data = await _fetch_letta_archival_payload(
            agent_id=agent_id,
            query=query,
            top_k=top_k,
            headers=headers,
            project_filter=project_filter,
            timeout_secs=effective_timeout,
        )
    except asyncio.CancelledError:
        with contextlib.suppress(Exception):
            await asyncio.shield(
                _schedule_letta_search_cache_warm(
                    cache_key=cache_key,
                    agent_id=agent_id,
                    query=query,
                    limit=limit,
                    top_k=top_k,
                    project_filter=project_filter,
                    topic_filter=topic_filter,
                    headers=headers,
                    prior_timeout_secs=effective_timeout,
                )
            )
        raise
    except Exception as exc:
        if _is_retrieval_timeout_error(exc):
            with contextlib.suppress(Exception):
                await _schedule_letta_search_cache_warm(
                    cache_key=cache_key,
                    agent_id=agent_id,
                    query=query,
                    limit=limit,
                    top_k=top_k,
                    project_filter=project_filter,
                    topic_filter=topic_filter,
                    headers=headers,
                    prior_timeout_secs=effective_timeout,
                )
        logger.warning("Letta retrieval query failed: %s", exc)
        return []
    rows = _letta_search_rows_from_payload(
        payload=data,
        query=query,
        limit=limit,
        project_filter=project_filter,
        topic_filter=topic_filter,
    )
    await _letta_search_cache_set(cache_key, rows)
    return rows


def _merge_federated_rows(
    results_by_source: dict[str, list[dict[str, Any]]],
    source_weights: dict[str, float],
    positive_terms: set[str],
    negative_terms: set[str],
    learning_enabled: bool,
    *,
    query: str = "",
    source_quality_multipliers: dict[str, float] | None = None,
    lifecycle_snapshot: dict[str, dict[str, Any]] | None = None,
    retrieval_intent: str = RETRIEVAL_INTENT_DEFAULT,
) -> list[dict[str, Any]]:
    normalized_intent = _normalize_retrieval_intent(retrieval_intent)
    normalized_query = re.sub(r"\s+", " ", str(query or "").strip().lower())
    query_targets_low_value_paths = _query_targets_low_value_paths(normalized_query)
    query_numeric_values = set(
        _extract_numeric_values_verbatim(normalized_query, limit=16)
    )
    quality_multipliers = {
        str(source).strip().lower(): float(multiplier)
        for source, multiplier in (source_quality_multipliers or {}).items()
    }
    lifecycle_records = lifecycle_snapshot if isinstance(lifecycle_snapshot, dict) else {}
    now_monotonic = time.monotonic()
    merged: dict[str, dict[str, Any]] = {}
    for source, rows in results_by_source.items():
        source_name = str(source or "").strip().lower()
        source_weight = float(source_weights.get(source_name, source_weights.get(source, 1.0)))
        quality_multiplier = float(quality_multipliers.get(source_name, 1.0))
        for row in rows:
            key = _result_identity(row)
            summary = str(row.get("summary") or "")
            file_name = str(row.get("file") or "")
            project = str(row.get("project") or "")
            topic_path = normalize_topic_path(str(row.get("topic_path") or "")) or derive_topic_path(file_name, None)
            text_blob = f"{project}\n{file_name}\n{summary}".lower()
            base_score = float(row.get("score") or 0.0)
            positive_hits = sum(1 for term in positive_terms if term in text_blob)
            negative_hits = sum(1 for term in negative_terms if term in text_blob)
            learning_adjustment = 0.0
            if learning_enabled:
                learning_adjustment += positive_hits * RETRIEVAL_LEARNING_POSITIVE_BOOST
                learning_adjustment -= negative_hits * RETRIEVAL_LEARNING_NEGATIVE_PENALTY
            lexical_adjustment = 0.0
            numeric_adjustment = 0.0
            numeric_match_ratio = 0.0
            if RETRIEVAL_FUSION_ENABLED and normalized_query:
                lexical_adjustment = (
                    _text_match_score(normalized_query, text_blob)
                    * RETRIEVAL_FUSION_LEXICAL_BOOST
                )
                if RETRIEVAL_FUSION_NUMERIC_MATCH_ENABLED and query_numeric_values:
                    row_numeric_values = set(
                        _extract_numeric_values_verbatim(text_blob, limit=16)
                    )
                    if row_numeric_values:
                        numeric_matches = len(query_numeric_values.intersection(row_numeric_values))
                        numeric_misses = max(0, len(query_numeric_values) - numeric_matches)
                        if len(query_numeric_values) > 0:
                            numeric_match_ratio = numeric_matches / len(query_numeric_values)
                            numeric_miss_ratio = numeric_misses / len(query_numeric_values)
                        else:
                            numeric_miss_ratio = 0.0
                        numeric_adjustment = (
                            numeric_match_ratio * RETRIEVAL_FUSION_NUMERIC_MATCH_BOOST
                            - numeric_miss_ratio * RETRIEVAL_FUSION_NUMERIC_MISS_PENALTY
                        )
                    else:
                        numeric_adjustment = -RETRIEVAL_FUSION_NUMERIC_MISS_PENALTY
            lifecycle_adjustment = _retrieval_lifecycle_adjustment(
                key=key,
                lifecycle_snapshot=lifecycle_records,
                now_monotonic=now_monotonic,
            )
            code_symbol_adjustment, code_path_adjustment, code_recency_adjustment = _code_context_adjustments(
                query=normalized_query or query,
                row=row,
            )
            code_context_adjustment = (
                code_symbol_adjustment + code_path_adjustment + code_recency_adjustment
            )
            fusion_adjustment = lexical_adjustment + numeric_adjustment
            weighted_base = base_score * source_weight * quality_multiplier
            composite_score = (
                weighted_base
                + learning_adjustment
                + fusion_adjustment
                + lifecycle_adjustment
                + code_context_adjustment
            )
            low_value_row = _is_low_value_memory_record(
                file_name=file_name,
                topic_path=topic_path,
                summary=summary,
                source_kind=str(row.get("source_kind") or ""),
                include_short_summary=False,
            )
            low_value_penalty = 0.0
            low_value_suppressed = False
            suppress_low_value = RETRIEVAL_LOW_VALUE_NON_LETTA_SUPPRESS
            if (
                normalized_intent == RETRIEVAL_INTENT_RAW
                and RETRIEVAL_INTENT_RAW_DISABLE_LOW_VALUE_SUPPRESS
            ):
                suppress_low_value = False
            if (
                suppress_low_value
                and source_name != RETRIEVAL_SOURCE_LETTA
                and low_value_row
                and not query_targets_low_value_paths
            ):
                low_value_penalty = RETRIEVAL_LOW_VALUE_NON_LETTA_PENALTY
                composite_score -= low_value_penalty
                if RETRIEVAL_LOW_VALUE_NON_LETTA_SCORE_CAP > 0:
                    composite_score = min(composite_score, RETRIEVAL_LOW_VALUE_NON_LETTA_SCORE_CAP)
                low_value_suppressed = True
            normalized = dict(row)
            normalized["source"] = source_name or source
            normalized["sources"] = [source_name or source]
            normalized["topic_path"] = topic_path or row.get("topic_path")
            normalized["base_score"] = round(base_score, 6)
            normalized["source_weight"] = round(source_weight, 4)
            normalized["quality_multiplier"] = round(quality_multiplier, 6)
            normalized["learning_adjustment"] = round(learning_adjustment, 6)
            normalized["fusion_adjustment"] = round(fusion_adjustment, 6)
            normalized["lexical_adjustment"] = round(lexical_adjustment, 6)
            normalized["numeric_adjustment"] = round(numeric_adjustment, 6)
            normalized["numeric_match_ratio"] = round(numeric_match_ratio, 6)
            normalized["lifecycle_adjustment"] = round(lifecycle_adjustment, 6)
            normalized["code_context_adjustment"] = round(code_context_adjustment, 6)
            normalized["code_symbol_adjustment"] = round(code_symbol_adjustment, 6)
            normalized["code_path_adjustment"] = round(code_path_adjustment, 6)
            normalized["code_recency_adjustment"] = round(code_recency_adjustment, 6)
            normalized["low_value"] = bool(low_value_row)
            normalized["low_value_penalty"] = round(low_value_penalty, 6)
            normalized["low_value_suppressed"] = bool(low_value_suppressed)
            normalized["pre_consensus_score"] = round(composite_score, 6)
            normalized["score"] = round(composite_score, 6)
            existing = merged.get(key)
            if existing is None:
                merged[key] = normalized
                continue
            sources = set(existing.get("sources") or [])
            sources.add(source_name or source)
            existing["sources"] = sorted(sources)
            if composite_score > float(existing.get("pre_consensus_score") or existing.get("score") or 0.0):
                normalized["sources"] = sorted(sources)
                merged[key] = normalized
    rows = list(merged.values())
    for row in rows:
        sources = sorted(set(row.get("sources") or []))
        consensus_adjustment = 0.0
        if RETRIEVAL_FUSION_ENABLED and len(sources) > 1:
            consensus_adjustment = (len(sources) - 1) * RETRIEVAL_FUSION_CONSENSUS_BOOST
        pre_consensus = float(row.get("pre_consensus_score") or row.get("score") or 0.0)
        row["sources"] = sources
        row["consensus_adjustment"] = round(consensus_adjustment, 6)
        row["score"] = round(pre_consensus + consensus_adjustment, 6)
    return rows


async def federated_search_memory(
    query: str,
    limit: int = 10,
    project_filter: str | None = None,
    topic_filter: str | None = None,
    sources: list[str] | None = None,
    explicit_source_override: bool | None = None,
    source_weights: dict[str, float] | None = None,
    preferences: dict[str, Any] | None = None,
    rerank_with_learning: bool = True,
    retrieval_mode: str = RETRIEVAL_MODE_BALANCED,
    retrieval_intent: str = RETRIEVAL_INTENT_DEFAULT,
    record_pathway_usage: bool = True,
    call_budget_secs: float | None = None,
    bypass_pathway_cache: bool = False,
    traffic_class: str = TRAFFIC_CLASS_USER,
    backend_policy: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any], list[str]]:
    federated_started_monotonic = time.monotonic()
    normalized_mode = _normalize_retrieval_mode(retrieval_mode)
    resolved_intent = _normalize_retrieval_intent(retrieval_intent)
    normalized_traffic_class = _normalize_traffic_class(traffic_class)
    runtime_backend_policy = (
        dict(backend_policy)
        if isinstance(backend_policy, dict)
        else _default_rust_retrieval_backend_policy()
    )
    memory_bank_backend_effective = _normalize_memory_bank_backend_choice(
        runtime_backend_policy.get("memory_bank_backend"),
        default=MEMORY_BANK_SPIKE_BACKEND,
    )
    runtime_backend_policy["memory_bank_backend"] = memory_bank_backend_effective
    normalized_call_budget_secs = (
        max(0.25, float(call_budget_secs))
        if call_budget_secs is not None
        else None
    )
    call_deadline_monotonic = (
        federated_started_monotonic + normalized_call_budget_secs
        if normalized_call_budget_secs is not None
        else None
    )
    call_budget_exhausted = False
    deferred_sources: list[str] = []

    def _remaining_call_budget_secs() -> float | None:
        if call_deadline_monotonic is None:
            return None
        return max(0.0, call_deadline_monotonic - time.monotonic())

    resolved_sources = _resolve_retrieval_sources_for_mode(mode=normalized_mode, sources=sources)
    resolved_weights = _normalize_retrieval_weights(source_weights)
    source_limit = _retrieval_mode_source_limit(limit, normalized_mode)
    explicit_source_override_resolved = bool(explicit_source_override)
    if explicit_source_override is None and sources:
        default_sources = set(_resolve_retrieval_sources_for_mode(mode=normalized_mode, sources=None))
        explicit_source_override_resolved = set(resolved_sources) != default_sources
    explicit_source_override = bool(explicit_source_override_resolved)
    warnings: list[str] = []
    template, template_cache_hit = await _get_retrieval_template(normalized_mode, resolved_sources)
    source_timeouts = {
        source: float(timeout)
        for source, timeout in (template.get("source_timeouts") or {}).items()
    }
    staged_fast_sources = [str(source) for source in (template.get("staged_fast_sources") or [])]
    staged_slow_sources = [str(source) for source in (template.get("staged_slow_sources") or [])]
    if (
        normalized_mode == RETRIEVAL_MODE_DEEP
        and RETRIEVAL_MONGO_RAW_DEEP_SYNC_ONLY_FOR_RAW_INTENT
        and not explicit_source_override
        and resolved_intent != RETRIEVAL_INTENT_RAW
        and RETRIEVAL_SOURCE_MONGO_RAW in staged_fast_sources
    ):
        staged_fast_sources = [
            source
            for source in staged_fast_sources
            if source != RETRIEVAL_SOURCE_MONGO_RAW
        ]
        if RETRIEVAL_SOURCE_MONGO_RAW not in staged_slow_sources:
            staged_slow_sources.append(RETRIEVAL_SOURCE_MONGO_RAW)
    staged_fetch_used = bool(template.get("staged_fetch_used"))
    runtime_policy = await _retrieval_slow_source_runtime_policy(
        sources=resolved_sources,
        retrieval_mode=normalized_mode,
        explicit_source_override=explicit_source_override,
    )
    backlog_policy = _retrieval_backlog_pressure_policy()
    backlog_blocked_sources = set(
        backlog_policy.get("blocked_sources")
        if isinstance(backlog_policy.get("blocked_sources"), list)
        else []
    )
    timeout_overrides = (
        runtime_policy.get("timeout_overrides")
        if isinstance(runtime_policy.get("timeout_overrides"), dict)
        else {}
    )
    degraded_sources = (
        runtime_policy.get("degraded")
        if isinstance(runtime_policy.get("degraded"), dict)
        else {}
    )
    degraded_slow_sources = [
        source
        for source in staged_slow_sources
        if source in degraded_sources
    ]
    circuit_blocked_slow_sources: list[str] = []
    degraded_probe_sources: list[str] = []
    if (
        RETRIEVAL_SLOW_SOURCE_STABILITY_ENABLED
        and RETRIEVAL_SLOW_SOURCE_CIRCUIT_SKIP_ENABLED
        and not explicit_source_override
    ):
        for source in list(staged_slow_sources):
            if source not in degraded_sources:
                continue
            if _degraded_source_probe_allowed(source):
                degraded_probe_sources.append(source)
                continue
            circuit_blocked_slow_sources.append(source)
    backlog_blocked_slow_sources: list[str] = []
    if RETRIEVAL_BACKLOG_GATING_ENABLED and not explicit_source_override:
        for source in list(staged_slow_sources):
            if source in backlog_blocked_sources:
                backlog_blocked_slow_sources.append(source)
    force_include_slow = bool(
        normalized_mode == RETRIEVAL_MODE_DEEP
        and RETRIEVAL_SYNC_ASYNC_DEEP_BLOCKING
        and not explicit_source_override
        and not degraded_slow_sources
        and not circuit_blocked_slow_sources
        and not backlog_blocked_slow_sources
    )
    effective_source_timeouts = dict(source_timeouts)
    for source_name, capped_timeout in timeout_overrides.items():
        if source_name not in effective_source_timeouts:
            continue
        effective_source_timeouts[source_name] = max(
            1.0,
            min(float(effective_source_timeouts[source_name]), float(capped_timeout)),
        )
    if (
        RETRIEVAL_QDRANT_SYNC_TIMEOUT_CAP_SECS > 0.0
        and not explicit_source_override
        and RETRIEVAL_SOURCE_QDRANT in effective_source_timeouts
        and RETRIEVAL_SOURCE_QDRANT in staged_fast_sources
    ):
        effective_source_timeouts[RETRIEVAL_SOURCE_QDRANT] = max(
            1.0,
            min(
                float(effective_source_timeouts[RETRIEVAL_SOURCE_QDRANT]),
                float(RETRIEVAL_QDRANT_SYNC_TIMEOUT_CAP_SECS),
            ),
        )
    fail_open_continuation_sources: list[str] = []

    slow_source_set = set(staged_slow_sources)
    if not slow_source_set:
        slow_source_set = {
            source
            for source in resolved_sources
            if source in DEFAULT_RETRIEVAL_SLOW_SOURCES
        }

    def _schedule_fail_open_continuation(
        source_name: str,
        *,
        timeout_only: bool,
        error: Exception | None = None,
    ) -> bool:
        normalized = str(source_name or "").strip().lower()
        if not normalized:
            return False
        if not RETRIEVAL_FAIL_OPEN_TIMEOUT_CONTINUATION_ENABLED:
            return False
        if normalized not in RETRIEVAL_FAIL_OPEN_TIMEOUT_CONTINUATION_SOURCES:
            return False
        if timeout_only:
            if error is None or not _is_retrieval_timeout_error(error):
                return False
        if normalized in fail_open_continuation_sources:
            return False
        warm_limit = (
            min(source_limit, max(limit, RETRIEVAL_LETTA_SCAN_LIMIT))
            if normalized == RETRIEVAL_SOURCE_LETTA
            else source_limit
        )
        _schedule_background_source_warm(
            source=normalized,
            query=query,
            limit=warm_limit,
            project_filter=project_filter,
            topic_filter=topic_filter,
            timeout_hint_secs=float(
                effective_source_timeouts.get(normalized, RETRIEVAL_LETTA_TIMEOUT_SECS)
            ),
            force=True,
            retrieval_mode=normalized_mode,
        )
        fail_open_continuation_sources.append(normalized)
        return True

    def _slow_sync_timeout_budget_exceeded(source_name: str, phase_label: str) -> bool:
        normalized = str(source_name or "").strip().lower()
        if not normalized or explicit_source_override:
            return False
        if normalized not in slow_source_set:
            return False
        return phase_label in {"slow-sync", "slow-sync-fallback", "all-sync"}

    def _source_error_payload(
        *,
        source_name: str,
        phase_label: str,
        timeout_secs: float | None,
        exc: Exception | None,
        deferred: bool = False,
        budget_exceeded: bool = False,
    ) -> dict[str, Any]:
        message = str(exc or "").strip()
        if deferred and not message:
            message = f"{source_name} retrieval deferred after call budget reached"
        kind = "error"
        timed_out = bool(exc is not None and _is_retrieval_timeout_error(exc))
        if deferred or budget_exceeded:
            kind = "budget_exceeded"
        elif timed_out:
            kind = "timeout"
        timeout_flag = bool(timed_out and kind == "timeout")
        payload = {
            "error": message,
            "kind": kind,
            "timeout": timeout_flag,
            "timed_out": timed_out,
            "budget_exceeded": bool(kind == "budget_exceeded"),
            "phase": phase_label,
        }
        if timeout_secs is not None:
            payload["timeout_secs"] = round(max(0.0, float(timeout_secs)), 3)
        return payload

    source_chain_debug: dict[str, list[dict[str, Any]]] = {}

    async def _timed_source(
        source_name: str,
        timeout_secs: float,
        timeout_as_budget_exceeded: bool,
        retrieval_mode_for_metrics: str,
        coro: Any,
    ) -> list[dict[str, Any]]:
        started = time.monotonic()
        ok = False
        timed_out = False
        try:
            rows = await asyncio.wait_for(coro, timeout=max(1.0, timeout_secs))
            ok = True
            return rows
        except asyncio.TimeoutError as exc:
            timed_out = True
            raise OrchestratorError(
                f"{source_name} retrieval timed out after {timeout_secs:.1f}s"
            ) from exc
        finally:
            await _record_retrieval_source_latency(
                source=source_name,
                duration_ms=(time.monotonic() - started) * 1000,
                ok=ok,
                timed_out=bool(timed_out and not timeout_as_budget_exceeded),
                budget_exceeded=bool(timed_out and timeout_as_budget_exceeded),
                retrieval_mode=_normalize_retrieval_mode(retrieval_mode_for_metrics),
                traffic_class=normalized_traffic_class,
            )

    def _build_source_coro(
        source: str,
        timeout_secs: float,
        retrieval_mode_override: str | None = None,
    ) -> Any:
        source_mode = _normalize_retrieval_mode(retrieval_mode_override or normalized_mode)
        if source == RETRIEVAL_SOURCE_QDRANT:
            return search_qdrant(
                query,
                limit=source_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
                retrieval_mode=source_mode,
            )
        if source == RETRIEVAL_SOURCE_WEAVIATE:
            return search_weaviate(
                query,
                limit=source_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
            )
        if source == RETRIEVAL_SOURCE_POSTGRES_PGVECTOR:
            return search_postgres_pgvector(
                query,
                limit=source_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
            )
        if source == RETRIEVAL_SOURCE_MONGO_RAW:
            return search_mongo_raw(
                query,
                limit=source_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
            )
        if source == RETRIEVAL_SOURCE_MINDSDB:
            return search_mindsdb_memory(
                query,
                limit=source_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
            )
        if source == RETRIEVAL_SOURCE_LETTA:
            letta_limit = min(source_limit, max(limit, RETRIEVAL_LETTA_SCAN_LIMIT))
            return search_letta_archival(
                query,
                limit=letta_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
                timeout_secs=timeout_secs,
                retrieval_mode=source_mode,
            )
        if source == RETRIEVAL_SOURCE_MEMORY_BANK:
            memory_bank_trace: dict[str, Any] = {}
            source_chain_debug.setdefault(RETRIEVAL_SOURCE_MEMORY_BANK, []).append(memory_bank_trace)
            return search_memory_bank_lexical(
                query,
                limit=source_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
                time_budget_secs=timeout_secs,
                backend_mode_override=memory_bank_backend_effective,
                fallback_trace=memory_bank_trace,
            )
        if source == RETRIEVAL_SOURCE_TOPIC_ROLLUPS:
            return search_topic_rollups(
                query,
                limit=source_limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
            )
        raise OrchestratorError(f"Unknown retrieval source: {source}")

    async def _run_source_batch(
        source_batch: list[str],
        *,
        phase_label: str,
        suppress_slow_timeout_warnings: bool = False,
        retrieval_mode_override: str | None = None,
    ) -> tuple[dict[str, list[dict[str, Any]]], dict[str, Any], list[str]]:
        nonlocal call_budget_exhausted
        batch_rows: dict[str, list[dict[str, Any]]] = {}
        batch_errors: dict[str, Any] = {}
        batch_warnings: list[str] = []
        batch_mode = _normalize_retrieval_mode(retrieval_mode_override or normalized_mode)
        if call_deadline_monotonic is not None:
            remaining = _remaining_call_budget_secs()
            if remaining is not None and remaining <= 0.0:
                call_budget_exhausted = True
                for source in source_batch:
                    batch_errors[source] = _source_error_payload(
                        source_name=source,
                        phase_label=phase_label,
                        timeout_secs=effective_source_timeouts.get(source),
                        exc=OrchestratorError(
                            f"{source} retrieval deferred before dispatch (call budget exhausted)"
                        ),
                        deferred=True,
                        budget_exceeded=True,
                    )
                    batch_warnings.append(
                        f"{source} retrieval deferred before dispatch (call budget exhausted)."
                    )
                    continuation_scheduled = _schedule_fail_open_continuation(
                        source,
                        timeout_only=False,
                        error=None,
                    )
                    if source in staged_slow_sources and not continuation_scheduled:
                        warm_limit = (
                            min(source_limit, max(limit, RETRIEVAL_LETTA_SCAN_LIMIT))
                            if source == RETRIEVAL_SOURCE_LETTA
                            else source_limit
                        )
                        _schedule_background_source_warm(
                            source=source,
                            query=query,
                            limit=warm_limit,
                            project_filter=project_filter,
                            topic_filter=topic_filter,
                            timeout_hint_secs=float(
                                effective_source_timeouts.get(source, RETRIEVAL_LETTA_TIMEOUT_SECS)
                            ),
                            retrieval_mode=normalized_mode,
                        )
                    deferred_sources.append(source)
                return batch_rows, batch_errors, batch_warnings
        tasks: dict[str, asyncio.Task[list[dict[str, Any]]]] = {}
        for source in source_batch:
            timeout = float(effective_source_timeouts.get(source, RETRIEVAL_QDRANT_TIMEOUT_SECS))
            tasks[source] = asyncio.create_task(
                _timed_source(
                    source,
                    timeout,
                    _slow_sync_timeout_budget_exceeded(source, phase_label),
                    batch_mode,
                    _build_source_coro(source, timeout, batch_mode),
                )
            )
        if not tasks:
            return batch_rows, batch_errors, batch_warnings
        if call_deadline_monotonic is None:
            gathered = await asyncio.gather(*tasks.values(), return_exceptions=True)
            for source, outcome in zip(tasks.keys(), gathered):
                if isinstance(outcome, Exception):
                    timeout_secs = float(
                        effective_source_timeouts.get(source, RETRIEVAL_QDRANT_TIMEOUT_SECS)
                    )
                    timeout_hit = _is_retrieval_timeout_error(outcome)
                    budget_exceeded = bool(
                        timeout_hit and _slow_sync_timeout_budget_exceeded(source, phase_label)
                    )
                    batch_errors[source] = _source_error_payload(
                        source_name=source,
                        phase_label=phase_label,
                        timeout_secs=timeout_secs,
                        exc=outcome,
                        budget_exceeded=budget_exceeded,
                    )
                    should_show_timeout_warning = not (
                        suppress_slow_timeout_warnings and budget_exceeded
                    )
                    if should_show_timeout_warning:
                        batch_warnings.append(f"{source} retrieval failed: {outcome}")
                    continuation_scheduled = _schedule_fail_open_continuation(
                        source,
                        timeout_only=True,
                        error=outcome,
                    )
                    if continuation_scheduled and should_show_timeout_warning:
                        batch_warnings.append(
                            f"{source} retrieval timed out; continuing asynchronously for cache warm."
                        )
                    continue
                batch_rows[source] = outcome
            return batch_rows, batch_errors, batch_warnings

        task_to_source = {task: source for source, task in tasks.items()}
        pending: set[asyncio.Task[list[dict[str, Any]]]] = set(tasks.values())
        done_total: set[asyncio.Task[list[dict[str, Any]]]] = set()
        while pending:
            remaining = _remaining_call_budget_secs()
            if remaining is None:
                remaining = 0.0
            if remaining <= 0.0:
                call_budget_exhausted = True
                break
            done, still_pending = await asyncio.wait(
                pending,
                timeout=remaining,
                return_when=asyncio.ALL_COMPLETED,
            )
            done_total.update(done)
            pending = set(still_pending)
            if pending:
                call_budget_exhausted = True
                break

        for task in done_total:
            source = task_to_source.get(task) or "unknown"
            timeout_secs = float(effective_source_timeouts.get(source, RETRIEVAL_QDRANT_TIMEOUT_SECS))
            try:
                outcome = task.result()
            except Exception as exc:
                timeout_hit = _is_retrieval_timeout_error(exc)
                budget_exceeded = bool(
                    timeout_hit and _slow_sync_timeout_budget_exceeded(source, phase_label)
                )
                batch_errors[source] = _source_error_payload(
                    source_name=source,
                    phase_label=phase_label,
                    timeout_secs=timeout_secs,
                    exc=exc,
                    budget_exceeded=budget_exceeded,
                )
                should_show_timeout_warning = not (
                    suppress_slow_timeout_warnings and budget_exceeded
                )
                if should_show_timeout_warning:
                    batch_warnings.append(f"{source} retrieval failed: {exc}")
                continuation_scheduled = _schedule_fail_open_continuation(
                    source,
                    timeout_only=True,
                    error=exc,
                )
                if continuation_scheduled and should_show_timeout_warning:
                    batch_warnings.append(
                        f"{source} retrieval timed out; continuing asynchronously for cache warm."
                    )
                continue
            batch_rows[source] = outcome

        if pending:
            for task in pending:
                source = task_to_source.get(task) or "unknown"
                task.cancel()
                deferred_sources.append(source)
                batch_errors[source] = _source_error_payload(
                    source_name=source,
                    phase_label=phase_label,
                    timeout_secs=effective_source_timeouts.get(source),
                    exc=OrchestratorError(f"{source} retrieval deferred after call budget reached"),
                    deferred=True,
                    budget_exceeded=True,
                )
                batch_warnings.append(
                    f"{source} retrieval deferred after call budget reached; returning best-available results."
                )
                continuation_scheduled = _schedule_fail_open_continuation(
                    source,
                    timeout_only=False,
                    error=None,
                )
                if source in staged_slow_sources and not continuation_scheduled:
                    warm_limit = (
                        min(source_limit, max(limit, RETRIEVAL_LETTA_SCAN_LIMIT))
                        if source == RETRIEVAL_SOURCE_LETTA
                        else source_limit
                    )
                    _schedule_background_source_warm(
                        source=source,
                        query=query,
                        limit=warm_limit,
                        project_filter=project_filter,
                        topic_filter=topic_filter,
                        timeout_hint_secs=float(
                            effective_source_timeouts.get(source, RETRIEVAL_LETTA_TIMEOUT_SECS)
                        ),
                        retrieval_mode=normalized_mode,
                    )
            with contextlib.suppress(Exception):
                await asyncio.gather(*pending, return_exceptions=True)
        return batch_rows, batch_errors, batch_warnings

    results_by_source: dict[str, list[dict[str, Any]]] = {}
    source_errors: dict[str, Any] = {}
    positive_terms, negative_terms = _extract_learning_terms(preferences)
    learning_enabled = bool(
        rerank_with_learning
        and RETRIEVAL_ENABLE_LEARNING_RERANK
        and (positive_terms or negative_terms)
    )
    pathway_cache_key = _retrieval_pathway_cache_key(
        query=query,
        limit=limit,
        project_filter=project_filter,
        topic_filter=topic_filter,
        sources=resolved_sources,
        source_weights=resolved_weights,
        retrieval_mode=normalized_mode,
        retrieval_intent=resolved_intent,
        learning_enabled=learning_enabled,
        positive_terms=positive_terms,
        negative_terms=negative_terms,
    )
    negative_cache_eligible = _retrieval_pathway_negative_cache_query_eligible(query)
    if not bypass_pathway_cache and negative_cache_eligible:
        negative_cached = await _retrieval_pathway_negative_cache_get(pathway_cache_key)
        if isinstance(negative_cached, dict):
            cached_debug = (
                negative_cached.get("retrieval_debug")
                if isinstance(negative_cached.get("retrieval_debug"), dict)
                else {}
            )
            cached_debug = dict(cached_debug)
            cached_cache = cached_debug.get("cache") if isinstance(cached_debug.get("cache"), dict) else {}
            cached_cache["pathway_negative_hit"] = True
            cached_cache["pathway_hit"] = False
            cached_cache["template_hit"] = template_cache_hit
            cached_debug["cache"] = cached_cache
            cached_debug["retrieval_mode"] = normalized_mode
            cached_debug["retrieval_intent"] = resolved_intent
            cached_debug.setdefault("sources", list(resolved_sources))
            cached_debug.setdefault("source_weights", dict(resolved_weights))
            cached_debug.setdefault("source_counts", {source: 0 for source in resolved_sources})
            cached_debug.setdefault("source_errors", {})
            cached_warnings = [
                str(item)
                for item in (
                    negative_cached.get("warnings")
                    if isinstance(negative_cached.get("warnings"), list)
                    else []
                )
                if str(item).strip()
            ]
            if record_pathway_usage:
                await _record_retrieval_pathway_observation(
                    query=query,
                    project_filter=project_filter,
                    topic_filter=topic_filter,
                    sources=resolved_sources,
                    source_weights=resolved_weights,
                    retrieval_mode=normalized_mode,
                    retrieval_intent=resolved_intent,
                )
            return [], cached_debug, cached_warnings
    cached_bundle = None
    if not bypass_pathway_cache:
        cached_bundle = await _retrieval_pathway_cache_get(pathway_cache_key)
    if cached_bundle is not None:
        cached_results, cached_debug, cached_warnings = cached_bundle
        cached_debug = dict(cached_debug)
        cached_cache = cached_debug.get("cache") if isinstance(cached_debug.get("cache"), dict) else {}
        cached_cache["pathway_hit"] = True
        cached_cache["template_hit"] = True
        cached_debug["cache"] = cached_cache
        cached_debug["retrieval_mode"] = normalized_mode
        cache_stale = bool(cached_cache.get("pathway_stale"))
        if cache_stale:
            _schedule_retrieval_pathway_swr_refresh(
                query=query,
                limit=limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
                sources=resolved_sources,
                explicit_source_override=explicit_source_override,
                source_weights=resolved_weights,
                preferences=preferences,
                rerank_with_learning=rerank_with_learning,
                retrieval_mode=normalized_mode,
                retrieval_intent=resolved_intent,
            )
        if record_pathway_usage:
            await _record_retrieval_pathway_observation(
                query=query,
                project_filter=project_filter,
                topic_filter=topic_filter,
                sources=resolved_sources,
                source_weights=resolved_weights,
                retrieval_mode=normalized_mode,
                retrieval_intent=resolved_intent,
            )
        return cached_results[:limit], cached_debug, cached_warnings

    lifecycle_snapshot = await _retrieval_lifecycle_snapshot()
    source_quality_snapshot: dict[str, Any] = {
        "enabled": bool(RETRIEVAL_SOURCE_QUALITY_ADAPTIVE_ENABLED),
        "sources": {},
        "multipliers": {},
    }

    slow_sources_skipped: list[str] = []
    async_warm_slow_sources: list[str] = []
    sync_fallback_slow_sources: list[str] = []
    backlog_async_warm_slow_sources: list[str] = []
    mongo_raw_intent_async_sources: list[str] = []
    hard_sync_async_split_applied = False
    rust_quality_fallback_attempted = False
    rust_quality_fallback_applied = False
    rust_quality_fallback_sources_used: list[str] = []
    rust_quality_fallback_mode_used: str | None = None
    if staged_fetch_used:
        fast_rows, fast_errors, fast_warnings = await _run_source_batch(
            staged_fast_sources,
            phase_label="fast",
            suppress_slow_timeout_warnings=False,
        )
        results_by_source.update(fast_rows)
        source_errors.update(fast_errors)
        warnings.extend(fast_warnings)
        source_quality_snapshot = await _retrieval_source_quality_snapshot(
            sources=list(fast_rows.keys()) or list(staged_fast_sources)
        )
        source_quality_multipliers = (
            source_quality_snapshot.get("multipliers")
            if isinstance(source_quality_snapshot.get("multipliers"), dict)
            else {}
        )
        fast_merged = _merge_federated_rows(
            fast_rows,
            resolved_weights,
            positive_terms,
            negative_terms,
            learning_enabled=learning_enabled,
            query=query,
            source_quality_multipliers={
                str(name): float(value)
                for name, value in source_quality_multipliers.items()
            },
            lifecycle_snapshot=lifecycle_snapshot,
            retrieval_intent=resolved_intent,
        )
        fast_merged.sort(
            key=lambda row: (
                float(row.get("score") or 0.0),
                float(row.get("base_score") or 0.0),
            ),
            reverse=True,
        )
        min_results_for_skip = max(1, min(limit, RETRIEVAL_SLOW_SOURCE_MIN_RESULTS))
        top_fast_score = float(fast_merged[0].get("score") or 0.0) if fast_merged else 0.0
        enough_fast_volume = len(fast_merged) >= max(min_results_for_skip, limit * 2)
        fast_sources_with_hits = sum(
            1
            for source_name in staged_fast_sources
            if len(fast_rows.get(source_name, [])) > 0
        )
        enough_fast_diversity = fast_sources_with_hits >= RETRIEVAL_SLOW_SOURCE_MIN_DIVERSITY
        fast_has_material_errors = any(
            _normalize_source_error_detail(error_payload).get("kind") in {"timeout", "error"}
            for error_payload in fast_errors.values()
        )
        fast_sources_failed = bool(not fast_merged or fast_has_material_errors)
        skip_slow = bool(
            len(fast_merged) >= min_results_for_skip
            and enough_fast_diversity
            and (
                top_fast_score >= RETRIEVAL_SLOW_SOURCE_MIN_TOP_SCORE
                or enough_fast_volume
            )
        )
        needs_async_warm_after_skip = bool(
            len(fast_merged) < max(limit, RETRIEVAL_SLOW_SOURCE_MIN_RESULTS)
            or top_fast_score < RETRIEVAL_SLOW_SOURCE_MIN_TOP_SCORE
            or not enough_fast_diversity
        )
        allowed_slow_sources = [
            source
            for source in staged_slow_sources
            if source not in circuit_blocked_slow_sources and source not in backlog_blocked_slow_sources
        ]
        forced_async_slow_sources: list[str] = []
        if (
            RETRIEVAL_SOURCE_MEMORY_BANK in allowed_slow_sources
            and normalized_mode != RETRIEVAL_MODE_DEEP
            and not explicit_source_override
            and not RETRIEVAL_MEMORY_SYNC_NON_DEEP_ENABLED
        ):
            allowed_slow_sources = [
                source
                for source in allowed_slow_sources
                if source != RETRIEVAL_SOURCE_MEMORY_BANK
            ]
            forced_async_slow_sources = [RETRIEVAL_SOURCE_MEMORY_BANK]
        if (
            RETRIEVAL_SOURCE_MONGO_RAW in allowed_slow_sources
            and normalized_mode == RETRIEVAL_MODE_DEEP
            and not explicit_source_override
            and RETRIEVAL_MONGO_RAW_DEEP_SYNC_ONLY_FOR_RAW_INTENT
            and resolved_intent != RETRIEVAL_INTENT_RAW
        ):
            allowed_slow_sources = [
                source
                for source in allowed_slow_sources
                if source != RETRIEVAL_SOURCE_MONGO_RAW
            ]
            if RETRIEVAL_MONGO_RAW_DEEP_ASYNC_WARM_NON_RAW:
                forced_async_slow_sources.append(RETRIEVAL_SOURCE_MONGO_RAW)
                mongo_raw_intent_async_sources.append(RETRIEVAL_SOURCE_MONGO_RAW)
            else:
                slow_sources_skipped.append(RETRIEVAL_SOURCE_MONGO_RAW)
        blocked_slow_sources = [
            source
            for source in staged_slow_sources
            if source in circuit_blocked_slow_sources or source in backlog_blocked_slow_sources
        ]
        if blocked_slow_sources:
            slow_sources_skipped.extend(blocked_slow_sources)
        if forced_async_slow_sources:
            slow_sources_skipped.extend(forced_async_slow_sources)
            async_warm_slow_sources.extend(forced_async_slow_sources)
        if force_include_slow:
            skip_slow = False
        sync_slow_requires_explicit = bool(
            (
                RETRIEVAL_SYNC_SLOW_REQUIRES_EXPLICIT
                or (
                    RETRIEVAL_STRICT_FAST_SYNC_DEFAULT
                    and normalized_mode in {RETRIEVAL_MODE_FAST, RETRIEVAL_MODE_BALANCED}
                )
            )
            and normalized_mode != RETRIEVAL_MODE_DEEP
        )
        if sync_slow_requires_explicit and not explicit_source_override:
            skip_slow = True
            needs_async_warm_after_skip = True
        if (
            RETRIEVAL_BACKLOG_GATING_LETTA_ASYNC_WARM_ENABLED
            and not explicit_source_override
            and backlog_blocked_slow_sources
        ):
            backlog_async_warm_slow_sources = [
                source
                for source in backlog_blocked_slow_sources
                if source == RETRIEVAL_SOURCE_LETTA
            ]
        hard_split_enabled = bool(
            RETRIEVAL_SYNC_ASYNC_SPLIT_ENABLED
            and not explicit_source_override
            and (normalized_mode != RETRIEVAL_MODE_DEEP or not RETRIEVAL_SYNC_ASYNC_DEEP_BLOCKING)
        )
        hard_sync_async_split_applied = hard_split_enabled
        if hard_split_enabled:
            min_fast_results = max(
                1,
                min(limit, RETRIEVAL_SYNC_ASYNC_MIN_FAST_RESULTS),
            )
            needs_sync_fallback = len(fast_merged) < min_fast_results
            fast_error_sources_for_quality_fallback = {
                source_name
                for source_name, error_payload in fast_errors.items()
                if _normalize_source_error_detail(error_payload).get("kind")
                in {"timeout", "error", "budget_exceeded"}
            }
            rust_quality_candidates = [
                source
                for source in RETRIEVAL_RUST_QUALITY_FALLBACK_SOURCES
                if (
                    source in staged_fast_sources
                    and source not in fast_error_sources_for_quality_fallback
                    and len(fast_rows.get(source, [])) == 0
                )
            ]
            if (
                needs_sync_fallback
                and RETRIEVAL_RUST_QUALITY_FALLBACK_ENABLED
                and not explicit_source_override
                and RUST_RETRIEVAL_LEXICAL_BACKEND == "tantivy_lexical"
                and rust_quality_candidates
            ):
                rust_quality_fallback_attempted = True
                rust_quality_fallback_sources_used = sorted(set(rust_quality_candidates))
                rust_quality_fallback_mode_used = RETRIEVAL_RUST_QUALITY_FALLBACK_MODE
                rust_rows, rust_errors, rust_warnings = await _run_source_batch(
                    rust_quality_fallback_sources_used,
                    phase_label="rust-quality-sync-fallback",
                    suppress_slow_timeout_warnings=not fast_sources_failed,
                    retrieval_mode_override=RETRIEVAL_RUST_QUALITY_FALLBACK_MODE,
                )
                results_by_source.update(rust_rows)
                source_errors.update(rust_errors)
                warnings.extend(rust_warnings)

                fast_rows = {
                    source: results_by_source.get(source, [])
                    for source in staged_fast_sources
                }
                fast_merged = _merge_federated_rows(
                    fast_rows,
                    resolved_weights,
                    positive_terms,
                    negative_terms,
                    learning_enabled=learning_enabled,
                    query=query,
                    source_quality_multipliers={
                        str(name): float(value)
                        for name, value in source_quality_multipliers.items()
                    },
                    lifecycle_snapshot=lifecycle_snapshot,
                    retrieval_intent=resolved_intent,
                )
                fast_merged.sort(
                    key=lambda row: (
                        float(row.get("score") or 0.0),
                        float(row.get("base_score") or 0.0),
                    ),
                    reverse=True,
                )
                top_fast_score = float(fast_merged[0].get("score") or 0.0) if fast_merged else 0.0
                enough_fast_volume = len(fast_merged) >= max(min_results_for_skip, limit * 2)
                fast_sources_with_hits = sum(
                    1
                    for source_name in staged_fast_sources
                    if len(fast_rows.get(source_name, [])) > 0
                )
                enough_fast_diversity = fast_sources_with_hits >= RETRIEVAL_SLOW_SOURCE_MIN_DIVERSITY
                needs_async_warm_after_skip = bool(
                    len(fast_merged) < max(limit, RETRIEVAL_SLOW_SOURCE_MIN_RESULTS)
                    or top_fast_score < RETRIEVAL_SLOW_SOURCE_MIN_TOP_SCORE
                    or not enough_fast_diversity
                )
                needs_sync_fallback = len(fast_merged) < min_fast_results
                if not needs_sync_fallback:
                    rust_quality_fallback_applied = True
                    warnings.append(
                        "Rust-first quality fallback satisfied minimum fast recall coverage; skipping sync slow-source fallback."
                    )
            fallback_sources = [
                source
                for source in RETRIEVAL_SYNC_ASYNC_FALLBACK_SOURCES
                if source in allowed_slow_sources
            ]
            if sync_slow_requires_explicit and not explicit_source_override:
                fallback_sources = []
            if needs_sync_fallback and fallback_sources:
                sync_fallback_slow_sources = list(fallback_sources)
                async_warm_slow_sources = [
                    source
                    for source in allowed_slow_sources
                    if source not in sync_fallback_slow_sources
                ]
                slow_sources_skipped.extend(async_warm_slow_sources)
                slow_rows, slow_errors, slow_warnings = await _run_source_batch(
                    sync_fallback_slow_sources,
                    phase_label="slow-sync-fallback",
                    suppress_slow_timeout_warnings=not fast_sources_failed,
                )
                results_by_source.update(slow_rows)
                source_errors.update(slow_errors)
                warnings.extend(slow_warnings)
            else:
                if needs_async_warm_after_skip:
                    async_warm_slow_sources = list(allowed_slow_sources)
                    slow_sources_skipped.extend(async_warm_slow_sources)
                else:
                    slow_sources_skipped.extend(list(allowed_slow_sources))
        elif skip_slow and not explicit_source_override:
            if needs_async_warm_after_skip:
                async_warm_slow_sources = list(allowed_slow_sources)
                slow_sources_skipped.extend(async_warm_slow_sources)
            else:
                slow_sources_skipped.extend(list(allowed_slow_sources))
        else:
            sync_batch = sync_fallback_slow_sources or allowed_slow_sources
            slow_rows, slow_errors, slow_warnings = await _run_source_batch(
                sync_batch,
                phase_label="slow-sync",
                suppress_slow_timeout_warnings=not fast_sources_failed,
            )
            results_by_source.update(slow_rows)
            source_errors.update(slow_errors)
            warnings.extend(slow_warnings)
        if backlog_async_warm_slow_sources:
            async_warm_slow_sources.extend(backlog_async_warm_slow_sources)
        should_schedule_async_warm = bool(async_warm_slow_sources) and (
            RETRIEVAL_SYNC_ASYNC_WARM_SLOW_SOURCES
            or any(source == RETRIEVAL_SOURCE_LETTA for source in async_warm_slow_sources)
            or (
                RETRIEVAL_MONGO_RAW_DEEP_ASYNC_WARM_NON_RAW
                and RETRIEVAL_SOURCE_MONGO_RAW in async_warm_slow_sources
            )
        )
        if should_schedule_async_warm:
            for source in async_warm_slow_sources:
                warm_limit = (
                    min(source_limit, max(limit, RETRIEVAL_LETTA_SCAN_LIMIT))
                    if source == RETRIEVAL_SOURCE_LETTA
                    else source_limit
                )
                _schedule_background_source_warm(
                    source=source,
                    query=query,
                    limit=warm_limit,
                    project_filter=project_filter,
                    topic_filter=topic_filter,
                    timeout_hint_secs=float(
                        effective_source_timeouts.get(source, RETRIEVAL_LETTA_TIMEOUT_SECS)
                    ),
                    force=bool(
                        source == RETRIEVAL_SOURCE_MONGO_RAW
                        and RETRIEVAL_MONGO_RAW_DEEP_ASYNC_WARM_NON_RAW
                    ),
                    retrieval_mode=normalized_mode,
                )
    else:
        batch_rows, batch_errors, batch_warnings = await _run_source_batch(
            resolved_sources,
            phase_label="all-sync",
            suppress_slow_timeout_warnings=False,
        )
        results_by_source.update(batch_rows)
        source_errors.update(batch_errors)
        warnings.extend(batch_warnings)

    if slow_sources_skipped:
        slow_sources_skipped = sorted(set(slow_sources_skipped))
    if async_warm_slow_sources:
        async_warm_slow_sources = sorted(set(async_warm_slow_sources))
    if sync_fallback_slow_sources:
        sync_fallback_slow_sources = sorted(set(sync_fallback_slow_sources))
    if fail_open_continuation_sources:
        fail_open_continuation_sources = sorted(set(fail_open_continuation_sources))
    if backlog_async_warm_slow_sources:
        backlog_async_warm_slow_sources = sorted(set(backlog_async_warm_slow_sources))
    if circuit_blocked_slow_sources:
        circuit_blocked_slow_sources = sorted(set(circuit_blocked_slow_sources))
    if degraded_probe_sources:
        degraded_probe_sources = sorted(set(degraded_probe_sources))
    if backlog_blocked_slow_sources:
        backlog_blocked_slow_sources = sorted(set(backlog_blocked_slow_sources))
    if mongo_raw_intent_async_sources:
        mongo_raw_intent_async_sources = sorted(set(mongo_raw_intent_async_sources))
        warnings.append(
            "mongo_raw deep retrieval ran asynchronously for non-raw intent to protect response latency."
        )

    source_quality_snapshot = await _retrieval_source_quality_snapshot(
        sources=list(results_by_source.keys()) or list(resolved_sources)
    )
    source_quality_multipliers = (
        source_quality_snapshot.get("multipliers")
        if isinstance(source_quality_snapshot.get("multipliers"), dict)
        else {}
    )
    merged = _merge_federated_rows(
        results_by_source,
        resolved_weights,
        positive_terms,
        negative_terms,
        learning_enabled=learning_enabled,
        query=query,
        source_quality_multipliers={
            str(name): float(value)
            for name, value in source_quality_multipliers.items()
        },
        lifecycle_snapshot=lifecycle_snapshot,
        retrieval_intent=resolved_intent,
    )
    merged.sort(
        key=lambda row: (
            float(row.get("score") or 0.0),
            float(row.get("base_score") or 0.0),
        ),
        reverse=True,
    )
    retrieval_debug = {
        "retrieval_mode": normalized_mode,
        "retrieval_intent": resolved_intent,
        "traffic_class": normalized_traffic_class,
        "sources": resolved_sources,
        "source_weights": resolved_weights,
        "source_counts": {
            source: len(results_by_source.get(source, []))
            for source in resolved_sources
        },
        "source_errors": source_errors,
        "cache": {
            "pathway_hit": False,
            "template_hit": template_cache_hit,
        },
        "staged_fetch": {
            "enabled": staged_fetch_used,
            "explicit_source_override": explicit_source_override,
            "force_include_slow": force_include_slow,
            "hard_sync_async_split": hard_sync_async_split_applied,
            "fast_sources": staged_fast_sources,
            "slow_sources": staged_slow_sources,
            "slow_sources_skipped": slow_sources_skipped,
            "sync_fallback_sources": sync_fallback_slow_sources,
            "async_warm_sources": async_warm_slow_sources,
            "fail_open_continuation_sources": fail_open_continuation_sources,
            "slow_source_min_results": RETRIEVAL_SLOW_SOURCE_MIN_RESULTS,
            "slow_source_min_top_score": RETRIEVAL_SLOW_SOURCE_MIN_TOP_SCORE,
            "slow_source_min_diversity": RETRIEVAL_SLOW_SOURCE_MIN_DIVERSITY,
            "rust_quality_fallback_attempted": rust_quality_fallback_attempted,
            "rust_quality_fallback_applied": rust_quality_fallback_applied,
            "rust_quality_fallback_sources": rust_quality_fallback_sources_used,
            "rust_quality_fallback_mode": rust_quality_fallback_mode_used,
        },
        "source_policy": {
            "stability_enabled": bool(runtime_policy.get("enabled")),
            "degraded_sources": degraded_sources,
            "timeout_overrides": timeout_overrides,
            "circuit_skip_enabled": RETRIEVAL_SLOW_SOURCE_CIRCUIT_SKIP_ENABLED,
            "circuit_blocked_sources": circuit_blocked_slow_sources,
            "degraded_probe_sources": degraded_probe_sources,
            "backlog_gating_enabled": RETRIEVAL_BACKLOG_GATING_ENABLED,
            "backlog_blocked_sources": backlog_blocked_slow_sources,
            "backlog_async_warm_sources": backlog_async_warm_slow_sources,
            "backlog_summary": backlog_policy.get("summary"),
            "backlog_summary_fresh": backlog_policy.get("summary_fresh"),
            "sync_slow_requires_explicit": sync_slow_requires_explicit if staged_fetch_used else RETRIEVAL_SYNC_SLOW_REQUIRES_EXPLICIT,
            "strict_fast_sync_default": RETRIEVAL_STRICT_FAST_SYNC_DEFAULT,
            "memory_bank_default_enabled": RETRIEVAL_MEMORY_BANK_DEFAULT_ENABLED,
            "memory_bank_sync_non_deep_enabled": RETRIEVAL_MEMORY_SYNC_NON_DEEP_ENABLED,
            "memory_bank_backend_configured": MEMORY_BANK_SPIKE_BACKEND,
            "memory_bank_backend_effective": memory_bank_backend_effective,
            "letta_top_k_by_mode": {
                RETRIEVAL_MODE_FAST: {
                    "factor": RETRIEVAL_LETTA_TOP_K_FACTOR_FAST,
                    "cap": RETRIEVAL_LETTA_TOP_K_CAP_FAST,
                },
                RETRIEVAL_MODE_BALANCED: {
                    "factor": RETRIEVAL_LETTA_TOP_K_FACTOR_BALANCED,
                    "cap": RETRIEVAL_LETTA_TOP_K_CAP_BALANCED,
                },
                RETRIEVAL_MODE_DEEP: {
                    "factor": RETRIEVAL_LETTA_TOP_K_FACTOR_DEEP,
                    "cap": RETRIEVAL_LETTA_TOP_K_CAP_DEEP,
                },
            },
            "source_chain_debug": {
                str(source_name): [
                    dict(entry)
                    for entry in entries
                    if isinstance(entry, dict)
                ]
                for source_name, entries in source_chain_debug.items()
                if isinstance(entries, list)
            },
            "memory_bank_fallback_chain": [
                dict(entry)
                for entry in source_chain_debug.get(RETRIEVAL_SOURCE_MEMORY_BANK, [])
                if isinstance(entry, dict)
            ],
            "mongo_raw_deep_sync_only_for_raw_intent": RETRIEVAL_MONGO_RAW_DEEP_SYNC_ONLY_FOR_RAW_INTENT,
            "mongo_raw_deep_async_warm_non_raw": RETRIEVAL_MONGO_RAW_DEEP_ASYNC_WARM_NON_RAW,
            "mongo_raw_intent_async_sources": mongo_raw_intent_async_sources,
            "rust_quality_fallback_enabled": RETRIEVAL_RUST_QUALITY_FALLBACK_ENABLED,
            "rust_quality_fallback_sources": RETRIEVAL_RUST_QUALITY_FALLBACK_SOURCES,
            "rust_quality_fallback_mode": RETRIEVAL_RUST_QUALITY_FALLBACK_MODE,
            "runtime_backend_policy": runtime_backend_policy,
            "qdrant_sync_timeout_cap_secs": RETRIEVAL_QDRANT_SYNC_TIMEOUT_CAP_SECS,
            "fail_open_timeout_continuation_enabled": RETRIEVAL_FAIL_OPEN_TIMEOUT_CONTINUATION_ENABLED,
            "fail_open_timeout_continuation_sources": RETRIEVAL_FAIL_OPEN_TIMEOUT_CONTINUATION_SOURCES,
        },
        "learning_rerank": {
            "enabled": learning_enabled,
            "positive_terms": len(positive_terms),
            "negative_terms": len(negative_terms),
        },
        "fusion": {
            "enabled": bool(RETRIEVAL_FUSION_ENABLED),
            "lexical_boost": RETRIEVAL_FUSION_LEXICAL_BOOST,
            "consensus_boost": RETRIEVAL_FUSION_CONSENSUS_BOOST,
            "numeric_match_enabled": bool(RETRIEVAL_FUSION_NUMERIC_MATCH_ENABLED),
            "numeric_match_boost": RETRIEVAL_FUSION_NUMERIC_MATCH_BOOST,
            "numeric_miss_penalty": RETRIEVAL_FUSION_NUMERIC_MISS_PENALTY,
        },
        "source_quality": source_quality_snapshot,
        "lifecycle": {
            "enabled": bool(RETRIEVAL_LIFECYCLE_ENABLED),
            "tracked_keys": len(lifecycle_snapshot),
            "max_keys": RETRIEVAL_LIFECYCLE_MAX_KEYS,
            "half_life_hours": RETRIEVAL_LIFECYCLE_HALFLIFE_HOURS,
        },
        "call_budget": {
            "configuredSecs": normalized_call_budget_secs,
            "elapsedMs": round((time.monotonic() - federated_started_monotonic) * 1000, 2),
            "exhausted": bool(call_budget_exhausted),
            "deferred_sources": sorted(set(deferred_sources)),
        },
    }
    returned_sources = sorted(
        {
            source
            for source, rows in results_by_source.items()
            if isinstance(rows, list) and len(rows) > 0
        }
    )
    budget_exceeded_sources = sorted(
        {
            source_name
            for source_name, error_payload in source_errors.items()
            if _normalize_source_error_detail(error_payload).get("kind") == "budget_exceeded"
        }
    )
    deferred_budget_sources = sorted(set(deferred_sources))
    should_emit_source_availability_summary = bool(
        budget_exceeded_sources
        or deferred_budget_sources
        or _source_errors_has_material_failures(source_errors)
    )
    deferred_context_sources = sorted(
        set(
            list(async_warm_slow_sources)
            + list(fail_open_continuation_sources)
            + list(backlog_async_warm_slow_sources)
            + list(deferred_budget_sources)
            + budget_exceeded_sources
        )
    )
    if returned_sources and should_emit_source_availability_summary:
        warnings.append("Sources returned now: " + ", ".join(returned_sources) + ".")
    if deferred_context_sources and should_emit_source_availability_summary:
        warnings.append(
            "Additional context may be available later from: "
            + ", ".join(deferred_context_sources)
            + ". Re-run after cache warm or use deep mode / longer timeout budgets for blocking retrieval."
        )
    retrieval_debug["source_availability"] = _build_source_availability_payload(retrieval_debug)
    retrieval_debug["staged_fetch"]["budget_exceeded_sources"] = budget_exceeded_sources
    final_results = merged[:limit]
    await _record_retrieval_lifecycle_observation(query=query, results=final_results)
    critical_deferred_sources = [
        source
        for source in deferred_budget_sources
        if (
            explicit_source_override
            or normalized_mode == RETRIEVAL_MODE_DEEP
            or source in staged_fast_sources
        )
    ]
    cache_write_skipped = bool(critical_deferred_sources)
    retrieval_debug["call_budget"]["critical_deferred_sources"] = critical_deferred_sources
    retrieval_debug["call_budget"]["cacheWriteSkipped"] = cache_write_skipped
    if not cache_write_skipped:
        await _retrieval_pathway_cache_set(
            pathway_cache_key,
            results=final_results,
            retrieval_debug=retrieval_debug,
            warnings=warnings,
        )
        if final_results:
            await _retrieval_pathway_negative_cache_invalidate(pathway_cache_key)
        elif negative_cache_eligible and not call_budget_exhausted and not deferred_budget_sources:
            await _retrieval_pathway_negative_cache_set(
                pathway_cache_key,
                retrieval_debug=retrieval_debug,
                warnings=warnings,
            )
    else:
        warnings.append(
            "Response returned with partial results due call budget; deferred sources continue warming in background."
        )
    if record_pathway_usage:
        await _record_retrieval_pathway_observation(
            query=query,
            project_filter=project_filter,
            topic_filter=topic_filter,
            sources=resolved_sources,
            source_weights=resolved_weights,
            retrieval_mode=normalized_mode,
            retrieval_intent=resolved_intent,
        )
    return final_results, retrieval_debug, warnings


async def _run_memory_recall_pipeline(
    *,
    query: str,
    limit: int,
    project_filter: str | None,
    topic_filter: str | None,
    sources: list[str] | None,
    source_weights: dict[str, float] | None,
    preferences: dict[str, Any] | None,
    rerank_with_learning: bool,
    retrieval_mode: str,
    agent_profile: dict[str, Any] | None = None,
    auto_escalate: bool = False,
    query_expansion: bool = True,
    retrieval_intent: str = RETRIEVAL_INTENT_DEFAULT,
    traffic_class: str = TRAFFIC_CLASS_USER,
    backend_policy: dict[str, Any] | None = None,
    bypass_pathway_cache: bool = False,
) -> tuple[list[dict[str, Any]], dict[str, Any], list[str], dict[str, Any]]:
    normalized_mode = _normalize_retrieval_mode(retrieval_mode)
    normalized_intent = _normalize_retrieval_intent(retrieval_intent)
    normalized_traffic_class = _normalize_traffic_class(traffic_class)
    profile = agent_profile if isinstance(agent_profile, dict) else {}
    source_override_requested = bool(sources is not None)
    if "_source_override_requested" in profile:
        source_override_requested = bool(profile.get("_source_override_requested"))
    profile_sources = profile.get("sources") if isinstance(profile.get("sources"), list) else None
    profile_weights = profile.get("source_weights") if isinstance(profile.get("source_weights"), dict) else None
    if source_override_requested:
        resolved_sources = _normalize_retrieval_sources(
            sources,
            explicit_source_override=True,
        )
    else:
        resolved_sources = _normalize_retrieval_sources(
            profile_sources,
            explicit_source_override=False,
        )
    merged_weights = dict(profile_weights) if profile_weights else {}
    if source_weights:
        for key, value in source_weights.items():
            merged_weights[str(key)] = value
    resolved_weights = merged_weights if merged_weights else None
    expand_enabled = bool(query_expansion and RETRIEVAL_QUERY_EXPANSION_ENABLED)
    base_query = re.sub(r"\s+", " ", str(query or "").strip())
    query_variants = _expand_query_variants(query) if expand_enabled else [base_query]
    query_variants = [item for item in query_variants if item]
    if not query_variants:
        query_variants = [base_query]
    scoped_query = bool(str(project_filter or "").strip() or str(topic_filter or "").strip())
    scoped_structural_variant_filtered = False
    if scoped_query:
        structural_aliases: set[str] = set()
        if " " in base_query and "/" not in base_query:
            structural_aliases = {
                base_query.replace(" ", "/"),
                base_query.replace(" ", "_"),
            }
        if structural_aliases:
            filtered = [item for item in query_variants if item not in structural_aliases]
            if filtered:
                scoped_structural_variant_filtered = len(filtered) != len(query_variants)
                query_variants = filtered
    max_variants_allowed = RETRIEVAL_QUERY_EXPANSION_MAX_VARIANTS
    max_escalation_steps = AGENT_RECALL_MAX_ESCALATION_STEPS
    if normalized_mode == RETRIEVAL_MODE_FAST:
        # Keep fast mode bounded to one variant to protect latency.
        max_variants_allowed = 1
    if scoped_query:
        max_variants_allowed = min(max_variants_allowed, RECALL_SCOPED_QUERY_VARIANT_CAP)
        max_escalation_steps = min(max_escalation_steps, RECALL_SCOPED_QUERY_MAX_ESCALATION_STEPS)
    query_variants = query_variants[: max(1, int(max_variants_allowed))]
    recall_budget_secs = _recall_e2e_budget_for_mode(normalized_mode)
    recall_budget_enabled = recall_budget_secs > 0.0
    recall_started_monotonic = time.monotonic()
    recall_deadline_monotonic = (
        recall_started_monotonic + recall_budget_secs
        if recall_budget_enabled
        else None
    )

    def _remaining_recall_budget_secs() -> float | None:
        if recall_deadline_monotonic is None:
            return None
        return max(0.0, recall_deadline_monotonic - time.monotonic())

    warnings_all: list[str] = []
    variant_results_all: list[list[dict[str, Any]]] = []
    variant_debug_records: list[dict[str, Any]] = []
    escalation_enabled = bool(AGENT_RECALL_ESCALATION_ENABLED and auto_escalate)
    min_results = int(profile.get("escalate_min_results") or AGENT_RECALL_ESCALATE_MIN_RESULTS)
    min_top_score = float(profile.get("escalate_min_top_score") or AGENT_RECALL_ESCALATE_MIN_TOP_SCORE)
    budget_exhausted = False
    timeout_adaptive_enabled = bool(
        RECALL_TIMEOUT_ADAPTIVE_SOURCE_SKIP_ENABLED
        and not source_override_requested
    )
    timeout_adaptive_skip_targets = {
        source for source in RECALL_TIMEOUT_ADAPTIVE_SKIP_SOURCES
    }
    timeout_adaptive_observed_sources: set[str] = set()
    timeout_adaptive_skipped_sources: set[str] = set()

    for variant_index, query_variant in enumerate(query_variants):
        remaining_before_variant = _remaining_recall_budget_secs()
        if remaining_before_variant is not None and remaining_before_variant <= 0.0:
            budget_exhausted = True
            warnings_all.append(
                "Recall response budget exhausted before all query variants completed; returning best-available results."
            )
            break
        if (
            remaining_before_variant is not None
            and remaining_before_variant < RECALL_E2E_MIN_FEDERATED_BUDGET_SECS
            and variant_results_all
        ):
            budget_exhausted = True
            warnings_all.append(
                "Recall response budget too low to evaluate additional query variants; returning best-available results."
            )
            break
        hop_mode = normalized_mode
        hop_result_sets: list[list[dict[str, Any]]] = []
        hop_debugs: list[dict[str, Any]] = []
        hop_warnings: list[str] = []
        hop_count = 0
        while True:
            remaining_before_hop = _remaining_recall_budget_secs()
            if remaining_before_hop is not None and remaining_before_hop <= 0.0:
                budget_exhausted = True
                hop_warnings.append(
                    "Recall response budget exhausted before escalation hops completed."
                )
                break
            if (
                remaining_before_hop is not None
                and remaining_before_hop < RECALL_E2E_MIN_FEDERATED_BUDGET_SECS
                and hop_result_sets
            ):
                budget_exhausted = True
                hop_warnings.append(
                    "Recall response budget too low for another escalation hop; returning best-available results."
                )
                break
            hop_count += 1
            call_budget_secs = float(remaining_before_hop) if remaining_before_hop is not None else None
            hop_sources = resolved_sources
            if timeout_adaptive_enabled and timeout_adaptive_skipped_sources:
                candidate_sources = _resolve_retrieval_sources_for_mode(
                    mode=hop_mode,
                    sources=hop_sources,
                )
                filtered_sources = [
                    source
                    for source in candidate_sources
                    if source not in timeout_adaptive_skipped_sources
                ]
                if filtered_sources and len(filtered_sources) < len(candidate_sources):
                    hop_sources = filtered_sources
            hop_results, hop_debug, hop_warn = await federated_search_memory(
                query_variant,
                limit=limit,
                project_filter=project_filter,
                topic_filter=topic_filter,
                sources=hop_sources,
                explicit_source_override=source_override_requested,
                source_weights=resolved_weights,
                preferences=preferences,
                rerank_with_learning=rerank_with_learning,
                retrieval_mode=hop_mode,
                retrieval_intent=normalized_intent,
                call_budget_secs=call_budget_secs,
                bypass_pathway_cache=bypass_pathway_cache,
                traffic_class=normalized_traffic_class,
                backend_policy=backend_policy,
            )
            if timeout_adaptive_enabled and isinstance(hop_debug, dict):
                timeout_sources = _source_errors_timeout_sources(
                    hop_debug.get("source_errors") if isinstance(hop_debug.get("source_errors"), dict) else None
                )
                newly_skipped: list[str] = []
                for source_name in timeout_sources:
                    if source_name in timeout_adaptive_skip_targets:
                        timeout_adaptive_observed_sources.add(source_name)
                        if source_name not in timeout_adaptive_skipped_sources:
                            timeout_adaptive_skipped_sources.add(source_name)
                            newly_skipped.append(source_name)
                if newly_skipped:
                    hop_warnings.append(
                        "Adaptive timeout policy skipped timed-out sources for remaining recall hops: "
                        + ", ".join(sorted(newly_skipped))
                        + "."
                    )
            hop_result_sets.append(hop_results)
            hop_debugs.append(hop_debug)
            hop_warnings.extend(hop_warn)
            call_budget_debug = (
                hop_debug.get("call_budget")
                if isinstance(hop_debug.get("call_budget"), dict)
                else {}
            )
            if bool(call_budget_debug.get("exhausted")):
                budget_exhausted = True
            should_escalate = escalation_enabled and _recall_should_escalate(
                results=hop_results,
                min_results=min_results,
                min_top_score=min_top_score,
            )
            if not should_escalate:
                break
            if hop_mode == RETRIEVAL_MODE_DEEP:
                break
            if hop_count >= max_escalation_steps:
                break
            if budget_exhausted:
                break
            hop_mode = _next_retrieval_mode(hop_mode)

        if budget_exhausted and not hop_result_sets:
            break

        merged_variant_results = _merge_ranked_result_sets(
            hop_result_sets,
            limit=max(limit * 3, limit),
        )
        for row in merged_variant_results:
            row.setdefault("query_variant", query_variant)
            row.setdefault("retrieval_mode_used", hop_mode)
        variant_results_all.append(merged_variant_results)
        last_debug = hop_debugs[-1] if hop_debugs else {}
        top_score = _top_result_score(merged_variant_results)
        variant_debug_records.append(
            {
                "query": query_variant,
                "variant_index": variant_index,
                "hop_count": len(hop_debugs),
                "escalated": len(hop_debugs) > 1,
                "final_mode": hop_mode,
                "result_count": len(merged_variant_results),
                "top_score": round(top_score, 6),
                "hop_modes": [debug.get("retrieval_mode") for debug in hop_debugs if isinstance(debug, dict)],
                "debug": last_debug,
            }
        )
        warnings_all.extend(hop_warnings)

        if budget_exhausted:
            break
        if variant_index == 0 and not _recall_should_escalate(
            results=merged_variant_results,
            min_results=max(1, min(limit, min_results)),
            min_top_score=min_top_score,
        ):
            break

    merged_results = _merge_ranked_result_sets(variant_results_all, limit=limit)
    best_variant_record = None
    if variant_debug_records:
        best_variant_record = max(
            variant_debug_records,
            key=lambda item: (float(item.get("top_score") or 0.0), int(item.get("result_count") or 0)),
        )
    best_debug = dict(best_variant_record.get("debug") or {}) if isinstance(best_variant_record, dict) else {}
    source_errors: dict[str, str] = {}
    source_counts: dict[str, int] = {}
    for record in variant_debug_records:
        debug = record.get("debug") if isinstance(record, dict) else None
        if not isinstance(debug, dict):
            continue
        errors = debug.get("source_errors")
        if isinstance(errors, dict):
            for source, message in errors.items():
                source_name = str(source)
                if source_name and source_name not in source_errors and str(message or "").strip():
                    source_errors[source_name] = str(message)
        counts = debug.get("source_counts")
        if isinstance(counts, dict):
            for source, value in counts.items():
                source_name = str(source)
                if not source_name:
                    continue
                source_counts[source_name] = max(
                    int(source_counts.get(source_name, 0) or 0),
                    int(value or 0),
                )
    pipeline_debug = {
        "query_expansion": {
            "enabled": expand_enabled,
            "max_variants": max_variants_allowed,
            "scoped_query": scoped_query,
            "scoped_structural_variant_filtered": scoped_structural_variant_filtered,
            "scoped_variant_cap": RECALL_SCOPED_QUERY_VARIANT_CAP,
            "source_override_requested": source_override_requested,
            "variants_considered": query_variants,
            "variants_used": [record.get("query") for record in variant_debug_records],
        },
        "escalation": {
            "enabled": escalation_enabled,
            "max_steps": max_escalation_steps,
            "scoped_max_steps": RECALL_SCOPED_QUERY_MAX_ESCALATION_STEPS,
            "min_results": min_results,
            "min_top_score": min_top_score,
            "variants": [
                {
                    "query": record.get("query"),
                    "hop_count": record.get("hop_count"),
                    "escalated": record.get("escalated"),
                    "final_mode": record.get("final_mode"),
                    "top_score": record.get("top_score"),
                    "result_count": record.get("result_count"),
                }
                for record in variant_debug_records
            ],
        },
        "retrieval_intent": normalized_intent,
        "traffic_class": normalized_traffic_class,
        "timeout_adaptive": {
            "enabled": timeout_adaptive_enabled,
            "skip_targets": sorted(timeout_adaptive_skip_targets),
            "observed_timeout_sources": sorted(timeout_adaptive_observed_sources),
            "skipped_sources": sorted(timeout_adaptive_skipped_sources),
        },
        "budget": {
            "enabled": recall_budget_enabled,
            "configuredSecs": recall_budget_secs if recall_budget_enabled else None,
            "minHopBudgetSecs": RECALL_E2E_MIN_FEDERATED_BUDGET_SECS,
            "elapsedMs": round((time.monotonic() - recall_started_monotonic) * 1000, 2),
            "exhausted": budget_exhausted,
        },
    }
    best_debug["retrieval_mode"] = _normalize_retrieval_mode(str(best_debug.get("retrieval_mode") or normalized_mode))
    best_debug["retrieval_intent"] = _normalize_retrieval_intent(
        str(best_debug.get("retrieval_intent") or normalized_intent)
    )
    best_debug["source_errors"] = source_errors
    best_debug["source_counts"] = source_counts
    best_debug["pipeline"] = pipeline_debug
    best_debug["traffic_class"] = normalized_traffic_class
    grounding = _build_grounding_payload(merged_results)
    await _record_recall_quality_observation(
        results=merged_results,
        retrieval_debug=best_debug,
        traffic_class=normalized_traffic_class,
    )
    if budget_exhausted:
        warnings_all.append(
            "Recall response budget reached; returning best-available partial results while slower sources continue warming."
        )
    deduped_warnings = []
    seen_warning: set[str] = set()
    for warning in warnings_all:
        text = str(warning or "").strip()
        if not text or text in seen_warning:
            continue
        seen_warning.add(text)
        deduped_warnings.append(text)
    return merged_results, best_debug, deduped_warnings, grounding


def _build_letta_archival_text(summary: str, context: dict[str, Any]) -> str:
    project = str(context.get("project") or "")
    file_name = str(context.get("file") or "")
    topic_path = str(context.get("topic_path") or "")
    content = str(context.get("content") or "")
    metadata = {
        key: value
        for key, value in context.items()
        if key not in {"project", "file", "topic_path", "content", "summary"}
    }
    lines: list[str] = []
    if project or file_name or topic_path:
        lines.append(f"project={project or '-'} file={file_name or '-'} topic={topic_path or '-'}")
    if summary:
        summary_text = summary if len(summary) <= 240 else f"{summary[:240]}..."
        lines.append(f"summary: {summary_text}")
    if LETTA_ARCHIVAL_INCLUDE_CONTENT and content:
        snippet = content if len(content) <= 220 else f"{content[:220]}..."
        lines.append(f"content_snippet: {snippet}")
    if metadata:
        metadata_json = json.dumps(metadata, default=str)
        lines.append(f"metadata: {metadata_json[:180]}")
    text = "\n".join(lines).strip()
    if not text:
        text = summary or "memory update"
    if len(text) > LETTA_ARCHIVAL_MAX_CHARS:
        text = text[:LETTA_ARCHIVAL_MAX_CHARS]
    return text


def _normalize_ollama_openai_base(url: str) -> str:
    cleaned = (url or "").strip().rstrip("/")
    if not cleaned:
        return cleaned
    if "ollama:11434" not in cleaned:
        return cleaned
    if cleaned.endswith("/v1"):
        return cleaned
    return f"{cleaned}/v1"


async def _ensure_letta_agent_endpoint_compat(
    agent_id: str,
    agent_payload: dict[str, Any],
    headers: dict[str, str],
) -> None:
    llm_cfg = agent_payload.get("llm_config")
    emb_cfg = agent_payload.get("embedding_config")
    if not isinstance(llm_cfg, dict) or not isinstance(emb_cfg, dict):
        return

    llm_endpoint = str(llm_cfg.get("model_endpoint") or "")
    emb_endpoint = str(emb_cfg.get("embedding_endpoint") or "")
    normalized_llm = _normalize_ollama_openai_base(llm_endpoint)
    normalized_emb = _normalize_ollama_openai_base(emb_endpoint)
    if normalized_llm == llm_endpoint and normalized_emb == emb_endpoint:
        return

    llm_patch = dict(llm_cfg)
    emb_patch = dict(emb_cfg)
    llm_patch["model_endpoint"] = normalized_llm or llm_endpoint
    emb_patch["embedding_endpoint"] = normalized_emb or emb_endpoint
    patch_payload = {"llm_config": llm_patch, "embedding_config": emb_patch}
    client = await _get_letta_client()
    resp = await client.patch(
        f"{LETTA_URL}/v1/agents/{agent_id}",
        json=patch_payload,
        headers=headers,
        timeout=LETTA_REQUEST_TIMEOUT_SECS,
    )
    if resp.status_code >= 400:
        raise OrchestratorError(
            f"Letta agent endpoint patch failed: status={resp.status_code} body={resp.text[:300]}"
        )


async def _resolve_letta_agent_id(session_id: str, headers: dict[str, str]) -> str:
    if session_id.startswith("agent-"):
        return session_id
    cached = LETTA_AGENT_CACHE.get(session_id)
    verified_at = LETTA_AGENT_VERIFIED_AT.get(session_id, 0.0)
    if cached and (time.time() - verified_at) < LETTA_AGENT_VERIFY_INTERVAL_SECS:
        return cached

    async with letta_agent_lock:
        cached = LETTA_AGENT_CACHE.get(session_id)
        client = await _get_letta_client()
        if cached:
            details = await client.get(
                f"{LETTA_URL}/v1/agents/{cached}",
                headers=headers,
                timeout=LETTA_REQUEST_TIMEOUT_SECS,
            )
            if details.status_code >= 400:
                raise OrchestratorError(
                    f"Letta agent fetch failed: status={details.status_code} body={details.text[:300]}"
                )
            detail_payload = details.json() if details.content else {}
            if isinstance(detail_payload, dict):
                await _ensure_letta_agent_endpoint_compat(cached, detail_payload, headers)
            LETTA_AGENT_VERIFIED_AT[session_id] = time.time()
            return cached

        lookup = await client.get(
            f"{LETTA_URL}/v1/agents/",
            params={"name": session_id},
            headers=headers,
            timeout=LETTA_REQUEST_TIMEOUT_SECS,
        )
        if lookup.status_code >= 400:
            raise OrchestratorError(
                f"Letta agent lookup failed: status={lookup.status_code} body={lookup.text[:300]}"
            )
        rows = lookup.json() if lookup.content else []
        if isinstance(rows, list) and rows:
            agent_id = str(rows[0].get("id") or "").strip()
            if agent_id:
                details = await client.get(
                    f"{LETTA_URL}/v1/agents/{agent_id}",
                    headers=headers,
                    timeout=LETTA_REQUEST_TIMEOUT_SECS,
                )
                if details.status_code >= 400:
                    raise OrchestratorError(
                        f"Letta agent fetch failed: status={details.status_code} body={details.text[:300]}"
                    )
                detail_payload = details.json() if details.content else {}
                if isinstance(detail_payload, dict):
                    await _ensure_letta_agent_endpoint_compat(agent_id, detail_payload, headers)
                LETTA_AGENT_CACHE[session_id] = agent_id
                LETTA_AGENT_VERIFIED_AT[session_id] = time.time()
                return agent_id

        create_payload: dict[str, Any] = {"name": session_id}
        if LETTA_AGENT_MODEL:
            create_payload["model"] = LETTA_AGENT_MODEL
        if LETTA_AGENT_EMBEDDING:
            create_payload["embedding"] = LETTA_AGENT_EMBEDDING
        created = await client.post(
            f"{LETTA_URL}/v1/agents/",
            json=create_payload,
            headers=headers,
            timeout=LETTA_REQUEST_TIMEOUT_SECS,
        )
        if created.status_code >= 400:
            # Handle benign races by retrying lookup once.
            if created.status_code not in (409, 422):
                raise OrchestratorError(
                    f"Letta agent create failed: status={created.status_code} body={created.text[:300]}"
                )
            retry_lookup = await client.get(
                f"{LETTA_URL}/v1/agents/",
                params={"name": session_id},
                headers=headers,
                timeout=LETTA_REQUEST_TIMEOUT_SECS,
            )
            if retry_lookup.status_code >= 400:
                raise OrchestratorError(
                    f"Letta agent lookup retry failed: status={retry_lookup.status_code} body={retry_lookup.text[:300]}"
                )
            rows = retry_lookup.json() if retry_lookup.content else []
            if isinstance(rows, list) and rows:
                agent_id = str(rows[0].get("id") or "").strip()
                if agent_id:
                    details = await client.get(
                        f"{LETTA_URL}/v1/agents/{agent_id}",
                        headers=headers,
                        timeout=LETTA_REQUEST_TIMEOUT_SECS,
                    )
                    if details.status_code >= 400:
                        raise OrchestratorError(
                            f"Letta agent fetch failed: status={details.status_code} body={details.text[:300]}"
                        )
                    detail_payload = details.json() if details.content else {}
                    if isinstance(detail_payload, dict):
                        await _ensure_letta_agent_endpoint_compat(agent_id, detail_payload, headers)
                    LETTA_AGENT_CACHE[session_id] = agent_id
                    LETTA_AGENT_VERIFIED_AT[session_id] = time.time()
                    return agent_id
            raise OrchestratorError(
                f"Letta agent create failed: status={created.status_code} body={created.text[:300]}"
            )
        payload = created.json() if created.content else {}
        agent_id = str(payload.get("id") or "").strip() if isinstance(payload, dict) else ""
        if not agent_id:
            raise OrchestratorError("Letta agent create returned no id")
        if isinstance(payload, dict):
            await _ensure_letta_agent_endpoint_compat(agent_id, payload, headers)
        LETTA_AGENT_CACHE[session_id] = agent_id
        LETTA_AGENT_VERIFIED_AT[session_id] = time.time()
        return agent_id


async def push_to_letta(
    session_id: str,
    summary: str,
    context: dict[str, Any],
) -> None:
    """Persist context to Letta archival memory."""
    headers: dict[str, str] = {}
    if LETTA_API_KEY:
        headers["Authorization"] = f"Bearer {LETTA_API_KEY}"
    elif LETTA_REQUIRE_API_KEY:
        raise OrchestratorError("LETTA_REQUIRE_API_KEY is enabled but LETTA_API_KEY is not set")

    async with _fanout_rate_limit(letta_fanout_rate_limiter):
        agent_id = await _resolve_letta_agent_id(session_id, headers)
        tags = ["contextlattice"]
        project = str(context.get("project") or "").strip()
        file_name = str(context.get("file") or "").strip()
        if project:
            tags.append(f"project:{project[:120]}")
        if file_name:
            tags.append(f"file:{file_name[:180]}")
        payload = {"text": _build_letta_archival_text(summary, context), "tags": tags[:8]}
        client = await _get_letta_client()

        async def _post_archival(agent_id: str) -> httpx.Response:
            return await client.post(
                f"{LETTA_URL}/v1/agents/{agent_id}/archival-memory",
                json=payload,
                headers=headers,
                timeout=LETTA_REQUEST_TIMEOUT_SECS,
            )

        resp = await client.post(
            f"{LETTA_URL}/v1/agents/{agent_id}/archival-memory",
            json=payload,
            headers=headers,
            timeout=LETTA_REQUEST_TIMEOUT_SECS,
        )
        if resp.status_code >= 500 and not session_id.startswith("agent-"):
            # Force agent revalidation in case endpoint config drifted.
            LETTA_AGENT_VERIFIED_AT[session_id] = 0.0
            agent_id = await _resolve_letta_agent_id(session_id, headers)
            resp = await _post_archival(agent_id)
        if resp.status_code >= 400:
            raise OrchestratorError(f"Letta sync failed: status={resp.status_code} body={resp.text[:300]}")


async def ensure_mindsdb_table() -> None:
    global mindsdb_table_ready, mindsdb_target_db, mindsdb_target_table
    if not MINDSDB_ENABLED or not MINDSDB_AUTOSYNC:
        return
    if mindsdb_table_ready:
        return
    async with mindsdb_table_lock:
        if mindsdb_table_ready:
            return
        primary_db = mindsdb_target_db or MINDSDB_AUTOSYNC_DB
        primary_table = MINDSDB_AUTOSYNC_TABLE
        try:
            await _ensure_mindsdb_table_exists(primary_table, primary_db)
            mindsdb_target_db = primary_db
            mindsdb_target_table = primary_table
            mindsdb_table_ready = True
            return
        except Exception as exc:  # pragma: no cover
            if not _looks_like_mindsdb_table_corruption(str(exc)):
                logger.warning("MindsDB table init error: %s", exc)
                return
    # Fallback activation requires a second lock pass.
    await _switch_mindsdb_to_fallback(
        "primary table appears corrupted",
        current_table=MINDSDB_AUTOSYNC_TABLE,
        current_db=(mindsdb_target_db or MINDSDB_AUTOSYNC_DB),
    )


async def _switch_mindsdb_to_fallback(
    reason: str,
    current_table: str | None = None,
    current_db: str | None = None,
) -> bool:
    global mindsdb_table_ready, mindsdb_target_db, mindsdb_target_table
    async with mindsdb_table_lock:
        seed_db = str(current_db or mindsdb_target_db or MINDSDB_AUTOSYNC_DB).strip() or MINDSDB_AUTOSYNC_DB
        seed_table = current_table or mindsdb_target_table or MINDSDB_AUTOSYNC_TABLE
        candidate = _mindsdb_next_fallback_table(seed_table)
        for _ in range(256):
            try:
                await _ensure_mindsdb_table_exists(candidate, seed_db)
                mindsdb_target_db = seed_db
                mindsdb_target_table = candidate
                mindsdb_table_ready = True
                logger.warning(
                    "MindsDB autosync switched to fallback table '%s.%s' after error: %s",
                    seed_db,
                    candidate,
                    reason[:240],
                )
                return True
            except Exception as exc:
                if _looks_like_mindsdb_table_corruption(str(exc)):
                    candidate = _mindsdb_next_fallback_table(candidate)
                    continue
                logger.warning("MindsDB fallback table activation failed: %s", exc)
                break

        candidate_db = _mindsdb_next_fallback_db(seed_db)
        for _ in range(64):
            try:
                await _ensure_mindsdb_table_exists(MINDSDB_AUTOSYNC_TABLE, candidate_db)
                mindsdb_target_db = candidate_db
                mindsdb_target_table = MINDSDB_AUTOSYNC_TABLE
                mindsdb_table_ready = True
                logger.warning(
                    "MindsDB autosync switched to fallback database '%s.%s' after error: %s",
                    candidate_db,
                    MINDSDB_AUTOSYNC_TABLE,
                    reason[:240],
                )
                return True
            except Exception as exc:
                if _looks_like_mindsdb_table_corruption(str(exc)):
                    candidate_db = _mindsdb_next_fallback_db(candidate_db)
                    continue
                logger.warning("MindsDB fallback database activation failed: %s", exc)
                return False
    logger.warning("MindsDB fallback table/database activation exhausted candidate paths")
    return False


async def _insert_into_mindsdb(item: dict[str, Any]) -> None:
    await ensure_mindsdb_table()
    created_at = item.get("created_at") or _utc_now()
    db_name = mindsdb_target_db or MINDSDB_AUTOSYNC_DB
    table_name = mindsdb_target_table or MINDSDB_AUTOSYNC_TABLE
    query = _mindsdb_insert_query(
        item["project"],
        item["file"],
        item.get("summary") or "",
        created_at,
        table_name,
        db_name,
    )
    try:
        await _mindsdb_execute(query)
    except Exception as exc:
        if not _looks_like_mindsdb_table_corruption(str(exc)):
            raise
        if not await _switch_mindsdb_to_fallback(str(exc), current_table=table_name, current_db=db_name):
            raise
        db_name = mindsdb_target_db or _mindsdb_next_fallback_db(db_name)
        fallback_table = mindsdb_target_table or _mindsdb_next_fallback_table(table_name)
        fallback_query = _mindsdb_insert_query(
            item["project"],
            item["file"],
            item.get("summary") or "",
            created_at,
            fallback_table,
            db_name,
        )
        await _mindsdb_execute(fallback_query)


async def _insert_many_into_mindsdb(items: list[dict[str, Any]]) -> None:
    if not items:
        return
    await ensure_mindsdb_table()
    db_name = mindsdb_target_db or MINDSDB_AUTOSYNC_DB
    table_name = mindsdb_target_table or MINDSDB_AUTOSYNC_TABLE
    query = _mindsdb_insert_many_query(items, table_name, db_name)
    try:
        await _mindsdb_execute(query)
    except Exception as exc:
        if not _looks_like_mindsdb_table_corruption(str(exc)):
            raise
        if not await _switch_mindsdb_to_fallback(str(exc), current_table=table_name, current_db=db_name):
            raise
        db_name = mindsdb_target_db or _mindsdb_next_fallback_db(db_name)
        fallback_table = mindsdb_target_table or _mindsdb_next_fallback_table(table_name)
        fallback_query = _mindsdb_insert_many_query(items, fallback_table, db_name)
        await _mindsdb_execute(fallback_query)


async def push_to_mindsdb(
    project: str,
    file_name: str,
    summary: str,
    allow_fallback_queue: bool = False,
) -> None:
    await push_batch_to_mindsdb(
        [
            {
                "project": project,
                "file": file_name,
                "summary": summary,
                "created_at": _utc_now(),
            }
        ],
        allow_fallback_queue=allow_fallback_queue,
    )


async def push_batch_to_mindsdb(
    items: list[dict[str, Any]],
    allow_fallback_queue: bool = False,
) -> None:
    if not MINDSDB_ENABLED or not MINDSDB_AUTOSYNC:
        return
    if not items:
        return
    normalized_items = [
        {
            "project": str(item.get("project") or ""),
            "file": str(item.get("file") or ""),
            "summary": str(item.get("summary") or ""),
            "created_at": str(item.get("created_at") or _utc_now()),
        }
        for item in items
    ]
    try:
        async with _fanout_rate_limit(mindsdb_fanout_rate_limiter):
            await _insert_many_into_mindsdb(normalized_items)
    except Exception as exc:  # pragma: no cover
        if allow_fallback_queue:
            logger.warning("MindsDB autosync error (queued for retry): %s", exc)
            for row in normalized_items:
                await _enqueue_mindsdb(row)
            return
        raise OrchestratorError(f"MindsDB autosync error: {exc}") from exc


async def get_mindsdb_analytics() -> dict[str, Any] | None:
    """Fetch analytics from MindsDB if available."""
    if not MINDSDB_ENABLED:
        return None
    try:
        client = await _get_mindsdb_client()
        resp = await client.get(f"{MINDSDB_URL}/api/status", timeout=30.0)
        if resp.status_code == 200:
            return {"available": True, "data": resp.json()}
    except Exception as exc:  # pragma: no cover
        logger.debug("MindsDB not available: %s", exc)
    return None


async def compute_trading_analytics_mindsdb() -> dict[str, Any]:
    """Compute trading analytics directly from MindsDB SQL with local fallback."""

    async def _local_fallback(reason: str) -> dict[str, Any]:
        async with trading_history_lock:
            history = list(trading_history)
        if not history:
            return {
                "error": "No trading history available",
                "source": "local_history",
                "warning": reason,
            }
        total_trades = len(history)
        profitable_trades = sum(1 for h in history if _safe_float(h.get("realized_pnl")) > 0)
        win_rate = profitable_trades / total_trades if total_trades > 0 else 0.0
        total_pnl = sum(_safe_float(h.get("realized_pnl")) for h in history)
        avg_position_size = (
            sum(_safe_float(h.get("total_value_usd")) for h in history) / total_trades
            if total_trades > 0
            else 0.0
        )
        cache_freshness_values = [
            _safe_float(h.get("price_cache_freshness"))
            for h in history
            if h.get("price_cache_freshness") is not None
        ]
        avg_freshness = (
            sum(cache_freshness_values) / len(cache_freshness_values)
            if cache_freshness_values
            else 0.0
        )
        return {
            "total_trades": total_trades,
            "win_rate": round(win_rate, 4),
            "total_pnl": round(total_pnl, 2),
            "avg_position_size": round(avg_position_size, 2),
            "avg_cache_freshness": round(avg_freshness, 4),
            "computed_at": datetime.utcnow().isoformat() + "Z",
            "source": "local_history",
            "warning": reason,
        }

    if (
        not MINDSDB_ENABLED
        or not MINDSDB_TRADING_AUTOSYNC
        or not TRADING_TELEMETRY_EXTERNAL_SYNC_ENABLED
        or "mindsdb" not in TRADING_TELEMETRY_EXTERNAL_SYNC_TARGETS
    ):
        return await _local_fallback("External trading telemetry sync disabled")

    try:
        await ensure_mindsdb_trading_table()
        sql = (
            "SELECT "
            "COUNT(*) AS total_trades, "
            "SUM(CASE WHEN realized_pnl > 0 THEN 1 ELSE 0 END) AS profitable_trades, "
            "COALESCE(SUM(realized_pnl), 0) AS total_pnl, "
            "COALESCE(AVG(total_value_usd), 0) AS avg_position_size, "
            "COALESCE(AVG(price_cache_freshness), 0) AS avg_cache_freshness "
            f"FROM {MINDSDB_TRADING_DB}.{MINDSDB_TRADING_TABLE};"
        )
        raw = await _mindsdb_execute(sql)
        rows = _mindsdb_rows(raw)
        if not rows:
            return await _local_fallback("MindsDB returned no rows")
        row = rows[0]
        total_trades = _safe_int(row.get("total_trades"))
        profitable_trades = _safe_int(row.get("profitable_trades"))
        total_pnl = _safe_float(row.get("total_pnl"))
        avg_position_size = _safe_float(row.get("avg_position_size"))
        avg_cache_freshness = _safe_float(row.get("avg_cache_freshness"))
        win_rate = profitable_trades / total_trades if total_trades > 0 else 0.0
        return {
            "total_trades": total_trades,
            "win_rate": round(win_rate, 4),
            "total_pnl": round(total_pnl, 2),
            "avg_position_size": round(avg_position_size, 2),
            "avg_cache_freshness": round(avg_cache_freshness, 4),
            "computed_at": datetime.utcnow().isoformat() + "Z",
            "source": "mindsdb_sql",
            "table": f"{MINDSDB_TRADING_DB}.{MINDSDB_TRADING_TABLE}",
        }
    except Exception as exc:  # pragma: no cover
        logger.error("Failed to compute MindsDB trading analytics: %s", exc)
        return await _local_fallback(str(exc))


@app.get("/projects")
async def get_projects():
    projects = await list_projects()
    semaphore = asyncio.Semaphore(8)

    async def _load(project: str) -> dict[str, Any]:
        async with semaphore:
            try:
                files = await list_files(project)
            except Exception as exc:  # pragma: no cover - defensive endpoint behavior
                logger.warning("Skipping project %s due to list failure: %s", project, exc)
                files = []
            return {"name": project, "files": [{"name": f} for f in files]}

    results = await asyncio.gather(*[_load(project) for project in projects])
    return {"projects": results}


@app.get("/projects/{project}/files")
async def get_files(project: str):
    files = await list_files(project)
    return {"files": files}


@app.get("/memory/recent")
async def get_recent_memory(limit: int = 20, project: str | None = None):
    limit = max(1, min(limit, MEMORY_WRITE_HISTORY_LIMIT))
    async with memory_write_history_lock:
        items = list(memory_write_history)
    if project:
        items = [item for item in items if item.get("project") == project]
    items = items[-limit:]
    return {"items": list(reversed(items))}


@app.post("/agents/tasks")
async def create_agent_task(payload: AgentTaskCreate):
    task_payload = dict(payload.payload or {})
    if payload.risk_level:
        task_payload["risk_level"] = payload.risk_level
    if payload.action_type:
        task_payload["action_type"] = payload.action_type
    if payload.approval_required is not None:
        task_payload["approval_required"] = payload.approval_required
    if payload.approved is not None:
        task_payload["approved"] = payload.approved
    if payload.topic_path:
        task_payload["topic_path"] = payload.topic_path
    task = await _scheduler_submit_via_runtime(
        title=payload.title,
        project=payload.project,
        agent=payload.agent,
        priority=payload.priority,
        payload=task_payload or None,
        run_after=payload.run_after,
        max_attempts=payload.max_attempts,
    )
    return {"task": task}


