def _prepare_content_for_storage(content: str) -> tuple[str, str | None]:
    payload = str(content or "")
    mode = SECRETS_STORAGE_MODE
    if mode == "allow":
        return payload, None
    if not _contains_sensitive_value(payload):
        return payload, None
    if mode == "block":
        raise HTTPException(422, "potential secret detected; storage blocked by SECRETS_STORAGE_MODE=block")
    redacted = _redact_sensitive_values(payload)
    if redacted != payload:
        return redacted, "potential secrets were redacted before storage (SECRETS_STORAGE_MODE=redact)"
    return payload, None


async def _execute_memory_write_batch(
    payload: MemoryWriteBatchRequest,
    request: Request,
    source_path: str,
) -> dict[str, Any]:
    items = payload.items if isinstance(payload.items, list) else []
    if not items:
        async with memory_write_batch_idempotency_lock:
            memory_write_batch_metrics["rejected"] = int(memory_write_batch_metrics.get("rejected", 0)) + 1
        raise HTTPException(422, "items must contain at least one write")
    if len(items) > MEMORY_WRITE_BATCH_MAX_ITEMS:
        async with memory_write_batch_idempotency_lock:
            memory_write_batch_metrics["rejected"] = int(memory_write_batch_metrics.get("rejected", 0)) + 1
        raise HTTPException(422, f"batch exceeds MEMORY_WRITE_BATCH_MAX_ITEMS={MEMORY_WRITE_BATCH_MAX_ITEMS}")

    request_key = _memory_write_batch_cache_key(payload.idempotencyKey or "", "request")
    if request_key:
        async with memory_write_batch_idempotency_lock:
            cached_response = await _memory_write_batch_idempotency_get(
                memory_write_batch_request_idempotency_seen,
                request_key,
            )
            if cached_response is not None:
                memory_write_batch_metrics["requestIdempotentHits"] = (
                    int(memory_write_batch_metrics.get("requestIdempotentHits", 0)) + 1
                )
                replayed = dict(cached_response)
                replayed["idempotentReplay"] = True
                replayed["idempotencyScope"] = "request"
                return replayed

    results: list[dict[str, Any]] = []
    successes = 0
    failures = 0
    local_item_cache: dict[str, dict[str, Any]] = {}
    for index, item in enumerate(items):
        item_key = _memory_write_batch_cache_key(item.idempotencyKey or "", "item")
        cached_item: dict[str, Any] | None = None
        if item_key and item_key in local_item_cache:
            cached_item = dict(local_item_cache[item_key])
        elif item_key:
            async with memory_write_batch_idempotency_lock:
                cached_item = await _memory_write_batch_idempotency_get(
                    memory_write_batch_item_idempotency_seen,
                    item_key,
                )
                if cached_item is not None:
                    memory_write_batch_metrics["itemIdempotentHits"] = (
                        int(memory_write_batch_metrics.get("itemIdempotentHits", 0)) + 1
                    )
                    local_item_cache[item_key] = dict(cached_item)

        if cached_item is not None:
            item_result = dict(cached_item)
            item_result["index"] = index
            item_result["itemId"] = item.itemId
            item_result["idempotentReplay"] = True
            item_result["idempotencyScope"] = "item"
            results.append(item_result)
            if bool(item_result.get("ok")):
                successes += 1
            else:
                failures += 1
            continue

        try:
            write_result = await write_memory(
                MemoryWrite(
                    projectName=item.projectName,
                    fileName=item.fileName,
                    content=item.content,
                    topicPath=item.topicPath,
                    fanoutExcludeTargets=item.fanoutExcludeTargets,
                ),
                request,
            )
            item_result = {
                "index": index,
                "itemId": item.itemId,
                "ok": bool(write_result.get("ok", True)),
                "event_id": write_result.get("event_id"),
                "warnings": list(write_result.get("warnings") or []),
                "fanout": dict(write_result.get("fanout") or {}),
                "rollup_buffered": bool(write_result.get("rollup_buffered", False)),
                "deduped": bool(write_result.get("deduped", False)),
                "latest_hash_unchanged": bool(write_result.get("latest_hash_unchanged", False)),
            }
            successes += 1 if item_result["ok"] else 0
            failures += 0 if item_result["ok"] else 1
        except HTTPException as exc:
            item_result = {
                "index": index,
                "itemId": item.itemId,
                "ok": False,
                "error": {
                    "status": int(exc.status_code),
                    "detail": str(exc.detail),
                },
                "warnings": [],
                "fanout": {},
            }
            failures += 1
        except Exception as exc:  # pragma: no cover - unexpected runtime path
            item_result = {
                "index": index,
                "itemId": item.itemId,
                "ok": False,
                "error": {
                    "status": 500,
                    "detail": str(exc),
                },
                "warnings": [],
                "fanout": {},
            }
            failures += 1

        if item_key:
            cacheable_result = {
                key: value
                for key, value in item_result.items()
                if key not in {"index", "itemId"}
            }
            local_item_cache[item_key] = dict(cacheable_result)
            async with memory_write_batch_idempotency_lock:
                await _memory_write_batch_idempotency_set(
                    memory_write_batch_item_idempotency_seen,
                    item_key,
                    cacheable_result,
                )
        results.append(item_result)

    response = {
        "ok": failures == 0,
        "partial": failures > 0 and successes > 0,
        "source": source_path,
        "accepted": len(items),
        "succeeded": successes,
        "failed": failures,
        "results": results,
    }

    async with memory_write_batch_idempotency_lock:
        memory_write_batch_metrics["accepted"] = int(memory_write_batch_metrics.get("accepted", 0)) + 1
        memory_write_batch_metrics["itemSuccesses"] = (
            int(memory_write_batch_metrics.get("itemSuccesses", 0)) + successes
        )
        memory_write_batch_metrics["itemFailures"] = (
            int(memory_write_batch_metrics.get("itemFailures", 0)) + failures
        )
        if request_key:
            await _memory_write_batch_idempotency_set(
                memory_write_batch_request_idempotency_seen,
                request_key,
                response,
            )
    return response


def _ops_queue_status_next_actions(
    *,
    pending: int,
    retrying: int,
    failed: int,
    queue_ratio: float,
    queue_high_watermark: float,
    retrying_high_threshold: int,
    pending_high_threshold: int,
    letta_backlog: int,
    letta_soft_limit: int,
    last_error: str,
) -> list[str]:
    actions: list[str] = []
    if failed > 0:
        actions.append(
            "Inspect deadletters via /telemetry/fanout/deadletters and run targeted rehydrate for safe subsets."
        )
    if retrying >= retrying_high_threshold:
        actions.append(
            "Retry backlog is elevated; run /telemetry/fanout/gc and verify per-target upstream health before rehydrate."
        )
    if pending >= pending_high_threshold:
        actions.append(
            "Pending backlog exceeded threshold; temporarily reduce optional sources for reads and increase worker throughput carefully."
        )
    if queue_ratio >= queue_high_watermark:
        actions.append(
            "In-memory fanout queue crossed high watermark; keep backpressure enabled and avoid large write bursts."
        )
    if letta_backlog >= letta_soft_limit:
        actions.append(
            "Letta backlog is above soft limit; keep staged fetch and throttle low-value Letta fanout until queue normalizes."
        )
    if "mindsdb autosync error" in last_error.lower():
        actions.append(
            "MindsDB autosync is failing; disable/de-prioritize MindsDB fanout temporarily or fix table/format compatibility first."
        )
    if not actions:
        actions.append("Queue pressure is within configured limits; continue monitoring trend snapshots.")
    return actions


async def _build_ops_queue_status_payload(
    *,
    include_deadletters: bool = True,
    deadletter_limit: int = 100,
    deadletter_target: str | None = None,
    queue_high_watermark: float | None = None,
    pending_high_threshold: int | None = None,
    retrying_high_threshold: int | None = None,
) -> dict[str, Any]:
    summary = await get_fanout_summary()
    by_status = summary.get("by_status") if isinstance(summary.get("by_status"), dict) else {}
    by_target = summary.get("by_target") if isinstance(summary.get("by_target"), dict) else {}
    pending = int(by_status.get("pending", 0) or 0)
    retrying = int(by_status.get("retrying", 0) or 0)
    running = int(by_status.get("running", 0) or 0)
    failed = int(by_status.get("failed", 0) or 0)
    succeeded = int(by_status.get("succeeded", 0) or 0)
    effective_pending = pending
    effective_retrying = retrying
    effective_running = running
    effective_failed = failed
    effective_succeeded = succeeded
    if not MINDSDB_FANOUT_ENABLED:
        mindsdb_state = (
            by_target.get(FANOUT_TARGET_MINDSDB)
            if isinstance(by_target.get(FANOUT_TARGET_MINDSDB), dict)
            else {}
        )
        effective_pending = max(0, effective_pending - int(mindsdb_state.get("pending", 0) or 0))
        effective_retrying = max(0, effective_retrying - int(mindsdb_state.get("retrying", 0) or 0))
        effective_running = max(0, effective_running - int(mindsdb_state.get("running", 0) or 0))
        effective_failed = max(0, effective_failed - int(mindsdb_state.get("failed", 0) or 0))
        effective_succeeded = max(0, effective_succeeded - int(mindsdb_state.get("succeeded", 0) or 0))
    queue_depth = memory_write_queue.qsize()
    queue_max = max(1, MEMORY_WRITE_QUEUE_MAX)
    queue_ratio = queue_depth / queue_max
    high_watermark = _normalize_watermark(
        float(queue_high_watermark)
        if queue_high_watermark is not None
        else FANOUT_BACKPRESSURE_QUEUE_HIGH_WATERMARK
    )
    default_pending_threshold = max(500, LETTA_ADMISSION_BACKLOG_SOFT_LIMIT * 2)
    default_retry_threshold = max(200, LETTA_ADMISSION_BACKLOG_SOFT_LIMIT)
    pending_threshold = max(1, int(pending_high_threshold or default_pending_threshold))
    retry_threshold = max(1, int(retrying_high_threshold or default_retry_threshold))
    letta_state = by_target.get(FANOUT_TARGET_LETTA) if isinstance(by_target.get(FANOUT_TARGET_LETTA), dict) else {}
    letta_backlog = int(letta_state.get("pending", 0) or 0) + int(letta_state.get("retrying", 0) or 0)
    deadletters: list[dict[str, Any]] = []
    deadletters_by_target: dict[str, int] = {}
    if include_deadletters:
        deadletters = await list_fanout_jobs(
            ["failed"],
            limit=max(1, min(deadletter_limit, 500)),
            target=str(deadletter_target or "").strip() or None,
        )
        for row in deadletters:
            target = str(row.get("target") or "unknown").strip().lower() or "unknown"
            deadletters_by_target[target] = deadletters_by_target.get(target, 0) + 1
    next_actions = _ops_queue_status_next_actions(
        pending=effective_pending,
        retrying=effective_retrying,
        failed=effective_failed,
        queue_ratio=queue_ratio,
        queue_high_watermark=high_watermark,
        retrying_high_threshold=retry_threshold,
        pending_high_threshold=pending_threshold,
        letta_backlog=letta_backlog,
        letta_soft_limit=LETTA_ADMISSION_BACKLOG_SOFT_LIMIT,
        last_error=str(outbox_health.get("lastError") or ""),
    )
    return {
        "updatedAt": _utc_now(),
        "queue": {
            "pending": effective_pending,
            "retrying": effective_retrying,
            "running": effective_running,
            "succeeded": effective_succeeded,
            "failed": effective_failed,
            "totalOutstanding": max(0, effective_pending + effective_retrying + effective_running),
            "pendingRaw": pending,
            "retryingRaw": retrying,
            "runningRaw": running,
            "succeededRaw": succeeded,
            "failedRaw": failed,
            "memoryWriteQueueDepth": queue_depth,
            "memoryWriteQueueMax": queue_max,
            "memoryWriteQueueRatio": round(queue_ratio, 6),
            "highWatermark": high_watermark,
            "pendingHighThreshold": pending_threshold,
            "retryingHighThreshold": retry_threshold,
            "highWatermarkExceeded": queue_ratio >= high_watermark,
        },
        "deadletters": {
            "included": include_deadletters,
            "count": len(deadletters),
            "byTarget": deadletters_by_target,
            "items": deadletters if include_deadletters else [],
        },
        "trend": {
            "snapshotAt": _utc_now(),
            "queueDepth": queue_depth,
            "outstanding": max(0, effective_pending + effective_retrying + effective_running),
            "processed": memory_write_queue_processed,
            "dropped": memory_write_queue_dropped,
            "lastProcessedAt": outbox_health.get("lastProcessedAt"),
            "lastBatchSize": outbox_health.get("lastBatchSize"),
        },
        "backpressure": {
            "enabled": FANOUT_BACKPRESSURE_ENABLED,
            "targets": FANOUT_BACKPRESSURE_TARGETS,
            "queueHighWatermark": _normalize_watermark(FANOUT_BACKPRESSURE_QUEUE_HIGH_WATERMARK),
            "maxSleepSecs": max(0.0, FANOUT_BACKPRESSURE_MAX_SLEEP_SECS),
        },
        "lettaAdmission": {
            "enabled": LETTA_ADMISSION_ENABLED,
            "softLimit": LETTA_ADMISSION_BACKLOG_SOFT_LIMIT,
            "hardLimit": LETTA_ADMISSION_BACKLOG_HARD_LIMIT,
            "backlog": letta_backlog,
            "lastReason": letta_admission_last_reason or None,
            "lastBacklog": letta_admission_last_backlog,
        },
        "health": {
            "lastError": outbox_health.get("lastError"),
            "lastProcessedAt": outbox_health.get("lastProcessedAt"),
        },
        "nextActions": next_actions,
    }


@app.post("/memory/write/batch")
async def write_memory_batch(payload: MemoryWriteBatchRequest, request: Request):
    return await _execute_memory_write_batch(payload, request, "/memory/write/batch")


@app.post("/memory/write")
async def write_memory(payload: MemoryWrite, request: Request):
    global memory_write_queue_dropped, memory_bank_queue_skipped_low_value
    start_time = asyncio.get_event_loop().time()
    file_name = normalize_memory_path(payload.fileName)
    if not file_name:
        raise HTTPException(400, "fileName is required")
    content_to_store, storage_policy_warning = _prepare_content_for_storage(payload.content)
    request_id = getattr(request.state, "request_id", None)
    hot_file = is_hot_memory_file(file_name)
    content_hash = memory_content_sha256(content_to_store)
    hot_rollup_mode = hot_file and HOT_MEMORY_ROLLUP_ENABLED

    topic_path = derive_topic_path(file_name, payload.topicPath)
    topic_tags = topic_tags_for_path(topic_path)
    summary = await summarize_content(content_to_store)
    code_context = _build_code_context_metadata(
        file_name=file_name,
        topic_path=topic_path,
        content=content_to_store,
        summary=summary,
    )

    async def _seed_mongo_retry(
        event_id: str,
        raw_event: dict[str, Any],
        local_letta_context: dict[str, Any] | None,
    ) -> None:
        global memory_write_queue_dropped
        outbox_payload = {
            "event_id": event_id,
            "project": payload.projectName,
            "file": file_name,
            "summary": summary,
            "payload": {
                "projectName": payload.projectName,
                "fileName": file_name,
            },
            "topic_path": topic_path,
            "topic_tags": topic_tags,
            "letta_session": LETTA_AUTO_SESSION_ID if _letta_target_enabled() else None,
            "letta_context": local_letta_context or {},
            "qdrant_collection": QDRANT_COLLECTION,
            "raw_event": raw_event,
            "code_context": code_context,
        }
        await enqueue_fanout_outbox(outbox_payload, [FANOUT_TARGET_MONGO_RAW], force_requeue=True)
        if memory_write_queue.full():
            memory_write_queue_dropped += 1
        else:
            await memory_write_queue.put(event_id)

    async def _persist_raw_event_sync_if_enabled(raw_event: dict[str, Any]) -> tuple[bool, str | None]:
        if not MONGO_RAW_SYNC_ON_WRITE_ENABLED:
            return False, "sync-on-write disabled"
        return await persist_raw_event_to_mongo(raw_event)

    def _fanout_status_counts_for_write_response() -> tuple[int, int]:
        # Keep write acknowledgements fast by using cached summary state and
        # scheduling refresh in background when stale.
        summary = _get_fanout_summary_cache()
        if not _fanout_cache_fresh(summary):
            _schedule_fanout_summary_refresh()
        retrying = int(summary.get("by_status", {}).get("retrying", 0))
        failed = int(summary.get("by_status", {}).get("failed", 0))
        if not _letta_target_enabled():
            letta_stats = summary.get("by_target", {}).get(FANOUT_TARGET_LETTA, {})
            retrying = max(0, retrying - int(letta_stats.get("retrying", 0)))
            failed = max(0, failed - int(letta_stats.get("failed", 0)))
        if not MINDSDB_FANOUT_ENABLED:
            mindsdb_stats = summary.get("by_target", {}).get(FANOUT_TARGET_MINDSDB, {})
            retrying = max(0, retrying - int(mindsdb_stats.get("retrying", 0)))
            failed = max(0, failed - int(mindsdb_stats.get("failed", 0)))
        return retrying, failed

    if hot_file and await should_skip_unchanged_latest_hash(payload.projectName, file_name, content_hash):
        event_id = uuid.uuid4().hex
        raw_event = build_raw_memory_event(
            event_id=event_id,
            project=payload.projectName,
            file_name=file_name,
            content=content_to_store,
            summary=summary,
            topic_path=topic_path,
            topic_tags=topic_tags,
            request_id=request_id,
        )
        warnings = ["latest snapshot unchanged (hash match); memory-bank and fanout writes suppressed"]
        if storage_policy_warning:
            warnings.append(storage_policy_warning)
        fanout_status: dict[str, str] = {
            "memory_bank": "skipped",
            FANOUT_TARGET_MONGO_RAW: "pending",
            FANOUT_TARGET_QDRANT: "skipped",
            FANOUT_TARGET_WEAVIATE: "skipped",
            FANOUT_TARGET_POSTGRES_PGVECTOR: "skipped",
            FANOUT_TARGET_MINDSDB: "skipped",
            FANOUT_TARGET_LANGFUSE: "skipped",
            FANOUT_TARGET_LETTA: "skipped",
        }
        mongo_ok, mongo_error = await _persist_raw_event_sync_if_enabled(raw_event)
        if mongo_ok:
            fanout_status[FANOUT_TARGET_MONGO_RAW] = "succeeded"
        else:
            fanout_status[FANOUT_TARGET_MONGO_RAW] = "retrying"
            warnings.append(
                f"raw-event Mongo write deferred; queued for retry ({mongo_error or 'unknown error'})"
            )
            await _seed_mongo_retry(event_id, raw_event, None)
        hot_memory_rollup_health["totalSkippedUnchanged"] = int(
            hot_memory_rollup_health.get("totalSkippedUnchanged") or 0
        ) + 1
        _json_log(
            "memory.write.latest_hash_unchanged",
            {
                "request_id": request_id,
                "event_id": event_id,
                "project": payload.projectName,
                "file": file_name,
                "bytes": len(content_to_store),
                "hash": content_hash[:16],
            },
        )
        return {
            "ok": True,
            "event_id": event_id,
            "warnings": warnings,
            "fanout": fanout_status,
            "deduped": True,
            "latest_hash_unchanged": True,
        }

    dedupe_key = build_memory_write_dedupe_key(payload.projectName, file_name, content_to_store)
    if await should_skip_duplicate_memory_write(dedupe_key):
        skipped_event_id = build_event_id(payload.projectName, file_name, content_to_store)
        warnings = [
            f"duplicate memory.write suppressed within {int(max(0.0, MEMORY_WRITE_DEDUP_WINDOW_SECS))} seconds"
        ]
        if storage_policy_warning:
            warnings.append(storage_policy_warning)
        _json_log(
            "memory.write.deduped",
            {
                "request_id": request_id,
                "event_id": skipped_event_id,
                "project": payload.projectName,
                "file": file_name,
                "bytes": len(content_to_store),
            },
        )
        return {
            "ok": True,
            "event_id": skipped_event_id,
            "warnings": warnings,
            "fanout": {
                "memory_bank": "skipped",
                FANOUT_TARGET_MONGO_RAW: "skipped",
                FANOUT_TARGET_QDRANT: "skipped",
                FANOUT_TARGET_WEAVIATE: "skipped",
                FANOUT_TARGET_POSTGRES_PGVECTOR: "skipped",
                FANOUT_TARGET_MINDSDB: "skipped",
                FANOUT_TARGET_LANGFUSE: "skipped",
                FANOUT_TARGET_LETTA: "skipped",
            },
            "deduped": True,
        }

    event_id = uuid.uuid4().hex
    raw_event = build_raw_memory_event(
        event_id=event_id,
        project=payload.projectName,
        file_name=file_name,
        content=content_to_store,
        summary=summary,
        topic_path=topic_path,
        topic_tags=topic_tags,
        request_id=request_id,
    )
    if code_context:
        raw_event["code_context"] = dict(code_context)
    payload_data = {
        "projectName": payload.projectName,
        "fileName": file_name,
        "content": content_to_store,
        "code_context": dict(code_context),
    }
    warnings: list[str] = []
    if storage_policy_warning:
        warnings.append(storage_policy_warning)
    fanout_exclude_targets = _normalize_fanout_targets(payload.fanoutExcludeTargets)
    mindsdb_fanout_disabled = (
        not MINDSDB_FANOUT_ENABLED
        or FANOUT_TARGET_MINDSDB in fanout_exclude_targets
    )
    telemetry_like_record = _is_telemetry_memory_record(file_name, topic_path, summary)
    strict_telemetry_isolation = TELEMETRY_STRICT_SINK_ISOLATION and telemetry_like_record
    qdrant_telemetry_skipped = strict_telemetry_isolation or (
        telemetry_like_record and QDRANT_TELEMETRY_GUARD_ENABLED
    )
    weaviate_telemetry_skipped = strict_telemetry_isolation or (
        telemetry_like_record and WEAVIATE_TELEMETRY_GUARD_ENABLED
    )
    pgvector_telemetry_skipped = strict_telemetry_isolation or (
        telemetry_like_record and PGVECTOR_TELEMETRY_GUARD_ENABLED
    )
    mindsdb_telemetry_skipped = strict_telemetry_isolation or (
        telemetry_like_record and MINDSDB_TELEMETRY_GUARD_ENABLED
    )
    letta_telemetry_skipped = strict_telemetry_isolation or (
        telemetry_like_record and LETTA_TELEMETRY_GUARD_ENABLED
    )
    memory_bank_low_value_excluded = bool(
        strict_telemetry_isolation
        or (
            MEMORY_BANK_TELEMETRY_GUARD_ENABLED
            and _looks_memory_bank_telemetry_file(file_name, topic_path)
        )
    )
    if memory_bank_low_value_excluded:
        warnings.append("memory-bank persistence skipped for telemetry-like artifact")
    if telemetry_like_record and (
        qdrant_telemetry_skipped
        or weaviate_telemetry_skipped
        or pgvector_telemetry_skipped
        or mindsdb_telemetry_skipped
        or letta_telemetry_skipped
    ):
        if strict_telemetry_isolation:
            warnings.append(
                "strict telemetry sink isolation routed artifact to mongo_raw-only lane; qdrant/weaviate/postgres_pgvector/mindsdb/letta/langfuse/memory_bank fanout filtered"
            )
        else:
            warnings.append(
                "telemetry-like artifact routed to telemetry sink path; qdrant/weaviate/postgres_pgvector/mindsdb/letta/langfuse fanout filtered"
            )
    fanout_status: dict[str, str] = {
        "memory_bank": (
            "skipped_low_value" if memory_bank_low_value_excluded else ("queued_rollup" if hot_rollup_mode else "queued")
        ),
        FANOUT_TARGET_MONGO_RAW: "pending",
        FANOUT_TARGET_QDRANT: (
            "skipped_low_value" if qdrant_telemetry_skipped else ("deferred_rollup" if hot_rollup_mode else "pending")
        ),
        FANOUT_TARGET_WEAVIATE: (
            "disabled"
            if not WEAVIATE_FANOUT_ENABLED
            else (
                "skipped_low_value"
                if weaviate_telemetry_skipped
                else ("deferred_rollup" if hot_rollup_mode else "pending")
            )
        ),
        FANOUT_TARGET_POSTGRES_PGVECTOR: (
            "disabled"
            if not PGVECTOR_FANOUT_ENABLED
            else (
                "skipped_low_value"
                if pgvector_telemetry_skipped
                else ("deferred_rollup" if hot_rollup_mode else "pending")
            )
        ),
        FANOUT_TARGET_MINDSDB: (
            "disabled"
            if mindsdb_fanout_disabled
            else (
                "skipped_low_value"
                if mindsdb_telemetry_skipped
                else ("deferred_rollup" if hot_rollup_mode else "pending")
            )
        ),
        FANOUT_TARGET_LANGFUSE: "disabled" if not LANGFUSE_API_KEY else ("deferred_rollup" if hot_rollup_mode else "pending"),
        FANOUT_TARGET_LETTA: "skipped_low_value" if letta_telemetry_skipped else "disabled",
    }
    mongo_persisted = False
    mongo_ok, mongo_error = await _persist_raw_event_sync_if_enabled(raw_event)
    if mongo_ok:
        fanout_status[FANOUT_TARGET_MONGO_RAW] = "succeeded"
        mongo_persisted = True
    else:
        fanout_status[FANOUT_TARGET_MONGO_RAW] = "retrying"
        warnings.append(
            f"raw-event Mongo write deferred; queued for retry ({mongo_error or 'unknown error'})"
        )
    letta_admitted = False
    letta_context = None
    if LETTA_AUTO_SESSION_ID:
        source_kind = "high_frequency_rollup" if hot_rollup_mode else "memory_write"
        if letta_telemetry_skipped:
            fanout_status[FANOUT_TARGET_LETTA] = "skipped_low_value"
        elif LETTA_REQUIRE_API_KEY and not LETTA_API_KEY:
            fanout_status[FANOUT_TARGET_LETTA] = "disabled"
            warnings.append("Letta sync disabled because LETTA_REQUIRE_API_KEY is true and LETTA_API_KEY is empty")
        elif not letta_runtime_enabled:
            fanout_status[FANOUT_TARGET_LETTA] = "disabled"
            reason = letta_runtime_disabled_reason or "runtime disabled"
            warnings.append(f"Letta sync disabled due to permanent fanout error ({reason})")
        else:
            admitted, admission_reason, backlog = await _letta_admission_should_enqueue(
                file_name,
                topic_path,
                summary,
                source_kind,
            )
            if admitted:
                letta_admitted = True
                fanout_status[FANOUT_TARGET_LETTA] = "deferred_rollup" if hot_rollup_mode else "pending"
            else:
                fanout_status[FANOUT_TARGET_LETTA] = "throttled_backlog"
                backlog_msg = max(0, int(backlog))
                reason_text = admission_reason or "backlog"
                warnings.append(
                    f"Letta fanout deferred under backlog ({reason_text}; outstanding={backlog_msg})"
                )
                _record_letta_admission_drop(
                    reason=reason_text,
                    backlog=backlog_msg,
                    project=payload.projectName,
                    file_name=file_name,
                    topic_path=topic_path,
                )
        letta_context = {
            "project": payload.projectName,
            "file": file_name,
            "summary": summary,
            "topic_path": topic_path,
            "source_kind": source_kind,
            "content_hash": content_hash,
            "code_context": dict(code_context),
        }
        if not hot_rollup_mode:
            letta_context["content"] = content_to_store

    if memory_bank_low_value_excluded:
        memory_bank_queue_skipped_low_value += 1
        await _finalize_memory_write_item(
            {
                "event_id": event_id,
                "project": payload.projectName,
                "file": file_name,
                "payload": payload_data,
                "summary": summary,
                "topic_path": topic_path,
                "topic_tags": topic_tags,
                "content_length": len(content_to_store),
                "letta_session": LETTA_AUTO_SESSION_ID if _letta_target_enabled() and letta_admitted else None,
                "letta_admit": letta_admitted,
                "letta_context": letta_context,
                "waiter": None,
                "start_time": start_time,
                "request_id": request_id,
                "raw_event": raw_event,
                "mongo_persisted": mongo_persisted,
                "qdrant_collection": QDRANT_COLLECTION,
                "code_context": dict(code_context),
                "fanout_exclude_targets": list(fanout_exclude_targets),
            },
            worker_id=None,
            persisted_to_memory_bank=False,
        )
        if not mongo_persisted:
            await _seed_mongo_retry(event_id, raw_event, letta_context)
        retrying, failed = _fanout_status_counts_for_write_response()
        if failed > 0:
            warnings.append(
                f"fanout currently degraded: {failed} failed and {retrying} retrying jobs; durability outside memory-bank is lagging"
            )
        elif retrying > 0:
            warnings.append(
                f"fanout backlog detected: {retrying} jobs retrying; writes may be temporarily memory-bank-only"
            )
        return {
            "ok": True,
            "event_id": event_id,
            "warnings": warnings,
            "fanout": fanout_status,
            "memory_bank_skipped_low_value": True,
        }

    if hot_rollup_mode:
        rollup_file = build_hot_memory_rollup_file(file_name)
        await enqueue_hot_memory_rollup(
            {
                "project": payload.projectName,
                "file": file_name,
                "summary": summary,
                "topic_path": topic_path,
                "topic_tags": topic_tags,
                "content_hash": content_hash,
                "content_length": len(content_to_store),
                "letta_session": LETTA_AUTO_SESSION_ID if _letta_target_enabled() and letta_admitted else None,
                "letta_admit": letta_admitted,
                "letta_context": letta_context or {},
                "qdrant_collection": QDRANT_COLLECTION,
                "code_context": dict(code_context),
            }
        )
        warnings.append(
            f"high-frequency write buffered; rollup flush every {int(max(1.0, HOT_MEMORY_ROLLUP_FLUSH_SECS))}s to {rollup_file}"
        )
        if not mongo_persisted:
            await _seed_mongo_retry(event_id, raw_event, letta_context)
        latency_ms = (asyncio.get_event_loop().time() - start_time) * 1000
        _json_log(
            "memory.write.rollup_buffered",
            {
                "request_id": request_id,
                "event_id": event_id,
                "project": payload.projectName,
                "file": file_name,
                "rollup_file": rollup_file,
                "bytes": len(content_to_store),
                "latency_ms": round(latency_ms, 2),
            },
        )
        retrying, failed = _fanout_status_counts_for_write_response()
        if failed > 0:
            warnings.append(
                f"fanout currently degraded: {failed} failed and {retrying} retrying jobs; durability outside memory-bank is lagging"
            )
        elif retrying > 0:
            warnings.append(
                f"fanout backlog detected: {retrying} jobs retrying; writes may be temporarily memory-bank-only"
            )
        return {
            "ok": True,
            "event_id": event_id,
            "warnings": warnings,
            "fanout": fanout_status,
            "rollup_buffered": True,
            "rollup_file": rollup_file,
        }

    waiter = None
    if not MEMORY_WRITE_ASYNC:
        waiter = asyncio.get_event_loop().create_future()
    await _enqueue_memory_bank_write(
        {
            "project": payload.projectName,
            "file": file_name,
            "payload": payload_data,
            "summary": summary,
            "topic_path": topic_path,
            "topic_tags": topic_tags,
            "content_length": len(content_to_store),
            "letta_session": LETTA_AUTO_SESSION_ID if _letta_target_enabled() and letta_admitted else None,
            "letta_admit": letta_admitted,
            "letta_context": letta_context,
            "waiter": waiter,
            "start_time": start_time,
            "request_id": request_id,
            "event_id": event_id,
            "raw_event": raw_event,
            "mongo_persisted": mongo_persisted,
            "qdrant_collection": QDRANT_COLLECTION,
            "code_context": dict(code_context),
            "fanout_exclude_targets": list(fanout_exclude_targets),
        }
    )
    if not mongo_persisted:
        # Seed mongo retry immediately so we do not depend on memory-bank completion.
        await _seed_mongo_retry(event_id, raw_event, letta_context)
    if waiter is not None:
        try:
            await waiter
        except Exception as exc:  # pragma: no cover
            raise HTTPException(502, f"Memory write failed: {exc}") from exc
    latency_ms = (asyncio.get_event_loop().time() - start_time) * 1000
    _json_log(
        "memory.write" if waiter is not None else "memory.write.queued",
        {
            "request_id": request_id,
            "event_id": event_id,
            "project": payload.projectName,
            "file": file_name,
            "bytes": len(content_to_store),
            "latency_ms": round(latency_ms, 2),
        },
    )
    retrying, failed = _fanout_status_counts_for_write_response()
    if failed > 0:
        warnings.append(
            f"fanout currently degraded: {failed} failed and {retrying} retrying jobs; durability outside memory-bank is lagging"
        )
    elif retrying > 0:
        warnings.append(
            f"fanout backlog detected: {retrying} jobs retrying; writes may be temporarily memory-bank-only"
        )
    return {
        "ok": True,
        "event_id": event_id,
        "warnings": warnings,
        "fanout": fanout_status,
    }


@app.post("/memory/browser-context")
async def write_browser_context(payload: BrowserContextIngest):
    if not BROWSER_CONTEXT_INGEST_ENABLED:
        raise HTTPException(503, "browser context ingest is disabled")
    project_name = str(payload.projectName or "").strip()
    if not project_name:
        raise HTTPException(422, "projectName is required")
    page_url = str(payload.pageUrl or "").strip()
    if not page_url:
        raise HTTPException(422, "pageUrl is required")
    text_snapshot = str(payload.textSnapshot or "").strip()
    if not text_snapshot:
        raise HTTPException(422, "textSnapshot is required")
    max_chars = int(payload.maxChars or 12000)
    bounded_snapshot = text_snapshot[: max(200, min(40000, max_chars))]
    file_name = _build_browser_context_file_name(page_url=page_url, title=payload.title)
    title_text = str(payload.title or "").strip()
    parsed = urlparse(page_url)
    host = str(parsed.netloc or "").strip()
    lines = [
        f"# Browser Context Snapshot: {title_text or host or 'untitled'}",
        "",
        f"- url: {page_url}",
        f"- host: {host or 'unknown'}",
        f"- captured_at: {_utc_now()}",
    ]
    if payload.agentId:
        lines.append(f"- agent_id: {str(payload.agentId).strip()}")
    lines.extend(["", "## Snapshot", "", bounded_snapshot])
    content = "\n".join(lines).strip() + "\n"
    topic_path = normalize_topic_path(payload.topicPath) or "browser/context"
    write_payload = MemoryWrite(
        projectName=project_name,
        fileName=file_name,
        content=content,
        topicPath=topic_path,
    )
    result = await write_memory(write_payload, _synthetic_request("/memory/browser-context"))
    warnings = list(result.get("warnings") or [])
    warnings.append("browser context persisted as text snapshot for retrieval/rerank")
    result["warnings"] = warnings
    result["browserContext"] = {
        "project": write_payload.projectName,
        "file": file_name,
        "topicPath": topic_path,
        "url": page_url,
    }
    return result


@app.post("/ingest/trajectory")
async def ingest_trajectory(body: TrajectoryIngest):
    summary = body.summary
    trajectory_content = json.dumps(body.trajectory, indent=2)
    content_to_store, storage_policy_warning = _prepare_content_for_storage(trajectory_content)
    langfuse_payload: dict[str, Any] = body.trajectory
    if storage_policy_warning:
        try:
            parsed = json.loads(content_to_store)
            if isinstance(parsed, dict):
                langfuse_payload = parsed
            else:
                langfuse_payload = {"trajectory": parsed}
        except Exception:
            langfuse_payload = {"trajectory": content_to_store}
    await call_memory_tool(
        "memory_bank_write",
        {
            "projectName": body.project,
            "fileName": f"trajectory-{uuid.uuid4().hex}.json",
            "content": content_to_store,
        },
    )
    await asyncio.gather(
        push_to_qdrant(body.project, "trajectory", summary),
        push_to_langfuse(body.project, summary, langfuse_payload),
    )
    response: dict[str, Any] = {"ok": True}
    if storage_policy_warning:
        response["warnings"] = [storage_policy_warning]
    return response


