@app.get("/status")
async def status():
    services = []
    # memory bank check
    try:
        await list_projects()
        services.append({"name": "memory-bank", "healthy": True, "detail": "MCP reachable"})
    except Exception as exc:  # pragma: no cover - health fallback
        services.append({"name": "memory-bank", "healthy": False, "detail": str(exc)})

    # Langfuse
    try:
        async with httpx.AsyncClient(timeout=5.0) as client:
            resp = await client.get(LANGFUSE_URL)
        services.append({
            "name": "langfuse",
            "healthy": resp.status_code == 200,
            "detail": f"status {resp.status_code}",
        })
    except Exception as exc:  # pragma: no cover
        services.append({"name": "langfuse", "healthy": False, "detail": str(exc)})

    # Qdrant
    try:
        await _qdrant_call(
            "status_probe",
            lambda client, target: client.get_collections(),
        )
        backend = _qdrant_operation_targets()[0]
        transport = "grpc-preferred" if QDRANT_GRPC_PREFER else "http-preferred"
        services.append({
            "name": "qdrant",
            "healthy": True,
            "detail": f"{backend} {transport}",
        })
    except Exception as exc:  # pragma: no cover
        services.append({"name": "qdrant", "healthy": False, "detail": str(exc)})

    # Weaviate
    if not WEAVIATE_ENABLED:
        services.append({"name": "weaviate", "healthy": True, "detail": "disabled"})
    else:
        try:
            client = await _get_weaviate_client()
            headers = _weaviate_headers()
            resp = await client.get(f"{WEAVIATE_URL.rstrip('/')}/v1/meta", headers=headers)
            services.append({
                "name": "weaviate",
                "healthy": resp.status_code < 500,
                "detail": f"status {resp.status_code}",
            })
        except Exception as exc:  # pragma: no cover
            services.append({"name": "weaviate", "healthy": False, "detail": str(exc)})

    # MindsDB
    if not MINDSDB_ENABLED:
        services.append({"name": "mindsdb", "healthy": True, "detail": "disabled"})
    else:
        try:
            async with httpx.AsyncClient(timeout=5.0) as client:
                resp = await client.get(f"{MINDSDB_URL}/api/status")
            services.append({
                "name": "mindsdb",
                "healthy": resp.status_code == 200,
                "detail": f"status {resp.status_code}",
            })
        except Exception as exc:  # pragma: no cover
            services.append({"name": "mindsdb", "healthy": False, "detail": str(exc)})

    # Letta
    try:
        async with httpx.AsyncClient(timeout=5.0) as client:
            resp = await client.get(LETTA_URL)
        services.append({
            "name": "letta",
            "healthy": resp.status_code < 500,
            "detail": f"status {resp.status_code}",
        })
    except Exception as exc:  # pragma: no cover
        services.append({"name": "letta", "healthy": False, "detail": str(exc)})

    task_runtime: dict[str, Any] | None = None
    with contextlib.suppress(Exception):
        task_runtime = await get_task_runtime_snapshot()

    return {
        "services": services,
        "taskRuntime": task_runtime,
        "pythonHotPathOwnership": _python_hot_path_ownership_payload(),
    }


@app.get("/migration/runtime")
async def migration_runtime_status():
    def _flags_payload() -> dict[str, Any]:
        if MIGRATION_FLAGS is None:
            return {}
        return {
            "use_rust_codec": bool(getattr(MIGRATION_FLAGS, "use_rust_codec", False)),
            "use_rust_memory": bool(getattr(MIGRATION_FLAGS, "use_rust_memory", False)),
            "use_rust_retrieval": bool(getattr(MIGRATION_FLAGS, "use_rust_retrieval", False)),
            "use_go_orchestrator": bool(getattr(MIGRATION_FLAGS, "use_go_orchestrator", False)),
            "engine_mode": str(getattr(MIGRATION_FLAGS, "engine_mode", "embedded")),
            "shadow_dual_run": bool(getattr(MIGRATION_FLAGS, "shadow_dual_run", False)),
            "canary_enabled": bool(getattr(MIGRATION_FLAGS, "canary_enabled", False)),
        }

    runtime = await _get_migration_runtime()
    if runtime is None:
        reason = "migration flags disabled; using legacy Python orchestration path"
        if not _migration_runtime_supported():
            reason = "runtime adapters unavailable; using legacy Python orchestration path"
        return {
            "enabled": False,
            "flags": _flags_payload(),
            "reason": reason,
        }
    snapshot = None
    if runtime_snapshot is not None:
        with contextlib.suppress(Exception):
            snapshot = await runtime_snapshot(runtime)
    response = {
        "enabled": True,
        "flags": _flags_payload(),
        "implementations": dict(getattr(runtime, "implementation_map", {}) or {}),
    }
    if isinstance(snapshot, dict):
        response["snapshot"] = snapshot
    return response


