@app.get("/telemetry/retrieval")
async def get_retrieval_metrics(limit: int = 20, traffic_class: str = TRAFFIC_CLASS_USER):
    payload = await _build_retrieval_metrics_payload(limit)
    traffic_class_token = str(traffic_class or "").strip().lower()
    class_filter = None if traffic_class_token == "all" else _normalize_traffic_class(traffic_class_token)
    if class_filter is not None:
        latency = payload.get("latency") if isinstance(payload.get("latency"), dict) else {}
        recall_quality = payload.get("recallQuality") if isinstance(payload.get("recallQuality"), dict) else {}
        latency_class = (
            latency.get("byTrafficClass", {}).get(class_filter)
            if isinstance(latency.get("byTrafficClass"), dict)
            else None
        )
        recall_class = (
            recall_quality.get("byTrafficClass", {}).get(class_filter)
            if isinstance(recall_quality.get("byTrafficClass"), dict)
            else None
        )
        if isinstance(latency_class, dict):
            payload["latency"] = {
                "updatedAt": latency.get("updatedAt"),
                "historyLimit": latency.get("historyLimit"),
                **latency_class,
            }
        if isinstance(recall_class, dict):
            payload["recallQuality"] = {
                "updatedAt": recall_quality.get("updatedAt"),
                **recall_class,
            }
        filtered_alerts = _build_retrieval_alerts(
            payload.get("latency") if isinstance(payload.get("latency"), dict) else {}
        )
        filtered_recall_alerts = _build_recall_quality_alerts(
            payload.get("recallQuality") if isinstance(payload.get("recallQuality"), dict) else {}
        )
        if isinstance(filtered_alerts, dict) and filtered_recall_alerts:
            active = filtered_alerts.get("active")
            if isinstance(active, list):
                active.extend(filtered_recall_alerts)
                filtered_alerts["active"] = active
                filtered_alerts["count"] = len(active)
        payload["alerts"] = filtered_alerts
    payload["trafficClass"] = class_filter or "all"
    if TELEMETRY_PERSIST_ENABLED and (class_filter in {None, TRAFFIC_CLASS_USER}):
        asyncio.create_task(_persist_retrieval_telemetry_snapshot(payload))
    return payload


async def _retrieval_source_quality_window_snapshot(
    window_secs: float,
    *,
    traffic_class: str | None = TRAFFIC_CLASS_USER,
) -> dict[str, Any]:
    now_dt = datetime.now(timezone.utc)
    effective_window_secs = max(60.0, min(float(window_secs), 86400.0))
    start_dt = now_dt - timedelta(seconds=effective_window_secs)
    class_filter = None
    if traffic_class is not None and str(traffic_class).strip().lower() != "all":
        class_filter = _normalize_traffic_class(traffic_class)
    async with recall_quality_lock:
        history = list(recall_quality_history)
    sample_count = 0
    per_source: dict[str, dict[str, int]] = {}
    for row in history:
        if not isinstance(row, dict):
            continue
        parsed_timestamp = _parse_timestamp_to_datetime(row.get("timestamp"))
        if parsed_timestamp is None or parsed_timestamp < start_dt:
            continue
        row_class = _normalize_traffic_class(row.get("trafficClass"))
        if class_filter is not None and row_class != class_filter:
            continue
        sample_count += 1
        source_counts = row.get("sourceCounts") if isinstance(row.get("sourceCounts"), dict) else {}
        if source_counts:
            for source_name, request_count in source_counts.items():
                normalized = str(source_name or "").strip().lower()
                if not normalized:
                    continue
                entry = per_source.setdefault(
                    normalized,
                    {"requests": 0, "timeouts": 0, "errors": 0, "budgetExceeded": 0},
                )
                entry["requests"] += max(0, int(request_count or 0))
        else:
            row_sources = row.get("sources") if isinstance(row.get("sources"), list) else []
            for source_name in row_sources:
                normalized = str(source_name or "").strip().lower()
                if not normalized:
                    continue
                entry = per_source.setdefault(
                    normalized,
                    {"requests": 0, "timeouts": 0, "errors": 0, "budgetExceeded": 0},
                )
                entry["requests"] += 1
        source_error_kinds = row.get("sourceErrorKinds") if isinstance(row.get("sourceErrorKinds"), dict) else {}
        if not source_error_kinds:
            source_errors = row.get("sourceErrors") if isinstance(row.get("sourceErrors"), dict) else {}
            source_error_kinds = {
                str(source_name or "").strip().lower(): _normalize_source_error_detail(payload).get("kind")
                for source_name, payload in source_errors.items()
                if str(source_name or "").strip()
            }
        for source_name, kind_value in source_error_kinds.items():
            normalized = str(source_name or "").strip().lower()
            kind = str(kind_value or "").strip().lower()
            if not normalized or not kind:
                continue
            entry = per_source.setdefault(
                normalized,
                {"requests": 0, "timeouts": 0, "errors": 0, "budgetExceeded": 0},
            )
            if kind == "budget_exceeded":
                entry["budgetExceeded"] += 1
            elif kind == "timeout":
                entry["timeouts"] += 1
                entry["errors"] += 1
            else:
                entry["errors"] += 1
    return {
        "windowSecs": round(effective_window_secs, 3),
        "startAt": start_dt.isoformat().replace("+00:00", "Z"),
        "endAt": now_dt.isoformat().replace("+00:00", "Z"),
        "sampleCount": sample_count,
        "sources": per_source,
    }


@app.get("/telemetry/retrieval/source-quality")
async def get_retrieval_source_quality(
    limit: int = 20,
    window_mins: int = 0,
    traffic_class: str = TRAFFIC_CLASS_USER,
):
    payload = await _build_retrieval_metrics_payload(limit)
    recall_quality = payload.get("recallQuality") if isinstance(payload.get("recallQuality"), dict) else {}
    latency = payload.get("latency") if isinstance(payload.get("latency"), dict) else {}
    source_circuit = payload.get("sourceCircuit") if isinstance(payload.get("sourceCircuit"), dict) else {}
    backlog_gating = payload.get("backlogGating") if isinstance(payload.get("backlogGating"), dict) else {}
    traffic_class_token = str(traffic_class or "").strip().lower()
    class_filter = None if traffic_class_token == "all" else _normalize_traffic_class(traffic_class_token)
    latency_selected = latency
    recall_quality_selected = recall_quality
    if class_filter is not None:
        latency_by_class = (
            latency.get("byTrafficClass")
            if isinstance(latency.get("byTrafficClass"), dict)
            else {}
        )
        recall_by_class = (
            recall_quality.get("byTrafficClass")
            if isinstance(recall_quality.get("byTrafficClass"), dict)
            else {}
        )
        latency_selected = (
            latency_by_class.get(class_filter)
            if isinstance(latency_by_class.get(class_filter), dict)
            else {"sources": {}, "modes": {}}
        )
        recall_quality_selected = (
            recall_by_class.get(class_filter)
            if isinstance(recall_by_class.get(class_filter), dict)
            else {"bySource": {}, "recent": []}
        )
    latency_sources = latency_selected.get("sources") if isinstance(latency_selected.get("sources"), dict) else {}
    by_source = (
        recall_quality_selected.get("bySource")
        if isinstance(recall_quality_selected.get("bySource"), dict)
        else {}
    )
    baseline_source = RETRIEVAL_SOURCE_QDRANT
    baseline_error_rate = float(
        (
            by_source.get(baseline_source, {}).get("errorRate")
            if isinstance(by_source.get(baseline_source), dict)
            else 0.0
        )
        or 0.0
    )
    window_enabled = int(window_mins) > 0
    window_snapshot = (
        await _retrieval_source_quality_window_snapshot(
            max(1, int(window_mins)) * 60.0,
            traffic_class=class_filter,
        )
        if window_enabled
        else {
            "windowSecs": 0.0,
            "startAt": None,
            "endAt": None,
            "sampleCount": 0,
            "sources": {},
        }
    )
    window_sources = (
        window_snapshot.get("sources")
        if isinstance(window_snapshot.get("sources"), dict)
        else {}
    )
    window_sample_count = max(0, int(window_snapshot.get("sampleCount") or 0))
    use_window_metrics = window_enabled and window_sample_count > 0
    rows: list[dict[str, Any]] = []
    lifetime_rows: list[dict[str, Any]] = []
    source_names = sorted(set(latency_sources.keys()) | set(by_source.keys()) | set(window_sources.keys()))
    for source_name in source_names:
        source_latency = (
            latency_sources.get(source_name)
            if isinstance(latency_sources.get(source_name), dict)
            else {}
        )
        source_quality = (
            by_source.get(source_name)
            if isinstance(by_source.get(source_name), dict)
            else {}
        )
        requests = int(source_latency.get("requests") or source_quality.get("requests") or 0)
        timeouts = int(source_latency.get("timeouts") or 0)
        timeout_rate = (float(timeouts) / float(requests)) if requests > 0 else 0.0
        error_rate = float(source_quality.get("errorRate") or 0.0)
        lifetime_rows.append(
            {
                "source": source_name,
                "requests": requests,
                "timeouts": timeouts,
                "timeoutRate": round(timeout_rate, 6),
                "errorRate": round(error_rate, 6),
                "errorRateDeltaVsQdrant": round(error_rate - baseline_error_rate, 6),
                "p50Ms": float(source_latency.get("p50Ms") or 0.0),
                "p95Ms": float(source_latency.get("p95Ms") or 0.0),
                "p99Ms": float(source_latency.get("p99Ms") or 0.0),
            }
        )
        window_row = (
            window_sources.get(source_name)
            if isinstance(window_sources.get(source_name), dict)
            else {}
        )
        window_requests = int(window_row.get("requests") or 0)
        window_timeouts = int(window_row.get("timeouts") or 0)
        window_errors = int(window_row.get("errors") or 0)
        window_budget_exceeded = int(window_row.get("budgetExceeded") or 0)
        window_timeout_rate = (
            (float(window_timeouts) / float(window_requests))
            if window_requests > 0
            else 0.0
        )
        window_error_rate = (
            (float(window_errors) / float(window_requests))
            if window_requests > 0
            else 0.0
        )
        window_budget_exceeded_rate = (
            (float(window_budget_exceeded) / float(window_requests))
            if window_requests > 0
            else 0.0
        )
        rows.append(
            {
                "source": source_name,
                "requests": window_requests if use_window_metrics else requests,
                "timeouts": window_timeouts if use_window_metrics else timeouts,
                "budgetExceeded": window_budget_exceeded if use_window_metrics else 0,
                "errors": window_errors if use_window_metrics else int(round(error_rate * requests)),
                "timeoutRate": (
                    round(window_timeout_rate, 6)
                    if use_window_metrics
                    else round(timeout_rate, 6)
                ),
                "budgetExceededRate": (
                    round(window_budget_exceeded_rate, 6)
                    if use_window_metrics
                    else 0.0
                ),
                "errorRate": (
                    round(window_error_rate, 6)
                    if use_window_metrics
                    else round(error_rate, 6)
                ),
                "errorRateDeltaVsQdrant": (
                    round(window_error_rate - baseline_error_rate, 6)
                    if use_window_metrics
                    else round(error_rate - baseline_error_rate, 6)
                ),
                "p50Ms": float(source_latency.get("p50Ms") or 0.0),
                "p95Ms": float(source_latency.get("p95Ms") or 0.0),
                "p99Ms": float(source_latency.get("p99Ms") or 0.0),
                "lifetimeRequests": requests,
                "lifetimeTimeouts": timeouts,
            }
        )
    rows.sort(key=lambda item: (item["timeoutRate"], item["errorRate"], item["p95Ms"]), reverse=True)
    recommendations: list[str] = []
    if rows and rows[0]["timeoutRate"] >= 0.25:
        recommendations.append(
            "At least one source has timeout rate >= 25%; keep it out of default decision path or reduce time budget."
        )
    if any(row.get("budgetExceededRate", 0.0) >= 0.25 for row in rows):
        recommendations.append(
            "Budget-exceeded rates are elevated for slower sources; this is expected with fail-open staged retrieval. Use deep mode or longer blocking budgets when completeness is more important than latency."
        )
    if any(row["source"] == RETRIEVAL_SOURCE_LETTA and row["timeoutRate"] >= 0.5 for row in rows):
        recommendations.append(
            "Letta timeout rate is high; keep staged fetch + backlog admission and avoid blocking critical read path on Letta."
        )
    if any(row["source"] == RETRIEVAL_SOURCE_MINDSDB and row["errorRate"] > 0 for row in rows):
        recommendations.append(
            "MindsDB source errors are non-zero; verify table format and keep LZ4 circuit protection enabled."
        )
    degraded_sources = (
        source_circuit.get("degradedSources")
        if isinstance(source_circuit.get("degradedSources"), dict)
        else {}
    )
    if degraded_sources:
        names = ", ".join(sorted(degraded_sources.keys()))
        recommendations.append(
            f"Adaptive source circuit is currently open for: {names}. Continue using staged fetch + async warm while sources recover."
        )
    if (
        backlog_gating.get("enabled")
        and int(backlog_gating.get("lettaOutstandingMax") or 0) > 0
    ):
        recommendations.append(
            "Backlog gating is enabled for slow sinks; high outbox pressure will suppress blocking reads from overloaded sources."
        )
    if not recommendations:
        recommendations.append("Source quality is within expected bounds for current thresholds.")
    return {
        "updatedAt": payload.get("updatedAt"),
        "trafficClass": class_filter or "all",
        "baselineSource": baseline_source,
        "window": {
            "minutes": max(0, int(window_mins)),
            "windowSecs": window_snapshot.get("windowSecs"),
            "startAt": window_snapshot.get("startAt"),
            "endAt": window_snapshot.get("endAt"),
            "sampleCount": window_snapshot.get("sampleCount"),
            "active": use_window_metrics,
        },
        "sources": rows,
        "lifetimeSources": lifetime_rows,
        "recommendations": recommendations,
    }


@app.get("/telemetry/recall")
async def get_recall_metrics(traffic_class: str = TRAFFIC_CLASS_USER):
    snapshot = await _recall_quality_snapshot()
    traffic_class_token = str(traffic_class or "").strip().lower()
    class_filter = None if traffic_class_token == "all" else _normalize_traffic_class(traffic_class_token)
    selected_snapshot = snapshot
    if class_filter is not None:
        by_class = snapshot.get("byTrafficClass") if isinstance(snapshot.get("byTrafficClass"), dict) else {}
        class_snapshot = by_class.get(class_filter) if isinstance(by_class.get(class_filter), dict) else {}
        empty_quality = _build_recall_quality_payload(
            totals={},
            source_requests={},
            source_errors={},
            source_budget_exceeded={},
            history_tail=[],
        )
        selected_snapshot = {
            "updatedAt": snapshot.get("updatedAt"),
            **empty_quality,
            **class_snapshot,
        }
    alerts = _build_recall_quality_alerts(selected_snapshot)
    return {
        "updatedAt": _utc_now(),
        "trafficClass": class_filter or "all",
        "quality": selected_snapshot,
        "alerts": {
            "thresholds": {
                "noHitRate": RECALL_ALERT_NO_HIT_RATE,
                "lowConfidenceRate": RECALL_ALERT_LOW_CONFIDENCE_RATE,
                "staleHitRate": RECALL_ALERT_STALE_HIT_RATE,
                "sourceErrorRate": RECALL_ALERT_SOURCE_ERROR_RATE,
                "minRequests": RECALL_ALERT_MIN_REQUESTS,
            },
            "active": alerts,
            "count": len(alerts),
        },
    }


