@app.post("/maintenance/telemetry/purge")
async def purge_telemetry_from_retrieval_sinks(
    dry_run: bool = True,
    scan_limit: int = 5000,
    max_deletes_per_sink: int = 5000,
    include_qdrant: bool = True,
    include_mindsdb: bool = True,
    include_letta: bool = True,
):
    scan_limit = max(100, int(scan_limit))
    max_deletes = max(1, int(max_deletes_per_sink))
    sinks: dict[str, Any] = {}
    errors: dict[str, str] = {}
    if include_qdrant:
        try:
            sinks["qdrant"] = await asyncio.wait_for(
                _run_qdrant_telemetry_purge_once(
                    scan_limit=scan_limit,
                    max_deletes=max_deletes,
                    dry_run=dry_run,
                ),
                timeout=max(5.0, SINK_RETENTION_TIMEOUT_SECS),
            )
        except Exception as exc:
            errors["qdrant"] = str(exc)
    if include_mindsdb:
        try:
            sinks["mindsdb"] = await asyncio.wait_for(
                _run_mindsdb_telemetry_purge_once(
                    scan_limit=scan_limit,
                    max_deletes=max_deletes,
                    dry_run=dry_run,
                ),
                timeout=max(5.0, SINK_RETENTION_TIMEOUT_SECS),
            )
        except Exception as exc:
            errors["mindsdb"] = str(exc)
    if include_letta:
        try:
            sinks["letta"] = await asyncio.wait_for(
                _run_letta_telemetry_purge_once(
                    scan_limit=scan_limit,
                    max_deletes=max_deletes,
                    dry_run=dry_run,
                ),
                timeout=max(5.0, SINK_RETENTION_TIMEOUT_SECS),
            )
        except Exception as exc:
            errors["letta"] = str(exc)
    return {
        "ok": not bool(errors),
        "dryRun": bool(dry_run),
        "scanLimit": scan_limit,
        "maxDeletesPerSink": max_deletes,
        "sinks": sinks,
        "errors": errors,
    }


@app.post("/maintenance/qdrant/payload-indexes/harden")
async def harden_qdrant_payload_indexes(
    collection: str | None = None,
    force: bool = False,
):
    started = time.monotonic()
    qdrant_payload_index_state["running"] = True
    result: dict[str, Any] = {}
    error_text: str | None = None
    try:
        result = await _ensure_qdrant_payload_indexes(collection, force=force)
        failed_fields = result.get("failedFields") if isinstance(result.get("failedFields"), dict) else {}
        if failed_fields:
            error_text = "failed fields: " + ", ".join(sorted(str(field) for field in failed_fields.keys()))
    except Exception as exc:
        error_text = str(exc)[:400]
        raise HTTPException(500, f"Qdrant payload index hardening failed: {exc}") from exc
    finally:
        qdrant_payload_index_state["running"] = False
        qdrant_payload_index_state["lastRunAt"] = _utc_now()
        qdrant_payload_index_state["lastDurationMs"] = round((time.monotonic() - started) * 1000, 2)
        qdrant_payload_index_state["runs"] = int(qdrant_payload_index_state.get("runs", 0) or 0) + 1
        qdrant_payload_index_state["lastError"] = error_text
        qdrant_payload_index_state["lastResult"] = dict(result) if isinstance(result, dict) else {}
    return {
        "ok": bool(
            result
            and not bool(result.get("collectionMissing"))
            and not bool(result.get("failedFields"))
        ),
        "result": result,
    }


